[75296] = {id=75296,name="General Zskorro",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,questType="standard"},
[75298] = {id=75298,name="Underlight Queen",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,questType="standard"},
[75301] = {id=75301,name="Mistie's Mix Magic",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The kith of Loamm request the skills of an alchemist! We have heard tales of the wondrous concoctions you uplanders have devised! We have alchemists of our own down below! Miss Mistie has requested a few of these items. Make a delivery to Loamm as soon as you can, won't you?",objectivesText="Deliver Aerated Mana Potions and Omnium Draconis to Mistie in Loamm. Progress: Did Kayann send you? Do you have what I asked for?",starts={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},ends={{mapID=2133,npcID=203607,x=0.56,y=0.565}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.6245},questType="profession"},
[75304] = {id=75304,name="I Need... a Tailor",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The kith of Loamm request the skills of a talented tailor! We niffen are terribly curious about the magical finery you create here! We have our own stitchers and clothes-makers down below. Mister Rossmar has expressed an interest in the procurement of bolts of high quality cloth! Make a delivery to Loamm as soon as you can, won't you?",objectivesText="Deliver Vibrant Wildercloth Bolts to Rossmar in Loamm. Progress: Did Kayann send you? Oh, thank the soil! I need those bolts of cloth, and quickly!",starts={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},ends={{mapID=2133,npcID=203608,x=0.56,y=0.566}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.6245},questType="profession"},
[75307] = {id=75307,name="Road to Season City",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The kith of Loamm request the skills of a culinary chef! We niffen are very proud of our cuisine, and wish to sample some from the surface! One of our best cooks, Mister Phiary , has heard of the potent spices found in the food of the Maruuk Centaur, and the complex flavors found in the food of the Iskaara Tuskarr, and wishes to try these for himself! Please deliver these to Loamm as soon as you can, won't you?",objectivesText="Deliver Yusa's Hearty Stews and Grand Banquets of the Kalu'ak to Phiary in Loamm. Progress: Hey, hey! You should stand back, it's about to get SPICY in here!",starts={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},ends={{mapID=2133,npcID=203609,x=0.568,y=0.562}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.6245},questType="profession"},
[75308] = {id=75308,name="Scrybbil Engineering",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The kith of Loamm request the skills of an engineer! We have heard of the marvelous machines invented right here in this city, and eagerly wish to put these to use underground! We have an engineer of our own down below, Mister Scrybbil , who has a special interest in what you call \"fishing rods\". How does such a thing work? Do you use them to spear the fish? How strange! Please deliver these \"fishing rods\" as soon as you can, won't you?",objectivesText="Deliver Draconium Fisherfriends to Scrybbil in Loamm. Progress: Step right up, and witness the fantastic inventions of Scrybbil ! Can I interest you in a firework, sir and/or ma'am? What's that? You have a delivery for me?",starts={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},ends={{mapID=2133,npcID=203610,x=0.558,y=0.558}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.6245},questType="profession"},
[75309] = {id=75309,name="If a Gem Isn't Pretty",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The kith of Loamm request the skills of a jewelcrafter! I have seen the wondrous sparkling gems in this glorious city, and the niffen below wish to see them as well. We don't see very well, so we know the value of a good sparkle! Our chief Gemfinder and Jewelshiner, Miss Fanilly , wishes to see some beautiful gems. I bet she'd love the ones named after Alexstrasza and Ysera! Please deliver them to Loamm as soon as you can, won't you?",objectivesText="Deliver Silken Gemdusts , Alexstraszites and Ysemeralds to Fanilly in Loamm. Progress: Hello, hello! Did Kayann send you? I'm eager to get my hands on those gems!",starts={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},ends={{mapID=2133,npcID=203612,x=0.566,y=0.552}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.6245},questType="profession"},
