[75388] = {id=75388,name="The Azure Vaults",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="There's a problem in the Azure Vault, <name>. Beneath the Azure Archives rests the Azure Vault. Sindragosa stored many important and dangerous magical curiosities in it. A large group of Sundered Flame have broken into the vault to unlock its secrets. You need to go in there and stop the Sundered Flame!",objectivesText="Stop the Sundered Flame within the Azure Vaults. Progress: Take care within the vaults.",starts={{mapID=2024,npcID=190000,x=0.394,y=0.63}},ends={{mapID=2024,npcID=190000,x=0.394,y=0.63}},coords={mapID=2024,source="quest_giver",x=0.394,y=0.63},questType="dungeon"},
[75390] = {id=75390,name="Vertical Anomaly",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,objectivesText="Transit Bubble accessed Crystal A Crystal C Waterlogged Key found Lost Dive Box opened",starts={{x=0.546,y=0.495,mapID=2133}},ends={{x=0.546,y=0.495,mapID=2133}},coords={mapID=2133,x=0.546,y=0.495},questType="standard"},
[75394] = {id=75394,name="Webwinder Weave",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.668,y=0.868,mapID=65,npcID=203735}},ends={{x=0.668,y=0.868,mapID=65,npcID=203735}},coords={mapID=65,x=0.668,y=0.868},questType="standard"},
