[75397] = {id=75397,name="Those Rascally Worms",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,objectivesText="Deal made with Melati Pipsee fed",starts={{x=0.573,y=0.514,mapID=2133}},ends={{x=0.573,y=0.514,mapID=2133}},coords={mapID=2133,x=0.573,y=0.514},questType="standard"},
[75407] = {id=75407,name="Silk Scavenging",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Hello friend! You're a tailor, right? So you must know about silk! Mister Rossmar down in Loamm knows how to make special silk from the cocoons of the Underlight Moths, but could use some help gathering them up! You should be able to find them in the mushroomy area near Glimmerogg. I'll sure he will make it worth your while!",objectivesText="Collect 10 Underlight Cocoons Fibers in Zaralek Cavern . Progress: Hey, uplander! Do you have those cocoons yet?",starts={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},ends={{mapID=2133,npcID=203608,x=0.56,y=0.566}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.6245},questType="profession"},
[75408] = {id=75408,name="Calling All Dracthyr!",level=36,requiredLevel=36,faction="both",expansion=10,zoneID=13862,mapID=2112,description="<This flyer is illustrated with inviting sketches of dracthyr eating, sparring, and having fun.> Calling all dracthyr! Do you feel adrift after the events of the underground? Do you want to bond with your creche mates? Do you just need someone to talk to? Come join us at Weyrnrest for food, fun, and camaraderie! ALL dracthyr welcome!",objectivesText="Go to the party at Weyrnrest in Valdrakken .",starts={{x=0.551,y=0.4,mapID=2112,objectID=398674}},ends={{mapID=2112,npcID=201766,x=0.24,y=0.32}},coords={mapID=2112,source="quest_giver",x=0.24,y=0.32},questType="standard"},
[75409] = {id=75409,name="Desolace Drift",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.281,y=0.633,mapID=66,npcID=203788}},ends={{x=0.281,y=0.633,mapID=66,npcID=203788}},coords={mapID=66,x=0.281,y=0.633},questType="standard"},
