[75414] = {id=75414,name="Great Divide Dive - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.414,y=0.13,mapID=199,npcID=203793}},ends={{x=0.414,y=0.13,mapID=199,npcID=203793}},coords={mapID=199,x=0.414,y=0.13},questType="standard"},
[75417] = {id=75417,name="Symbol of Hope",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Champion--Ebyssian, Sabellian, and Wrathion have come to an agreement of who should lead, and are presenting a unified front. All three were quite eager to speak of your contributions and aid in Zaralek Cavern as well. It seems that they are also in agreement that they could not have succeeded without you. High praise indeed--and well deserved. Please, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.",objectivesText="Speak with Alexstrasza. Progress: Please, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.",starts={{mapID=2112,npcID=187678,x=0.583778,y=0.357111}},ends={{mapID=2112,npcID=187678,x=0.583778,y=0.357111}},coords={mapID=2112,source="quest_giver",x=0.583778,y=0.357111},questType="standard"},
[75419] = {id=75419,name="Sundered Flames",level=36,requiredLevel=36,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Did Neltharion keep this place as his hoard? No wonder that Sarkareth was looking for it. Neltharion's \"treasures\" litter every corner of it. There's no telling what Sarkareth has gotten his claws on here. Stay close!",objectivesText="Find Sarkareth.",starts={{mapID=2133,npcID=200075,x=0.627,y=0.735}},ends={{mapID=2133,npcID=204040,x=0.63,y=0.74}},coords={mapID=2133,source="quest_giver",x=0.627,y=0.735},questType="standard"},
[75437] = {id=75437,name="Razorfen Roundabout",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.428,y=0.931,mapID=199,npcID=203908}},ends={{x=0.428,y=0.931,mapID=199,npcID=203908}},coords={mapID=199,x=0.428,y=0.931},questType="standard"},
[75438] = {id=75438,name="Razorfen Roundabout - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.428,y=0.931,mapID=199,npcID=203908}},ends={{x=0.428,y=0.931,mapID=199,npcID=203908}},coords={mapID=199,x=0.428,y=0.931},questType="standard"},
[75439] = {id=75439,name="Razorfen Roundabout - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.428,y=0.931,mapID=199,npcID=203908}},ends={{x=0.428,y=0.931,mapID=199,npcID=203908}},coords={mapID=199,x=0.428,y=0.931},questType="standard"},
[75440] = {id=75440,name="Satiating Sharpbeak",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Sheridon Hastle was our flight master and Sharpbeak 's rider. After his death, she won't let anyone touch her. <Narvra clutches her side in pain.> Or feed her. Rupert tried but... she just won't. The rest of us are too injured to move... I'm worried about her. Can you... ow... try? Someone new may get through to her. Her feed is in the bag by the tent. And... if you can get her to accept food, she might let you ride her.",objectivesText="Feed Sharpbeak in the Dragonscale Camp in Zaralek Cavern . Progress: < Sharpbeak looks at you mournfully.>",starts={{mapID=2133,npcID=200953,x=0.4655,y=0.4805}},ends={{mapID=2133,npcID=200300,x=0.402,y=0.678}},coords={mapID=2133,source="quest_giver",x=0.4655,y=0.4805},questType="standard"},
[75441] = {id=75441,name="Smelly Scramble",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,objectivesText="Muskmettle's concotion made by returning smellies to pot",starts={{x=0.576,y=0.571,mapID=2133}},ends={{x=0.576,y=0.571,mapID=2133}},coords={mapID=2133,x=0.576,y=0.571},questType="standard"},
[75444] = {id=75444,name="Waygate Exploration: The Forbidden Reach",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="Thaelin Darkanvil have something of an interest for you yet again.>",starts={{npcID=196643,x=0.454,y=0.55,mapID=2112}},ends={{npcID=189066,x=0.472,y=0.902,mapID=2022}},coords={x=0.454,y=0.55,source="quest_giver",mapID=2022},questType="standard"},
[75456] = {id=75456,name="News From Beneath",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Before I arrived, I was informed that the Life-Binder has need of our aid. There is news of the Incarnates, and she requests our presence at the Seat of the Aspects. As for Emberthal -- there is very little we can do for now. It is best we allow her to reflect and gather thoughts alone.",starts={{npcID=200277,x=0.768,y=0.382,zoneID=14433}},ends={{npcID=201281,x=0.612,y=0.42,mapID=2112}},coords={x=0.768,y=0.382,source="quest_giver",mapID=2112},questType="standard"},
[75459] = {id=75459,name="Brand New Digs",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,objectivesText="Myrrit picked up Key found Shield investigated Sniffed for clues Burrowed with Myrrit Burrowed past the toxic gas at the entrance Myrrit placed on the pressure plate Chest puzzle solved",starts={{x=0.559,y=0.499,mapID=2133}},ends={{x=0.559,y=0.499,mapID=2133}},coords={mapID=2133,x=0.559,y=0.499},questType="world"},
[75462] = {id=75462,name="Mouse Rescuers",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="I feel bad for everything I did working for Malrogg . He was just so big and scary, I never felt like I had a choice... < Agrul slowly shakes his head.> No more excuses. We need to get that sniffin' mouse back home to Yarren . I was never strong enough to take on Malrogg alone. But you... You can save Persii .",objectivesText="Kill Malrogg . Progress: Did you find that drogbar?",starts={{mapID=2133,npcID=202600,x=0.4875,y=0.7735}},ends={{mapID=2133,npcID=202597,x=0.51,y=0.74}},coords={mapID=2133,source="quest_giver",x=0.4875,y=0.7735},questType="standard"},
