[75466] = {id=75466,name="Lost Time-Lost Vikings",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Some rowdy customers stumbled out of a temporal portal a bit ago. Before I could get a Timewalker to help get them home, they decided to visit Valdrakken. Would you find Olaf , Baelog , and Eric and get them to come back here before they cause too much of a ruckus?",objectivesText="Convince the Lost Vikings to return to Eon's Fringe.",starts={{mapID=2025,npcID=203769,x=0.522,y=0.815}},ends={{mapID=2025,npcID=203769,x=0.522,y=0.815}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.815},questType="standard"},
