[75694] = {id=75694,name="Aberrus, the Shadowed Crucible: Sarkareth",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="I have no interest in following my brothers within Aberrus, but I continue to care for their safety. Neltharion fell so deeply into madness that his secret stronghold is no doubt filled with any number of unspeakable dangers. Go with them, <name>. Stand with them. They will need your support in what is to come.",objectivesText="Enter Aberrus, the Shadowed Crucible, and defeat Sarkareth. Progress: Aberrus holds mysteries and dangers alike. They must be dealt with, before any of them fall into the wrong hands.",starts={{mapID=2133,npcID=199965,x=0.483,y=0.28225},{mapID=2133,npcID=201727,x=0.48,y=0.118}},ends={{mapID=2133,npcID=199965,x=0.483,y=0.28225},{mapID=2133,npcID=201727,x=0.48,y=0.118},{mapID=2112,npcID=204287,x=0.6056,y=0.4176},{mapID=2112,npcID=214851,x=0.603333,y=0.41}},coords={mapID=2133,source="quest_giver",x=0.483,y=0.28225},questType="raid"},
[75699] = {id=75699,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=401752,x=0.47,y=0.457,mapID=2112}},ends={{npcID=401752,x=0.47,y=0.457,mapID=2112}},coords={x=0.47,y=0.457,source="quest_giver",mapID=2112},questType="standard"},
[75700] = {id=75700,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=401753,x=0.726,y=0.469,mapID=2112}},ends={{npcID=401753,x=0.726,y=0.469,mapID=2112}},coords={x=0.726,y=0.469,source="quest_giver",mapID=2112},questType="standard"},
[75701] = {id=75701,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=401754,x=0.224,y=0.312,mapID=2112}},ends={{npcID=401754,x=0.224,y=0.312,mapID=2112}},coords={x=0.224,y=0.312,source="quest_giver",mapID=2112},questType="standard"},
[75702] = {id=75702,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14433,starts={{npcID=401755,x=0.339,y=0.589,zoneID=14433}},ends={{npcID=401755,x=0.339,y=0.589,zoneID=14433}},coords={x=0.339,y=0.589,source="quest_giver",zoneID=14433},questType="standard"},
[75706] = {id=75706,name="A Race to the Finish",level=36,requiredLevel=36,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Everyone loves a good snail race! In the most exciting races, every snail has a chance to win. You can help a snail win by giving it treats. Watch how fast it makes them go! Grab a bag of treats and toss them in the path of the snails. See if you can get Tricky to win!",objectivesText="Help Tricky win a race. Progress: Has your snail won the race?",starts={{mapID=2133,npcID=201099,x=0.444,y=0.804}},ends={{mapID=2133,npcID=201099,x=0.444,y=0.804}},coords={mapID=2133,source="quest_giver",x=0.444,y=0.804},questType="standard"},
[75707] = {id=75707,name="A Race to the Finish",level=36,requiredLevel=36,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Everyone loves a good snail race! In the most exciting races, every snail has a chance to win. You can help a snail win by giving it treats. Watch how fast it makes them go! Grab a bag of treats and toss them in the path of the snails. See if you can get Brulee to win!",objectivesText="Help Brulee win a race. Progress: Has your snail won the race?",starts={{mapID=2133,npcID=201099,x=0.444,y=0.804}},ends={{mapID=2133,npcID=201099,x=0.444,y=0.804}},coords={mapID=2133,source="quest_giver",x=0.444,y=0.804},questType="standard"},
[75709] = {id=75709,name="Find a Rumble Coin",faction="alliance",expansion=10,zoneID=13862,mapID=84,description="To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin here at the docks. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!",objectivesText="Find a Rumble Coin in Stormwind Harbor and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.",starts={{mapID=84,npcID=201230,x=0.423333,y=0.468333}},ends={{mapID=84,npcID=201230,x=0.423333,y=0.468333}},coords={mapID=84,source="quest_giver",x=0.423333,y=0.468333},questType="standard"},
[75711] = {id=75711,name="Find a Rumble Coin",faction="horde",expansion=10,zoneID=13862,mapID=84,description="To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin over in the inn. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!",objectivesText="Find a Rumble Coin in the Broken Tusk and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.",starts={{mapID=84,npcID=201230,x=0.423333,y=0.468333}},ends={{mapID=84,npcID=201230,x=0.423333,y=0.468333}},coords={mapID=84,source="quest_giver",x=0.423333,y=0.468333},questType="standard"},
[75712] = {id=75712,name="Warcraft Rumble Minis: New Look!",level=0,requiredLevel=0,faction="alliance",expansion=10,zoneID=13862,mapID=2112,description="This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!",objectivesText="Go to the Warcraft Rumble machine in Stormwind Harbor.",ends={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},questType="standard"},
[75713] = {id=75713,name="Warcraft Rumble Minis: New Look!",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=13862,mapID=2112,description="This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!",objectivesText="Go to the Warcraft Rumble machine in Orgrimmar 's Valley of Strength.",ends={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},questType="standard"},
[75720] = {id=75720,name="Care to Barter?",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Hey, Uplander! I hear you like helping. Maybe you could help me out? I need some packages sent to Valdrakken. If you don't peek and don't ask, I can make it worthwhile. Stop by when you're in Loamm. We can work out a deal! Your new friend, Ponzo .",objectivesText="Talk to Ponzo in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=204693,x=0.58,y=0.538}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75721] = {id=75721,name="Bartering 101",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="So here's what I need you to do. A friend of mine, Kayann , went all the way up to Valdrakken . He's expecting a delivery from me. Can you get it to him? No questions, though. Don't look, don't smell, don't taste. This is for Kayann 's nose only! If that's all right with you, I'll send you on your way--with my thanks, of course!",objectivesText="Deliver Ponzo 's box to Kayann in Valdrakken .",starts={{mapID=2133,npcID=204693,x=0.58,y=0.538}},ends={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},coords={mapID=2133,source="quest_giver",x=0.58,y=0.538},questType="standard"},
[75722] = {id=75722,name="Bag of Gold",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Hello, $p! I heard you've been helping us out! Good deeds should be rewarded--and I've got something special for you! Why don't you meet me in Loamm? Keep up the good work, Mimuup",objectivesText="Talk to Mimuup in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=204254,x=0.565,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75723] = {id=75723,name="Cavern Drakewatching",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Well hey there, Uplander! Word is, you've been helping us out a lot! We got a little something for you in return. See me in Loamm and I'll hand it over! Best, Harlowe Marl",objectivesText="Talk to Harlowe Marl in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=202468,x=0.564,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75724] = {id=75724,name="Like the Niffen Do",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Hello there, $p! We want to thank you for all the help you've given us. It's only right! Meet me in Loamm and I'll teach you to dig like we niffen do! Sincerely, Mimuup",objectivesText="Talk to Mimuup in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=204254,x=0.565,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75725] = {id=75725,name="Off to the Track",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Hey Champ! We got a fresh golden opportunity for you. Snail racing! One of the most dynamic sports in the games! Ponzo said you'd be interested. Called you a real go-getter! So go! Get to the track in Glimmerogg! See ya there, Briggul",objectivesText="Talk to Briggul in Glimmerogg.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=201752,x=0.442,y=0.8}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75726] = {id=75726,name="Sweaty Armor",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,objectivesText="Talk to Harlowe Marl in Loamm.",questType="standard"},
[75727] = {id=75727,name="The Smelliest Tabard",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Greetings, $p! You just keep doing us amazing favors, don't you? Come on back to Loamm for an extra special reward! Sincerely, Mimuup",objectivesText="Talk to Mimuup in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=204254,x=0.565,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75728] = {id=75728,name="Bartering Boulders",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Oh hey, Uplander! I could use your help again. I like your battering style. But you know these bricks? They're useless! Boulders are where it's at! Come see me in Loamm, and I'll give you all the details. Ponzo",objectivesText="Talk to Ponzo in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=204693,x=0.58,y=0.538}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75729] = {id=75729,name="Attune to the Observer",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13644,mapID=2022,description="Can you believe this used to be an observatory? Our records indicate that the dragonkin here were mapping heavenly bodies in an attempt to predict the future. How do you think they did it? I'm picking up a partial signature that matches the time window we're shooting for. Put on the Technoscryers and try to pinpoint the sources so we can dial it in.",objectivesText="Technoscry for the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.",starts={{mapID=2022,npcID=204835,x=0.564,y=0.44}},ends={{mapID=2022,npcID=204835,x=0.564,y=0.44}},coords={mapID=2022,source="quest_giver",x=0.564,y=0.44},questType="standard"},
[75730] = {id=75730,name="Slitherdrake Watching",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Well hello there! Word around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over! Best, Harlowe Marl",objectivesText="Talk to Harlowe Marl in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=202468,x=0.564,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75731] = {id=75731,name="Scented Boots",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Well hello there! Word gets around of your continued support. We've found some armor that you may be able to use. Come meet me in Loamm and we'll see if it's useful! Best, Harlowe Marl",objectivesText="Talk to Harlowe Marl in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=202468,x=0.564,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75741] = {id=75741,name="Bundle of Boulders",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Hey Uplander! I heard you've been telling people I've been mean to you. I haven't, but they told me to be nicer to you because all you've done for us. Taken advantage of? More like giving you some honest work! To make you and the others happy, I'll give you some boulders. See me in Loamm, Ponzo",objectivesText="Talk to Ponzo in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=204693,x=0.58,y=0.538}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75742] = {id=75742,name="Drake Helms",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Howdy! Word gets around of your continued support. We got a little something for ya. Meet me in Loamm so I can get it to ya! Best, Harlowe Marl",objectivesText="Talk to Harlowe Marl in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=202468,x=0.564,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75744] = {id=75744,name="A Token of Our Gratitude",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Greetings! With all the help you've given us, we've decided it's only fair to return the favor. Meet me in Loamm. We have a reward we're eager to give you. Sincerely, Mimuup",objectivesText="Talk to Mimuup in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=204254,x=0.565,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[75765] = {id=75765,name="Liquid Art",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<A clay pot filled with... mud? It appears to be niffen in origin. Perhaps a resident of Loamm is looking for it!>",objectivesText="Return the Dripping Clay Pot to its owner in Loamm. Progress: Oh, is that...?",starts={{x=0.55,y=0.489,mapID=2133}},ends={{mapID=2133,npcID=204215,x=0.578,y=0.542}},coords={mapID=2133,source="quest_giver",x=0.578,y=0.542},questType="standard"},
[75766] = {id=75766,name="Ruby in the Rough",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<A beautiful ruby set in fine gold sits nestled in a box of draconic origin. The jewelcrafter in Loamm would love to take a look at this.>",objectivesText="Deliver the Shimmering Draconic Gem to Fanilly in Loamm. Progress: It's SO shiny!!",ends={{mapID=2133,npcID=203612,x=0.566,y=0.552}},coords={mapID=2133,source="quest_giver",x=0.566,y=0.552},questType="standard"},
[75767] = {id=75767,name="Good Time Boy",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<A very wet gorloc totem rests on the cave floor. How did this even get here? The niffen love stuff like this. Maybe someone in Loamm will take it off your hands.>",objectivesText="Find a new home for the Soaked Totem in Loamm. Progress: I've needed a backup dancer!",starts={{x=0.56,y=0.509,mapID=2133}},ends={{mapID=2133,npcID=204863,x=0.572,y=0.538}},coords={mapID=2133,source="quest_giver",x=0.572,y=0.538},questType="standard"},
[75768] = {id=75768,name="Lucky Ducky",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<You find a small toy duckling. It reminds you just a little of Loamm's swallows. Maybe Cinnam will like this?>",objectivesText="Give the Feathered Friend to Cinnam in Loamm. Progress: This is for me?",starts={{x=0.587,y=0.5,mapID=2133}},ends={{mapID=2133,npcID=200056,x=0.551,y=0.575},{mapID=2133,npcID=205318,x=0.556,y=0.602}},coords={mapID=2133,source="quest_giver",x=0.551,y=0.575},questType="standard"},
[75769] = {id=75769,name="Drawing a Blank",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<A discarded painting covered in dust rests on the cave floor. Maybe someone in Loamm could make use of this?>",objectivesText="Give the Stretched Canvas to a niffen in Loamm. Progress: How did you know I wanted to try my nose at scent-painting?",starts={{x=0.585,y=0.515,mapID=2133}},ends={{mapID=2133,npcID=204861,x=0.572,y=0.526}},coords={mapID=2133,source="quest_giver",x=0.572,y=0.526},questType="standard"},
[75770] = {id=75770,name="A Glass of Bubbly",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<You find a glowing blue potion of indeterminate origin. Maybe the Loamm alchemist will want to take a look?>",objectivesText="Take the Bubbling Elixir to Mistie in Loamm. Progress: Hmm... I'll need to run some analysis!",starts={{x=0.567,y=0.529,mapID=2133}},ends={{mapID=2133,npcID=203607,x=0.56,y=0.565}},coords={mapID=2133,source="quest_giver",x=0.56,y=0.565},questType="standard"},
[75771] = {id=75771,name="Incense Replay",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<You find some incense that smells familiar, but you can't quite place it. Citros will definitely want to take a sniff.>",objectivesText="Take the Mysterious Incense to Citros in Loamm. Progress: Boy howdy! That's some mighty strong incense!",starts={{x=0.56,y=0.575,mapID=2133}},ends={{mapID=2133,npcID=200055,x=0.568,y=0.54}},coords={mapID=2133,source="quest_giver",x=0.568,y=0.54},questType="standard"},
[75772] = {id=75772,name="Flask Manager",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<A small leather-wrapped flask sits on a shelf in the cave. Someone might be missing this.>",objectivesText="Find the owner of the leather-wrapped flask . Progress: Well it's not mine, but I'll take it off your hands!",starts={{x=0.585,y=0.564,mapID=2133}},ends={{mapID=2133,npcID=203644,x=0.572,y=0.558}},coords={mapID=2133,source="quest_giver",x=0.572,y=0.558},questType="standard"},
[75773] = {id=75773,name="Little Blank Book",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<You find a book filled with Draconic text and not much else. Maybe someone in Loamm could help you decipher it?>",objectivesText="Bring the book back to Loamm. Progress: What do you mean, read it? It's blank, silly!",starts={{x=0.601,y=0.574,mapID=2133}},ends={{mapID=2133,npcID=204860,x=0.568,y=0.564}},coords={mapID=2133,source="quest_giver",x=0.568,y=0.564},questType="standard"},
[75789] = {id=75789,name="Flashfrost Flyover - Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.628,y=0.74,mapID=2022,npcID=190326}},ends={{x=0.628,y=0.74,mapID=2022,npcID=190326}},coords={mapID=2022,x=0.628,y=0.74},questType="standard"},
[75790] = {id=75790,name="Flashfrost Flyover - Reverse Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.628,y=0.74,mapID=2022,npcID=190326}},ends={{x=0.628,y=0.74,mapID=2022,npcID=190326}},coords={mapID=2022,x=0.628,y=0.74},questType="standard"},
[75791] = {id=75791,name="Wild Preserve Circuit - Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.426,y=0.945,mapID=2022,npcID=190503}},ends={{x=0.426,y=0.945,mapID=2022,npcID=190503}},coords={mapID=2022,x=0.426,y=0.945},questType="standard"},
[75792] = {id=75792,name="Wild Preserve Circuit - Reverse Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.426,y=0.945,mapID=2022,npcID=190503}},ends={{x=0.426,y=0.945,mapID=2022,npcID=190503}},coords={mapID=2022,x=0.426,y=0.945},questType="standard"},
[75831] = {id=75831,name="Barter Up",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,objectivesText="Bring the Pungent Morsel to Ponzo in Loamm. Provided item:",questType="standard"},
[75833] = {id=75833,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=1637,mapID=85,ends={{npcID=185468,x=0.51,y=0.718,mapID=84},{npcID=185472,x=0.488,y=0.762,mapID=85}},questType="standard"},
[75865] = {id=75865,name="Relic Rustler",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2112,description="A group of mean, scaly uplanders moved in near the old titan ruins south of Loamm and started tearing the place apart. Rude, but they're sure to have uncovered all sorts of ancient titan scraps. And that stuff is almost always magic in some way. Grab some and go see what Dustmonger Topuiz back in Loamm can make of it!",objectivesText="Collect 8 Relic Shards . Progress: I can't wait to see what you uncover!",starts={{mapID=2112,npcID=203516,x=0.365,y=0.6245}},ends={{mapID=2133,npcID=203172,x=0.56,y=0.568}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.6245},questType="profession"},
[75867] = {id=75867,name="A Link to the Past",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13644,mapID=2022,description="Okay, calibrations complete! Mine too, so I'll be able to see what you see. Let's head over to that telescope and we'll see what we see.",objectivesText="Observe the events from the past. Progress: I wonder what we'll find?",starts={{mapID=2022,npcID=204835,x=0.564,y=0.44}},ends={{mapID=2022,npcID=204835,x=0.564,y=0.44}},coords={mapID=2022,source="quest_giver",x=0.564,y=0.44},questType="standard"},
[75868] = {id=75868,name="A Window into the Future",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13644,mapID=2022,description="Those lenses are a wondrous integration of technology and arcane artifice. I'm sure we could learn much, and maybe even upgrade my own invention. But first we'll need to find it. You're a dragonrider, right? Can you fly up and recover the lens? It's possible the dreadsqualls still have it in one of their nests.",objectivesText="Search Dreadsqualls nests to recover the lens. Progress: Did you recover the lens, <name>?",starts={{mapID=2022,npcID=204835,x=0.564,y=0.44}},ends={{mapID=2022,npcID=204835,x=0.564,y=0.44}},coords={mapID=2022,source="quest_giver",x=0.564,y=0.44},questType="standard"},
[75874] = {id=75874,name="Time to Fly",level=30,requiredLevel=30,faction="horde",expansion=10,zoneID=8670,mapID=1165,description="Zandalar is home to many pterrordaxes. One will accompany you into the skies. Visit Beast Master Kalatak at Dazar'alor in Zuldazar.",objectivesText="Find Beast Master Kalatak.",ends={{mapID=1165,npcID=122696,x=0.458,y=0.362}},coords={mapID=1165,source="quest_giver",x=0.458,y=0.362},questType="standard"},
[75877] = {id=75877,name="Time to Fly",level=30,requiredLevel=30,faction="alliance",expansion=10,zoneID=8568,mapID=1161,description="Kul Tiras is home to many gryphons. One will accompany you into the skies. Visit Leila Stafford at the Tradewinds Market in Boralus.",objectivesText="Find Leila Stafford .",ends={{npcID=142073,x=0.696,y=0.13,mapID=1161}},questType="standard"},
[75885] = {id=75885,name="Get Rich Quick",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Uplander! I have a question for you. Do you want to wear an expensive hat like mine? Own the best snails in town? Enjoy the good life? If the answer is yes, you're ready to make more wealth than you've ever dreamed of! Ponzo style! Together we can both be rich! Of course I'm already rich, but you can be too! Just take these items I have here and show them around town. I'll cut you in for a share of the profits for every order you get.",objectivesText="Get the citizens of Loamm to order some Ponzo 's Cream and Glimmerogg Timeshare Vouchers. Progress: Did you get any orders?",starts={{mapID=2133,npcID=204693,x=0.58,y=0.538}},ends={{mapID=2133,npcID=204693,x=0.58,y=0.538}},coords={mapID=2133,source="quest_giver",x=0.58,y=0.538},questType="standard"},
[75887] = {id=75887,name="Fyrakk's Forces",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14022,mapID=2112,description="Champion, Fyrakk and his Primalist allies have struck a dark bargain with the djaradin. We have received word that their forces are assaulting the Dragon Isles in search of resources for some nefarious project. Please, champion, find one of these Suffusion Camps and assist any of our allies you can find there.",objectivesText="Journey to a Suffusion Camp.",starts={{mapID=2112,npcID=205647,x=0.492667,y=0.558}},ends={{mapID=2023,npcID=201648,x=0.752,y=0.692},{mapID=2024,npcID=203520,x=0.58,y=0.345}},coords={mapID=2112,source="quest_giver",x=0.492667,y=0.558},questType="standard"},
[75888] = {id=75888,name="Suffusion Camp",level=60,requiredLevel=60,faction="both",expansion=10,zoneID=13646,mapID=2023,description="Fyrakk has made a deal with the dragon hunting djaradin! Their blacksmith, Igira, has sent her finest crafters under the aegis of Fyrakk's Primalists. They are gathering materials for the construction of... something. Find a way to access their Suffusion Crucibles and Molds. Keep what you find but we must learn more about what they are doing. The forces appear to require special wards to access the Crucibles and Molds. Start there.",objectivesText="Loot a Suffusion Crucible and a Suffusion Mold. Progress: What have you found in the Crucibles and Molds? All of this shadowflame about makes my scales crawl.",starts={{mapID=2023,npcID=201648,x=0.752,y=0.692},{mapID=2024,npcID=203520,x=0.58,y=0.345}},ends={{mapID=2023,npcID=201648,x=0.752,y=0.692},{mapID=2024,npcID=203520,x=0.58,y=0.345}},coords={mapID=2023,source="quest_giver",x=0.752,y=0.692},questType="standard"},
[75890] = {id=75890,name="The Clarion Call",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=1519,mapID=84,description="Good to see you, <name>. I have a message from someone called Arko'narin Starshade . It reads... \"As a protector of the kaldorei, I must ask for you to meet me near the embassy in Stormwind. Tyrande has called the Wardens to action, and Maiev Shadowsong herself requested your aid in this matter as well.\" Arko'narin Starshade",objectivesText="Speak with Arko'narin Starshade near the Stormwind Embassy in Stormwind City. Provided item:",starts={{x=0.524,y=0.142,mapID=84,objectID=405958}},ends={{mapID=84,npcID=207353,x=0.525,y=0.045}},coords={mapID=84,source="quest_giver",x=0.525,y=0.045},questType="standard"},
[75891] = {id=75891,name="Ancient Curses",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=1519,mapID=84,description="Thank you for answering my call so quickly, <name>. Demonic corruption has seen a resurgence in Felwood recently. Tyrande sent out a contingent of Sentinels and one of her own priestesses to investigate the matter further. None have returned. Tyrande asked the Wardens to look into the matter--and Maiev has asked for your assistance personally. We need to make haste to Felwood, and see what Maiev has discovered.",objectivesText="Meet Maiev Shadowsong in Felwood. Progress: May Elune guide us all to victory in this forsaken place.",starts={{mapID=84,npcID=207353,x=0.525,y=0.045}},ends={{mapID=77,npcID=202702,x=0.372667,y=0.549333}},coords={mapID=84,source="quest_giver",x=0.525,y=0.045},questType="standard"},
[75918] = {id=75918,name="Fire Season",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="No doubt you have seen the destruction that Fyrakk continues to leave in his wake. While others fight him directly, my troops and I have been serving as the eyes and ears of the green dragonflight. Although Fyrakk's actions may seem erratic, there are trends to his strategies. We learned that he is to have a secret meeting with Vyranoth soon in Lunedane. This is a deviation from his recent tactics, and we need to know why. Given the danger, we would value your aid. Meet me in Lunedane.",objectivesText="Meet Shandris at Lunedane in the Ohn'ahran Plains .",starts={{mapID=2112,npcID=205067,x=0.502,y=0.533}},ends={{mapID=2023,npcID=205068,x=0.186,y=0.798}},coords={mapID=2112,source="quest_giver",x=0.502,y=0.533},questType="standard"},
[75919] = {id=75919,name="Dousing the Wards",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="Fyrakk and Vyranoth are already here. I spotted them near the overlook at the northeastern edge of Lunedane. Landing close to their location would reveal our presence, thus we are forced to begin our mission here. However, the bridge connecting this area to the overlook has been protected with fire magic. We will not be able to break through it. Fyrakk's Primalist allies appear to be maintaining the fire using wards set up around this area. If we destroy the wards, the fire should subside.",objectivesText="Destroy 4 Warding Firestones. Progress: We need to bring that barrier down so we can get closer to the Incarnates. We cannot hear them from this far away.",starts={{mapID=2023,npcID=205068,x=0.186,y=0.798}},ends={{mapID=2023,npcID=205068,x=0.186,y=0.798}},coords={mapID=2023,source="quest_giver",x=0.186,y=0.798},questType="standard"},
[75920] = {id=75920,name="Eyes of Fire",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="This area is swarming with far more Primalists than I expected. Fyrakk does not generally travel with guards, so I doubt the Primalists are here to accompany him. They seem to be trying to establish a foothold here. But why? Perhaps whatever the Incarnates are discussing will answer that question. In the meantime, let us thin out the Primalists guarding this area. We cannot risk having them in full force behind us as we cross the bridge.",objectivesText="Kill 8 Burning Flamespeakers or Blazing Overseers . Progress: We will need to work quickly. We cannot risk drawing the attention of the Incarnates.",starts={{mapID=2023,npcID=205068,x=0.186,y=0.798}},ends={{mapID=2023,npcID=205068,x=0.186,y=0.798}},coords={mapID=2023,source="quest_giver",x=0.186,y=0.798},questType="standard"},
[75921] = {id=75921,name="Through the Flames",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="Druids of the Flame... <Shandris frowns deeply, eyes shut as she holds back her anger.> To think that they still exist. That any of our people would join Fyrakk and his-- <She stops, releases a heavy breath, and continues.> We have a mission to complete. We need to cross the bridge to get close enough to the Incarnates that we can overhear their conversation. I will shroud us so that we can move between the elementals still guarding the way forward.",objectivesText="Collect 4 Smoldering Blossoms while crossing the bridge towards Fyrakk and Vyranoth. Progress: We need be as close to the Incarnates as we can. We cannot afford to miss a single word of their conversation.",starts={{npcID=205892}},ends={{mapID=2023,npcID=205134,x=0.218,y=0.772}},coords={mapID=2023,source="quest_giver",x=0.218,y=0.772},questType="standard"},
[75922] = {id=75922,name="Inflammatory Information",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="<Shandris whispers to you.> Do you see that up ahead? The Druids of the Flame have captured what appears to be a keeper--a guardian of nature, sacred to our people. If their power is already enough to... <Shandris shakes her head, then gestures at the dense shrubbery nearby.> Stay hidden with me and we will listen to the Incarnates, and perhaps discern what the druids intend to do with the keeper.",objectivesText="Eavesdrop on Fyrakk and Vyranoth. Progress: I will hold off any reinforcements that come. Deal with the keeper!",starts={{mapID=2023,npcID=205134,x=0.218,y=0.772}},ends={{mapID=2023,npcID=205142,x=0.216,y=0.77}},coords={mapID=2023,source="quest_giver",x=0.218,y=0.772},questType="standard"},
[75923] = {id=75923,name="Raise the Alarm",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="So the Druids of the Flame have allied with Fyrakk to help him invade the Emerald Dream. They were able to turn that keeper to the flame with hardly any effort. Fyrakk must be bolstering their power, perhaps as payment for their aid in accessing the Dream. We need to mobilize troops immediately to find every Druid of the Flame on the Dragon Isles and stop them. Go to Captain Drine in Valdrakken and alert her. She will dispatch the drakonid. I will go to Merithra and handle things here.",objectivesText="Deliver your report to Captain Drine at the Seat of the Aspects in Valdrakken.",starts={{mapID=2023,npcID=205142,x=0.216,y=0.77}},ends={{mapID=2112,npcID=206041,x=0.544,y=0.4724}},coords={mapID=2023,source="quest_giver",x=0.216,y=0.77},questType="standard"},
[75932] = {id=75932,name="Loamm Niffen",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[75935] = {id=75935,name="Time, Signature",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Oh good, an adventurer. You've heard of Pedgi, I presume? The composer? No? Well, don't tell him that. We were traveling to research his next song, when we stumbled upon a dragon named Tempo. Pedgi is now convinced they're the only one who can help us. Yes, because of the name. That's really all it takes for him. But Tempo here is, understandably, too busy to help us. Could you talk to them? See if we can help clear their schedule?",objectivesText="See if Tempo would be willing to help Pedgi with his music. Progress: Yes, he's always like this. But he pays well and I get to travel.",starts={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},ends={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},coords={mapID=2025,source="quest_giver",x=0.538,y=0.8416},questType="standard"},
[75936] = {id=75936,name="Slimy Yet Satisfying",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<A worm. You know someone who might love this.>",objectivesText="Bring 1 Wriggling Worm to Marie Shellie in Loamm. Progress: < Marie Shellie drips slime.>",starts={{x=0.569,y=0.521,mapID=2133}},ends={{mapID=2133,npcID=204356,x=0.568,y=0.54}},coords={mapID=2133,source="quest_giver",x=0.568,y=0.54},questType="standard"},
[75949] = {id=75949,name="Downbeat Data",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="You say that Tempo mentioned objects from other timelines? I have a device used for syncing melodies. Strangely enough, it seems to have the same effect on timelines in this town. Perhaps a side effect of the chaotic temporal energies here? I've upgraded Pedgi's glasses to allow him to observe the rhythms of the world. They may make it easier to find mis-timed entities. Ask if you can borrow them.",objectivesText="Use Melly's device near objects from other timelines. Pedgi's sunglasses will make them easier to find. Progress: Have you found any mis-timed entities?",starts={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},ends={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},coords={mapID=2025,source="quest_giver",x=0.538,y=0.8416},questType="standard"},
[75950] = {id=75950,name="An Exemplar of Justice: Hadwin",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13646,mapID=2024,description="We've been out here for a good bit of time. Time enough for me to watch the gnolls around here. Gnolls are usually a nuisance, but the decay gnolls around Brackenhide Hollow... The decay doesn't just warp their bodies. It warps their minds too. Decaymonger Rotpaw is the worst of them. She's indiscriminate in who or what she spreads her decay to: the unwilling of her people, travelers, animals, children... If there's any justice in this world, she should be taken down.",objectivesText="Help Hadwin defeat Decaymonger Rotpaw .",starts={{mapID=2024,npcID=204590,x=0.176,y=0.314}},ends={{mapID=2024,npcID=204590,x=0.176,y=0.314}},coords={mapID=2024,source="quest_giver",x=0.176,y=0.314},questType="standard"},
[75951] = {id=75951,name="An Exemplar of Order: Talthis",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13646,mapID=2024,description="I know why Travard chose this area for our training. The decay here is... chaotic and disordered. Things that Tyr and the titans are not! The nearby gnolls revel in the decay. Revolting. They have taken over territory that was once occupied by the proud, noble, and civil tuskarr. The tuskarr have asked that relics they had to abandon are returned to them. Please help me fight the gnolls and retrieve the relics so the tuskarr can continue their rituals in Iskaara.",objectivesText="Bring Talthis 5 Tuskarr relics. Progress: The gnolls had no right to those relics. They belong to the tuskarr.",starts={{mapID=2024,npcID=204593,x=0.175,y=0.314}},ends={{mapID=2024,npcID=204593,x=0.175,y=0.314}},coords={mapID=2024,source="quest_giver",x=0.175,y=0.314},questType="standard"},
[75952] = {id=75952,name="An Exemplar of Sacrifice: Nolaki",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13646,mapID=2024,description="Much is said about how decay spreads through the air and ground. But it also spreads through the water. Slimes that live in the rivers and streams ooze pestilence. The water is toxic with it. But if we wade in and kill the big one, the poison in the water will diminish. It may poison me in the process, but I am going to kill one if it's the last thing I do. This place needs a purging. Are you with me, <name>?",objectivesText="Help Nolaki defeat a massive slime.",starts={{mapID=2024,npcID=204592,x=0.175,y=0.314}},ends={{mapID=2024,npcID=204592,x=0.175,y=0.314}},coords={mapID=2024,source="quest_giver",x=0.175,y=0.314},questType="standard"},
[75953] = {id=75953,name="An Exemplar of Compassion: Valunei",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13646,mapID=2024,description="It makes my heart ache to see what the decay has done to some of the wildlife here... I cannot save all the creatures that live around Brackenhide Hollow, but I wish for my trial to at least save some. In a cave to the west, there is a family of bears that has recently been corrupted. I believe I can fight my way there and heal them. Will you help me, <name>?",objectivesText="Protect Valunei from decay gnolls.",starts={{mapID=2024,npcID=204591,x=0.176,y=0.314}},ends={{mapID=2024,npcID=204591,x=0.176,y=0.314}},coords={mapID=2024,source="quest_giver",x=0.176,y=0.314},questType="standard"},
[75966] = {id=75966,name="Compose Yourself",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="I promise he's not always like this. But he is, often, like this. Usually it takes him a few days to come out of his funk, but we don't have that sort of time. The commission he got to write this song won't last forever. Maybe we can speed up the process. Could you help raise Pedgi 's confidence?",objectivesText="Raise Pedgi 's confidence. Progress: Hmm...",starts={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},ends={{mapID=2025,npcID=204987,x=0.538,y=0.8416}},coords={mapID=2025,source="quest_giver",x=0.538,y=0.8416},questType="standard"},
[75970] = {id=75970,name="Tracked Through Time",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="A Timewalker spotted a bear cub who stumbled into our present time. She was so frightened she ran off before he could catch her! Can you find the poor thing? You'll need to calm her down before she'll follow you. Bring her back here and I'll open a temporal portal to take her home.",objectivesText="Rescue a Time-Lost Cub and return her to her proper time. Progress: That cub must be so scared, all alone and in a strange place. We need to get her back home!",starts={{mapID=2025,npcID=205424,x=0.522,y=0.816}},ends={{mapID=2025,npcID=205424,x=0.522,y=0.816}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.816},questType="standard"},
[75971] = {id=75971,name="Squeaky Toy of Time and Space",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="We have detected another time anomaly. A strange object that even we cannot understand the significance of. This artifact must be returned before it does irreparable damage to the true timeline and the world as we know it. Return here once you have recovered the artifact. I will open a portal so you may return it to its proper place.",objectivesText="Find the Time-Displaced Toy and return it to its proper time. Progress: All of our fates depend on returning that artifact to its proper time.",starts={{mapID=2025,npcID=205769,x=0.522,y=0.816}},ends={{mapID=2025,npcID=205769,x=0.522,y=0.816}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.816},questType="standard"},
[75985] = {id=75985,name="Rest Well, Warrior",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="Shalkeel deserves to be seen off properly. I want to dress his burial area and say a few words. I know your time is precious, but would you take the shovel and bury his ashes while I perform the rites?",objectivesText="Assist Khasar with Shalkeel's burial. Progress: If I were able to handle his ashes, I'd have poured them out over the stream he and I played in when we were children.",starts={{mapID=2023,npcID=202788,x=0.87,y=0.272}},ends={{mapID=2023,npcID=202788,x=0.87,y=0.272}},coords={mapID=2023,source="quest_giver",x=0.87,y=0.272},questType="standard"},
[75986] = {id=75986,name="Feats Per Minute",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Alright, one last problem to help solve. Succeed at this and we'll surely have earned an audience with Tempo! The investigators discovered another Time Slime. A much larger, powerful Time Slime. We've come to call it Time Slime Prime . Its temporal energies are greatly accelerated, making it especially deadly. I recommend using the metronographer several times to slow it back down before engaging in combat.",objectivesText="Re-synchronize and defeat the Time Slime Prime .",starts={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},ends={{mapID=2025,npcID=195773,x=0.548,y=0.816}},coords={mapID=2025,source="quest_giver",x=0.538,y=0.8416},questType="standard"},
[75987] = {id=75987,name="Woolomancer",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Somehow, Jaina Proudmoore has found a magic wand. Not our Jaina, of course, but her childhood self. She is far too young to have access to such power. We need you to help clean up the mess she's made and confiscate that wand.",objectivesText="Dispel 8 Polymorphed Creatures and confiscate Jaina's Wand of Mass Polymorph . Progress: Jaina must not practice magic until she is old enough to handle it responsibly. I trust you to put a stop to this before the situation becomes dire.",starts={{mapID=2025,npcID=205769,x=0.522,y=0.816}},ends={{mapID=2025,npcID=205769,x=0.522,y=0.816}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.816},questType="standard"},
[75988] = {id=75988,name="Lucky Hearthstone Card",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="I was playing Hearthstone with my father when I somehow ended up here. Then some dragon whelps flew off with my lucky card to add it to their... card tornado? Then all the adults started saying I need to go home. But I can't leave without my lucky card! Can you please help me? I promise I'll go home if you bring it back for me!",objectivesText="Kill the Enchanted Card Swarm and retrieve Anduin's Lucky Hearthstone Card . Progress: I feel a little better. Bob gave me some juice. But I still don't know what's going on. Where is this place? How did I get here?",starts={{mapID=2025,npcID=205604,x=0.522,y=0.816}},ends={{mapID=2025,npcID=205604,x=0.522,y=0.816}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.816},questType="standard"},
[75989] = {id=75989,name="The Black Prince Parade",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Five separate portals opened up here at the same time, and the same person stepped out of each one. Now we have an inn full of Wrathions. All different ages, dealing with different things in their own lives, and very eager to blame each other for their problems. Let's get them all back to their proper times before they cause too much trouble.",objectivesText="Send each Wrathion back to his time through his temporal portal. Progress: All this commotion is bad for business.",starts={{mapID=2025,npcID=203769,x=0.522,y=0.815}},ends={{mapID=2025,npcID=203769,x=0.522,y=0.815}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.815},questType="standard"},
[75990] = {id=75990,name="Star-Crossed Lovers",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="We found a time disruption long, long ago. Someone helped Illidan charm Tyrande, dooming us all to the Burning Legion! Malfurion is so distraught he can't even sleep. He has no idea how to win her back. We need you to help him out before the timeline is ruined.",objectivesText="Help Malfurion gain Tyrande's affection in Val'sharah. Progress: As painful as it can be, heartbreak can be essential for making us who we are. Even if who are isn't always... nice.",starts={{mapID=2025,npcID=205424,x=0.522,y=0.816}},ends={{mapID=2025,npcID=205424,x=0.522,y=0.816}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.816},questType="standard"},
[75991] = {id=75991,name="What Could Have Been",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="A mysterious stranger showed up here a bit ago through one of those time portals. Said there's a threat nearby they need your help with. Some kind of cloaking device. Though you might not like what you see once it's disabled. In fact, you may not particularly like this stranger, for that matter.",objectivesText="Help an alternate version of yourself defeat a mutual foe. Progress: I know it must be hard to see yourself like this. At least you're on the same side for this one.",starts={{mapID=2025,npcID=203769,x=0.522,y=0.815}},ends={{mapID=2025,npcID=203769,x=0.522,y=0.815}},coords={mapID=2025,source="quest_giver",x=0.522,y=0.815},questType="standard"},
[75998] = {id=75998,name="Crispety Crunchety",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<You've seen this kind of beetle near the stables in Loamm. Maybe the stable master will know more about them?>",objectivesText="Bring the Crunchy Beetle to Vanndual in Loamm. Progress: A cherry beetle!",starts={{x=0.573,y=0.493,mapID=2133}},ends={{mapID=2133,npcID=203294,x=0.576,y=0.578}},coords={mapID=2133,source="quest_giver",x=0.576,y=0.578},questType="standard"},
[76004] = {id=76004,name="Deep Cuts",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<You find a discarded deepflayer claw . You've seen some niffen wield these as weapons.>",objectivesText="Bring 1 Deepflayer Claw to Kilnmaster Crubus in Loamm. Progress: Be careful, those are sharp.",starts={{x=0.576,y=0.564,mapID=2133}},ends={{mapID=2133,npcID=203170,x=0.57,y=0.55}},coords={mapID=2133,source="quest_giver",x=0.57,y=0.55},questType="standard"},
[76014] = {id=76014,name="Living Statue",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,objectivesText="Etched Key West restored Etched Key South restored Etched Key East restored Etched Key North restored Debris A Debris B Debris C Statue activated Heated Titan Key obtained",questType="standard"},
[76015] = {id=76015,name="Heart of Iron",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,objectivesText="Sniff out the Scorched Chest",questType="standard"},
[76016] = {id=76016,name="The Living Drill",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,mapID=2133,questType="standard"},
[76026] = {id=76026,name="Surveying the Tower",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Get a load of those rock formations! Surveying doesn't get much better than this. This tower has been here for ages. The black dragonflight used it for some seriously dark stuff, but that's not why we're here. After the dragons left, a troupe of niffen bandits took shelter in the ruins and robbed the place blind. But they left a bunch of trash everywhere. Imagine what we could learn about the niffen from that trash once we get digging!",objectivesText="Speak with Roska to start the dig, then excavate artifacts from around the tower.",starts={{mapID=2133,npcID=205413,x=0.486,y=0.484}},ends={{mapID=2133,npcID=208055,x=0.476,y=0.485}},coords={mapID=2133,source="quest_giver",x=0.486,y=0.484},questType="standard"},
[76027] = {id=76027,name="Flapping and Screaming",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14022,objectivesText="Treasure Chest unlocked",starts={{x=0.546,y=0.495,mapID=2133}},ends={{x=0.546,y=0.495,mapID=2133}},coords={mapID=2133,x=0.546,y=0.495},questType="standard"},
[76030] = {id=76030,name="Airborne Winding",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Well hello there! Word around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over! Best, Harlowe Marl",objectivesText="Talk to Harlowe Marl in Loamm.",starts={{mapID=2133,npcID=205127,x=0.564,y=0.566}},ends={{mapID=2133,npcID=202468,x=0.564,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.564,y=0.566},questType="standard"},
[76032] = {id=76032,name="Hidden in the Midden",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14022,mapID=2133,description="<This dragon statue is similar to others found in the region but has been covered in paint. Googly eyes, stink lines, whiskers, and all manner of other rude drawings decorate the otherwise-imposing stone. The paint looks old and is flaking in places but is not as old as the statue itself. Roska will want to have a look at this!>",objectivesText="Carefully excavate the defaced dragon statue . Progress: Nothing like volcanic rock, eh <name>? Never know what you'll find!",starts={{mapID=2133,npcID=207931,x=0.475,y=0.485}},ends={{mapID=2133,npcID=208055,x=0.476,y=0.485}},coords={mapID=2133,source="quest_giver",x=0.475,y=0.485},questType="standard"},
[76033] = {id=76033,name="Felwood Flyover - Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.582,y=0.108,mapID=77,npcID=203479}},ends={{x=0.582,y=0.108,mapID=77,npcID=203479}},coords={mapID=77,x=0.582,y=0.108},questType="standard"},
