[76276] = {id=76276,name="A Changed Land",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="The arrival of Amirdrassil brings great change to Azeroth. Its roots are finding a home in the soil beneath even as its branches stretch skyward to taste the air. This is an auspicious moment, but we must not forget our allies from the Isles. Visit with those nearby to ensure they are safe and sound.",objectivesText="Check on nearby Dragon Isles residents. Progress: Amirdrassil has safely arrived, but we must make sure our allies are also safe and sound.",starts={{mapID=2023,npcID=206397,x=0.148,y=0.558}},ends={{mapID=2023,npcID=206397,x=0.148,y=0.558}},coords={mapID=2023,source="quest_giver",x=0.148,y=0.558},questType="standard"},
[76278] = {id=76278,name="Work It",faction="both",expansion=10,zoneID=13647,mapID=2025,description="The Trial of Style gives us the opportunity to look good, <class>. The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",objectivesText="Focus on the photographer and follow their directions. Progress: Focus on me and follow my directions. I'll make sure you look great.",starts={{mapID=2025,npcID=206200,x=0.722,y=0.56}},ends={{mapID=2025,npcID=206200,x=0.722,y=0.56}},coords={mapID=2025,source="quest_giver",x=0.722,y=0.56},questType="standard"},
[76280] = {id=76280,name="New Moon",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="With these offerings and water from the Well of Eternity, we have all that we need. Speak with me when you are ready to begin the ritual.",objectivesText="Speak with Tyrande Whisperwind in the Central Encampment to begin the ritual. Progress: Amirdrassil...",starts={{mapID=2239,npcID=208537,x=0.508,y=0.615}},ends={{mapID=2239,npcID=208537,x=0.508,y=0.615}},coords={mapID=2239,source="quest_giver",x=0.508,y=0.615},questType="standard"},
[76281] = {id=76281,name="Something Worth Celebrating",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="At long last... let us celebrate all that we have overcome, and the hope that burns brightly amongst these gathered kaldorei. Come, join the festivities.",objectivesText="Serve tables at the celebration in Bel'ameth. Progress: Have you thoroughly enjoyed yourself, Champion?",starts={{mapID=2239,npcID=208537,x=0.508,y=0.615}},ends={{mapID=2239,npcID=206849,x=0.542,y=0.578}},coords={mapID=2239,source="quest_giver",x=0.508,y=0.615},questType="standard"},
[76282] = {id=76282,name="A Disquieting Feeling",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="Ah, <name>! You're just the person I was looking for. I'm a little concerned about Khadgar. I don't think it's anything dire, but he doesn't seem to be enjoying himself like everyone else--he just seems... distracted. I don't want to pry, but perhaps you could bring him a drink for me? He may open up to you.",objectivesText="Bring Khadgar a drink in Bel'ameth. Progress: Were you able to cheer up Khadgar, <name>?",starts={{mapID=2239,npcID=209042,x=0.542,y=0.578}},ends={{mapID=2239,npcID=209042,x=0.542,y=0.578}},coords={mapID=2239,source="quest_giver",x=0.542,y=0.578},questType="standard"},
[76283] = {id=76283,name="Andu-falah-dor",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="My mother asked for us all to meet her by the moonwell. It has been long enough. We should not keep her waiting. Speak with me there.",objectivesText="Speak with Merithra in Bel'ameth.",starts={{mapID=2239,npcID=206849,x=0.542,y=0.578}},ends={{mapID=2239,npcID=208763,x=0.508,y=0.616}},coords={mapID=2239,source="quest_giver",x=0.542,y=0.578},questType="standard"},
[76284] = {id=76284,name="Work It",faction="both",expansion=10,zoneID=13646,mapID=2024,description="The Trial of Style gives us the opportunity to look good, <class>. The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",objectivesText="Focus on the photographer and follow their directions. Progress: Focus on me and follow my directions. I'll make sure you look great.",starts={{mapID=2024,npcID=206201,x=0.574,y=0.152}},ends={{mapID=2024,npcID=206201,x=0.574,y=0.152}},coords={mapID=2024,source="quest_giver",x=0.574,y=0.152},questType="standard"},
