[76521] = {id=76521,name="Buzzing Boffins",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="<After running up to you with great speed, this robotic creature does not attack you. It is persistent in its desire to be close to you. It has the word \" Boffins \" etched into its side. Soridormi will want to see this.>",objectivesText="After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?",starts={{x=0.775,y=0.641,mapID=2199,npcID=207509}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2025,source="quest_giver",x=0.51,y=0.57},questType="standard"},
[76523] = {id=76523,name="Fuselight Night Flight",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.671,y=0.367,mapID=15,npcID=207467}},ends={{x=0.671,y=0.367,mapID=15,npcID=207467}},coords={mapID=15,x=0.671,y=0.367},questType="standard"},
