[76529] = {id=76529,name="Krazzworks Klash - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.729,y=0.279,mapID=241,npcID=207485}},ends={{x=0.729,y=0.279,mapID=241,npcID=207485}},coords={mapID=241,x=0.729,y=0.279},questType="standard"},
[76530] = {id=76530,name="Unliving Summons",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=13983,mapID=2070,description="We need you in Tirisfal, <name>. Come quickly. There's a new situation brewing just outside the Ruins of Lordaeron, and it's not looking pretty. I'll get you up to speed when you arrive.",objectivesText="Report to Lilian Voss in the Ruins of Lordaeron.",starts={{mapID=2070,npcID=186091,x=0.638,y=0.682}},ends={{mapID=2070,npcID=186091,x=0.638,y=0.682}},coords={mapID=2070,source="quest_giver",x=0.638,y=0.682},questType="standard"},
[76532] = {id=76532,name="Assault on the Wellspring",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Terro gave his life to protect the Dream. Which means we must see it through. Vyranoth should be able to handle Lethka, we must find Suzska . I hope Lethka did not attack her first. We should start looking near the Wellspring. Meet me there so we can continue our search.",objectivesText="Spy on the Wellspring of Life with Buri . Progress: Come on, let's head to the Wellspring.",starts={{mapID=2200,npcID=210178,x=0.395,y=0.228}},ends={{mapID=2200,npcID=208378,x=0.276,y=0.322}},coords={mapID=2200,source="quest_giver",x=0.395,y=0.228},questType="standard"},
[76533] = {id=76533,name="Dangerous Documentation",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14846,mapID=2025,description="<The flickering of a hologram stands out among the surrounding greenery.> A quick investigation of the item reveals this is some sort of catalog left by a Watcher in its timeway. It details observations of the yaungol, ancestors of the tauren. < Soridormi will want to see this.>",objectivesText="Return to Soridormi in the Tyrhold Reservoir. Provided item:",starts={{x=0.582,y=0.39,mapID=2205,npcID=207525}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2025,source="quest_giver",x=0.51,y=0.57},questType="standard"},
[76536] = {id=76536,name="Redridge Rally",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.408,y=0.25,mapID=49,npcID=207524}},ends={{x=0.408,y=0.25,mapID=49,npcID=207524}},coords={mapID=49,x=0.408,y=0.25},questType="standard"},
[76537] = {id=76537,name="Redridge Rally - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.408,y=0.25,mapID=49,npcID=207524}},ends={{x=0.408,y=0.25,mapID=49,npcID=207524}},coords={mapID=49,x=0.408,y=0.25},questType="standard"},
[76538] = {id=76538,name="Redridge Rally - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.408,y=0.25,mapID=49,npcID=207524}},ends={{x=0.408,y=0.25,mapID=49,npcID=207524}},coords={mapID=49,x=0.408,y=0.25},questType="standard"},
[76544] = {id=76544,name="Wasteland Warriors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="<This book has what appears to be a modified Horde symbol on it. You recognize it as the Blood Horde symbol you have seen from timeway incursions. It is odd it is still here, after the incursion has ended. The book has been soaked in blood, though it has long since dried off. Soridormi might be interested in this.>",objectivesText="After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?",starts={{x=0.712,y=0.702,mapID=2199}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2025,source="quest_giver",x=0.51,y=0.57},questType="standard"},
[76545] = {id=76545,name="Brewfest in Valdrakken",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Have you heard? Brewfest has made its way here! You should speak to Bragdur Battlebrew in the Artisan's Market--he can tell you all about it.",objectivesText="Speak to Bragdur Battlebrew .",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61}},ends={{mapID=2112,npcID=207496,x=0.298,y=0.565}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="standard"},
[76546] = {id=76546,name="Mantid Methodology",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="<This amber sword was left behind as you knocked one of the Mantid back through a time rift. You take a moment to ensure it's safe, then place it in your pack. Perhaps Soridormi would be interested in it.>",objectivesText="After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?",starts={{x=0.635,y=0.654,mapID=2199}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2025,source="quest_giver",x=0.51,y=0.57},questType="standard"},
[76547] = {id=76547,name="All That Glitters...",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14844,mapID=2025,description="<Having recently defeated the Time Anomaly in this timeway, you notice this golden vase glittering. It is extremely worn, be it by time or something else. You can't make out the details of its carvings along the edges. Battered as it is, it still manages to give off a warm light, contrasting the chill here. It looks very out of place. Soridormi may be interested in it.>",objectivesText="Return to Soridormi in the Tyrhold Reservoir. Provided item:",starts={{x=0.401,y=0.397,mapID=2203}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2025,source="quest_giver",x=0.51,y=0.57},questType="standard"},
[76548] = {id=76548,name="A Fishy Gift",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Murglgalgul! Glulmual, rluu glua ffrl wawawamual. Lalala! Mowua ha mwaaay. < Murloc You raises a fish up in both of <his/her:their> hands towards you. It seems very officious. Soridormi may want to see this.>",objectivesText="After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?",starts={{x=0.571,y=0.632,mapID=2199,npcID=207756}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2025,source="quest_giver",x=0.51,y=0.57},questType="standard"},
[76552] = {id=76552,name="In Sync",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="While Pedgi had you out killing slimes, I asked the investigators here how we can actually help. Seems quite a few of them are stuck in time anomalies. Luckily, I've just finished giving the metronographer a few temporal upgrades. It should now help the investigators get back in sync. But we need to test it out first. Looks like there's someone nearby who will do the trick.",objectivesText="Test the upgraded Metronographer. Progress: Oh, I saw that Pedgi had you collect time slime grime for me. I did not ask for it and I do not need it. <Melly sighs a long suffering sigh.> At least he's trying to be helpful.",starts={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},ends={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},coords={mapID=2025,source="quest_giver",x=0.538,y=0.8416},questType="standard"},
[76554] = {id=76554,name="Torch - 01",level=0,requiredLevel=0,faction="none",expansion=10,zoneID=13862,mapID=2112,description="description",objectivesText="log",questType="standard"},
[76557] = {id=76557,name="Without Honor",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,mapID=2151,description="Ok, the goggles should be calibrated. Looks like the confluence point is right here on the ledge. I wonder what happened to him?",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},ends={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},coords={x=0.77,y=0.384,source="quest_giver",zoneID=14433},questType="standard"},
[76564] = {id=76564,name="The Tools of the Dragonkillers",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14022,mapID=2133,description="If you're going to go after a dragon, who better to employ than the Djaradin? Let's see what we can find, <name>.",objectivesText="Locate the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.",starts={{mapID=2133,npcID=207763,x=0.382,y=0.498}},ends={{mapID=2133,npcID=207763,x=0.382,y=0.498}},coords={mapID=2133,source="quest_giver",x=0.382,y=0.498},questType="standard"},
[76566] = {id=76566,name="The Dryad Garden",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="$p, there is a situation I am personally concerned about. A garden cared for by my kin, the dryads, has suffered from growing pains amidst Amirdrassil's growth. An overwrought druid currently tends the garden, but I suspect he will need more assistance than he has requested. Please assist him in his task on my behalf.",objectivesText="Speak with Ethidris Creekward in the Root-Bound Sanctuary.",starts={{mapID=2200,npcID=209318,x=0.508,y=0.62}},ends={{mapID=2200,npcID=207779,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.508,y=0.62},questType="standard"},
[76567] = {id=76567,name="Grousing Garden",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="The sanctuary has been overrun! The roots of the World Tree have grown alongside this garden, but it seems the wildlife have grown uncomfortable with the change. Please help them get out their restless energy. Perhaps tired out, they will relax in this space again.",objectivesText="Tire out 8 wildlife in the Root-Bound Sanctuary. Progress: <Ethidris winces and rubs his shoulder.> You would think being a bear would lend oneself resistance to being knocked around by deer.",starts={{mapID=2200,npcID=207779,x=0.538,y=0.745}},ends={{mapID=2200,npcID=207779,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.538,y=0.745},questType="standard"},
[76568] = {id=76568,name="Pineshrew Panic",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="With the garden in such disarray, the pineshrews here are hoarding seeds. Important seeds. Seeds we've spent a lot of time caring for and teaching. A gentle shake will release the seeds properly. Please hurry before they run off with any more!",objectivesText="Shake out 20 Pineshrew seeds in the Root-Bound Sanctuary. Progress: Ordinarily, pineshrews shake out collected seeds across the Dream to promote variety and growth. It's a beautiful cycle. If you have a few hours, I have a lesson prepared about pineshrew migration habits.",starts={{mapID=2200,npcID=207779,x=0.538,y=0.745}},ends={{mapID=2200,npcID=207779,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.538,y=0.745},questType="standard"},
[76569] = {id=76569,name="Druid-Guardian Conference",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Typically, the druid assigned to a dryad sanctuary would guide a newborn dryad until they were ready to take on a position of their own. Unfortunately, it is difficult to separate a dryad from whoever she imprints on. <Ethidris sighs and rubs his eyes.> Which she has made very clear. Regardless, tell me about yourself. Perhaps you will be just as apt a caretaker as I would have been.",objectivesText="Speak with Ethidris Creekward about raising a dryad in the Root-Bound Sanctuary. Progress: <Ethidris furrows his brow at Dionaessa.> Among so many other things happening right now, there's a new dryad to raise.",starts={{mapID=2200,npcID=207779,x=0.538,y=0.745}},ends={{mapID=2200,npcID=207779,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.538,y=0.745},questType="standard"},
[76570] = {id=76570,name="The Family Business",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="I was charged with imparting knowledge on every dryad seed. Dionaessa will have retained all of my teachings, but she will be unpracticed in implementing them. Since it seems you are practiced at completing tasks, you will show Dionaessa the ropes. A group of lashers have grown strangely restless in the Twisting Wood just outside the garden. Collect some of their hearts so we can discern what has happened.",objectivesText="Collect 6 Lasher Hearts in the Twisting Wood near the Root-Bound Sanctuary. Progress: The druid Creekward told me lashers tend to lie in wait for their prey. I'm glad these are not. Makes the fight more interesting!",starts={{mapID=2200,npcID=207779,x=0.538,y=0.745}},ends={{mapID=2200,npcID=207779,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.538,y=0.745},questType="standard"},
[76571] = {id=76571,name="Growth Experience",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Dionaessa's connection to Cenarius gives her the ability to grow plants, but she needs space to practice. The stirred-up wildlife here will be in your way. The Twisting Wood nearby will have plenty of space with far fewer hooves. <Melyrine smiles. Her eyes shine with intensity.> If she gets poisoned by a podling, don't worry. Dryads are immune to poison. You are not.",objectivesText="Have Dionaessa grow 3 flowers in the Twisting Wood. Progress: Do you smell that? <Dionaessa scrunches up her face.> The druid Creekward did not describe lashers and podlings as smelling so foul. I have been misled!",starts={{mapID=2200,npcID=207781,x=0.538,y=0.745}},ends={{mapID=2200,npcID=207781,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.538,y=0.745},questType="standard"},
[76572] = {id=76572,name="A Poisonous Promotion",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Guardian! These podlings have been poisoning the lashers, and now they have twisted that mandragora! If we do not stop it, it will spread the poison to the garden. This must be what had the wildlife in the garden so disturbed. They were on the verge of invasion! Let us kill it. This is what you have prepared me for--a dire quest!",objectivesText="Defeat the Sickened Growth in the Twisting Wood.",starts={{npcID=210813}},ends={{mapID=2200,npcID=209788,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.538,y=0.745},questType="standard"},
[76576] = {id=76576,name="An Unlikely Proposal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14022,mapID=2133,description="Tuskarr artifacts, underground, deep in Djaradin territory? If we didn't find it ourselves I wouldn't believe it. What do you think they were doing down here? Ok looks like the nexus point is right here in this cave. Let's get to the bottom of this!",objectivesText="Observe the Scene from the past. Progress: I wonder what we'll find?",starts={{mapID=2133,npcID=207763,x=0.382,y=0.498}},ends={{mapID=2133,npcID=207763,x=0.382,y=0.498}},coords={mapID=2133,source="quest_giver",x=0.382,y=0.498},questType="standard"},
[76577] = {id=76577,name="Brewfest in Valdrakken",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=1,mapID=27,description="We've sent some Brewfest shipments off to the Dragon Isles. I've heard they've started some of their own celebrations! Of course ye can't beat the festivities here, but it may be worth paying the dragons a visit!",objectivesText="Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.",starts={{mapID=27,npcID=24710,x=0.506,y=0.491}},ends={{mapID=2112,npcID=207496,x=0.298,y=0.565}},coords={mapID=27,source="quest_giver",x=0.506,y=0.491},questType="standard"},
[76578] = {id=76578,name="Khaz Algar Rally",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,objectivesText="Race through the rings.",questType="standard"},
[76579] = {id=76579,name="Brewfest in Valdrakken",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="Seems the dracthyr have decided to host their own Brewfest festivities this year! Once you've finished celebrating here, you should venture to the Dragon Isles and see what they've put together.",objectivesText="Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.",starts={{mapID=1,npcID=155194,x=0.415,y=0.183}},ends={{mapID=2112,npcID=207496,x=0.298,y=0.565}},coords={mapID=1,source="quest_giver",x=0.415,y=0.183},questType="standard"},
[76591] = {id=76591,name="Bubbling Brews",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews through the city and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it! Take a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.",objectivesText="Collect brew bubbles in Valdrakken. Progress: Have ye filled up the barrel?",starts={{mapID=2112,npcID=207496,x=0.298,y=0.565}},ends={{mapID=2112,npcID=207496,x=0.298,y=0.565}},coords={mapID=2112,source="quest_giver",x=0.298,y=0.565},questType="standard"},
[76592] = {id=76592,name="A Single Wing",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="Amythora has returned with grave news. The Sundered Flame live on! We have been trying to locate and repatriate independent bands of dracthyr here in Valdrakken. I sent Amythora and Marithos to talk to the last of them, but Amythora reports they are a remnant of the Sundered Flame. And they have captured Marithos! Given that he used to be one of them, Marithos could be in grave danger. We must investigate and ensure his safety.",starts={{npcID=207790,x=0.232,y=0.372,mapID=2112}},ends={{npcID=208236,x=0.74,y=0.548,mapID=2024}},coords={x=0.232,y=0.372,source="quest_giver",mapID=2024},questType="standard"},
[76593] = {id=76593,name="The Best Intentions",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="Not only did they beat him--they put him in shackles too! What's worse is... I probably would have done the same... We will not be able to carry Marithos out of here with this weight chained to him. The key must be around the camp somewhere. Try to find it, <name>, while I keep him comfortable.",objectivesText="Look for a key to Marithos's shackles in the Lonely Falls. Progress: We must free Marithos from his bonds.",starts={{mapID=2024,npcID=207819,x=0.748,y=0.55}},ends={{mapID=2024,npcID=207819,x=0.748,y=0.55}},coords={mapID=2024,source="quest_giver",x=0.748,y=0.55},questType="standard"},
[76594] = {id=76594,name="Dracthyr Down",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="What was done to Marithos goes beyond what simple healing can fix. If we expect him to fly out of here, he will need extra care. Thankfully, there are herbs nearby that may give his healing a boost--enough to get him standing, anyway. Look around and collect some of the Wingfoil nearby, <name>.",objectivesText="Look for Wingfoil herbs in the Lonely Falls. Progress: Have you found that Wingfoil ? Marithos cannot fly without it.",starts={{mapID=2024,npcID=207819,x=0.748,y=0.55}},ends={{mapID=2024,npcID=207819,x=0.748,y=0.55}},coords={mapID=2024,source="quest_giver",x=0.748,y=0.55},questType="standard"},
[76595] = {id=76595,name="Urgent Exfiltration",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="The Sundered Flame here are not going to take Quartermaster Doros's death well... They are going to come looking for me. Marithos and Amythora are vulnerable. We cannot let them find us. Secure the perimeter and keep the Sundered Flame away from Amythora and Marithos.",objectivesText="Keep the Sundered Flame away from Amythora and Marithos. Progress: If they find us, I do not think the Sundered Flame loyalists will take prisoners.",starts={{mapID=2024,npcID=207820,x=0.748,y=0.55}},ends={{mapID=2024,npcID=207820,x=0.748,y=0.55}},coords={mapID=2024,source="quest_giver",x=0.748,y=0.55},questType="standard"},
[76597] = {id=76597,name="On New Wings",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="I am glad that Winglord Dezran arrived when he did. If he had not, this would have gone... very differently. We must take Marithos back to Valdrakken so he can recuperate, but once I have debriefed Dezran, we will send an envoy to help re-introduce them to our people. They have suffered. We have suffered. Perhaps now we can all heal. Follow me back to Valdrakken. We have much to discuss.",objectivesText="Talk to Emberthal in Valdrakken.",starts={{mapID=2024,npcID=207820,x=0.748,y=0.55}},ends={{mapID=2112,npcID=207790,x=0.232,y=0.374}},coords={mapID=2024,source="quest_giver",x=0.748,y=0.55},questType="standard"},
[76598] = {id=76598,name="Rough Edges",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="I apologize for not meeting you in person, <name>, but this method seemed most timely. Our war against the Primalists has always troubled our queen, but recently she has grown increasingly upset. Something weighs on her. I know how heavy the burdens of the mind can become. She left Valdrakken some time ago, saying she needed to find a quiet place to think, but... I am concerned. Please--seek her out, and make sure she is all right. She does not need to know I sent you.",objectivesText="Find Alexstrasza and check on her.",starts={{mapID=2025,npcID=208052,x=0.548,y=0.814}},ends={{mapID=2022,npcID=208004,x=0.565,y=0.412}},coords={mapID=2025,source="quest_giver",x=0.548,y=0.814},questType="standard"},
[76600] = {id=76600,name="Right Between the Gyro-Optics",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="My husband Ezgi loves those harvesters, but I don't trust them, and now you can see why! The lights go out, and they all start trying to kill us! You want to help me sort this out? I'm a crack shot with a rifle. You mark the target, and I'll start shooting!",objectivesText="With Auebry's help, eliminate 8 Dark-Crazed Harvesters .",starts={{npcID=206441,x=0.652,y=0.28,zoneID=14838}},ends={{npcID=212398,x=0.652,y=0.28,zoneID=14838}},coords={x=0.652,y=0.28,source="quest_giver",zoneID=14838},questType="standard"},
[76733] = {id=76733,name="Tater Trawl",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Harvesting in this area has become a challenge, with crazed Harvesters destroying most of our crops. There are potatoes to be found if you look closely. If you light the harvest torches, you might uncover some potatoes hiding in the shadows. Using those lights, gather as many potatoes as you can. Every bit helps in these trying times.",objectivesText="Light 5 Harvest Torches and gather 15 Firelight Spuds . Progress: Have you found any spuds?",starts={{npcID=206441,x=0.652,y=0.28,zoneID=14838}},ends={{npcID=206441,x=0.652,y=0.28,zoneID=14838}},coords={x=0.652,y=0.28,source="quest_giver",zoneID=14838},questType="standard"},
[76735] = {id=76735,name="Rise in Relic Theft",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},ends={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},coords={x=0.604,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[76983] = {id=76983,name="Time Rifts",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[76984] = {id=76984,name="Time Rifts",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[76985] = {id=76985,name="Time Rifts",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[76997] = {id=76997,name="Lost in Shadows",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Greetings, . I find myself in a dire situation. Some fresh recruits and I were on patrol in these lands when our torches went out, leaving us utterly lost and disoriented. I found safety in this house, but most of the recruits fled, confused into the darkness. Will you help me locate them? I have a spare Patrol Torch . The mere sight of it should rally them to your side.",objectivesText="Find and rally 3 Demoralized Recruits using the Patrol Torch . Progress: Have you found the recruits?",starts={{npcID=208186,x=0.646,y=0.306,zoneID=14838}},ends={{npcID=208186,x=0.646,y=0.306,zoneID=14838}},coords={x=0.646,y=0.306,source="quest_giver",zoneID=14838},questType="standard"},
[77093] = {id=77093,name="The Shadowflame Axe",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="The moment you attempted to wield Fyrakk's axe, Fyr'alath, its flames consumed you. Clearly the weapon's shadowflame was too intense. Perhaps you should consult an expert on shadowflame and ancient artifacts. Maybe one of the scholars at the Azerothian Archives can deduce a method for handling it safely.",objectivesText="Visit the Azerothian Archives to find an expert on Shadowflame",ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[77098] = {id=77098,name="Getting to Ground",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="He needs to be healed--now. We're too out in the open here. Sundered Flame loyalists could ambush us at any time. Let's find cover somewhere so we can assess his wounds. Cover me!",objectivesText="Get Marithos to safety in the Azure Span .",starts={{mapID=2024,npcID=208236,x=0.74,y=0.548}},ends={{mapID=2024,npcID=207820,x=0.748,y=0.55}},coords={mapID=2024,source="quest_giver",x=0.74,y=0.548},questType="standard"},
[77100] = {id=77100,name="Surveying the Cliffside",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,mapID=2151,description="Nothing like brisk ocean air to get you in the mood to dig! We're standing in the rubble of an ancient dragonkin fishing village. These dragonkin were ancestors of the blue dragonkin that live on the island today. Humble as it is, the remote location means it's gone relatively undisturbed by treasure hunters. If there's anything left that hasn't fallen into the sea, we'll find it!",starts={{npcID=208362,x=0.172,y=0.164,zoneID=14433}},ends={{npcID=208398,x=0.142,y=0.148,zoneID=14433}},coords={x=0.172,y=0.164,source="quest_giver",zoneID=14433},questType="standard"},
[77101] = {id=77101,name="Ingredient Quest Template",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14529,mapID=2200,description="Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research. I had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em! Help me wrangle everyone's ideas into one perfect weapon!",objectivesText="Help Rocket-Chief Fuselage build the perfect weapon.",questType="standard"},
[77102] = {id=77102,name="Hellfire Hustle",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.754,y=0.443,mapID=100,npcID=208246}},ends={{x=0.754,y=0.443,mapID=100,npcID=208246}},coords={mapID=100,x=0.754,y=0.443},questType="standard"},
[77103] = {id=77103,name="Hellfire Hustle - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.754,y=0.443,mapID=100,npcID=208246}},ends={{x=0.754,y=0.443,mapID=100,npcID=208246}},coords={mapID=100,x=0.754,y=0.443},questType="standard"},
[77104] = {id=77104,name="Hellfire Hustle - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.754,y=0.443,mapID=100,npcID=208246}},ends={{x=0.754,y=0.443,mapID=100,npcID=208246}},coords={mapID=100,x=0.754,y=0.443},questType="standard"},
[77151] = {id=77151,name="The Cache in the Crag",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,mapID=2151,starts={{x=0.14,y=0.147,mapID=2151,npcID=208402}},ends={{npcID=208398,x=0.142,y=0.148,zoneID=14433}},coords={mapID=2151,x=0.14,y=0.147},questType="standard"},
[77154] = {id=77154,name="A Taste of the Past",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,mapID=2151,description="Usually, we go to great lengths to avoid busting artifacts open, but I think in this case we'll learn more about the past from what's inside than just staring at a sealed barrel. That said, there's someone we should get permission from first. It's her history, after all. In fact, I think she's the only person still around who might have a personal stake in this find. I'll see to getting this up the cliff. Ask if Atrenosh Hailstone wants to watch us crack 'er open, eh?",starts={{npcID=208398,x=0.142,y=0.148,zoneID=14433}},ends={{npcID=208362,x=0.172,y=0.164,zoneID=14433}},coords={x=0.142,y=0.148,source="quest_giver",zoneID=14433},questType="standard"},
[77163] = {id=77163,name="Seeing Reason",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="They seem to know that Sarkareth is gone, but because their missions were so far from Zaralek Cavern, it looks like they never heard how he met his demise. We should talk to them. Maybe if they knew why so many of their brethren now follow me they would become Ebon Scales again. Or not... <Emberthal sighs.> This could backfire catastrophically, but I feel like we must try. Quartermaster Doros seems to be in command here. Go and speak to him, <name>. I do not think he would listen to me...",objectivesText="Confront Quartermaster Doros in the Lonely Falls. Progress: Find Quartermaster Doros . If you can talk to him, we might be able to avoid a conflict.",starts={{mapID=2024,npcID=207820,x=0.748,y=0.55}},ends={{mapID=2024,npcID=207820,x=0.748,y=0.55}},coords={mapID=2024,source="quest_giver",x=0.748,y=0.55},questType="standard"},
[77165] = {id=77165,name="A Secretive Contact",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=207696,x=0.478,y=0.47,mapID=2112}},ends={{npcID=207696,x=0.478,y=0.47,mapID=2112}},coords={x=0.478,y=0.47,source="quest_giver",mapID=2112},questType="standard"},
[77166] = {id=77166,name="A Practical Test",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Now that you know how to use the device, we will put your skills to the test. I have attuned your Technoscryers to a valuable item hidden somewhere on this island. Provided you can find it, we will use it to view a scene from the past and deduce how it got there. It is time for science! Put... the goggles... on! Resume your scrying!",objectivesText="Use the Technoscryers to find the hidden object. Progress: Have you found that hidden object, <name>?",starts={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},ends={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},coords={mapID=2025,source="quest_giver",x=0.616,y=0.305333},questType="standard"},
[77169] = {id=77169,name="Coilfang Caper",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.37,y=0.372,mapID=102,npcID=208318}},ends={{x=0.37,y=0.372,mapID=102,npcID=208318}},coords={mapID=102,x=0.37,y=0.372},questType="standard"},
[77170] = {id=77170,name="Coilfang Caper - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.37,y=0.372,mapID=102,npcID=208318}},ends={{x=0.37,y=0.372,mapID=102,npcID=208318}},coords={mapID=102,x=0.37,y=0.372},questType="standard"},
[77171] = {id=77171,name="Coilfang Caper - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.37,y=0.372,mapID=102,npcID=208318}},ends={{x=0.37,y=0.372,mapID=102,npcID=208318}},coords={mapID=102,x=0.37,y=0.372},questType="standard"},
[77176] = {id=77176,name="I Can See Through Time!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Okay, the Technoscryers should be calibrated. I have made the same adjustments to my own pair, so we can view the same phenomena. Are you ready? Put... them on... again! This time, we will use the Observation mode.",objectivesText="Observe events from the past. Progress: I wonder what we will find?",starts={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},ends={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},coords={mapID=2025,source="quest_giver",x=0.616,y=0.305333},questType="standard"},
[77178] = {id=77178,name="Tactical Withdrawal",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="We have stopped this attack on the barrier, but Fyrakk will find a way through. $p, we need to return to Alexstrasza and Merithra and tell them his plans for the Wellspring. Return as soon as possible. It is more urgent than ever to stop Fyrakk.",objectivesText="Return to Alexstrasza in the Central Encampment.",starts={{mapID=2200,npcID=210733,x=0.336,y=0.252}},ends={{mapID=2200,npcID=208503,x=0.508,y=0.628}},coords={mapID=2200,source="quest_giver",x=0.336,y=0.252},questType="standard"},
[77191] = {id=77191,name="Handling It",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="If you want to wield Fyr'alath safely, you'll need to modify the weapon's haft with three components. First, you'll need a fireproof hide that can handle intense heat. Next, acquire enchanted vellum that can contain the weapon's volatile magic. Finally, a scribe must apply the proper runes, so you can bind the first two materials to the axe. My journal over there includes a few recommendations of crafters who can help you. You might also know a few!",objectivesText="Obtain a Symbiotic Glowspore Grip , a Rune of Shadowbinding , and a Concentrated Sophic Vellum . Progress: Please collect the necessary materials quickly. I'm excited to begin.",starts={{mapID=2025,npcID=206107,x=0.615,y=0.312}},ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[77192] = {id=77192,name="An Axe Tempered",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Exemplary. Some of the components can be wrapped and attached by hand, but for the last step, you'll need a powerful forge to unify all three in flame. I've been speaking to Wrathion . He can direct you to a suitable forge in the Obsidian Citadel. I'll meet you both there! I can't wait to see what happens as a result of my ingenious plan!",objectivesText="Head to the Obsidian Citadel and ask the smith to forge the handle onto the axe. Progress: We need to attach the modified handle to the axe head. That's more perilous than it sounds...",starts={{mapID=2025,npcID=206107,x=0.615,y=0.312}},ends={{mapID=2022,npcID=208421,x=0.246,y=0.605}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[77193] = {id=77193,name="The Power of Temptation",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="Just to be clear: if the axe defeats you, I will be obligated to step in. But that's not going to happen, is it? You're not going to be corrupted by shadowflame. You won't devolve into a monstrous, murderous shadow of your former self. I'm not going to have to... intervene. As long as we're clear on this, no one is going to have to kill anyone. All right, let's get this done.",objectivesText="Talk to Wrathion to travel to Aberrus, and complete the scenario \"A Hero's Resolve.\" Progress: What an intimidating axe!",starts={{mapID=2022,npcID=208421,x=0.246,y=0.605}},ends={{mapID=947,npcID=208422,x=0,y=0}},coords={mapID=2022,source="quest_giver",x=0.246,y=0.605},questType="standard"},
[77194] = {id=77194,name="Free Knot!",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=2557,objectivesText="Progress: It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it. I think any of the ogres might have it, but I'm not sure if any specific ones do. Maybe the guards have a better chance of having one... What am I talking about - you have it already, don't you?! Is that it there??!",starts={{npcID=14338}},questType="dungeon"},
[77195] = {id=77195,name="A Dragon's Eye View",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2025,description="I believe I know just the location for the Netherwing to roost. It has a wonderful view and is quite secluded. I'd like to show our guest some of the sights of Valdrakken before we go. Meet you there?",objectivesText="Travel to the cave above the Sand-Lost Sanctum in Thaldraszus. Progress: Really, the view from the cave is quite remarkable.",starts={{mapID=2025,npcID=207350,x=0.474,y=0.676}},ends={{mapID=2025,npcID=207350,x=0.474,y=0.676}},coords={mapID=2025,source="quest_giver",x=0.474,y=0.676},questType="standard"},
[77197] = {id=77197,name="A Whelping Hand",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2025,description="Well done, <name>. Now we must ensure the whelps of the netherwing have the best opportunities to grow and flourish. Let us speak to Mother Elion . I know she would relish the opportunity to care for the young of a new flight. Can you meet us at the Ruby Lifeshrine?",objectivesText="Meet Mother Elion at the Ruby Lifeshrine in the Waking Shores.",starts={{mapID=2025,npcID=207350,x=0.474,y=0.676}},ends={{mapID=2022,npcID=185904,x=0.615,y=0.686}},coords={mapID=2025,source="quest_giver",x=0.474,y=0.676},questType="standard"},
[77198] = {id=77198,name="Home in Time for Tea",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2022,description="I must admit, I did not expect to be altering the future of my flight when I arrived. But it feels as though we belong here. Perhaps this is the call they spoke of... Regardless, I am looking forward to some rest. Wrathion mentioned retiring to the Roasted Ram Inn. Can you meet us there?",objectivesText="Meet Wrathion, Mordenaku , and Vyranoth in the Roasted Ram Inn in Valdrakken. Progress: I am looking forward to some rest.",starts={{mapID=2022,npcID=207352,x=0.615,y=0.687}},ends={{mapID=2022,npcID=207352,x=0.615,y=0.687}},coords={mapID=2022,source="quest_giver",x=0.615,y=0.687},questType="standard"},
[77200] = {id=77200,name="Offerings for the Well",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="Amirdrassil has been ushered into this world by the denizens of the Dream. Now we must ensure its roots are bathed in the waters of Elune by creating a new moonwell. So many of my people have brought us to this moment. Each should have a part in this dedication. Go, speak to the kaldorei gathered here, and see if they have offerings for the ceremony.",objectivesText="Gather offerings from night elves in the Central Encampment. Progress: Have you collected all the offerings for the ceremony?",starts={{mapID=2239,npcID=208537,x=0.508,y=0.615}},ends={{mapID=2239,npcID=208537,x=0.508,y=0.615}},coords={mapID=2239,source="quest_giver",x=0.508,y=0.615},questType="standard"},
[77201] = {id=77201,name="A Personal Offering",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=15105,mapID=2239,description="$p. You have done so much for our people. I would have you participate in this ceremony and provide an offering of your own, should you wish it. Let me know what it is that you would like to put forward and it will be done.",objectivesText="Speak with Tyrande Whisperwind in Central Encampment to choose an offering. Progress: Are you certain of your offering?",starts={{mapID=2239,npcID=208537,x=0.508,y=0.615}},ends={{mapID=2239,npcID=208537,x=0.508,y=0.615}},coords={mapID=2239,source="quest_giver",x=0.508,y=0.615},questType="standard"},
[77202] = {id=77202,name="The Preservationists",faction="both",expansion=10,zoneID=13862,mapID=2112,description="Welcome, adventurer. Have you heard the news? There's been a rash of artifact thefts as rumors of treasures and secret locations are being exposed. If you'd like to learn more, seek out Preservationist Kathos . Your skills at deciphering secrets might help reveal who's behind this chaos.",objectivesText="Speak with Preservationist Kathos at the Roasted Ram in Valdrakken .",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61}},ends={{mapID=2025,npcID=206864,x=0.604,y=0.59}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="standard"},
[77203] = {id=77203,name="Preserving Rarities",faction="both",expansion=10,zoneID=13862,mapID=2025,description="Let's unravel a secret! Prepare your mind for puzzles... Speak to me again when you're ready to start down the path of the preservationists.",objectivesText="Speak with Preservationist Kathos to begin a secret, then let her know when it's solved. Progress: That mystery isn't going to solve itself!",starts={{mapID=2025,npcID=206864,x=0.604,y=0.59}},ends={{mapID=2025,npcID=206864,x=0.604,y=0.59}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.59},questType="standard"},
[77205] = {id=77205,name="Blade's Edge Brawl",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.61,y=0.276,mapID=105,npcID=208488}},ends={{x=0.61,y=0.276,mapID=105,npcID=208488}},coords={mapID=105,x=0.61,y=0.276},questType="standard"},
[77206] = {id=77206,name="Blade's Edge Brawl - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.61,y=0.276,mapID=105,npcID=208488}},ends={{x=0.61,y=0.276,mapID=105,npcID=208488}},coords={mapID=105,x=0.61,y=0.276},questType="standard"},
[77207] = {id=77207,name="Blade's Edge Brawl - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.61,y=0.276,mapID=105,npcID=208488}},ends={{x=0.61,y=0.276,mapID=105,npcID=208488}},coords={mapID=105,x=0.61,y=0.276},questType="standard"},
[77208] = {id=77208,name="Barreling Down",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="If it's ale ye be looking for, we've plenty to sample! Or at least we would if the Valdrakken folk would hurry up and bring the rest of the barrels down here. We've shipped our Brewfest brews here so they can celebrate--and wouldn't ye know it, they've already started their own traditions! Rolling barrels through the city? That's no way to treat a good brew! Mind lending a hand to bring those barrels down here? And try not to break 'em!",objectivesText="Deliver barrels to the Artisan's Market in Valdrakken. Progress: Careful with the barrels! Ye shouldn't jostle a good ale.",starts={{mapID=2112,npcID=207496,x=0.298,y=0.565}},ends={{mapID=2112,npcID=207496,x=0.298,y=0.565}},coords={mapID=2112,source="quest_giver",x=0.298,y=0.565},questType="standard"},
[77231] = {id=77231,name="Technoscrying 101",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Through a near-perfect blend of technology and arcane enchantment, I have developed a way to analyze the psychometric properties of objects. Wearing these goggles, you can see the data as dynamic simulacra! Simple, yes? I call it... the Psychometric Visuo-Auditory Discrete Waveform Analysis and Viewing Device! For the layperson, we're calling them \" Technoscryers .\" Trademark and patent pending. Here, try them on!",objectivesText="Learn to use the Technoscryers . Progress: I have given you the Technoscryers . Please! Put them on!",starts={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},ends={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},coords={mapID=2025,source="quest_giver",x=0.616,y=0.305333},questType="standard"},
[77236] = {id=77236,name="When Time Needs Mending",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="We need to close rifts. We need to fix timeways. Honestly, we need all the help we can get. There's always more work to do. Are you ready for the next challenge?",objectivesText="Close a Time Rift by defeating a Fractured Causality. Progress: Come now, these rifts aren't going to close themselves.",starts={{mapID=2025,npcID=204450,x=0.51,y=0.57}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2025,source="quest_giver",x=0.51,y=0.57},questType="standard"},
[77237] = {id=77237,name="Unfinished Thinking Cap",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="<Take the Unfinished Thinking Cap to Fangli Hoot near the Barber Shop in Valdrakken .>",objectivesText="Take the Unfinished Thinking Cap to Fangli Hoot in Valdrakken . Progress: <Fangli looks at you, but doesn't speak.>",starts={{x=0.266,y=0.539,mapID=2112}},ends={{mapID=2112,npcID=207697,x=0.2656,y=0.5432}},coords={mapID=2112,source="quest_giver",x=0.2656,y=0.5432},questType="standard"},
[77238] = {id=77238,name="Telaar Tear",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.583,y=0.758,mapID=107,npcID=208540}},ends={{x=0.583,y=0.758,mapID=107,npcID=208540}},coords={mapID=107,x=0.583,y=0.758},questType="standard"},
