[77262] = {id=77262,name="Razorthorn Rise Rush - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.599,y=0.049,mapID=108,npcID=208576}},ends={{x=0.599,y=0.049,mapID=108,npcID=208576}},coords={mapID=108,x=0.599,y=0.049},questType="standard"},
[77263] = {id=77263,name="The Torch of Pyrreth",faction="both",expansion=10,zoneID=13862,mapID=2025,description="Let's begin with a simple test. I have hidden an artifact somewhere in the Ruby Enclave. If you have the torch out, it should illuminate when you get close to the target. And if my theory is correct, it should interact with a lock I put on the artifact. Bring me back what's inside. Got it?",objectivesText="Use the Torch of Opening to unlock Kathos' artifact, hidden somewhere in The Ruby Enclave. Progress: Return when you have retrieved what I ask.",starts={{mapID=2025,npcID=206864,x=0.604,y=0.59}},ends={{mapID=2025,npcID=206864,x=0.604,y=0.59}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.59},questType="standard"},
[77264] = {id=77264,name="Auchindoun Coaster",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.422,y=0.679,mapID=108,npcID=208596}},ends={{x=0.422,y=0.679,mapID=108,npcID=208596}},coords={mapID=108,x=0.422,y=0.679},questType="standard"},
[77265] = {id=77265,name="Auchindoun Coaster - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.422,y=0.679,mapID=108,npcID=208596}},ends={{x=0.422,y=0.679,mapID=108,npcID=208596}},coords={mapID=108,x=0.422,y=0.679},questType="standard"},
[77266] = {id=77266,name="Auchindoun Coaster - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.422,y=0.679,mapID=108,npcID=208596}},ends={{x=0.422,y=0.679,mapID=108,npcID=208596}},coords={mapID=108,x=0.422,y=0.679},questType="standard"},
[77267] = {id=77267,name="Excavation 101",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="So, you want to learn how to excavate artifacts? You came to the right orc! Turns out being able to shape the earth is useful when you're trying to get stuff out of the ground. And given how much the elements affect our work, it helps having an elemental to lend a hand. But you don't have to be a shaman to master excavation. I've got the elements covered. I'll just walk you through the detail work.",objectivesText="Meet with Roska outside to learn about excavation. Progress: What do you think? Having fun yet?",starts={{mapID=2025,npcID=208614,x=0.615,y=0.306}},ends={{mapID=2025,npcID=208614,x=0.615,y=0.306}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.306},questType="standard"},
[77268] = {id=77268,name="Hands-On Experience",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Great job on that small find! Now, are you ready for something big? More often than not, shaking up the small stuff will shake up something even BIGGER just below the surface. Another little rumble, and we'll have a major find on our hands, I can feel it. A major find works almost the same as the smaller ones with a couple extra steps. Why don't you tackle this one too? It'll be good practice for ya. Don't worry! I can guide you through it.",objectivesText="Unearth the major find, then speak to Roska to begin excavating it. Progress: Rare to find big stuff like that up here! Zenata might be up to her tricks again.",starts={{mapID=2025,npcID=208614,x=0.615,y=0.306}},ends={{mapID=2025,npcID=208614,x=0.615,y=0.306}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.306},questType="standard"},
[77276] = {id=77276,name="An Inside Job?",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Fangli Hoot says they have a theory on who might be stealing the artifacts. Seek her out again near the Barber Shop.",objectivesText="Speak with Fangli Hoot near the Valdrakken Barber Shop.",starts={{mapID=2112,npcID=207696,x=0.476,y=0.470667}},ends={{mapID=2112,npcID=207697,x=0.2656,y=0.5432}},coords={mapID=2112,source="quest_giver",x=0.476,y=0.470667},questType="standard"},
[77277] = {id=77277,name="Preservationist Cleared",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Ya better return the item before the Preservationist notices it's missing. Then let Fangli know that her theory didn't pan out.",objectivesText="Return the Burial Banner to the Preservationist's Locker in the Roasted Ram. Progress: What did you discover?",starts={{mapID=2112,npcID=208620,x=0.624667,y=0.733333}},ends={{mapID=2112,npcID=207697,x=0.2656,y=0.5432}},coords={mapID=2112,source="quest_giver",x=0.624667,y=0.733333},questType="standard"},
[77278] = {id=77278,name="Tempest Keep Sweep",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.689,y=0.477,mapID=109,npcID=208625}},ends={{x=0.689,y=0.477,mapID=109,npcID=208625}},coords={mapID=109,x=0.689,y=0.477},questType="standard"},
