[77281] = {id=77281,name="Securing an Artifact",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=185562,x=0.474,y=0.466,mapID=2112}},ends={{npcID=185562,x=0.474,y=0.466,mapID=2112}},coords={x=0.474,y=0.466,source="quest_giver",mapID=2112},questType="standard"},
[77282] = {id=77282,name="Artifact Secured",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="<Returning the torch to Preservationist Kathos might give insight into how it was used.>",objectivesText="Return the Torch of Pyrreth to Preservationist Kathos in Valdrakken . Progress: Welcome back adventurer, have you found something?",starts={{x=0.546,y=0.204,mapID=2022}},ends={{mapID=2025,npcID=206864,x=0.604,y=0.59}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.59},questType="standard"},
[77283] = {id=77283,name="A Multi-Front Battle",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="The kaldorei have set up a temporary base beneath the boughs of Amirdrassil. With hope and hard work, this encampment will become permanent when the tree enters our world. Feel free to acquaint yourself with the provisions available. Then return to me.",objectivesText="Meet Saelienne in the Central Encampment. Progress: Have you found what you needed here in camp?",starts={{mapID=2200,npcID=206896,x=0.508,y=0.628}},ends={{mapID=2200,npcID=206896,x=0.508,y=0.628}},coords={mapID=2200,source="quest_giver",x=0.508,y=0.628},questType="standard"},
[77284] = {id=77284,name="A Chilling Ascent",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=207696,x=0.478,y=0.47,mapID=2112}},ends={{npcID=207696,x=0.478,y=0.47,mapID=2112}},coords={x=0.478,y=0.47,source="quest_giver",mapID=2112},questType="standard"},
[77286] = {id=77286,name="A Knowledgeable Descent",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="<The rubbing is in an ancient language. Perhaps Bobby Carlisle can get the text translated.>",objectivesText="Take the Unveiled Tablet Rubbing to Bobby Carlisle in Valdrakken . Progress: Did you find anything?",starts={{x=0.789,y=0.324,mapID=2024,objectID=405523}},ends={{mapID=2112,npcID=207696,x=0.476,y=0.470667}},coords={mapID=2112,source="quest_giver",x=0.476,y=0.470667},questType="standard"},
[77303] = {id=77303,name="Idol Searching",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=185562,x=0.474,y=0.466,mapID=2112}},ends={{npcID=185562,x=0.474,y=0.466,mapID=2112}},coords={x=0.474,y=0.466,source="quest_giver",mapID=2112},questType="standard"},
[77304] = {id=77304,name="An Idol in Hand",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples. Preservationist Kathos would surely be interested in this.>",objectivesText="Return the Idol of Ohn'ahra to Preservationist Kathos in Valdrakken . Progress: What have you found?",ends={{mapID=2025,npcID=206864,x=0.604,y=0.59}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.59},questType="standard"},
[77305] = {id=77305,name="Out of the Sands",faction="both",expansion=10,zoneID=13647,mapID=2025,description="<The Time-Lost fragments are now joined to form a stone tablet, but many of its inscriptions are worn and incomplete. Preservationist Kathos will want to see this.>",objectivesText="Return the Incomplete Tablet to Preservationist Kathos . Progress: XENO! How was your luck in the Shifting Sands? Did you find the tablet fragments?",ends={{mapID=2025,npcID=206864,x=0.604,y=0.59}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.59},questType="standard"},
[77310] = {id=77310,name="Memory of the Dreamer",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="In the Dream, memories can live on in unusual ways. Memories are not always linear. And memories that are not of your own can become yours. Perhaps you were drawn to this place by the presence of the once-Dreamer. Or perhaps you were drawn to this place because of my great friend. Come, won't you see? Rest here and let the magic of the Dream wash over you.",objectivesText="Rest at the Eye of Ysera.",starts={{mapID=2200,npcID=210022,x=0.586,y=0.238}},ends={{mapID=2200,npcID=208713,x=0.586,y=0.24}},coords={mapID=2200,source="quest_giver",x=0.586,y=0.238},questType="standard"},
[77311] = {id=77311,name="Healing Helper",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Gracus sent word for Ysera to come and see him. We arrived and found him in a dire condition. Our efforts to heal him so far have proved fruitless. But now that you are here, you can assist. Gracus is of the Dream. Perhaps infusing his roots with something grown here will be the final thing we need to restore him.",objectivesText="Use the Root Restoration Fruit to help heal Gracus. Progress: Gracus' condition is dire. We must do what we can to try to help.",starts={{mapID=2200,npcID=208713,x=0.586,y=0.24}},ends={{mapID=2200,npcID=208713,x=0.586,y=0.24}},coords={mapID=2200,source="quest_giver",x=0.586,y=0.24},questType="standard"},
[77312] = {id=77312,name="Nature Persists",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Admittedly, I do not know what to do next. If he is to rest here... flowers would be lovely. The podlings in this area have been hiding among the flowers. Retrieve seeds from them, Champion, and I will make them bloom. I think Gracus will like the flowers.",objectivesText="Collect 6 Sprouted Seedlings from Sneaky Podlings. Progress: There must be something more that we... No. Ysera seems certain.",starts={{mapID=2200,npcID=208713,x=0.586,y=0.24}},ends={{mapID=2200,npcID=208713,x=0.586,y=0.24}},coords={mapID=2200,source="quest_giver",x=0.586,y=0.24},questType="standard"},
[77313] = {id=77313,name="A Solemn Summons",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="It is as I feared. It is Gracus' time. Healing him would never have worked. The world beyond already calls to him. Although he has such peace, those that care for him will still grieve. He will still be dearly missed. Not everyone is granted a chance to say goodbye. We must ensure that in this case, they are.",objectivesText="Inform Gracus' loved ones. Progress: I am grateful we can give them this opportunity to say goodbye.",starts={{mapID=2200,npcID=208714,x=0.586,y=0.238}},ends={{mapID=2200,npcID=208714,x=0.586,y=0.238}},coords={mapID=2200,source="quest_giver",x=0.586,y=0.238},questType="standard"},
[77314] = {id=77314,name="Requiem in a Dream",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="As one life ends so too will a life begin. We must remind those that love Gracus of this, <name>. Plant seeds around Gracus. My sister can handle the rest. This place will not only represent an end but also a beginning of new life.",objectivesText="Plant 6 flowers around Gracus. Progress: These flowers will bloom around Gracus and serve as a reminder of all he helped to grow during his life.",starts={{mapID=2200,npcID=208714,x=0.586,y=0.238}},ends={{mapID=2200,npcID=208714,x=0.586,y=0.238}},coords={mapID=2200,source="quest_giver",x=0.586,y=0.238},questType="standard"},
[77315] = {id=77315,name="Ancient Memories",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Those dark memories cannot be allowed to fester in the Dream. Unleashing them was necessary. Gracus needed to let go. But if they linger, they may become malevolent. Defeat the memory that haunts him most so that Gracus can slumber at last.",objectivesText="Kill the Lingering Torment .",starts={{mapID=2200,npcID=208714,x=0.586,y=0.238}},ends={{mapID=2200,npcID=208714,x=0.586,y=0.238}},coords={mapID=2200,source="quest_giver",x=0.586,y=0.238},questType="standard"},
[77316] = {id=77316,name="Trouble at the Tree",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="<name>! Merithra needs your help. Some nasty trickster spriggans followed us into the Dream and now they're causing all sorts of havoc! Like the most important thing of all, stealing top secret super important supplies. It's urgent you stop them and get the supplies back.",objectivesText="Retrieve 6 Very Important Tree Supplies from Spriggans. Progress: If we don't get those supplies back from those pesky spriggans, we'll be so behind schedule!",starts={{mapID=2200,npcID=208669,x=0.498,y=0.625}},ends={{mapID=2200,npcID=208669,x=0.498,y=0.625}},coords={mapID=2200,source="quest_giver",x=0.498,y=0.625},questType="standard"},
[77317] = {id=77317,name="Hatted Hibernation",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="I'll let you in on a secret, these crates? They're prank supplies! People are so serious around here. What's better than a little prank to lift everyone's spirits? You could put some of these fun hats on some of the sleeping druids because what's more fun than a surprise hat? Be careful though, their connection to the dream could make anything happen!",objectivesText="Put 6 silly hats on Dreaming Druids . Progress: Napping in the Dream... I wonder what they're dreaming about!",starts={{mapID=2200,npcID=208669,x=0.498,y=0.625}},ends={{mapID=2200,npcID=208669,x=0.498,y=0.625}},coords={mapID=2200,source="quest_giver",x=0.498,y=0.625},questType="standard"},
[77318] = {id=77318,name="Merithra Says",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Some druids are volunteering to help tend to the tree and set up camp. But they're so sad! < Lady Moonberry grows a mischievous grin.> We have to give them a reason to smile. You can give them some orders that remind them to have fun. But there's no way they'll take orders from you. That's why I got this costume for you. With this and a little spell they'll for sure listen to you!",objectivesText="Give instructions to 5 druids while disguised as Merithra. Progress: You're clearly a master prankster but you'll have to be a master actor as well. A costume and a spell can only do so much.",starts={{mapID=2200,npcID=208669,x=0.498,y=0.625}},ends={{mapID=2200,npcID=208669,x=0.498,y=0.625}},coords={mapID=2200,source="quest_giver",x=0.498,y=0.625},questType="standard"},
[77322] = {id=77322,name="Shattrath City Sashay",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.716,y=0.701,mapID=111,npcID=208673}},ends={{x=0.716,y=0.701,mapID=111,npcID=208673}},coords={mapID=111,x=0.716,y=0.701},questType="standard"},
[77323] = {id=77323,name="Shattrath City Sashay - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.716,y=0.701,mapID=111,npcID=208673}},ends={{x=0.716,y=0.701,mapID=111,npcID=208673}},coords={mapID=111,x=0.716,y=0.701},questType="standard"},
[77324] = {id=77324,name="Shattrath City Sashay - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.716,y=0.701,mapID=111,npcID=208673}},ends={{x=0.716,y=0.701,mapID=111,npcID=208673}},coords={mapID=111,x=0.716,y=0.701},questType="standard"},
[77325] = {id=77325,name="To the Archives!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Are you a scholar, historian, or a high-minded intellectual? Do you enjoy heavy, mindless labor in exchange for gold? Then take hold of your future, and join the newly budding ranks of the Azerothian Archives!* <Your eyes move to the fine print near the parchment's edge.> *Temporary offices are located at the Algeth'ar Academy in northern Thaldraszus.",objectivesText="Speak with Lead Archivist Eadweard Dalyngrigge at Algeth'ar Academy.",starts={{x=0.466,y=0.475,mapID=2112,objectID=405593}},ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[77327] = {id=77327,name="Nirobin and the Office",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13644,mapID=2023,description="Perhaps there is more to investigate, but I need time to go over our findings here first. Our colleague, Nirobin , the one arcane projecting himself into the headquarters, should be ready for your assistance by now. He's got his own office at the Academy in Thaldraszus that he tends to squirrel himself away in. I'm positive he'll be there... Mostly because he never leaves it.",objectivesText="Speak with Nirobin at his office in Thaldraszus.",starts={{mapID=2023,npcID=204643,x=0.664,y=0.46},{mapID=2022,npcID=204835,x=0.564,y=0.44}},ends={{mapID=2025,npcID=205967,x=0.585,y=0.368}},coords={mapID=2023,source="quest_giver",x=0.664,y=0.46},questType="standard"},
[77328] = {id=77328,name="Back to Headquarters!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Eadweard called for your return to the main office after I'd finished with you... er, this experiment, I mean. I'm sure it has to do with pomp, circumstance, reward, and what have you. If any of that entices you, then best hurry before his bag of goodies runs dry to all the other recent recruits.",objectivesText="Meet with Eadweard Dalyngrigge at Algeth'ar Academy in Thaldraszus.",starts={{mapID=2025,npcID=205967,x=0.585,y=0.368}},ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.585,y=0.368},questType="standard"},
[77329] = {id=77329,name="Auspicious Gathering",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13645,mapID=2023,description="As you know, Amirdrassil is no ordinary tree. Tyrande Whisperwind and the rest of the kaldorei have been preparing to properly welcome it with a ceremony of their own, and establish a new moonwell. I am certain that Tyrande would want you there for the dedication. Let us join them at the Central Encampment.",objectivesText="Speak with Tyrande Whisperwind in the Central Encampment.",starts={{mapID=2023,npcID=206397,x=0.148,y=0.558}},ends={{mapID=2239,npcID=208537,x=0.508,y=0.615}},coords={mapID=2023,source="quest_giver",x=0.148,y=0.558},questType="standard"},
[77331] = {id=77331,name="Graduation Day",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="You've turned out to be quite a fine member of our high-skilled crew of rag tags and diggers of dirt. Between the sites you've broken ground on with Roska, Zenata, and Nirobin, as well as the larger one in Traitor's Rest, the varied histories collected by these Dragon Isles have never been more ripe for the harvest. There will always be work and companionship here when you desire it. We hope you'll join us on other continents as well. ...When we receive appropriate funding, that is.",objectivesText="Receive congratulations from your Azerothian Archivist peers. Progress: Worry not. I've already written to our benefactors of your efforts.",starts={{mapID=2025,npcID=206107,x=0.615,y=0.312}},ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[77339] = {id=77339,name="Data Recovery",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="After a lot of rigorous training, the time has come! Travard believes the Tyr's Guard is ready to recover the disc of Tyr from the Nighthold. Meet us at Tyr's Rest, the new Tyr's Guard headquarters. It's just south of Tyrhold. We will finally make Tyr whole again!",objectivesText="Meet Travard at the Tyr's Guard headquarters.",starts={{mapID=2025,npcID=208703,x=0.608,y=0.636}},ends={{mapID=2025,npcID=208701,x=0.605,y=0.636}},coords={mapID=2025,source="quest_giver",x=0.608,y=0.636},questType="standard"},
[77340] = {id=77340,name="Infiltrating the Nighthold",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="The information from our beacons suggests that Elisande has locked the disc away in Astromancer's Rise. It is a place of learning, and the inside will have minimal protection. I have opened a portal where you and the Tyr's Guard will have the least resistance... except for Elisande and whatever guards are under her employ. All of you are on your own once you get there, so try not to muck it up.",objectivesText="Retrieve the Disc of Tyr from Elisande in the Nighthold. Progress: I wonder what Tyr is like? I bet he's super nice!",starts={{mapID=2025,npcID=208832,x=0.604,y=0.59}},ends={{mapID=2025,npcID=208835,x=0.604,y=0.588}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.59},questType="standard"},
[77341] = {id=77341,name="Logotyrapy",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Dear $p, It seems wrong to say this of someone as mighty as Tyr, but I am worried about him. When he arrived at Tyr's Rest, he spent many days talking with us. We all asked him many questions, learning about the titans, ancient history, and his philosophy. But recently, Tyr has been speaking less, and the answers he does give are shorter and some have an edge to them. I'm not sure what's wrong, but something is different. Will you come speak with him? For Tyr, Valunei",objectivesText="Speak with Tyr at Tyr's Rest. Progress: Tyr seems restless. Perhaps you could talk to him, <name>?",ends={{mapID=2025,npcID=208839,x=0.608,y=0.638}},coords={mapID=2025,source="quest_giver",x=0.608,y=0.638},questType="standard"},
[77342] = {id=77342,name="Disc Delivery",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="You have recovered the disc? Good. At last, we can awake Tyr. The disc must be placed in the console so it can attune to the Silver Scale and pass on to Tyr. I believe you should do the honors, $p.",objectivesText="Insert the Disc of Tyr into the titan console. Progress: Did you place the disc in the titan console?",starts={{mapID=2025,npcID=208834,x=0.604,y=0.588}},ends={{mapID=2025,npcID=208834,x=0.604,y=0.588}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.588},questType="standard"},
[77343] = {id=77343,name="A Tyrful Reunion",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="This is incredible, seeing our friend back after so many thousands of years. So much has happened since we last spoke. The world has changed. Our loss of Tyr was before even the Sundering. But there will be time to discuss all those things later. For now, it's simply good to be with our friend. Stay with us, will you, $p, while we reconnect?",objectivesText="Listen to the Aspects' conversation with Tyr. Progress: One moment, <name>--I want to hear what Tyr and the aspects are saying!",starts={{mapID=2025,npcID=208833,x=0.604,y=0.586}},ends={{mapID=2025,npcID=208800,x=0.604,y=0.588}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.586},questType="standard"},
[77344] = {id=77344,name="Time to Process",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Tyr is back after thousands of years. I don't even know how many thousands. His world has changed more than we can even imagine. He's going to have many questions and need answers. Meanwhile, there's nothing any of the Tyr's Guard would rather do than talk with Tyr. Tyr's Rest seems like the perfect place to give him time, answer questions, and process those answers. Would you ask him to join us there?",objectivesText="Invite Tyr to join the Tyr's Guard at Tyr's Rest. Progress: We certainly live in interesting times, <name>...",starts={{mapID=2025,npcID=208800,x=0.604,y=0.588}},ends={{mapID=2025,npcID=208839,x=0.608,y=0.638}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.588},questType="standard"},
[77345] = {id=77345,name="The Need For Higher Velocities",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="Sometimes you'll need to travel longer distances. If you don't need to travel up and over any obstacles using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky. Follow the rings again to your destination and use Surge Forward when prompted to maintain your speed. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.",objectivesText="Fly through the rings and land in the target area. Progress: Well done, <name>.",starts={{mapID=2022,npcID=193287,x=0.576,y=0.668}},ends={{mapID=2022,npcID=183141,x=0.575,y=0.63}},coords={mapID=2022,source="quest_giver",x=0.576,y=0.668},questType="standard"},
[77346] = {id=77346,name="Shadowmoon Slam",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.618,y=0.482,mapID=104,npcID=208748}},ends={{x=0.618,y=0.482,mapID=104,npcID=208748}},coords={mapID=104,x=0.618,y=0.482},questType="standard"},
[77347] = {id=77347,name="Shadowmoon Slam - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.618,y=0.482,mapID=104,npcID=208748}},ends={{x=0.618,y=0.482,mapID=104,npcID=208748}},coords={mapID=104,x=0.618,y=0.482},questType="standard"},
[77348] = {id=77348,name="Shadowmoon Slam - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.618,y=0.482,mapID=104,npcID=208748}},ends={{x=0.618,y=0.482,mapID=104,npcID=208748}},coords={mapID=104,x=0.618,y=0.482},questType="standard"},
[77377] = {id=77377,name="To Tyrhold! For Tyr!",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="We recovered. We trained. And now it's time to face Elisande. Come with us to Tyrhold where Nozdormu, Chromie, and Eternus are waiting to send us to the Nighthold. We will get that disc, and Tyr will finally be with us once more.",objectivesText="Speak with Eternus in Tyrhold.",starts={{mapID=2025,npcID=208701,x=0.605,y=0.636}},ends={{mapID=2025,npcID=208832,x=0.604,y=0.59}},coords={mapID=2025,source="quest_giver",x=0.605,y=0.636},questType="standard"},
[77398] = {id=77398,name="Eco-Dome Excursion",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.509,y=0.417,mapID=109,npcID=208803}},ends={{x=0.509,y=0.417,mapID=109,npcID=208803}},coords={mapID=109,x=0.509,y=0.417},questType="standard"},
[77399] = {id=77399,name="Eco-Dome Excursion - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.509,y=0.417,mapID=109,npcID=208803}},ends={{x=0.509,y=0.417,mapID=109,npcID=208803}},coords={mapID=109,x=0.509,y=0.417},questType="standard"},
[77400] = {id=77400,name="Eco-Dome Excursion - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.509,y=0.417,mapID=109,npcID=208803}},ends={{x=0.509,y=0.417,mapID=109,npcID=208803}},coords={mapID=109,x=0.509,y=0.417},questType="standard"},
[77408] = {id=77408,name="Prophecy Stirs",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=1637,mapID=84,description="Prophet Velen has roused from meditation and he requests your immediate presence. A matter of great import has come to his attention. He would value both your wisdom and strength in addressing it. The Prophet awaits you aboard the Vindicaar . Take this crystal. Our artificers have attuned it to the ship's teleportation matrix.",objectivesText="Use the Teleportation Crystal to meet Prophet Velen aboard the Vindicaar . Progress: I am thankful that you could make this journey.",starts={{mapID=84,npcID=209790,x=0.6545,y=0.265},{mapID=85,npcID=209803,x=0.718,y=0.445}},ends={{mapID=84,npcID=209790,x=0.6545,y=0.265}},coords={mapID=84,source="quest_giver",x=0.6545,y=0.265},questType="standard"},
[77409] = {id=77409,name="Uncertainty",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=9359,mapID=830,description="Scattered visions came to me as I meditated. Yellow and red. Shattering glass. A rush of warmth. I see my own hand, but I am afraid to grasp it. The scent of fel--of Argus. When I awoke, a message had been delivered. Hatuun wishes to meet. After the defeat of the Legion, I offered to help Hatuun and his people rejoin us. However, they chose to remain on Argus. Hatuun has seldom reached out to us since then. Perhaps he has reconsidered. I will make the journey to Krokuun . Please, join me.",objectivesText="Speak to Chieftain Hatuun in Krokuun . Progress: I did not expect Velen to come. He has surprised me.",starts={{x=0.442,y=0.264,mapID=940,npcID=208815}},ends={{mapID=830,npcID=208830,x=0.538,y=0.682}},coords={mapID=830,source="quest_giver",x=0.538,y=0.682},questType="standard"},
[77410] = {id=77410,name="Opening Wounds",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=8574,mapID=830,description="My hunters were the ones who found Arzal'kal. They said he helped them fight off several Legion ambushes. During our endless vigil on Argus, we had seen nothing like it. He was not as powerful as some demons, but he was persistent. He said he wished to speak with Velen and knew that we had been in contact with him. So, I have fulfilled his request. If Velen is all he claims to be, then he would not turn away even the least worthy of his people. We will see. I expect little.",objectivesText="Speak to Arzal'kal and listen to what he has to say. Progress: If Hatuun called me here to listen, then I will. I owe Hatuun that respect.",starts={{mapID=830,npcID=208830,x=0.538,y=0.682}},ends={{mapID=830,npcID=208837,x=0.535,y=0.682}},coords={mapID=830,source="quest_giver",x=0.538,y=0.682},questType="standard"},
[77411] = {id=77411,name="Contrition",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=8574,mapID=830,description="The man'ari have grown desperate since the Legion fell. Some grasp for power. Some isolate themselves. Others have formed cults awaiting the return of Sargeras. They have faith that he will lead them again one day. Nalridun is the leader of one such cult. They are reclusive, but it is rumored that he has seized an ancient relic that Kil'jaeden kept until his death. Nalridun claims to use it to commune with Sargeras. I believe I know what this relic is. If I am correct, it must be returned to Velen.",objectivesText="Meet Arzal'kal in the Grove of Naroua, then slay Speaker Nalridun and retrieve the ancient draenic relic. Progress: Even if I die here, at least it will not be at the Legion's whim.",starts={{mapID=830,npcID=208831,x=0.536,y=0.682}},ends={{mapID=830,npcID=208831,x=0.536,y=0.682}},coords={mapID=830,source="quest_giver",x=0.536,y=0.682},questType="standard"},
[77412] = {id=77412,name="Proof and Promise",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=8574,mapID=830,description="Reinforcements are unlikely, but the relic is too important to risk. You should return to Prophet Velen with it immediately. There is a teleporter just ahead that I can attune to a sigil of my own. It will provide you swift passage. I will rejoin you later.",objectivesText="Deliver the Brilliant Star to Prophet Velen in Krokuun . Progress: I sense something of great power in your possession. It feels... familiar. But placing the memory feels like grasping at sunlight. Did Arzal'kal lead you to something?",starts={{x=0.73,y=0.323,mapID=830,npcID=208836}},ends={{mapID=830,npcID=208893,x=0.535,y=0.684}},coords={mapID=830,source="quest_giver",x=0.535,y=0.684},questType="standard"},
[77414] = {id=77414,name="Dreamsurge Investigation",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2022,description="The Emerald Dream bleeding over into Azeroth is unprecedented, <name>. We need to understand exactly what is being affected by this phenomenon if we're to prepare ourselves for what is to come. Perhaps we can even turn this to our advantage. Head out into the affected area and see what you can learn. Bring back anything of interest and we will see what can be done.",objectivesText="Complete activities in the Dreamsurge. Progress: How fares the Dreamsurge?",starts={{mapID=2022,npcID=208649,x=0.584,y=0.678}},ends={{mapID=2022,npcID=208649,x=0.584,y=0.678}},coords={mapID=2022,source="quest_giver",x=0.584,y=0.678},questType="standard"},
[77415] = {id=77415,name="The Hidden Hand",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,mapID=2151,description="Catching him at the very moment he's alone? They must've been watching somewhere nearby but just out of sight. Can you check that cave across the water? Those hornswogs are known hoarders. If those drakonid left something behind, it may still be there.",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},ends={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},coords={x=0.77,y=0.384,source="quest_giver",zoneID=14433},questType="standard"},
[77417] = {id=77417,name="What Makes an Infinite",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Eternus clearly has something she wishes to impart to us. I am unsure where this conversation will lead. But I trust Chromie. If she believes that Eternus can be swayed, I trust her judgment. When you are ready, I will see what she has to say.",objectivesText="See what Eternus has to reveal. Progress: I am interested in learning what Eternus wishes to say.",starts={{mapID=2025,npcID=207106,x=0.655,y=0.802}},ends={{mapID=2025,npcID=207106,x=0.655,y=0.802}},coords={mapID=2025,source="quest_giver",x=0.655,y=0.802},questType="standard"},
[77423] = {id=77423,name="Surging Dreams",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Change is coming, <name>. Those attuned to the Emerald Dream can feel it on the wind. We need your aid in uncovering what this change entails. Let us reconvene in the affected area and formulate a plan.",objectivesText="Meet the druids investigating the Dreamsurge.",starts={{mapID=2112,npcID=211031,x=0.5055,y=0.5735}},ends={{mapID=2022,npcID=208649,x=0.584,y=0.678}},coords={mapID=2112,source="quest_giver",x=0.5055,y=0.5735},questType="standard"},
[77426] = {id=77426,name="Practice Makes Perfect: Rusziona",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[77427] = {id=77427,name="Practice Makes Perfect: Zhusadormu",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[77428] = {id=77428,name="Practice Makes Perfect: Zalethgos",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[77429] = {id=77429,name="Practice Makes Perfect: Posidriss",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[77430] = {id=77430,name="Practice Makes Perfect: Belastrasza",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[77432] = {id=77432,name="Pedgi the Parched",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Pedgi's being dramatic. Again. I know it seems childish, and that's because it is childish, but he responds well to little treats when he's in a mood. Could you get him a coffee from the bar downstairs?",objectivesText="Get Pedgi a drink from the inn's bartender. Progress: Pedgi's treat should get him to stop moping. By the titans, I can't believe I had to say that...",starts={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},ends={{mapID=2025,npcID=204990,x=0.538,y=0.8416}},coords={mapID=2025,source="quest_giver",x=0.538,y=0.8416},questType="standard"},
[77433] = {id=77433,name="Excavation: Riverbed",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="There's a Riverbed near Maruukai in Ohn'ahran Plains that's teeming with local lore about a lost caravan! Meet me there as quick as you can! And wear your best, old, mud-ready boots!",objectivesText="Meet Roska Rocktooth at the Riverbed dig site in Ohn'ahran Plains.",starts={{mapID=2025,npcID=208614,x=0.615,y=0.306}},ends={{mapID=2023,npcID=204094,x=0.674,y=0.475}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.306},questType="standard"},
[77434] = {id=77434,name="Technoscrying: Observatory",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="My dowsing rods have been pointing towards a set of Drakonid ruins atop a cliff in Waking Shores. I know not what we'll find, but it's never wise to question the whims of my inventions. They're always 97% correct. Always.",objectivesText="Meet Zenata at the Concord Observatory in Waking Shores.",starts={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},ends={{mapID=2022,npcID=204835,x=0.564,y=0.44}},coords={mapID=2025,source="quest_giver",x=0.616,y=0.305333},questType="standard"},
[77436] = {id=77436,name="The Burning Barrow",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=14529,mapID=2200,description="Fyrakk's forces have already set their plans in motion. We are one step behind, and we need to catch up quickly if we are to properly protect Amirdrassil. While you were on your way here, we received word of suspicious-looking figures entering one of the nearby barrow dens. Tyrande already went to investigate. Seek her out and lend her your aid.",objectivesText="Find Tyrande near the Sor'theril Barrow Den.",starts={{mapID=2200,npcID=206896,x=0.508,y=0.628}},ends={{mapID=2200,npcID=206247,x=0.514,y=0.428}},coords={mapID=2200,source="quest_giver",x=0.508,y=0.628},questType="standard"},
[77437] = {id=77437,name="Eon's Fringe",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Timewalker Tempo and their team finally unfroze Eon's Fringe! Er... mostly. The Timewalkers have things more or less under control but Eon's Fringe has some problems the people of the town wouldn't mind a hand with. Tell Bob I sent ya!",objectivesText="Find Bartender Bob in Eon's Fringe.",starts={{mapID=2112,npcID=209020,x=0.789,y=0.446}},ends={{mapID=2025,npcID=203769,x=0.522,y=0.815}},coords={mapID=2112,source="quest_giver",x=0.789,y=0.446},questType="standard"},
[77483] = {id=77483,name="Technoscrying: Dragonskull Island",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,mapID=2151,description="I tuned my various sensors for Dracthyr relics, and they've triangulated a new location for us to investigate off the eastern coast of the Forbidden Reach. The local Drakonid tell me it's named Dragonskull Island. Ominous, no? You're not easily frightened, are you?",starts={{npcID=208355,x=0.618,y=0.298,mapID=2025}},ends={{npcID=207311,x=0.77,y=0.384,zoneID=14433}},coords={x=0.618,y=0.298,source="quest_giver",zoneID=13647},questType="standard"},
[77484] = {id=77484,name="Technoscrying: Igira's Watch",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Of all places, my sensors are indicating a site of interest beneath the surface in Zaralek Cavern. Best bring a weapon for this excursion. My preliminary scouting indicated a elevated presence of both lava and djaradin.",objectivesText="Meet Zenata at Igira's Watch in Zaralek Cavern.",starts={{mapID=2025,npcID=208355,x=0.616,y=0.305333}},ends={{mapID=2133,npcID=207763,x=0.382,y=0.498}},coords={mapID=2025,source="quest_giver",x=0.616,y=0.305333},questType="standard"},
[77485] = {id=77485,name="Technoscrying: Back to Eadweard!",level=70,requiredLevel=70,faction="none",expansion=10,mapID=2025,description="Thanks for all your help! Let's head back to Eadward and the others back at the Academy to go over all the new information we've uncovered.",objectivesText="Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.",questType="standard"},
[77486] = {id=77486,name="Excavation: Gaze of Neltharion",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="A Niffen colleague of mine gave me the underground info about an underground tower. It's decrepit and smack-dab in the middle of Zaralek between Loamm, the Djaradin, and that ghastly lab of Neltharion's. Grab your favorite shovel and meet me there!",objectivesText="Meet Roska Rocktooth at the Gaze of Neltharion in Zaralek Cavern.",starts={{mapID=2025,npcID=208614,x=0.615,y=0.306}},ends={{mapID=2133,npcID=205413,x=0.486,y=0.484}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.306},questType="standard"},
[77487] = {id=77487,name="Excavation: Winglord's Perch",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14433,mapID=2151,description="We've discovered an ancient fishing village in the Forbidden Reach! It's this humble isle off the northwest coast with its own crumbling bridge and everything! I'll be there if you're looking for more dirt to dig up!",starts={{npcID=208614,x=0.616,y=0.31,mapID=2025}},ends={{npcID=208362,x=0.172,y=0.164,zoneID=14433}},coords={x=0.616,y=0.31,source="quest_giver",zoneID=13647},questType="standard"},
[77488] = {id=77488,name="Excavation: Back to Eadweard!",level=70,requiredLevel=70,faction="none",expansion=10,mapID=2025,description="Great job, ! We've got plenty of history to report back to Eadweard with. Let's meet back at the Academy!",objectivesText="Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.",questType="standard"},
[77570] = {id=77570,name="Nuoberon, the Wild Dream of a Child",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14529,mapID=2200,objectivesText="Participate in Nuo's dream to summon a massive creature",questType="standard"},
[77581] = {id=77581,name="Kill them Gnolls!",level=1,requiredLevel=1,faction="none",expansion=10,zoneID=14730,questType="standard"},
[77589] = {id=77589,name="Warmaul Wingding",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.295,y=0.249,mapID=107,npcID=209150}},ends={{x=0.295,y=0.249,mapID=107,npcID=209150}},coords={mapID=107,x=0.295,y=0.249},questType="standard"},
