[77593] = {id=77593,name="Warmaul Wingding - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.295,y=0.249,mapID=107,npcID=209150}},ends={{x=0.295,y=0.249,mapID=107,npcID=209150}},coords={mapID=107,x=0.295,y=0.249},questType="standard"},
[77644] = {id=77644,name="The Scarlet Key",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=85,objectivesText="Progress: <Though dirt and rust have accumulated on these keys, the one you currently possess looks no different otherwise.>",starts={{x=0.469,y=0.576,mapID=19}},ends={{x=0.469,y=0.576,mapID=19}},coords={mapID=19,x=0.469,y=0.576},questType="standard"},
[77645] = {id=77645,name="Skettis Scramble",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.671,y=0.659,mapID=108,npcID=209234}},ends={{x=0.671,y=0.659,mapID=108,npcID=209234}},coords={mapID=108,x=0.671,y=0.659},questType="standard"},
[77646] = {id=77646,name="Skettis Scramble - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.671,y=0.659,mapID=108,npcID=209234}},ends={{x=0.671,y=0.659,mapID=108,npcID=209234}},coords={mapID=108,x=0.671,y=0.659},questType="standard"},
[77647] = {id=77647,name="Skettis Scramble - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.671,y=0.659,mapID=108,npcID=209234}},ends={{x=0.671,y=0.659,mapID=108,npcID=209234}},coords={mapID=108,x=0.671,y=0.659},questType="standard"},
[77653] = {id=77653,name="A Key Story",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Here for the latest? Well, have I got news for you. A weaponsmith was just here visiting Tithris. Koref, I think? Couldn't help but overhear their discussion about some sort of ancient key. Might be of interest to you, what with all your artifact hunting. Weaponsmith Koref was headed back to the Obsidian Enclave. You should head there and get the scoop about this ancient key.",objectivesText="Seek out Weaponsmith Koref and interview him about the key.",starts={{mapID=2112,npcID=207696,x=0.476,y=0.470667}},ends={{mapID=2112,npcID=195769,x=0.365,y=0.515}},coords={mapID=2112,source="quest_giver",x=0.476,y=0.470667},questType="standard"},
[77662] = {id=77662,name="A Call to Aid",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Ah, so you are $p? Hm, I suppose Lilian consorts with heroes of all sorts now... Lilian sent me with a message. She and Shandris have been tasked with tracking a powerful Druid of the Flame. He continues to elude them, but with your assistance, they believe they can corner him and his dryad conspirators. Seek them out if you are able to aid them.",objectivesText="Meet with Shandris and Lilian in the Lushdream Crags.",starts={{mapID=2200,npcID=209516,x=0.5,y=0.61}},ends={{mapID=2200,npcID=209083,x=0.496,y=0.462}},coords={mapID=2200,source="quest_giver",x=0.5,y=0.61},questType="standard"},
[77664] = {id=77664,name="One Last Step",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="This operation would not have come this far without Lilian's aid. We may not have much in common, but Lillian is a... dependable ally. After fighting side-by-side in the Dream, we have an odd kinship that was forged by this mission. Together, we will finish this. With the stones in our hands, it is now safe to take out Raelas and end his little crusade. Onward.",objectivesText="Eliminate Raelas Firewind .",starts={{npcID=209677}},ends={{mapID=2200,npcID=209799,x=0.552,y=0.424}},coords={mapID=2200,source="quest_giver",x=0.552,y=0.424},questType="standard"},
[77665] = {id=77665,name="Bound to You",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="I haven't worked with Shandris long, but... it's unusual for her to act like that. But it doesn't matter. While she deals with logistics, you and I should go ahead and find a way to cleanse these stones. Maybe Shae'lune knows what to do next.",objectivesText="Ask Shae'lune about the cleansing the stones.",starts={{mapID=2200,npcID=209082,x=0.552,y=0.424}},ends={{mapID=2200,npcID=209328,x=0.552,y=0.422}},coords={mapID=2200,source="quest_giver",x=0.552,y=0.424},questType="standard"},
[77673] = {id=77673,name="Under the Surface",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="I knew coming into this that Shandris likes to work alone, but letting us know where she's going would be nice. Not a great turn in our professional relationship. Keeper Sillas won't speak to me... We should take a look around the camp. Maybe she left a note or some clue... maybe in her mission log? Take a look, and see if you can get anything out of Sillas. I'll wait here in case she comes back.",objectivesText="Find clues regarding Shandris' whereabouts.",starts={{mapID=2200,npcID=209328,x=0.552,y=0.422}},ends={{mapID=2200,npcID=209323,x=0.51,y=0.473}},coords={mapID=2200,source="quest_giver",x=0.552,y=0.422},questType="standard"},
[77674] = {id=77674,name="Wounds of the Past",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="It's all making sense now. I believe the missing dream spirit bonded with her--like Cyanthesa said. It's making Shandris relive traumatic moments from her life. It's not malicious, but the spirit and Shandris are feeding off each others' fears. We have to bring her back to the camp. Shae'lune might be able to help her. Talk to her. I look like the enemy right now. But maybe she'll talk to you.",objectivesText="Talk to Shandris and help her back to the camp.",starts={{mapID=2200,npcID=209323,x=0.51,y=0.473}},ends={{mapID=2200,npcID=209328,x=0.552,y=0.422}},coords={mapID=2200,source="quest_giver",x=0.51,y=0.473},questType="standard"},
[77675] = {id=77675,name="A Better Future, Together",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="<name>, we need to work with Shae'lune and help her perform the purification ritual on Shandris. Shae'lune says she's only done it on objects before--not people. There is some... risk involved. But I've come to know Shandris. She'd do the same for me. Talk to Shae'lune and follow her instructions.",objectivesText="Help Shae'lune perform the separation ritual on Shandris. Progress: I will help Shandris as best I can. It's the least I can do for another soldier.",starts={{mapID=2200,npcID=209328,x=0.552,y=0.422}},ends={{mapID=2200,npcID=209328,x=0.552,y=0.422}},coords={mapID=2200,source="quest_giver",x=0.552,y=0.422},questType="standard"},
[77677] = {id=77677,name="Some Water...",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="<The plant is clear of soot and flame, but its leaves are limp with thirst. Perhaps someone from Central Encampment will know the perfect remedy.>",objectivesText="Nurse the plant back to health. Progress: <The plant's leaves are fringed in brown and brittle along the edges.>",starts={{mapID=2200,npcID=209292,x=0.486,y=0.678}},ends={{mapID=2200,npcID=209292,x=0.486,y=0.678}},coords={mapID=2200,source="quest_giver",x=0.486,y=0.678},questType="standard"},
[77679] = {id=77679,name="To Soridormi's Aid",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Have you heard? Time rifts are opening in Tyrhold Reservoir! It's a catastrophe! Folks have seen portals to other timeways randomly appearing. Now all kinds of fantastic creatures are swarming into Azeroth. Thank goodness for Soridormi . I heard she's getting everyone organized to make a stand. If you can offer any assistance, I'm sure she could use it. They say she's still stationed in Tyrhold Reservoir. Do it for Valdrakken. Do it for Azeroth!",objectivesText="Speak with Soridormi in Tyrhold Reservoir.",starts={{mapID=2112,npcID=197574,x=0.726667,y=0.473333}},ends={{mapID=2025,npcID=204450,x=0.51,y=0.57}},coords={mapID=2112,source="quest_giver",x=0.726667,y=0.473333},questType="standard"},
[77681] = {id=77681,name="Alerting all Adversaries!",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The Artisan's Consortium has struck another deal with the quartermasters of the Gladiator's Refuge! In addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas! Present this leaflet to Calderax to receive two complimentary Trophies of Conquest, on us! - Rabul",objectivesText="Deliver the leaflet to Calderax in the Gladiator's Refuge of Valdrakken .",ends={{mapID=2112,npcID=199599,x=0.444667,y=0.366667}},coords={mapID=2112,source="quest_giver",x=0.444667,y=0.366667},questType="standard"},
[77684] = {id=77684,name="Fel Pit Fracas",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.51,y=0.401,mapID=104,npcID=209424}},ends={{x=0.51,y=0.401,mapID=104,npcID=209424}},coords={mapID=104,x=0.51,y=0.401},questType="standard"},
[77685] = {id=77685,name="Fel Pit Fracas - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.51,y=0.401,mapID=104,npcID=209424}},ends={{x=0.51,y=0.401,mapID=104,npcID=209424}},coords={mapID=104,x=0.51,y=0.401},questType="standard"},
[77686] = {id=77686,name="Fel Pit Fracas - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.51,y=0.401,mapID=104,npcID=209424}},ends={{x=0.51,y=0.401,mapID=104,npcID=209424}},coords={mapID=104,x=0.51,y=0.401},questType="standard"},
[77697] = {id=77697,name="The Right Food...",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="<The plant is now a promising sapling and has thrived with the attention you've given. Peering closely at the plant's leaves, you see its exterior brimming with dew. Perhaps the right food will help the plant even further.>",objectivesText="Bring some fertilizer for the plant. Progress: <The plant is hydrated, but remains severely underfed.>",starts={{mapID=2200,npcID=209458,x=0.486,y=0.678}},ends={{mapID=2200,npcID=209458,x=0.486,y=0.678}},coords={mapID=2200,source="quest_giver",x=0.486,y=0.678},questType="standard"},
[77698] = {id=77698,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,starts={{npcID=407048,x=0.431,y=0.666,mapID=2022}},ends={{npcID=407048,x=0.431,y=0.666,mapID=2022}},coords={x=0.431,y=0.666,source="quest_giver",mapID=2022},questType="standard"},
[77711] = {id=77711,name="And a Pinch of Magic",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="The diligence you've shown here is astounding, <name>. I never suspected that someone who couldn't even find their own bucket, could do something like this. I think the sapling is almost there, and with my help we can bring it the rest of the way. Take this totem and place it near some of the weakened, flame-corrupted Roottenders found in the Singing Fen. This should siphon the unstable magical energies out of their bodies and transform it into something we can use.",objectivesText="Defeat Roottenders while they are under the effects of the Druidic Totem . Progress: Is the totem charged?",starts={{mapID=2200,npcID=208337,x=0.496,y=0.628},{mapID=2200,npcID=209571,x=0.486,y=0.68}},ends={{mapID=2200,npcID=209571,x=0.486,y=0.68}},coords={mapID=2200,source="quest_giver",x=0.496,y=0.628},questType="standard"},
[77739] = {id=77739,name="Smother the Flames",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Lilian and I have been shadowing Raelas Firewind and have uncovered his plan. He has manipulated the Sisters of the Flame to bind spirits from the Dream to magical spirit stones. With Raelas's blessing, these stones became powerful tools of corruption, allowing these fallen dryads to twist the Dream and its denizens. We will start our purge with the dryads--they have the stones. Then we will end Raelas. The hunt begins, $p.",objectivesText="Help Shandris and Lilian retrieve the spirit stones from the Sisters of Flame dryads. Progress: Bring me all four spirit stones. We must keep them close so they do not fall into the wrong hands.",starts={{mapID=2200,npcID=209083,x=0.496,y=0.462}},ends={{mapID=2200,npcID=209083,x=0.496,y=0.462}},coords={mapID=2200,source="quest_giver",x=0.496,y=0.462},questType="standard"},
[77760] = {id=77760,name="Curious Find: Dragonhorn Flute",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2025,description="<This flute is inexpertly hewn out of the horn of a dragon. The cracking around the base suggests the dragon was long gone by the time the flute was made. The mouthpiece is strange. It's almost like it isn't designed to be played with the mouth at all but the nose. Could this flute have been crafted by the niffen? Eadweard would know how to preserve this find and figure out whom it might belong to.>",objectivesText="Bring the Dragonhorn Flute to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.",ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[77762] = {id=77762,name="A Little Hope is Never Without Worth",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="The plant has matured and is thriving. And with this little corner of our ecosystem restored, we've seen something I've been wishing for since I learned what you were up to: the dreamtalons have returned with their kits! One of the grateful mature dreamtalons has offered their services to you, if you wish it.",objectivesText="Speak to Professor Ash .",starts={{mapID=2200,npcID=208337,x=0.496,y=0.628},{mapID=2200,npcID=209571,x=0.486,y=0.68}},ends={{mapID=2200,npcID=209571,x=0.486,y=0.68}},coords={mapID=2200,source="quest_giver",x=0.496,y=0.628},questType="standard"},
[77766] = {id=77766,name="Curious Find: Hole-Punched Bakar Tooth",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2025,description="<This milk-tooth came from a young bakar, though the way the bone has yellowed suggests it's thousands of years old. Someone has carefully drilled a hole at the top of this tooth to turn it into a bead. Upon closer examination, the tattered remains of a woolen cord can still be seen threaded through it. Eadweard would know how to preserve this find and figure out whom it might belong to.>",objectivesText="Bring the Hole-Punched Bakar Tooth to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.",ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[77777] = {id=77777,name="Ruby Lifeshrine Loop - Storm Gryphon",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.633,y=0.709,mapID=2022,npcID=190123}},ends={{x=0.633,y=0.709,mapID=2022,npcID=190123}},coords={mapID=2022,x=0.633,y=0.709},questType="standard"},
[77779] = {id=77779,name="The Tale of Sir Thomas",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=6109,mapID=18,description="Suzannah... I never thought I would find her. Now we can return to our children, and rest at last. All thanks to you, <name>. Do you still have my tome? My story has reached its end, and I would see it penned by my own hand. <Thomas glides his finger across a blank page, spectral ink marking his words.> Please return this to the Orphan Matron. And... please apologize on my behalf for frightening her, would you?",objectivesText="Return to the Orphan Matron. Provided item:",starts={{x=0.43,y=0.53,mapID=435,npcID=209609}},ends={{mapID=18,npcID=53865,x=0.624,y=0.665},{mapID=37,npcID=53869,x=0.32,y=0.502}},coords={mapID=18,source="quest_giver",x=0.624,y=0.665},questType="standard"},
[77780] = {id=77780,name="A Blossom Witnessed",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Amirdrassil has bloomed beyond the confines of the Dream. Let us venture to the Dragon Isles and see where this new World Tree has taken root.",objectivesText="Speak with Merithra at the Ancient Bough in the Ohn'ahran Plains. Progress: It is magnificent!",starts={{mapID=2200,npcID=211634,x=0.276,y=0.314}},ends={{mapID=2023,npcID=206397,x=0.148,y=0.558}},coords={mapID=2200,source="quest_giver",x=0.276,y=0.314},questType="standard"},
[77781] = {id=77781,name="A Different Enthusiasm",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="I noticed the festivities have drawn the attention of a few spriggans from Ardenweald. They are curious creatures with... interesting tastes. Their pranks have been more than disruptive. Please root them out so the celebration may continue in peace.",objectivesText="Reveal 6 Spriggan Pranksters in Bel'ameth. Progress: Have you discovered all of them? I have already heard a middling rumor that I suspect they spun up.",starts={{mapID=2239,npcID=206849,x=0.542,y=0.578}},ends={{mapID=2239,npcID=206849,x=0.542,y=0.578}},coords={mapID=2239,source="quest_giver",x=0.542,y=0.578},questType="standard"},
[77784] = {id=77784,name="Tyrhold Trial - Storm Gryphon",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.572,y=0.669,mapID=2025,npcID=193651}},ends={{x=0.572,y=0.669,mapID=2025,npcID=193651}},coords={mapID=2025,x=0.572,y=0.669},questType="standard"},
[77785] = {id=77785,name="Fen Flythrough - Storm Gryphon",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.863,y=0.358,mapID=2023,npcID=191121}},ends={{x=0.863,y=0.358,mapID=2023,npcID=191121}},coords={mapID=2023,x=0.863,y=0.358},questType="standard"},
[77786] = {id=77786,name="Vakthros Ascent - Storm Gryphon",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.713,y=0.247,mapID=2024,npcID=192115}},ends={{x=0.713,y=0.247,mapID=2024,npcID=192115}},coords={mapID=2024,x=0.713,y=0.247},questType="standard"},
[77788] = {id=77788,name="Ashphodel Research Notes",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Q'onzu would definitely be interested in a sample of the pollen and these notes.>",ends={{npcID=210585,x=0.658,y=0.378,mapID=2200}},questType="standard"},
[77789] = {id=77789,name="Severing Ties",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=8574,mapID=830,description="Nalridun has recruited a small army of cultists. They believe he speaks for Sargeras through the relic, clinging to every word he says. The same way we clung to our leaders when Sargeras came to Argus. It was a comfort. A hope. And, in the end, empty deception. But his followers do not believe they are deceived. They have constructed their own conduits in the area to try to tap into the relic's power. To hear the voice themselves. They will try to stop us. We must cut a path through them.",objectivesText="Slay 10 man'ari cultists and overload 5 Sargerei Conduits. Progress: May their delusions die with them. We cannot risk any power they might be adding to Nalridun's rituals.",starts={{mapID=830,npcID=208858,x=0.635,y=0.425}},ends={{mapID=830,npcID=208858,x=0.635,y=0.425}},coords={mapID=830,source="quest_giver",x=0.635,y=0.425},questType="standard"},
[77791] = {id=77791,name="Handling It: Symbiotic Glowspore Grip",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13645,mapID=2023,description="I know a crafter who could help temper Fyr'alath. Erden of Clan Shikaar is extremely resourceful. He's performed many experiments with various reagents throughout the Dragon Isles. Hunters are only as good as their weapons. Erden is known for crafting exquisite weaponry with exotic materials. His expertise in various flora and fauna should prove quite informative.",objectivesText="Seek out Erden in the Ohn'ahran Plains.",starts={{x=0.616,y=0.312,mapID=2025,npcID=209601}},ends={{mapID=2023,npcID=194842,x=0.824,y=0.505}},coords={mapID=2023,source="quest_giver",x=0.824,y=0.505},questType="standard"},
[77793] = {id=77793,name="Crystal Circuit - Storm Gryphon",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.386,y=0.606,mapID=2133,npcID=202524}},ends={{x=0.386,y=0.606,mapID=2133,npcID=202524}},coords={mapID=2133,x=0.386,y=0.606},questType="standard"},
[77795] = {id=77795,name="Scavenged Artifacts",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=8574,mapID=830,starts={{npcID=125246,x=0.568,y=0.686,mapID=830}},ends={{npcID=125246,x=0.568,y=0.686,mapID=830}},coords={x=0.568,y=0.686,source="quest_giver",mapID=830},questType="standard"},
[77802] = {id=77802,name="What Do I Call You?",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Guardian! Or... teacher! Parent? I want you to tell me what to call you. The other dryads will ask me who my druid is now that I am working in the garden on my own. I want to tell them that I do not have a druid. I have you! Tell me what title you prefer.",objectivesText="Speak with Dionaessa to choose a title in the Root-Bound Sanctuary. Progress: I have heard so many titles from the druid Creekward. I am certain we can come up with something far more interesting.",starts={{mapID=2200,npcID=209788,x=0.538,y=0.745}},ends={{mapID=2200,npcID=209788,x=0.538,y=0.745}},coords={mapID=2200,source="quest_giver",x=0.538,y=0.745},questType="standard"},
[77813] = {id=77813,name="Lightning Strikes",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="<Flaps does a spin and deposits a drool-soaked note into your hand.> Ah, <name>. I am told you have acquired a fine new mount. A gryphon that soars upon the very storm itself! I would very much like to see how this wondrous creature flies. I will await you at Skytop Observatory.",objectivesText="Meet Lord Andestrasz at the Skytop Observatory.",starts={{mapID=2112,npcID=197478,x=0.455,y=0.5545}},ends={{mapID=2022,npcID=193359,x=0.752,y=0.55}},coords={mapID=2112,source="quest_giver",x=0.455,y=0.5545},questType="standard"},
[77815] = {id=77815,name="The Storm Race Tour",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="This storm gryphon is intriguing! Whatever land gave rise to such a creature merits further exploration. But since you are here, let us test its training--and your riding skills. My colleagues in the bronze flight have laid out new courses to put the mount through its paces. When a timekeeper sees you upon your gryphon, they will offer you the chance to fly these \"storm races\". Fortune favors the bold, $p. Good luck!",starts={{npcID=193359,x=0.752,y=0.55,mapID=2022}},ends={{npcID=193359,x=0.752,y=0.55,mapID=2022}},coords={x=0.752,y=0.55,source="quest_giver",mapID=2022},questType="standard"},
[77818] = {id=77818,name="The Cruel",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Primalists, djaradin, and Druids of the Flame all work together against us. But I can sense that this is not the last of them. Something powerful is trying to come through this portal. Let us try to seal them out for as long as we can.",objectivesText="Help Merithra close the flaming portal.",starts={{mapID=2200,npcID=206688,x=0.628,y=0.685}},ends={{mapID=2200,npcID=206806,x=0.589333,y=0.615333}},coords={mapID=2200,source="quest_giver",x=0.628,y=0.685},questType="standard"},
[77822] = {id=77822,name="A Titanic Mold",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="<The Titan Key Mold was at the location referenced in the story. Weaponsmith Koref will be so excited to see the mold!>",objectivesText="Return the Titan Key Mold to Weaponsmith Koref in Valdrakken . Progress: By the forge, did you actually do it? Did you find the Titan Key mold ?",ends={{mapID=2112,npcID=195769,x=0.365,y=0.515}},coords={mapID=2112,source="quest_giver",x=0.365,y=0.515},questType="standard"},
[77829] = {id=77829,name="Reforging a Legend",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="There you are! Weaponsmith Koref was just looking for you. Left me with a note asking you to meet him in the Obsidian Conclave. Sounds like you're helping him reforge an ancient titan key? Let me know how it goes! That's headline news if I ever heard it.",objectivesText="Seek out Weaponsmith Koref in the Obsidian Enclave.",starts={{mapID=2112,npcID=207696,x=0.476,y=0.470667}},ends={{mapID=2112,npcID=195769,x=0.365,y=0.515}},coords={mapID=2112,source="quest_giver",x=0.476,y=0.470667},questType="standard"},
[77831] = {id=77831,name="A Key To Reforg(ing)",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="You have the final materials! Perfect. I prepared the forge and the mold. I just need you to add the ingredients when I say. Oh, and be ready to use that Torch of Pyrreth. Seems the relic is crucial to the forging process. I'll tell you when!",objectivesText="Assist Weaponsmith Koref in reforging the Titan Key. Progress: The Titan Key. By the forge... Let me have a look.",starts={{mapID=2022,npcID=210837,x=0.245,y=0.608}},ends={{mapID=2022,npcID=210837,x=0.245,y=0.608}},coords={mapID=2022,source="quest_giver",x=0.245,y=0.608},questType="standard"},
[77832] = {id=77832,name="Shadows upon shadows",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14023,description="I need to save him.",objectivesText="Slay the Shadows.",questType="standard"},
[77833] = {id=77833,name="Handling It: Concentrated Sophic Vellum",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13645,mapID=2023,description="I know of a sage who can help temper Fyr'alath. Shalasar Glimmerdusk is an expert in intellectual matters, often pondering theories for controlling volatile magics. Few understand sophic matters as well as she does. Seek her guidance in managing shadowflame. I suspect her solution may include a sprinkle of Chromatic Dust!",objectivesText="Seek out Shalasar Glimmerdusk in the Ohn'ahran Plains.",starts={{x=0.616,y=0.312,mapID=2025,npcID=209601}},ends={{mapID=2023,npcID=194837,x=0.624,y=0.186}},coords={mapID=2023,source="quest_giver",x=0.624,y=0.186},questType="standard"},
[77835] = {id=77835,name="Handling It: Rune of Shadowbinding",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="Lydiara Whisperfeather is an academic who recognizes the rigidity of the rules that govern our world. She also likes bending them. If there is anyone who can assist in binding Fyr'alath's power, it's her.",objectivesText="Seek out Lydiara Whisperfeather in the Azure Span.",starts={{x=0.616,y=0.312,mapID=2025,npcID=209601}},ends={{mapID=2024,npcID=194840,x=0.402,y=0.644}},coords={mapID=2024,source="quest_giver",x=0.402,y=0.644},questType="standard"},
[77838] = {id=77838,name="Tattered Dreamleaf",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14529,mapID=2023,description="The properties of Dreamleaf are foreign to you. Completing events during the Superbloom will give you the knowledge necessary to help your ally.",objectivesText="Complete events during the Superbloom.",ends={{mapID=2023,npcID=194842,x=0.824,y=0.505}},coords={mapID=2023,source="quest_giver",x=0.824,y=0.505},questType="standard"},
[77839] = {id=77839,name="The Eastern Kingdoms Cup Circuit",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=4922,mapID=2112,description="It is once again time to test your mettle. My bronze colleagues have traveled to the Eastern Kingdoms to create new racing challenges. Many racecourses await you across the continent. Are you up to the task?",objectivesText="Fly through the introductory Eastern Kingdoms Cup courses. Progress: Have you taken wing today?",starts={{mapID=2112,npcID=206737,x=0.27,y=0.474},{mapID=84,npcID=214111,x=0.6,y=0.663},{mapID=85,npcID=214112,x=0.524,y=0.599}},ends={{mapID=2112,npcID=206737,x=0.27,y=0.474}},coords={mapID=2112,source="quest_giver",x=0.27,y=0.474},questType="standard"},
[77840] = {id=77840,name="The Eastern Kingdoms Cup Begins",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Skyrider! You just missed Lord Andestrasz . He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Valdrakken.",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61}},ends={{mapID=2112,npcID=206737,x=0.27,y=0.474}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="standard"},
[77841] = {id=77841,name="Ysera Invitational",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.591,y=0.288,mapID=2200,npcID=210023}},ends={{x=0.591,y=0.288,mapID=2200,npcID=210023}},coords={mapID=2200,x=0.591,y=0.288},questType="standard"},
[77842] = {id=77842,name="Ysera Invitational - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.591,y=0.288,mapID=2200,npcID=210023}},ends={{x=0.591,y=0.288,mapID=2200,npcID=210023}},coords={mapID=2200,x=0.591,y=0.288},questType="standard"},
[77843] = {id=77843,name="Ysera Invitational - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.591,y=0.288,mapID=2200,npcID=210023}},ends={{x=0.591,y=0.288,mapID=2200,npcID=210023}},coords={mapID=2200,x=0.591,y=0.288},questType="standard"},
[77844] = {id=77844,name="Ysera Invitational - Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.591,y=0.288,mapID=2200,npcID=210023}},ends={{x=0.591,y=0.288,mapID=2200,npcID=210023}},coords={mapID=2200,x=0.591,y=0.288},questType="standard"},
[77845] = {id=77845,name="Ysera Invitational - Reverse Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.591,y=0.288,mapID=2200,npcID=210023}},ends={{x=0.591,y=0.288,mapID=2200,npcID=210023}},coords={mapID=2200,x=0.591,y=0.288},questType="standard"},
[77865] = {id=77865,name="A Proper Burial",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},ends={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},coords={x=0.604,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[77869] = {id=77869,name="Return to the Echo Isles",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=1637,mapID=85,description="<name>, there appears to be trouble in the Echo Isles. Rokhan has requested your help.",objectivesText="Meet with Rokhan in the Echo Isles.",starts={{mapID=85,npcID=213791,x=0.325,y=0.648}},ends={{mapID=463,npcID=210198,x=0.61,y=0.655}},coords={mapID=85,source="quest_giver",x=0.325,y=0.648},questType="standard"},
[77871] = {id=77871,name="De Old Loa",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="Bwonsamdi does not be visiting in person without a good reason. Listen to all he has to say. Den we think, den we act.",objectivesText="Hear Bwonsamdi's message to the Darkspear trolls and find a solution. Progress: What Bwonsamdi be saying is very serious. Mueh'zala worship is a bloody one.",starts={{mapID=463,npcID=210092,x=0.602,y=0.644}},ends={{mapID=463,npcID=214839,x=0.6005,y=0.6535}},coords={mapID=463,source="quest_giver",x=0.602,y=0.644},questType="standard"},
[77874] = {id=77874,name="De Loa of de Past",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="We need to be findin' de old loa and call dem back. There must be a way to find where dey went. If we can find de old loa, we can host a Trial of the Loa to reconnect with their power. Bwonsamdi said dey are still out there. I think he be dropping a hint for us...",objectivesText="Find a guide to one of the lost loa by making a proper effigy, and follow the guide.",starts={{mapID=463,npcID=214839,x=0.6005,y=0.6535}},ends={{mapID=50,npcID=210238,x=0.832,y=0.44}},coords={mapID=463,source="quest_giver",x=0.6005,y=0.6535},questType="standard"},
[77877] = {id=77877,name="One with the Loa",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="Pieces of Lukou be scattered. But her heart be deep inside the ogre mound. De shadows can take us there. Quietly. Quickly. Speak to me when you are ready.",objectivesText="Talk to Kevo to be taken inside the Mosh'Ogg Ogre Mound. Progress: Kevo ya Siti wants to bring us inside the mound.",starts={{mapID=50,npcID=222666,x=0.65,y=0.475}},ends={{mapID=50,npcID=210091,x=0.663333,y=0.459}},coords={mapID=50,source="quest_giver",x=0.65,y=0.475},questType="standard"},
[77878] = {id=77878,name="Envoy of Winter",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14529,mapID=2200,objectivesText="Gather Tributes for the Envoy of Winter",questType="standard"},
[77879] = {id=77879,name="Stalking the Stalker",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="If dis loa be huntin' here, he may have seen us already. Since we don't know for sure, let's split up. I be hunting for him, while ya get his attention. Jani says the loa has been taking the offerings meant for Hakkar, the loa of blood. But we don't know WHY. Collect some and see if he wants them. If his motive is something else... we be knowin' soon enough.",objectivesText="Collect 6 Offerings to Hakkar to attract the loa. Progress: < Kevo ya Siti examines your offerings.>",starts={{mapID=50,npcID=210238,x=0.832,y=0.44}},ends={{mapID=50,npcID=209891,x=0.818,y=0.478}},coords={mapID=50,source="quest_giver",x=0.832,y=0.44},questType="standard"},
[77880] = {id=77880,name="Looking for Lukou",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="Dis be the last place Kevo ya Siti sensed Lukou. We be needing to ask around, see who knows where she might have gone.",objectivesText="Ask about Lukou and follow the trail to find her. Progress: With enough information, we can track Lukou down.",starts={{mapID=50,npcID=210091,x=0.663333,y=0.459}},ends={{mapID=50,npcID=210091,x=0.663333,y=0.459}},coords={mapID=50,source="quest_giver",x=0.663333,y=0.459},questType="standard"},
[77881] = {id=77881,name="There is Another",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="If Mueh'zala be involved... I will help. But for a loa trial fit to push Mueh'zala out, we will need another. Our sister loa is also lost. We were a team, her and I, until disagreement pushed us apart. Lukou is the loa of regeneration. She be the ideal loa to balance against death. I owe her an apology. You are here, and it be time. I last sensed her presence near the small settlement of Bambala. I be meeting you there.",objectivesText="Go to Bambala to seek out Lukou.",starts={{mapID=50,npcID=209891,x=0.818,y=0.478}},ends={{mapID=50,npcID=222657,x=0.635,y=0.412}},coords={mapID=50,source="quest_giver",x=0.818,y=0.478},questType="standard"},
[77882] = {id=77882,name="Stolen but Not Forgotten",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="There be many pieces missin' from dis altar. We be needing to repair it so dat Lukou is not angered when she returns, Lukou must see dat we are on her side.",objectivesText="Collect 8 altar fragments from around the Mosh'Ogg Ogre Mound. Progress: We need all the pieces you can find.",starts={{mapID=50,npcID=210091,x=0.663333,y=0.459}},ends={{mapID=50,npcID=210091,x=0.663333,y=0.459}},coords={mapID=50,source="quest_giver",x=0.663333,y=0.459},questType="standard"},
[77885] = {id=77885,name="Dream Wardens",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[77886] = {id=77886,name="Handling It: Shadowed Dreamleaf",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13645,mapID=2023,description="When Fyr'alath's power is at its limit, you will need a grip that can cool itself. It is like standing your ground when a beast charges you: as the battle heats up, you need a way to stay focused. Various leathers throughout the Dragon Isles have that cooling property, but I know of something better. Foliage that is routinely exposed to shadowflame would be the best choice for binding the components together. Let us gather what you need.",objectivesText="Collect Shadowed Dreamleaf from completing objectives in the Superbloom. Progress: Did you find what we need?",starts={{mapID=2023,npcID=194842,x=0.824,y=0.505}},ends={{mapID=2023,npcID=194842,x=0.824,y=0.505}},coords={mapID=2023,source="quest_giver",x=0.824,y=0.505},questType="standard"},
[77889] = {id=77889,name="A Fiery Proposal",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Ah hello! I have been working with some inscribers recently. We've been making a new type of ink. It's like fire ink, but even fierier! We need fiery essence from fire elementals, and fire elementals are currently attacking the dream. I believe this is what is called a \"win win\" scenario. Please drop their essence off at my associate in Amirdrassil.",objectivesText="Collect 10 Fiery Essence from fire elementals in the Emerald Dream . Progress: New knowledge can come from the strangest sources!",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=208337,x=0.496,y=0.628}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77891] = {id=77891,name="Fixing The Dream",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Engineering is an exact science! When something explodes, engineers plan it that way. Dreams are not exact, especially emerald ones! Someday, someone will want engineers to fix the Dream, and we won't know how to do it. We need a lot more information to understand what we're dealing with! Go to the Dream and place research beacons at my designated points. They will gather the information needed for any future repairs. Use this handy teleport device if you want to find the locations quickly.",objectivesText="Activate 8 Research Beacons Progress: I wonder if we'll ever truly understand the dream.",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2112,npcID=210162,x=0.367,y=0.629}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77892] = {id=77892,name="Pearls Of Great Value",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="When Amirdrassil's roots spread to the water, many rare creatures arose from the ocean's depths and now flourish around the dreams. One such rare creature is the Sandsparkle Clam, which can contain magical pearls! See if you can locate these clams and find some pearls within.",objectivesText="Collect 10 Sandsparkle Pearls Progress: Have you found any pearls?",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2112,npcID=210162,x=0.367,y=0.629}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77894] = {id=77894,name="Heart of Lukou",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="I was hoping we'd be getting more pieces than dis, but we make do with what we got, eh? Call Lukou to de altar. Hopefully she will answer.",objectivesText="Summon and speak with Lukou at the altar. Progress: We're close!",starts={{mapID=50,npcID=210091,x=0.663333,y=0.459}},ends={{mapID=50,npcID=210091,x=0.663333,y=0.459}},coords={mapID=50,source="quest_giver",x=0.663333,y=0.459},questType="standard"},
[77896] = {id=77896,name="A Sleepy Search",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="In our fight against Fyrakk's forces, a group of my fellow druids went out in search for a quiet and safe place to rest. But with Fyrakk's forces closing in on their location... I have to start planning for another assault, I can't split my time as much as I wish. I last saw them heading south to a cave by the shore. Please, I just need to make sure they're safe.",objectivesText="Check up with the sleeping druids.",starts={{mapID=2200,npcID=210133,x=0.502,y=0.634}},ends={{mapID=2200,npcID=210164,x=0.58,y=0.774}},coords={mapID=2200,source="quest_giver",x=0.502,y=0.634},questType="standard"},
[77897] = {id=77897,name="A Special Book",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=207696,x=0.478,y=0.47,mapID=2112}},ends={{npcID=207696,x=0.478,y=0.47,mapID=2112}},coords={x=0.478,y=0.47,source="quest_giver",mapID=2112},questType="standard"},
[77898] = {id=77898,name="Honor and Tribute",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="It be time to return home. Let us welcome dese loa to the Echo Isles. Their positive influence should make short work of Mueh'zala's presence. Go ahead, I be right behind ya.",objectivesText="Set up the loa altars at Darkspear Hold. Progress: The offerings need to be set exactly right.",starts={{mapID=50,npcID=210091,x=0.663333,y=0.459}},ends={{mapID=463,npcID=210086,x=0.597333,y=0.654667}},coords={mapID=50,source="quest_giver",x=0.663333,y=0.459},questType="standard"},
[77899] = {id=77899,name="The Rush'kah",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="When we make de rush'kah, we recreate de shape of the loa as we be seein' dem in our mind. By knowing the shape of de loa, we better understand who dey are. But de mask be shaped by our hands, so when de loa sees it, dey know what we expect dem to be. If the loa don't bless the mask, we expect dem to be something dey will not be. If de loa bless de mask, dey like what we see in dem and a bargain can be struck. We could just write a contract, but it is easier to lie with words than with your hands.",objectivesText="Make a rush'kah. Progress: De rush'kah be important in bonding with the loa.",starts={{mapID=463,npcID=210086,x=0.597333,y=0.654667}},ends={{mapID=463,npcID=223215,x=0.594,y=0.638}},coords={mapID=463,source="quest_giver",x=0.597333,y=0.654667},questType="standard"},
[77900] = {id=77900,name="The Loa Trials",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="When de loa bless the rush'kah, de trials will begin. Loa be giving tasks to teach us. Once de trials start, dey don't stop for nobody! Let's go to de altar together. Witch Doctor Tzadah will lead us in de ritual. She be Master Gadrin's apprentice, but be showin' real initiative in helping out on the trial.",objectivesText="Start the trial at the Altar of Darkspear Loa. Progress: It is time to begin de trial.",starts={{mapID=463,npcID=223215,x=0.594,y=0.638}},ends={{mapID=463,npcID=212784,x=0.589,y=0.6465}},coords={mapID=463,source="quest_giver",x=0.594,y=0.638},questType="standard"},
[77901] = {id=77901,name="Retraining the Trainees",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="Your witch doctor is trying to twist the trial to empower Mueh'zala. Many will be enthralled by this power, but we still stand with the Darkspear. I had a different trial in mind. Now, we adapt. Free your fellow trolls from his sacrificial magic. Dis charm will help them, but you must weaken them first. Try not to sacrifice dem.",objectivesText="Extract 8 shadows from lost trainees after weakening them. Progress: Use the charm on the trainees after you weaken them!",starts={{mapID=463,npcID=210260,x=0.5752,y=0.5844}},ends={{mapID=463,npcID=213638,x=0.577,y=0.61}},coords={mapID=463,source="quest_giver",x=0.5752,y=0.5844},questType="standard"},
[77902] = {id=77902,name="Ritual Recovery",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="Dat witch doctor has stolen de trial. She mocks us, trying to eat de life of living things to free Mueh'zala. We still have influence over it, though. Together, we will overwhelm her evil circles. When you find a circle, call upon me, and we will push death aside.",objectivesText="Remove 3 ritual circles with Lukou 's aid.",starts={{mapID=463,npcID=205981,x=0.578,y=0.626667}},ends={{mapID=463,npcID=213638,x=0.577,y=0.61}},coords={mapID=463,source="quest_giver",x=0.578,y=0.626667},questType="standard"},
[77903] = {id=77903,name="De Power of Death",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="De trial can't be stopped after it starts, but we won't let Tzadah use our people or our loa to aid Mueh'zala. If we be doing nothing, even more Darkspear could be swayed to find power in Mueh'zala. I'll look for a way to breach Tzadah's protective energy, you stop the spirits from taking over our home!",objectivesText="Kill Mueh'zala's summoned spirits.",starts={{mapID=463,npcID=212784,x=0.589,y=0.6465}},ends={{mapID=463,npcID=213638,x=0.577,y=0.61}},coords={mapID=463,source="quest_giver",x=0.589,y=0.6465},questType="standard"},
[77905] = {id=77905,name="Avatar of Mueh'zala",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="It be down to dis moment: working with our loa to save de soul of de Darkspear. See if Jani has found anything. Hopefully, his item will let you get close enough to Tzadah's effigies to destroy dem. That should give us a chance to strike the Witch Doctor herself. I'll occupy her attention with Kevo ya Siti's aid, but watch out for her guardians. Dey won't let you destroy her effigies without a fight.",objectivesText="Collect Jani's blessing and then travel with Lukou to the top of the pillars to defeat Tzadah's protection totems. Progress: Tzadah is a disgrace to the Darkspear.",starts={{mapID=463,npcID=213638,x=0.577,y=0.61}},ends={{mapID=463,npcID=212782,x=0.585,y=0.655}},coords={mapID=463,source="quest_giver",x=0.577,y=0.61},questType="standard"},
[77906] = {id=77906,name="De Darkspear Loa",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=6453,mapID=463,description="Dat was not a traditional trial, but we only keep tradition if it be helping de tribe. It be our strength: to adapt to what comes. It be time to shed de past and honor those most important to us. De Darkspear was never de largest tribe, nor de strongest. We endure because we choose our path, and our allies, well. Dese loa and you all worked and sacrificed not just to help Bwonsamdi, but to protect de souls of de Darkspear. Dat be why we honor our loa... and you.",objectivesText="Destroy Mueh'zala's altar and add Jani's. Progress: The effigies need to reflect our favored loa.",starts={{mapID=463,npcID=212782,x=0.585,y=0.655}},ends={{mapID=463,npcID=213669,x=0.588,y=0.655}},coords={mapID=463,source="quest_giver",x=0.585,y=0.655},questType="standard"},
[77908] = {id=77908,name="A Legacy of Secrets",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="<Return the book to Bobby Carlisle in Valdrakken to assist with deciphering the tablet text!>",objectivesText="Return the book, Tyr's Legacy , to Bobby Carlisle in Valdrakken . Progress: Was my source any good? Were you able to find the book?",ends={{mapID=2112,npcID=207696,x=0.476,y=0.470667}},coords={mapID=2112,source="quest_giver",x=0.476,y=0.470667},questType="standard"},
[77910] = {id=77910,name="Enchanted Shrubbery",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2133,description="Certain plants from the Emerald Dream could contain ingredients that would be helpful in our work here, but we need a lot of them, and I'm not hiring some herbalist to collect them. I've enchanted a water pot to help solve the problem. Travel to the Emerald Dream and use it on the plants I require. The plants should then deliver themselves.",objectivesText="Use the Watering Pot on 12 Enchanted Shrubs . Progress: Have you found the plants?",starts={{mapID=2133,npcID=203172,x=0.56,y=0.568},{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2112,npcID=210162,x=0.367,y=0.629}},coords={mapID=2133,source="quest_giver",x=0.56,y=0.568},questType="profession"},
[77911] = {id=77911,name="Build-a-Blanket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="I am unable to rest! I have spent all my energy in battle, but there is too much noise and the ground is too hard for me to sleep... I know! It pains me to ask this, but I need to rest so I can go back out and fight. Could you feed two birds with one seed for me? Take out the enraged lashers and retrieve their leaves so I can make a blanket to rest on.",objectivesText="Collect 6 Velvety Lasher Leaves from lashers. Progress: For the Emerald Dream , it sure is quite chaotic here.",starts={{mapID=2200,npcID=210164,x=0.58,y=0.774}},ends={{mapID=2200,npcID=210164,x=0.58,y=0.774}},coords={mapID=2200,source="quest_giver",x=0.58,y=0.774},questType="standard"},
[77912] = {id=77912,name="Unmodern Jewelry",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Some of the local Jewelcrafters are looking to study examples of the Zaqali tribes adornments. Given they are currently attacking my home, we may take advantage of the situation. I thought you might take them violently, yes? Argonax waits once you have collected them.",objectivesText="Collect 10 Zaqali Adornments . Progress: New knowledge can come from the strangest sources.",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=208340,x=0.572,y=0.272}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77914] = {id=77914,name="Burning Runes",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="I am told that the Druids of the Flame help to stabilize their portals into the dream through the use of a unique sort of inscription! While their ends are abhorrent, I cannot help but be curious as to their means. If we can better understand their methods, then perhaps we can better equip our allies to stem the tide of their arrival. If you get your hands on any burning runes , could you bring them to my colleague for further study?",objectivesText="Collect 10 Burning Runes from druids of the flame in the Emerald Dream . Progress: Take care, friend. I doubt the Druids of the Flame will part with their runework willingly.",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=208409,x=0.36,y=0.326}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77922] = {id=77922,name="Fluffy Filler Retrieval",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="There is no way I could rest without something soft to sleep on. Luckily, the dream has some sage so plush, that it would even put roc feathers to shame! It would be a perfect filling! Could you collect some sage around the area for me to rest on?",objectivesText="Collect 8 Silky Sage . Progress: The sage should be soft enough to make a comfortable place to sleep. Thank you for your assistance.",starts={{mapID=2200,npcID=210164,x=0.58,y=0.774}},ends={{mapID=2200,npcID=210164,x=0.58,y=0.774}},coords={mapID=2200,source="quest_giver",x=0.58,y=0.774},questType="standard"},
[77928] = {id=77928,name="They Are Always Listening",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Remember my contact, Fangli Hoot ? Seems she has another theory about the one behind these artifact thefts. I'm a bit weary after the last tip went nowhere, but we can't turn down a lead. Journalistic integrity demands we at least hear her out. You'll find her by the barber shop.",objectivesText="Speak with Fangli Hoot near the Valdrakken barber shop.",starts={{mapID=2112,npcID=207696,x=0.476,y=0.470667}},ends={{mapID=2112,npcID=207697,x=0.2656,y=0.5432}},coords={mapID=2112,source="quest_giver",x=0.476,y=0.470667},questType="standard"},
[77932] = {id=77932,name="Warmth of Life",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The Druids of the Flame practice virulent magics that warp and burn all they touch. They do, however, have excellent taste in alchemical reagents. If you should happen across any of their metamorphic ash, could you gather it up for me? One of my contacts within the Dream has been asking after the stuff.",objectivesText="Collect eight samples of Metamorphic Ash from Druids of the Flame in the Smoldering Copse. Progress: Ah, there you are! Have you managed to get your hands on any of that ash, yet? Its alchemical properties are truly wondrous.",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=208406,x=0.692,y=0.535}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77933] = {id=77933,name="Bubbling Discoveries",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The rise of Amirdrassil has unlocked various geological wonders in the dream. Among these are a variety of magical springs, bubbling water from deep within Azeroth. Travel the dream and gather samples from these springs.",objectivesText="Collect 8 samples from Bubbling Springs . Progress: Have you gathered the samples?",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2112,npcID=210162,x=0.367,y=0.629}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77934] = {id=77934,name="A Complete Inventory",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="<Compile your notes on the caches for Fangli Hoot in Valdrakken .>",objectivesText="Report your findings to Fangli Hoot near the barber shop in Valdrakken . Provided item:",starts={{mapID=2112,npcID=207697,x=0.2656,y=0.5432}},ends={{mapID=2112,npcID=207697,x=0.2656,y=0.5432}},coords={mapID=2112,source="quest_giver",x=0.2656,y=0.5432},questType="standard"},
[77935] = {id=77935,name="A-Sword-ed Needs",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Swords! Sorry, I saw you and I did not want to forget. Yes. We need swords. In the Dream. You can provide, yes? Please deliver them to Cylania .",objectivesText="Deliver 3 Draconium Swords to Cylania in the Emerald Dream Progress: Can I help you?",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=207755,x=0.498,y=0.628}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77936] = {id=77936,name="A Warm Harvest",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2112,description="Everyone knows heat plays a critical role in blacksmithing. I hear the Emerald Dream is still heavily under attack by allies of the flame. There must be a way to harvest fuel from those eternally fiery creatures. If you do secure anything, I'm sure one of the local blacksmiths in the Dream will be very interested.",objectivesText="Collect 10 Essence of Endless Flame in the Emerald Dream . Progress: Hmm. Yes?",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=208340,x=0.572,y=0.272}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77937] = {id=77937,name="Forbidden Sugar",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="During this very unique time of bloom, a new flower has been discovered in the Dream. These stunning flowers produce a marvelous pollen. Its aroma is a delight, just like fresh baked cookies. To the dismay of chefs, even eating a tiny bit will result in rapid, severe poisoning of the liver. However, it is an incredible all-purpose addition to enchanting. Early tests demonstrate potency as high as quadruple that of Chromatic Dust. Traders from Valdrakken are very interested in its acquisition.",starts={{npcID=210162,x=0.368,y=0.628,mapID=2112}},ends={{npcID=210162,x=0.368,y=0.628,mapID=2112}},coords={x=0.368,y=0.628,source="quest_giver",mapID=2112},questType="standard"},
[77938] = {id=77938,name="An Unlikely Engineer",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2112,description="I hear there is a legendary engineer in the Dream who crafts the most beautiful dream catchers. This engineer, Nyla Bushtail , enjoys acorn-flavored morels and relies on them to fuel her work. Acorn-flavored mushrooms... certainly strange, but perhaps not unheard of. There's a coastal area close to the Eye of Ysera where these morels grow abundantly. Do tread carefully around any wildlife in the area. If these morels are as tasty as I hear, they will be guarded greedily.",objectivesText="Collect 8 Whiteburr Morels for Nyla Bushtail in the Emerald Dream .",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=210636,x=0.525,y=0.252}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77945] = {id=77945,name="Boots on the Ground",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Just who I wanted to see. I have a requisition script for items of leather from some of the denizens of the Dream. Shoes, of course. Bipeds tend to go through them like a bird through the forest, yes? Once you have acquired them, please take them to Cylania .",objectivesText="Deliver 3 Pioneer's Leather Boots to Cylania in the Emerald Dream . Progress: Can I help you?",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=207755,x=0.498,y=0.628}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77946] = {id=77946,name="Fibrous Thread",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Fine thread may conjure images of tailory, but it can serve a vital role in leatherwork as well. Some of the Dream's hardier flora can be processed into a thread strong enough to secure even the thickest of hides and scales. If you happen upon any dense fiber during your travels, you would be well-served by bringing it to my colleague in the Dream.",objectivesText="Bring 1 Emerald Fiber from Enchanted Thickets in the Emerald Dream . Progress: You needn't worry about the plants themselves. They are nigh impossible to harm, and so long as they are treated respectfully, they will be more than happy to share their bounty with you.",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=208404,x=0.544,y=0.248}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77947] = {id=77947,name="Primalist Fashion",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Ah, <name>, there you are! The robes of the primalists make for interesting study for the local tailors. If you could retrieve some from the primalists assaulting the dream, I would be pleased, yes? No rips or tears please. Blood stains optional. They can be washed out.",objectivesText="Collect 10 Intact Primalist Garb from the Emerald Dream . Progress: Can I help you?",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2200,npcID=207755,x=0.498,y=0.628}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77948] = {id=77948,name="Burning Out",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Please, I know how this looks, but we are on the same side! My siblings and I intended to defect from the Flame together. However, none of them have escaped or met up with me since I left, and it's been days! I fear the worst. Do you think I would be begging for aid, alone and unarmed, if I was not honest? Please, find them. They are all I have left.",objectivesText="Find Solarys's siblings in the Smoldering Copse.",starts={{mapID=2200,npcID=210196,x=0.512,y=0.635333}},ends={{mapID=2200,npcID=210196,x=0.512,y=0.635333}},coords={mapID=2200,source="quest_giver",x=0.512,y=0.635333},questType="standard"},
[77949] = {id=77949,name="Fashion Feathers",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Much of the Dream's wildlife is feathered or furred. Their shed, whether it be down fur or feathers, is reputed to be extremely durable, soft, and fashionable. The great somnowls' feathers are particularly desirable. They don't shed often, and feathers are quickly retrieved by local wildlife for nest building. I've heard that your best chance is scouring the Meandering Rootlands in the Dream.",objectivesText="Collect 10 Shed Great Feathers in the Emerald Dream . Progress: Have you found any feathers? They're easy to identify. As large as two hands lengthwise, often snowy in color, and buttery soft.",starts={{mapID=2112,npcID=210162,x=0.367,y=0.629}},ends={{mapID=2112,npcID=210162,x=0.367,y=0.629}},coords={mapID=2112,source="quest_giver",x=0.367,y=0.629},questType="profession"},
[77953] = {id=77953,name="A Sphere in Danger",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=185562,x=0.474,y=0.466,mapID=2112}},ends={{npcID=185562,x=0.474,y=0.466,mapID=2112}},coords={x=0.474,y=0.466,source="quest_giver",mapID=2112},questType="standard"},
[77954] = {id=77954,name="A Curious Orb",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="< Tithris told you to return the orb to him in Valdrakken . He will pass it to Preservationist Kathos.>",objectivesText="Return the Orb of Rathmus to Tithris in Valdrakken . Progress: You got that orb for me? For Kathos, I mean.",starts={{x=0.474,y=0.467,mapID=2112}},ends={{mapID=2112,npcID=185562,x=0.4745,y=0.465}},coords={mapID=2112,source="quest_giver",x=0.4745,y=0.465},questType="standard"},
[77955] = {id=77955,name="Heated Hearthstone Hustle",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Wait, my hearthstone! I can't sleep without my hearthstone. A djaradin stole it during our last battle. It stays warm perpetually and I always sleep with it. I hate that I must ask more of you, but could you get my hearthstone? The djaradin that stole it should be near Fyrakk's army, just north of here.",objectivesText="Retrieve the Heated Hearthstone from the Stonewarmer. Progress: My eyes grow tired, but my body is still awake...",starts={{mapID=2200,npcID=210164,x=0.58,y=0.774}},ends={{mapID=2200,npcID=210164,x=0.58,y=0.774}},coords={mapID=2200,source="quest_giver",x=0.58,y=0.774},questType="standard"},
[77957] = {id=77957,name="A Treacherous Race",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},ends={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},coords={x=0.604,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[77958] = {id=77958,name="Sleepy Druid in Emerald Dream",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Why can I still not fall asleep, even with a heated blanket? < Thaalean curses the air then sighs.> This is embarrassing to request, but my mother used to sing me a lullaby before I slept back in Teldrassil, may I ask you to do the same? Any lullaby will do, I just want to rest peacefully.",objectivesText="Sing a lullaby for sleepy druid.",starts={{mapID=2200,npcID=210164,x=0.58,y=0.774}},ends={{mapID=2200,npcID=210133,x=0.502,y=0.634}},coords={mapID=2200,source="quest_giver",x=0.58,y=0.774},questType="standard"},
[77977] = {id=77977,name="An Ominous Artifact",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="<An orb would fit perfectly atop the console.>",objectivesText="Secure the Orb of Rathmus as well as the artifact it is hiding. Progress: A chest! Locked away in Tyrhold all this time. Can I examine it?",starts={{x=0.602,y=0.587,mapID=2025,objectID=411936}},ends={{mapID=2025,npcID=206864,x=0.604,y=0.59}},coords={mapID=2025,source="quest_giver",x=0.604,y=0.59},questType="standard"},
[77978] = {id=77978,name="A Passed Torch",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="<Strategic documents are scattered around Lyandris. Notes detailing experiments and future assault locations covering many of them.> <It would be of great use to your allies to find more of these documents. Thinning out the Flame's numbers wouldn't hurt either.>",objectivesText="Collect documents and kill Druids of the Flame within the Smoldering Copse. Progress: What is it?",starts={{x=0.38,y=0.472,mapID=2200,objectID=409077}},ends={{mapID=2200,npcID=210196,x=0.512,y=0.635333}},coords={mapID=2200,source="quest_giver",x=0.512,y=0.635333},questType="standard"},
[77983] = {id=77983,name="Smoldering Sprint",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.372,y=0.441,mapID=2200,npcID=210310}},ends={{x=0.372,y=0.441,mapID=2200,npcID=210310}},coords={mapID=2200,x=0.372,y=0.441},questType="standard"},
