[77999] = {id=77999,name="Viridescent Venture - Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.351,y=0.552,mapID=2200,npcID=210412}},ends={{x=0.351,y=0.552,mapID=2200,npcID=210412}},coords={mapID=2200,x=0.351,y=0.552},questType="standard"},
[78000] = {id=78000,name="Viridescent Venture - Reverse Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.351,y=0.552,mapID=2200,npcID=210412}},ends={{x=0.351,y=0.552,mapID=2200,npcID=210412}},coords={mapID=2200,x=0.351,y=0.552},questType="standard"},
[78002] = {id=78002,name="To The Test: Concentrated Sophic Vellum",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13645,mapID=2023,description="The Order and shadowflame magics are competing with each other. The enchantment will never be able to funnel Fyr'alath's power if we can't channel the excess Order magic being forced away from it. If you can channel the enchantment, your allies can catch any excess Order magic.",objectivesText="Return the excess Order magic to Shalasar's Sophic Vellum . Progress: Don't give up. I know this is tough, but keep your goal in mind.",starts={{mapID=2023,npcID=194837,x=0.624,y=0.186}},ends={{mapID=2023,npcID=194837,x=0.624,y=0.186}},coords={mapID=2023,source="quest_giver",x=0.624,y=0.186},questType="standard"},
[78003] = {id=78003,name="Handling It: Taut Tethercoil",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13646,mapID=2024,description="I've read of a root in the Emerald Dream known for its defensive qualities. It binds its tendrils to powerful foes as a way to protect surrounding flora and fauna. A friendly scribe might be able to help you adapt its properties. If I could just get my hands on some of that root, I'm sure I could dissect its properties and mold it into something capable of harnessing Fyr'alath's power. Here are my notes. You should be able to find powerful creatures guarding patches of wild tethercoil. Good hunting.",objectivesText="Collect Taut Tethercoil from powerful foes throughout the Emerald Dream. Progress: Ah, thank you for bringing these to me.",starts={{mapID=2024,npcID=194840,x=0.402,y=0.644}},ends={{mapID=2024,npcID=194840,x=0.402,y=0.644}},coords={mapID=2024,source="quest_giver",x=0.402,y=0.644},questType="standard"},
[78015] = {id=78015,name="Firebrand Fystia",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14529,mapID=2200,objectivesText="Eliminate the Primalists to draw their leader out",questType="standard"},
[78016] = {id=78016,name="Shoreline Switchback",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.696,y=0.526,mapID=2200,npcID=210497}},ends={{x=0.696,y=0.526,mapID=2200,npcID=210497}},coords={mapID=2200,x=0.696,y=0.526},questType="standard"},
[78017] = {id=78017,name="Shoreline Switchback - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.696,y=0.526,mapID=2200,npcID=210497}},ends={{x=0.696,y=0.526,mapID=2200,npcID=210497}},coords={mapID=2200,x=0.696,y=0.526},questType="standard"},
[78018] = {id=78018,name="Shoreline Switchback - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.696,y=0.526,mapID=2200,npcID=210497}},ends={{x=0.696,y=0.526,mapID=2200,npcID=210497}},coords={mapID=2200,x=0.696,y=0.526},questType="standard"},
[78019] = {id=78019,name="Shoreline Switchback - Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.696,y=0.526,mapID=2200,npcID=210497}},ends={{x=0.696,y=0.526,mapID=2200,npcID=210497}},coords={mapID=2200,x=0.696,y=0.526},questType="standard"},
[78020] = {id=78020,name="Shoreline Switchback - Reverse Challenge",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.696,y=0.526,mapID=2200,npcID=210497}},ends={{x=0.696,y=0.526,mapID=2200,npcID=210497}},coords={mapID=2200,x=0.696,y=0.526},questType="standard"},
[78040] = {id=78040,name="The Outland Cup Begins",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Skyrider! You just missed Lord Andestrasz . He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Valdrakken.",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61}},ends={{mapID=2112,npcID=206737,x=0.27,y=0.474}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="standard"},
[78041] = {id=78041,name="Sky Mother's Ire",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="We received reports that the Druids of the Flame have established another staging ground just south of the Eye of Ysera. Unfortunately for them, their incursion point has disrupted the local winged wildlife and drawn the ire of the Mother of Flight. Speak with Aviana and lend her your aid. We will need her eyes and wings in the battle to come.",objectivesText="Seek out Aviana .",starts={{mapID=2200,npcID=209318,x=0.508,y=0.62}},ends={{mapID=2200,npcID=210587,x=0.658,y=0.376}},coords={mapID=2200,source="quest_giver",x=0.508,y=0.62},questType="standard"},
[78042] = {id=78042,name="Aviana's Assessment",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="< Aviana 's eyes narrow as she watches the Druids of the Flame far below.> Q'onzu may be content with letting these heretics destroy the very fabric of the Dream, but I am not. Bring me scraps of their armor stained with blood as proof of your deed. Do not hold back, <name>. Remember what these heathens are capable of.",objectivesText="Collect 20 Bloodied Armor Scraps . Progress: Every minute they are left uncontested, another portion of the Dream is lost to their heinous acts.",starts={{mapID=2200,npcID=210587,x=0.658,y=0.376}},ends={{mapID=2200,npcID=210587,x=0.658,y=0.376}},coords={mapID=2200,source="quest_giver",x=0.658,y=0.376},questType="standard"},
[78043] = {id=78043,name="Q'onzu's Quandary",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="You again! Well, you must be here to help, correct? Absolutely you are. Why would you not? This development is so exciting. What could these desolating druids be up to? Fortunately, a few of my friends have infiltrated the druids. I'm sure they have quite the story to tell. Go forth, my curious companion and bring back exciting news!",objectivesText="Speak to the Flame-Disguised Dreamkin to gather intel on the Druids of the Flame. Progress: Change has come to the dream and yet we are so quick to snuff it out. How unnaturally boring.",starts={{mapID=2200,npcID=210585,x=0.658,y=0.378}},ends={{mapID=2200,npcID=210585,x=0.658,y=0.378}},coords={mapID=2200,source="quest_giver",x=0.658,y=0.378},questType="standard"},
[78044] = {id=78044,name="Appalling Pollen",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="This cinder pollen doesn't evoke interesting change. It consumes all until nothing, but ash remains. It brings... uniformity. And I find that to be tragically stale. I'm all for change, no matter the origin. But if THIS change stymies all future possibilities for further change, then it must be stopped. If creatures of the dream have been infected by this pollen, then they must be extinguished. This is not a flame that can be allowed to grow.",objectivesText="Reveal and kill 10 Cinderpollen Beasts. Progress: Bringing about change to the dream through fire is a fascinating concept - life and fire can coexist! < Q'onzu 's expression hardens as they shudder.> But this change is not that.",starts={{mapID=2200,npcID=210585,x=0.658,y=0.378}},ends={{mapID=2200,npcID=210585,x=0.658,y=0.378}},coords={mapID=2200,source="quest_giver",x=0.658,y=0.378},questType="standard"},
[78045] = {id=78045,name="Uproot the Cause",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="< Aviana 's gaze remains locked on Q'onzu for a moment, her brow furrowed.> While I don't see eye to eye with Q'onzu's fascination for change, their incessant inquiry has unveiled a more deep-seated plot than originally suspected. Putting down the wildlife won't mean much if we don't tear out the root of the cause. Locate the burning ashphodels in the glade below and tear them out.",objectivesText="Collect 8 Uprooted Ashphodels . Progress: If the ashphodels are allowed to spread their foul pollen unchecked, then the rest of the dream is in grave danger. < Aviana grimaces.>",starts={{mapID=2200,npcID=210587,x=0.658,y=0.376}},ends={{mapID=2200,npcID=210587,x=0.658,y=0.376}},coords={mapID=2200,source="quest_giver",x=0.658,y=0.376},questType="standard"},
[78046] = {id=78046,name="Overseer Oversight",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Those research notes you brought Q'onzu made mention of the ones behind these foul experiments. The overseer, the one named Chardryn, has been under our noses this whole time. He oversees their research station below us. If we are to permanently end their terrible experiments and disrupt their progress, then he must be made an example of.",objectivesText="Slay Overseer Chardryn . Progress: If Chardryn and his insane herbologists are allowed to carry out biological warfare here in the dream, then Amirdrassil and all of Azeroth is at risk. We cannot allow these sycophants of fire to remain alive.",starts={{mapID=2200,npcID=210587,x=0.658,y=0.376}},ends={{mapID=2200,npcID=210587,x=0.658,y=0.376}},coords={mapID=2200,source="quest_giver",x=0.658,y=0.376},questType="standard"},
[78047] = {id=78047,name="The Outland Cup Circuit",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=3519,mapID=2112,description="It is time once again to test your mettle. My bronze colleagues have traveled to Outland to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit! Are you up to the task?",objectivesText="Fly through Outland Cup courses. Progress: Have you taken wing today?",starts={{mapID=2112,npcID=206737,x=0.27,y=0.474},{mapID=84,npcID=214111,x=0.6,y=0.663},{mapID=85,npcID=214112,x=0.524,y=0.599}},ends={{mapID=2112,npcID=206737,x=0.27,y=0.474},{mapID=84,npcID=214111,x=0.6,y=0.663},{mapID=85,npcID=214112,x=0.524,y=0.599}},coords={mapID=2112,source="quest_giver",x=0.27,y=0.474},questType="standard"},
[78064] = {id=78064,name="Q'onzu's Perception",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="You have many questions and I have many worries. Such pressing worries. An interloper, a rude disrupter of our joyous day. How I worry so. If only someone could confront this trespasser. Wait, you could do it for me! It's a win-win, you go confront the trespasser and I answer your questions. I've tracked them down to a cave in the north. Surely you can handle them.",objectivesText="Find and confront the interloper in Q'onzu 's nest. Progress: I can sense the interloper causing a disturbance in my nest!",starts={{mapID=2200,npcID=210524,x=0.346,y=0.692}},ends={{mapID=2200,npcID=210524,x=0.346,y=0.692}},coords={mapID=2200,source="quest_giver",x=0.346,y=0.692},questType="standard"},
[78065] = {id=78065,name="The Q'onzu Query",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Champion, I understand we were unable to convince Q'onzu to join us. However, we need all the aid we can gather. You must discover why they refuse to aid us and convince them of the right path. Q'onzu and I have a rather strained relationship. Your efforts could bear more fruit. I hear Q'onzu has built a nest near Shiversnap Grove. Would you go and approach them?",objectivesText="Approach Q'onzu again and ask what they've been up to.",starts={{mapID=2200,npcID=209318,x=0.508,y=0.62}},ends={{mapID=2200,npcID=210646,x=0.348,y=0.69}},coords={mapID=2200,source="quest_giver",x=0.508,y=0.62},questType="standard"},
[78066] = {id=78066,name="The Answers You've Earned",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Ah, that's much better. Now I can think. What did you want, again? Oh yes! Questions. Ask away, if you must.",objectivesText="Get answers about Q'onzu .",starts={{mapID=2200,npcID=210524,x=0.346,y=0.692}},ends={{mapID=2200,npcID=211821,x=0.346,y=0.692}},coords={mapID=2200,source="quest_giver",x=0.346,y=0.692},questType="standard"},
[78068] = {id=78068,name="An Artificer's Appeal",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=1519,mapID=103,description="<name>, I received an item for you from Grand Artificer Romuul . Romuul wished for you to listen to the message before proceeding to the Exodar.",objectivesText="Meet Grand Artificer Romuul in the Exodar.",starts={{x=0.53,y=0.155,mapID=84,objectID=415303}},ends={{mapID=103,npcID=210340,x=0.548444,y=0.797111}},coords={mapID=103,source="quest_giver",x=0.548444,y=0.797111},questType="standard"},
[78069] = {id=78069,name="Reviving Tradition",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3557,mapID=103,description="The Prophet wished to personally ask for your help with the Tishamaat. But since he is working elsewhere, I asked you first to jumpstart our task. My colleague and I have been working on a special project. And since the Prophet has declared today the Tishamaat, we will unveil it at the celebration! For this, I need the emitter, but it needs an overhaul. We only have time for a hot wiring. Get some filament and a soldering tool from the crates nearby, <name>. Then maybe I can wire it to an array.",objectivesText="Help Romuul finish repairing the Holographic Emitter. Progress: I regret not having apprentices in times like this.",starts={{mapID=103,npcID=210340,x=0.548444,y=0.797111}},ends={{mapID=103,npcID=210340,x=0.548444,y=0.797111}},coords={mapID=103,source="quest_giver",x=0.548444,y=0.797111},questType="standard"},
[78070] = {id=78070,name="Pressing Deadlines",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3557,mapID=103,description="During this Tishamaat, Ataanya and I will present our project's schematics. Ataanya is High Artificer of Shattrath. Her father was my late mentor, the famed Exarch Hataaru. Hataaru's hoofplates are hard to fill, but Ataanya has more than done so. She has the schematics, and she should be here when they are presented. But she is not responding to my messages. Ataanya seldom leaves the city, but surely she can make an exception for the Tishamaat. Perhaps you can reason with her.",objectivesText="Speak to Ataanya in Shattrath City.",starts={{mapID=103,npcID=210340,x=0.548444,y=0.797111}},ends={{mapID=111,npcID=208494,x=0.386,y=0.466667}},coords={mapID=103,source="quest_giver",x=0.548444,y=0.797111},questType="standard"},
[78071] = {id=78071,name="Rush Order",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3703,mapID=111,description="My schematics speak for themselves. Each calculation has been verified. It is respectful of all building codes. I even included a layout of the channels that the power grid must follow. Romuul knows the project. He already signed off on everything. He can explain it to the masses himself. I do not need to waste my valuable time traveling to the Exodar for this ridiculous holiday. My apprentice will give you the schematics on a data crystal. Take it and leave.",objectivesText="Speak to Beruun. Perhaps he knows a way to convince Ataanya to leave Shattrath. Progress: We will do what we can for Ataanya.",starts={{mapID=111,npcID=208494,x=0.386,y=0.466667}},ends={{mapID=111,npcID=208496,x=0.386,y=0.466}},coords={mapID=111,source="quest_giver",x=0.386,y=0.466667},questType="standard"},
[78072] = {id=78072,name="An Old Wound",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3703,mapID=111,description="<Beruun whispers to you.> There are ways, I'm sure you know, for the draenei to speak to the dead. It's not the same as having a loved one back but... Hataaru's ashes were taken to Auchindoun after the soulpriests reclaimed the temple. Maybe they might know a way to help Ataanya with her loss?",objectivesText="Speak to the soulpriests at Auchindoun.",starts={{mapID=111,npcID=208496,x=0.386,y=0.466}},ends={{mapID=108,npcID=210578,x=0.375,y=0.642}},coords={mapID=111,source="quest_giver",x=0.386,y=0.466},questType="standard"},
[78073] = {id=78073,name="Lingering Scars",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3519,mapID=108,description="I believe we may be able to help. But perhaps you could aid me first... When we received word that the Tishamaat was upon us, we hurried to prepare our most tortured spirits for the journey to the Exodar. The celebration's sacraments may help them rest peacefully. However, they must consent to being moved. So, we must commune with and soothe them first. Will you help calm these spirits? Afterward, I will take you to where Hataaru is entombed and give you what you seek.",objectivesText="Help Exarch Maladaar commune and soothe the spirits of Auchindoun. Progress: Your kindness may help these spirits find peace in death.",starts={{mapID=108,npcID=210578,x=0.375,y=0.642}},ends={{mapID=108,npcID=210581,x=0.415,y=0.616}},coords={mapID=108,source="quest_giver",x=0.375,y=0.642},questType="standard"},
[78074] = {id=78074,name="To See Clearly",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3519,mapID=108,description="Fortunately, not all of the fallen entombed here in Auchindoun suffer as these three do. Some ease gracefully into death, like soil settling after a rainfall. Exarch Hataaru is one such soul. Thanks be to the Light that he rests easy. Come, I will show you to his tomb.",objectivesText="Visit Exarch Hataaru's tomb and then return to Ataanya in Shattrath. Progress: <Ataanya crosses her arms tightly, not looking at you or Beruun.>",starts={{mapID=108,npcID=210581,x=0.415,y=0.616}},ends={{mapID=111,npcID=210569,x=0.388,y=0.465}},coords={mapID=108,source="quest_giver",x=0.415,y=0.616},questType="standard"},
[78075] = {id=78075,name="Moving Past",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3703,mapID=111,description="My mother died on a colony planet. My father and I helped each other move past that, but when he died in the siege of Shattrath, watching the walls of his greatest accomplishment crumble to dust... There was no one left for me. So I worked. And now I have the schematics of my own Shattrath. A better Shattrath. <Ataanya clenches the lens in her fist then exhales in resignation.> I'll go to the Exodar--but if Romuul says one word about it, I will make him eat his soldering tool.",objectivesText="Return to Grand Artificer Romuul in the Exodar.",starts={{mapID=111,npcID=210569,x=0.388,y=0.465}},ends={{mapID=103,npcID=210562,x=0.555,y=0.795}},coords={mapID=111,source="quest_giver",x=0.388,y=0.465},questType="standard"},
[78076] = {id=78076,name="Emergency Efforts",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3557,mapID=103,description="<name>! Velen told me I may find you here. He needs your assistance. The satyr that infest a nearby island have been ambushing draenei traveling for the Tishamaat. Velen and I have been attempting to solve the problem quietly. He does not wish to mobilize the vindicators and alarm his people on a day of sacrament. But, despite our efforts, the attacks have continued. The event may need to be canceled if we cannot get the demons under control. Come with me so we may end this threat.",objectivesText="Use the Argussian Mana Ray to fly to Bloodmyst Isle with Chieftain Hatuun .",starts={{mapID=103,npcID=210563,x=0.544,y=0.7716}},ends={{mapID=106,npcID=210390,x=0.52,y=0.755}},coords={mapID=103,source="quest_giver",x=0.544,y=0.7716},questType="standard"},
[78077] = {id=78077,name="Beneath the Skin",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3525,mapID=106,description="Arzaal and I are of the same mind. We must know the strength of these satyr before we attempt to drive them back with force. Else we may be walking into a fight we cannot win. I can learn much about my enemies by observing what damage they leave in their wake. The wildlife here was corrupted by the Exodar's lingering energies, but I suspect the demons' presence made it worse. Collect bones from the local wildlife for me. Studying them may give us some clues.",objectivesText="Collect 8 Pitted Bones from corrupted wildlife. Progress: Remember, you are putting them out of their misery.",starts={{mapID=106,npcID=210391,x=0.52,y=0.755}},ends={{mapID=106,npcID=210391,x=0.52,y=0.755}},coords={mapID=106,source="quest_giver",x=0.52,y=0.755},questType="standard"},
[78078] = {id=78078,name="Assessing the Enemy",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3525,mapID=106,description="The Legion may be one entity, but it is vast. The demons that comprise it are as varied as the innumerable worlds they have conquered. But I have had no dealings with satyr. From what the Prophet has told me, they seem disorganized. Intelligent certainly, but feral in their malevolence. I am inclined to believe their recent attacks are random, but perhaps not. Bring me the totems they have scattered across Bloodmyst. I may be able to ascertain what, if anything, their end goal is.",objectivesText="Collect 6 Satyr Totems . Progress: I would prefer to know the capabilities of the satyr before engaging them.",starts={{mapID=106,npcID=210588,x=0.52,y=0.755}},ends={{mapID=106,npcID=210588,x=0.52,y=0.755}},coords={mapID=106,source="quest_giver",x=0.52,y=0.755},questType="standard"},
[78079] = {id=78079,name="Excision",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3525,mapID=106,description="I cannot in good conscience gather the draenei for the Tishamaat if we are threatened this close to home. If one of the man'ari is using the satyr to orchestrate these attacks, or to distract us from some larger foul purpose, then they must be rooted out immediately. We will divide our efforts to look for signs of the enemy. Arzaal will search the northern satyr camp. You, Hatuun, and myself will search the closer camp.",objectivesText="Meet Velen and Hatuun in Nazzivian to search for signs of man'ari presence in the area.",starts={{mapID=106,npcID=210390,x=0.52,y=0.755}},ends={{mapID=106,npcID=210600,x=0.422,y=0.368}},coords={mapID=106,source="quest_giver",x=0.52,y=0.755},questType="standard"},
[78080] = {id=78080,name="At the Source",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3525,mapID=106,description="Can you hear that? The silence? The area is empty. Not even the rabid wildlife dare approach the camp. I do not see any immediate cause, but the fel resonance here is overwhelming. I sense it was woven by man'ari hands, but I'm being blocked from probing more deeply. Something is being hidden. It must be the cloaking magic Hatuun reported from the other camp that hinders me. I can dispel it, but I cannot guarantee what we will find when I do.",objectivesText="Discover the source of the fel concentration in Axxarien and destroy it. Progress: This ends here!",starts={{mapID=106,npcID=210598,x=0.422,y=0.365}},ends={{mapID=106,npcID=210605,x=0.415,y=0.33}},coords={mapID=106,source="quest_giver",x=0.422,y=0.365},questType="standard"},
[78081] = {id=78081,name="Pain Recedes",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3525,mapID=106,description="With Sironas slain once again, Bloodmyst will finally be able to heal. Her influence was no doubt anchoring the corruption to the land. It is another reason to celebrate today. But it is not the true reason I called Hatuun and Arzaal to Azeroth. I would have them attend the Tishamaat with us. The sacrament asks us to reflect on the past and commit to a better future. The unity of our efforts epitomizes that. I will bring them to the Exodar. Please join us when you are ready.",objectivesText="Meet with Prophet Velen in the Exodar.",starts={{mapID=106,npcID=210605,x=0.415,y=0.33}},ends={{mapID=103,npcID=214021,x=0.55,y=0.806}},coords={mapID=106,source="quest_giver",x=0.415,y=0.33},questType="standard"},
[78082] = {id=78082,name="A Burden Shared",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3557,mapID=103,description="The Tishamaat was once a solitary holiday. Each eredar would inscribe a stone with a painful memory we carried. We would reflect on what that memory could teach us then commit to moving forward with that wisdom. At last, the stones are dissolved in the Flame of Reprieve, symbolically removing the weight from our souls. Today, the Tishamaat will be celebrated not in solitude, but as a community. Gather the stones of those who would trust you with them then take them to the flame.",objectivesText="Collect 10 Memory Stones, create your own Memory Stone, and then dissolve the stones in the Flame of Reprieve. Progress: For many, this is the first Tishamaat they have participated in. For others, it is a distant memory.",starts={{mapID=103,npcID=214021,x=0.55,y=0.806}},ends={{mapID=103,npcID=212387,x=0.6452,y=0.8708}},coords={mapID=103,source="quest_giver",x=0.55,y=0.806},questType="standard"},
[78083] = {id=78083,name="Our Path Forward",level=50,requiredLevel=50,faction="alliance",expansion=10,zoneID=3557,mapID=103,description="Ah, I believe I hear the Prophet calling the attendants before the stage. I am curious to see what he and Romuul plan to announce now that everyone is gathered. We should make haste, yes?",objectivesText="Speak to Prophet Velen to begin the ceremony. Progress: The future is ours.",starts={{mapID=103,npcID=212387,x=0.6452,y=0.8708}},ends={{mapID=103,npcID=212402,x=0.5504,y=0.8084}},coords={mapID=103,source="quest_giver",x=0.6452,y=0.8708},questType="standard"},
[78102] = {id=78102,name="Canopy Concours",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.628,y=0.881,mapID=2200,npcID=210784}},ends={{x=0.628,y=0.881,mapID=2200,npcID=210784}},coords={mapID=2200,x=0.628,y=0.881},questType="standard"},
