[78586] = {id=78586,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78587] = {id=78587,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78588] = {id=78588,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78589] = {id=78589,name="Invasive Cuisine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Chef Dinaire .>",objectivesText="Deliver the Umbral Eggplant to Chef Dinaire at the Fungal Fields. Provided item:",ends={{npcID=206533,x=0.644,y=0.31,zoneID=14838}},coords={mapID=2215,source="quest_giver",x=0.644,y=0.31},questType="standard"},
[78591] = {id=78591,name="Getaway to Scenic Nagrand!",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=12,mapID=37,description="Today's special is a magical getaway to the great plains of Nagrand! If you're headed there, would you mind shooting a few animals? Oh, not like that! Here, borrow my camera. My friend Beatrice has been roaming around there lately. She would really appreciate some photographs, but I've got portals to attend to.",objectivesText="Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Beatrice. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.",starts={{mapID=37,npcID=212677,x=0.342,y=0.515}},ends={{mapID=37,npcID=212677,x=0.342,y=0.515}},coords={mapID=37,source="quest_giver",x=0.342,y=0.515},questType="standard"},
[78594] = {id=78594,name="Getaway to Scenic Feralas!",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=12,mapID=37,description="Today's special is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited! Unfortunately, some of the partygoers who took this portal earlier left their gifts here at the gala. Could you help me return them? Meet me at the beach and we'll figure out which gifts belong to whom.",objectivesText="Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.",starts={{mapID=37,npcID=212677,x=0.342,y=0.515}},ends={{mapID=37,npcID=212677,x=0.342,y=0.515}},coords={mapID=37,source="quest_giver",x=0.342,y=0.515},questType="standard"},
[78595] = {id=78595,name="Dream Infused",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="< Melsysra drops a slightly damp note into your hand.> <name>, your deeds have helped garner enough strength for a dream infusion ! Meet me at the Central Encampment so I can get it to you. - Elianna",objectivesText="Talk to Elianna in the Central Encampment.",starts={{mapID=2200,npcID=211962,x=0.496,y=0.622}},ends={{mapID=2200,npcID=211209,x=0.502,y=0.618}},coords={mapID=2200,source="quest_giver",x=0.496,y=0.622},questType="standard"},
[78596] = {id=78596,name="Summons to Lord Greymane",level=70,requiredLevel=70,faction="alliance",expansion=10,zoneID=1519,mapID=84,description="Greetings, Lord Greymane has requested your presence at Stormwind Harbor to assist him with a matter regarding Gilneas. That is all I am able to say. Good luck, <name>.",objectivesText="Meet with Genn Greymane at Stormwind Harbor.",starts={{mapID=84,npcID=212899,x=0.6248,y=0.7212}},ends={{mapID=84,npcID=214538,x=0.339,y=0.155667}},coords={mapID=84,source="quest_giver",x=0.6248,y=0.7212},questType="standard"},
[78597] = {id=78597,name="Clandestine Movements",level=70,requiredLevel=70,faction="horde",expansion=10,zoneID=130,mapID=85,description="<name>, Lilian Voss and Calia Menethil have requested your presence for a clandestine operation involving Gilneas. They will brief you in full when you arrive.",objectivesText="Meet with Lilian and Calia in Pyrewood Village in Silverpine Forest. Progress: Excellent, we've been waiting for you.",starts={{mapID=85,npcID=212916,x=0.523333,y=0.886}},ends={{mapID=21,npcID=210964,x=0.426,y=0.727}},coords={mapID=85,source="quest_giver",x=0.523333,y=0.886},questType="standard"},
[78598] = {id=78598,name="Dream Infusion",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=211209,x=0.502,y=0.618,mapID=2200}},ends={{npcID=211209,x=0.502,y=0.618,mapID=2200}},coords={x=0.502,y=0.618,source="quest_giver",mapID=2200},questType="standard"},
[78600] = {id=78600,name="Amirdrassil, the Dream's Hope: Up in Smoke",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14643,description="Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.",objectivesText="Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Normal difficulty. Progress: The energy found within these fragments will allow us to quickly access the Throne of the Firelord.",starts={{npcID=210016}},questType="raid"},
[78601] = {id=78601,name="Amirdrassil, the Dream's Hope: Up in Smoke",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14643,description="Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.",objectivesText="Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Heroic difficulty. Progress: The energy found within these fragments will allow us to quickly access the Throne of the Firelord.",starts={{npcID=210016}},questType="raid"},
[78602] = {id=78602,name="Amirdrassil, the Dream's Hope: Up in Smoke",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14643,description="Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.",objectivesText="Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Mythic difficulty. Progress: The energy found within these fragments will allow us to quickly access the Throne of the Firelord.",starts={{npcID=210016}},questType="raid"},
[78608] = {id=78608,name="Geothermal Jaunt",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.541,y=0.154,mapID=114,npcID=213086}},ends={{x=0.541,y=0.154,mapID=114,npcID=213086}},coords={mapID=114,x=0.541,y=0.154},questType="standard"},
[78609] = {id=78609,name="Geothermal Jaunt - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.541,y=0.154,mapID=114,npcID=213086}},ends={{x=0.541,y=0.154,mapID=114,npcID=213086}},coords={mapID=114,x=0.541,y=0.154},questType="standard"},
[78610] = {id=78610,name="Geothermal Jaunt - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.541,y=0.154,mapID=114,npcID=213086}},ends={{x=0.541,y=0.154,mapID=114,npcID=213086}},coords={mapID=114,x=0.541,y=0.154},questType="standard"},
[78614] = {id=78614,name="Mereldar's Light",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I still need more time with Alleria to learn about Xal'atath. What I have learned is very worrying. Faerin sent word that she was going to the orphanage, and asked you to meet her there. She often entertains the children while she is in Mereldar, I don't doubt she would appreciate you doing the same.",objectivesText="Play with 3 Arathi Orphans . Progress: It's great to see how happy these kids are, after what they have gone through.",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=220124,x=0.426,y=0.556,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="standard"},
[78615] = {id=78615,name="The Bell Tolls",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Those bells mean Mereldar is under attack! Let's get to the gates and find out what is going on.",objectivesText="Go to the main gates of Mereldar in Hallowfall .",starts={{npcID=220124,x=0.426,y=0.556,zoneID=14838}},ends={{npcID=213107,x=0.41,y=0.546,zoneID=14838}},coords={x=0.426,y=0.556,source="quest_giver",zoneID=14838},questType="standard"},
[78621] = {id=78621,name="The Shadow Rising",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I can sense three beacons of void ahead, all funneling their power into one massive font of darkness. You will need to kill them. With them dead, I can bring down the shield.",objectivesText="Kill the kobyss deepspeakers in the Veneration Grounds in Hallowfall . Progress: I'm ready to end this.",starts={{npcID=214402,x=0.41,y=0.546,zoneID=14838}},ends={{npcID=214402,x=0.41,y=0.546,zoneID=14838}},coords={x=0.41,y=0.546,source="quest_giver",zoneID=14838},questType="standard"},
[78626] = {id=78626,name="Spar Day",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Your skills in combat are impressive, . We are rotating our next round of reserves into active duty, and they need to sharpen their skills. While Alleria fills me in on Xal'atath, I would appreciate it if you could help with their training.",objectivesText="Duel 8 Arathi Recruits in Mereldar. Progress: The tricks they learn from you today will help them survive a difficult encounter later.",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="standard"},
[78631] = {id=78631,name="Speaking to the Speakers",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I've heard about a problem nearby, and I think I know what's wrong. We used to have a mining operation northeast of Gundargaz. When we moved out, kobolds moved in. We haven't heard from those kobolds in a long time, but it sounds like they're raiding us now! And the High Speaker is doing nothing about it. Someone has to do something. If we can solve this, more Machine Speakers will listen to us. If the High Speaker doesn't get results, we will.",objectivesText="Reassure Gundargaz' defenders on the way to the Lost Mines.",starts={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.472,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[78634] = {id=78634,name="Leave No Stone Behind",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Many earthen fell when the kobolds took this mine. Worse, those who fell were left to crumble where they dropped. There was no attempt to recover them. We couldn't provide closure or respect their memories. Why? Why did we forsake the fallen? We will not fail them again, . Gather the identification plaques of those we lost, so we may commemorate them properly.",objectivesText="Recover Identification Plaques from fallen earthen in the Lost Mines. Progress: Have you found them?",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78635] = {id=78635,name="Death and Waxes",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Kobolds take candles seriously. Wax, even more. More important than gold. More important than freedom! We steal candles from Candle King. We make him look weak. Bully that looks weak loses control. Gets dead! Also means we not have to wait out here in dark until get eaten. Hurry!",objectivesText="Recover Flickerflame Candles from around the Lost Mines. Progress: Did you take candle?",starts={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78636] = {id=78636,name="Retaking the Mines",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Now that we have the keys, it is time to take the fight to the Candle King. Get that gate open. Once we're inside, we'll move on to the next step.",objectivesText="Unlock the gate to the Lost Mines.",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=215671,x=0.594,y=0.218,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78637] = {id=78637,name="Cracking Cogchewer",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Cogchewer is muscle for Candle King. So mean! Rebuilds earthen gears for wars. Also in charge of mine's defenses. Need his keys to get in the mines... and get me out of this thing!",objectivesText="Kill Cogchewer in the Lost Mines and recover his keys. Progress: Did you find keys?",starts={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78638] = {id=78638,name="Engineering Destruction",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Some of the kobolds are retrofitting equipment left behind when the mines fell. Please, destroy the rigs before they're used against us. I'd rather they be scrap than in the hands of an enemy. There was a storage depot on the western edge of the lowest level of the mine. Start there.",objectivesText="Destroy mining rigs in the Lost Mines. Progress: Are any still operable, <name>?",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78639] = {id=78639,name="Ko-boldening",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Bullies everywhere! Innocent kobolds kept down by Candle King's thugs all across Warrens. Give bullies taste of own medicine! Once bullies beaten, innocent have chance to run. Be free!",objectivesText="Free oppressed kobolds in the Warrens by defeating their captors. Progress: Now they will see what it feels like!",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[78640] = {id=78640,name="Manifesto Destiny",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Before take mines, my people live in great city. Stoneheads call it the Warrens. Candle King's bullies run it now. We need see what we are fighting. Let kobolds know we here to help! Better choices than Candle King. What better way than pamphlets? Everyone love pamphlet! We draw real good! Brinthe say you have some sort of flying dragon-bird-thing? Perfect for scout! Perfect for dropping pamphlets! Skitter looks at you expectantly, making small flapping motions as she waits.>",objectivesText="Scout out and distribute pamphlets across the Warrens from the air. Progress: Never flown before. Is fun?",starts={{npcID=215672,x=0.594,y=0.218,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.594,y=0.218,source="quest_giver",zoneID=14795},questType="standard"},
[78641] = {id=78641,name="Tackling Torchsnarl",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Torchsnarl runs Warrens for Candle King. Nothing but big bully! Very, very big bully. We show everyone. Bullies can be beaten!",objectivesText="Defeat Torchsnarl in the Warrens. Progress: Torchsnarl is big one. Don't know why hiding behind flunkies. Still, can't miss him!",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[78642] = {id=78642,name="New Candle, New Hope",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We weaken Candle King's grasp. Still need symbol, rally my people. King has ancient relic: symbol of hope. Called Candle Crown . Heart of my people. Candle King threw away! Found new prize: Darkflame Candle. That crown? Still in hoard. Candle King should come out now. See what we did here! While he looks, we sneak in! Use old tunnels! Take what's ours! We smart.",objectivesText="Recover the Candle Crown from the Darkflame Cleft. Progress: We take hope from darkness, <name>.",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[78646] = {id=78646,name="Fire Watch",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="My mother seems unable to fully attune with the Eye. Perhaps it senses her ties to Ardenweald... Her shield is but a fraction of the Eye's power. If she was fully attuned, she could completely quench our foes' flames. But we cannot idly wait. We still need more information about Galok and his plan of attack. Bodwin indicates there is new flurry of activity in Igira's base of operations. With Bodwin's help, we can investigate without being seen.",objectivesText="Regroup with Merithra at the edge of Eye of Ysera, overlooking Slagfell Hold.",starts={{mapID=2200,npcID=206406,x=0.5225,y=0.2785}},ends={{mapID=2200,npcID=206406,x=0.5225,y=0.2785}},coords={mapID=2200,source="quest_giver",x=0.5225,y=0.2785},questType="standard"},
[78655] = {id=78655,name="Adaptive Cooling Salve",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13645,mapID=2023,description="Should you need my assistance, I can craft you an ointment that should prove helpful in your attunement with Fyr'alath. Bring me the materials I don't have, and I'm sure I can put something together.",objectivesText="Bring Erden Zaralek Glowspores , Awakened Frost , and a Dreaming Essence for the Adaptive Cooling Salve . Progress: Keep at it. All this hard work is going to pay off.",starts={{mapID=2023,npcID=194842,x=0.824,y=0.505}},ends={{mapID=2023,npcID=194842,x=0.824,y=0.505}},coords={mapID=2023,source="quest_giver",x=0.824,y=0.505},questType="standard"},
[78656] = {id=78656,name="Hose It Down",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="With the flame restored, you can see the extent of contamination to the fishing hole. Kobyss and frogs have left heaps of strange goo that pollutes the shoreline. We need your help to clean up this gooey blight! I have a specially modified harvester equipped with a water barrel. Use this device to spray water on the goo piles and clean the shore of this contamination.",objectivesText="Activate Baeny the Barrel and use the hose to wash away 40 Contaminating Goo. Progress: Have you cleaned up the shoreline?",starts={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},ends={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},coords={x=0.658,y=0.244,source="quest_giver",zoneID=14838},questType="standard"},
[78658] = {id=78658,name="The Hallowed Path",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2214,description="$p, I'm glad our paths have crossed. Adelgonn has been telling me about a cavern called Hallowfall . She's told me the people there are called the Arathi. I cannot imagine that they are related to the ancient human kingdom, but it can't be a coincidence. Adelgonn's people had fruitful contact with them some time ago. Whatever happened, I hope to repair that relationship and gain their aid. Please meet me at the Hallowfall Gate.",objectivesText="Meet with the denizens of Hallowfall . Progress: Who are you?",starts={{npcID=213983,x=0.47,y=0.322,zoneID=14795}},ends={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},coords={x=0.47,y=0.322,source="quest_giver",zoneID=14795},questType="standard"},
[78659] = {id=78659,name="Where the Light Touches",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Many in Hallowfall will call you \"outsider\". I would call you friend. I would also ask for your help, if you are no stranger to combat. Desperate times forge strong friendships. General Steelstrike ordered the army to fall back from the nerubian onslaught. In doing so, she abandoned a Lamplighter and many troops to the darkness. I may not be able to save them on my own, but with your help I may succeed. If you're willing, ride with me or meet me there.",objectivesText="Meet with Faerin's ally near the Aegis Wall.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78664] = {id=78664,name="The Gift of Self-Care",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=12,mapID=37,description="The eyes of a tired adventurer. A <class> that does many great deeds for many people. When was the last time you did a kind gesture for yourself? Perhaps now is the time. Look into your heart. What do YOU desire?",objectivesText="Speak with Ying to discover your heart's desire. Progress: Love is a blessing, especially if it comes from within.",starts={{mapID=37,npcID=213262,x=0.35,y=0.505}},ends={{mapID=37,npcID=213262,x=0.35,y=0.505}},coords={mapID=37,source="quest_giver",x=0.35,y=0.505},questType="standard"},
[78665] = {id=78665,name="Tunnel Trouble",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14752,mapID=2215,description="It's good to have new allies here. Together, we have much better chances of protecting this tower. The nerubians have overwhelmed us. If we're going to have any chance against them, we need to destroy the burrows they're using to come under the Wall. If you can handle that, we will survey the field from the top of the wall and meet you there.",objectivesText="Destroy 6 Nerubian Burrows . Progress: Were you able to stop the nerubians from coming under the ground?",starts={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},ends={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},coords={x=0.7,y=0.612,source="quest_giver",zoneID=14838},questType="standard"},
[78666] = {id=78666,name="The Only Good Spider",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="$p, if we don't stem the tide of nerubians climbing up to us, nothing else will matter. Their numbers are just too great. We need to delay their onslaught to buy the people of Hallowfall time to prepare. The wall still serves as a very effective chokepoint. Do what you can to thin their numbers.",objectivesText="Kill 12 Nerubian attackers. Progress: <name>, every nerubian you kill here could mean a life saved in Hallowfall , and aids the chances of our own success.",starts={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},ends={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},coords={x=0.7,y=0.612,source="quest_giver",zoneID=14838},questType="standard"},
[78667] = {id=78667,name="Rekindled Memories",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Good people died here today, $p--a lot of them. Every Arathi soldier carries a tinderbox. It represents their devotion to the Sacred Flame. Many use it as a focus to bring forth the Flame's light. In the dark places beyond the light of Beledar, the Sacred Flame brings hope. With the nerubian attack, we can't recover their bodies. So we must retrieve these symbols, to venerate their sacrifice. Then use this torch to burn their bodies. It's the best funeral we can offer.",objectivesText="Recover 6 Arathi tinderboxes from fallen soldiers and burn their bodies. Progress: Have you recovered their tinderboxes? Every life deserves to be remembered in the Sacred Flame.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78668] = {id=78668,name="Rally on the Dawnbreaker",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="It's critical, with so many nerubians pouring through the Aegis Wall, that we defend our airships docked at Tenir's Ascent. The nerubians have always outnumbered us, but our fleet allows us to concentrate our defenders where they are attacking, as well as allowing us to bombard them from the safety of the skies. If we lose our armada, our hopes fade dramatically. Meet us there when you can.",objectivesText="Meet Faerin at Tenir's Ascent aboard the Dawnbreaker.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=224945,x=0.574,y=0.644,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78669] = {id=78669,name="For Their Eyes Only",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="We've fought the nerubians since we arrived, $p. Their attacks have not risen to this level in a long time. These airship docks are clearly a target, but do they have any others? Is there a larger goal? The nerubians carry shadecasters with orders from their queen. We need to learn what we can of their plans and intentions, and recovering a few of those shadecasters is the best way we can do so.",objectivesText="Gather 3 nerubian Shadecasters to learn their plans. Progress: Have you found any of those shadecasters yet, <name>?",starts={{npcID=224946,x=0.574,y=0.644,zoneID=14838}},ends={{npcID=213120,x=0.568,y=0.682,zoneID=14838}},coords={x=0.574,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[78670] = {id=78670,name="Siege Weapon Sabotage",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="$p, if we're going to hold the nerubians back, we have to deal with their siege weapons. Around Tenir's Ascent, there are kegs of black powder to supply our ships for combat. Since the nerubians have caught these ships on the ground, let's put that powder to work. Gather some barrels, and take them down to the nerubian siege weapons.",objectivesText="Destroy 4 siege weapons below Tenir's Ascent. Progress: Were you able to destroy their siege weapons, <name>?",starts={{npcID=224945,x=0.574,y=0.644,zoneID=14838}},ends={{npcID=213120,x=0.568,y=0.682,zoneID=14838}},coords={x=0.574,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[78671] = {id=78671,name="The Light of the Dawntower",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="$p, Faerin went to light the dawntower. She said it keeps the light of the Sacred Flame shining upon Hallowfall . Kyron is there as well. It's hard to imagine that any beacon could outshine their star Beledar, but I am eager to see this new expression of the Light. Meet me by the dawntower and we can see how the Sacred Flame of the Arathi helps to safeguard these long-lost cousins of mine.",objectivesText="Assist the Lamplighters in lighting the dawntower.",starts={{npcID=213120,x=0.568,y=0.682,zoneID=14838}},ends={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},coords={x=0.568,y=0.682,source="quest_giver",zoneID=14838},questType="standard"},
[78672] = {id=78672,name="A Lamplighter's Duty",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Darkness has fallen. We can't rest yet. Faerin gives you a weary smile, but there is a light in her eyes.> The light from the tower will hold the worst dangers in the darkness at bay. It's my duty, as a Lamplighter, to keep all the towers blazing. My patrol takes me to Lorel's Crossing by air next. I would welcome you and Anduin at my side, for all our sakes.",objectivesText="Take the Lamplighter Skiff to Lorel's Crossing.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=214378,x=0.538,y=0.314,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78674] = {id=78674,name="The Gift of Relief",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=12,mapID=37,description="You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. I saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. Perhaps he has insight to teach you.",objectivesText="Speak to Simeon Griswold at the Gala of Gifts, then relieve your stress in Old Town. Progress: I've seen men die of stress. You don't want to bottle it up every day.",starts={{mapID=37,npcID=213262,x=0.35,y=0.505}},ends={{mapID=37,npcID=213294,x=0.338,y=0.505}},coords={mapID=37,source="quest_giver",x=0.35,y=0.505},questType="standard"},
[78686] = {id=78686,name="Lights Out",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Name's Aegor. I try to keep tabs on Lamplighters in the field and assess what areas of Hallowfall may be in need of their aid. The dawntower fell dark at Velhan's Claim a few weeks ago. Based on what's been happening around Hallowfall , it's probably because of the rising tide of kobyss. Lamplighters Taenar and Aemyra are heading there, but this might be more than even two Lamplighters together can handle. Will you meet them there and help them restore the light at Velhan's Claim?",objectivesText="Meet Taenar and Aemyra near Velhan's Claim.",starts={{npcID=214019,x=0.492,y=0.41,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.492,y=0.41,source="quest_giver",zoneID=14838},questType="standard"},
[78687] = {id=78687,name="Crash Recovery",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="A lot of things went wrong when the Indomitable crashed, $p. But the most upsetting one is that--when the order was finally given to make our way back to Mereldar, we couldn't honor our fallen comrades. It seems the kobyss reanimated our fallen stalwarts, who now wander the Indomitable in a ghastly skeletal form. Take back their tinderboxes. If we can deliver those to the Sacred Flame, they'll finally be free after all these years.",objectivesText="Retrieve 4 Recovered Tinderboxes from the Indomitable's stalwarts. Progress: Did you find those tinderboxes, <name>?",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78688] = {id=78688,name="Cage, Match",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="When we were scouting before you arrived, we saw a lot of cages set up around Velhan's Claim. Typically, the kobyss use these to hold their victims until they're needed for a ritual sacrifice. Those sacrifices lead to... lots of other dark activities. Not the least of which is eating the victims. Let's get ahead of all that. Take my torch, and destroy the cages, so we don't have to see that happen to anyone from Velhan's Claim.",objectivesText="Burn 10 kobyss cages with Aemyra's Holy Flame. Progress: Have you dealt with those cages yet? The citizens of Velhan's Claim won't be safe until you do.",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78689] = {id=78689,name="If It Leads, It Bleeds",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Everything rises and falls on leadership, $p. With a good leader, a unit can achieve almost anything. With a bad leader, chaos ensues and success moves out of reach. I've seen that first-hand. Without leaders, the kobyss siege will break like a wave and everything else we do here becomes easier. I've seen three kobyss who seem to be leading the others--let me mark their locations on your map. Deal with them, and we'll be much more able to help Velhan's Claim.",objectivesText="Defeat the kobyss leaders besieging Velhan's Claim. Progress: Did you find their leaders? They look strong, but I'm sure you're up to the task.",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78690] = {id=78690,name="Situational Awareness",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Regardless of what history Taenar and Velhan have between them, we need to take care of the people here at Velhan's Claim. $p, will you please check in with the families here? Let them know we're here to help. See if they're worried or need anything. And reassure them that the Lamplighters will drive back the kobyss.",objectivesText="Speak with 10 citizens of Velhan's Claim. Progress: It's so important to reassure the citizens of Velhan's Claim, <name>, that they'll get through this. Hope is everything in dark times.",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78691] = {id=78691,name="The One That Got Away",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="$p, my son is out with the kobyss. He convinced the other kids they should sneak out with him to fight. Said they should, \"be brave like my dad\". When they met a kobyss, the others all ran back here, while he ran toward the crashed ship, to lead it away. I have not handled myself bravely, $p. The story of the Indomitable says I was a hero; those lies were my report. If there was ever a time to step up, it's now. But I'm no match for the kobyss alone. Come with me, $p--help me save Maximillian.",objectivesText="Rescue Maximillian at the crash of the Indomitable. Progress: Stay focused, <name>--we have to find my son.",starts={{npcID=213787,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213787,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78692] = {id=78692,name="Teach a Man to Fish",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="$p, the people of Velhan's Claim have been locked up inside, afraid of the dark, for too long. And there's plenty to fear out there, but these are capable, strong people. They should be driving the kobyss away, not hiding behind their walls. Get these spears to the people of Velhan's Claim. They've learned to hide from their problems, but we'll give them the means to take their lives back!",objectivesText="Distribute 8 spears to the residents of Velhan's Claim. Progress: Have you handed out those spears yet? The people need them to remind them what they're capable of.",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78693] = {id=78693,name="Spears for Fears",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="It seems Velhan and his followers hoped they could live in peace here. They were so sure they could, in fact, that they didn't bring any weapons with them. This is a problem, with the kobyss attacking now, but the kobyss can actually solve it for us. They've brought plenty of spears for their siege on Velhan's Claim, and a spear will skewer a kobyss just as well as a human. Head out there and gather some spears for the people, $p, and they won't have to be so afraid.",objectivesText="Gather 8 Kobyss Spears for the people of Velhan's Claim. Progress: Kobyss giving you trouble? Soon, the people of Velhan's Claim will be the ones giving them trouble.",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78694] = {id=78694,name="Reclaiming Velhan's Claim",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The problem I see, $p, is the kobyss. There's just so many of them. Everyone here was serving in the Empire's military when we arrived in Hallowfall . They may be rusty now, but they've all trained before, and know how to be dangerous. But we need to eliminate every disadvantage, including the kobyss numbers. So head out there and even up the numbers. Aemyra and I will keep everyone safe here.",objectivesText="Kill 12 Kobyss warriors around Velhan's Claim. Progress: How's it going out there, <name>? You sending those creatures of darkness back to the deeps?",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78695] = {id=78695,name="Lamp Lit",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The kobyss normally live deep underwater, $p. When Beledar is at its brightest, they don't bother us. Other sources of bright light will usually keep them away, but definitely weaken them. As Lamplighters, we not only go into the dark to protect those in need, but we provide them the light that will keep them safe. Go set up these torches along the perimeter, then meet us up at the dawntower behind Velhan's Claim.",objectivesText="Place 8 torches around the perimeter of Velhan's Claim, then observe the re-lighting of the dawntower. Progress: Did you get those torches set, <name>? The people will be able to quickly light them whenever Beledar fades.",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213787,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78714] = {id=78714,name="A Poor Reception",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=81,description="There's strong evidence that the Radiant Song is a warning from Azeroth herself. A cry for help. That's why we're here. If this vision truly is Azeroth's message, Magni will know what she's trying to tell us. He should be in the Chamber of the Heart. Let's go.",objectivesText="Go to the Heart Chamber to ask Magni for help deciphering the Radiant Song.",starts={{npcID=213620,x=0.418,y=0.45,zoneID=1377}},ends={{mapID=81,npcID=213620,x=0.418,y=0.45}},coords={x=0.418,y=0.45,source="quest_giver",zoneID=1377},questType="standard"},
[78715] = {id=78715,name="Azeroth's Voice",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=1377,mapID=81,description="I haven't spoken with Azeroth for years. At first I just didn't feel the need. Then I realized I had started to resent her. For leaving me like... this. And now I'm not sure if I can. But I know the stakes. This Radiant Song of hers foretells something dire. And we need to know what. First, we need to prepare the Heart Chamber. Can ye start up the consoles nearby?",objectivesText="Help Magni perform his ritual. Progress: I understand Magni's concerns, but we have no other choice. The future of our world is at stake. We must try everything we can to understand what Azeroth is trying to warn us of.",starts={{x=0.501,y=0.644,mapID=2321,npcID=213624}},ends={{npcID=213625,x=0.418,y=0.45,zoneID=1377}},coords={mapID=81,source="quest_giver",x=0.418,y=0.45},questType="standard"},
[78716] = {id=78716,name="Painful Lessons",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=81,description="Magni appears stable for now, but he's still not responsive. We need to get him treatment quickly. I'll open a portal to Dalaran . Follow us when you can.",objectivesText="Take the portal to Dalaran .",starts={{npcID=213625,x=0.418,y=0.45,zoneID=1377}},ends={{mapID=81,npcID=213625,x=0.418,y=0.45}},coords={x=0.418,y=0.45,source="quest_giver",zoneID=1377},questType="standard"},
[78717] = {id=78717,name="A Mysterious Warning",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin. I saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us. That's what we need to protect.",objectivesText="Discuss the next steps, then follow up with Khadgar. Progress: Khaz Algar...",starts={{x=0.453,y=0.574,mapID=627,npcID=213624}},ends={{x=0.453,y=0.574,mapID=627,npcID=213624}},coords={mapID=627,x=0.453,y=0.574},questType="standard"},
[78718] = {id=78718,name="Strengthen the Wards",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst. Here, take this wand. It's been attuned with Dalaran 's defense magics. Just wave it near strategic parts of the city to strengthen our magical defenses.",objectivesText="Strengthen Dalaran 's defenses. Progress: We will be hard pressed to save Khaz Algar if our own defenses aren't strong enough to withstand attack.",starts={{x=0.564,y=0.332,mapID=627,npcID=214665}},ends={{x=0.564,y=0.332,mapID=627,npcID=214665}},coords={mapID=627,x=0.564,y=0.332},questType="standard"},
[78719] = {id=78719,name="Citizens of Dalaran",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Our citizens must be prepared for Dalaran 's departure. Can you ask around the city and see if anyone requires aid? I'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.",objectivesText="Help the citizens of Dalaran prepare for the teleportation. Progress: Dalaran is always ready to defend the world, but that doesn't mean we can do so on a whim. Preparations are key to a smooth transportation.",starts={{x=0.412,y=0.623,mapID=627,npcID=213627}},ends={{x=0.412,y=0.623,mapID=627,npcID=213627}},coords={mapID=627,x=0.412,y=0.623},questType="standard"},
[78721] = {id=78721,name="Meet the Team",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. They're calling themselves the Algari Expedition this time around. I'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?",objectivesText="Check in on the Algari Expedition. Progress: A league and an expedition walk into a tavern... Nope, nothing's coming to me.",starts={{x=0.47,y=0.491,mapID=627,npcID=214669}},ends={{x=0.47,y=0.491,mapID=627,npcID=214669}},coords={mapID=627,x=0.47,y=0.491},questType="standard"},
[78722] = {id=78722,name="To Khaz Algar!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out. Let me know when you're ready to depart.",objectivesText="Tell Khadgar you're ready to depart.",starts={{x=0.412,y=0.623,mapID=627,npcID=213627}},ends={{npcID=214908,x=0.502,y=0.504,mapID=2305}},coords={mapID=627,x=0.412,y=0.623},questType="standard"},
[78724] = {id=78724,name="Loving Yourself, Your Way",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=12,mapID=37,description="If it's a challenge you're after, I think I have an idea. I saw a boastful champion heading toward Goldshire. You could challenge him to a duel. This would satisfy your desire and perhaps teach him a valuable lesson in humility.",objectivesText="Defeat Matley Graston in a duel near Goldshire. Progress: How fares your challenge?",starts={{mapID=37,npcID=213262,x=0.35,y=0.505}},ends={{mapID=37,npcID=213262,x=0.35,y=0.505}},coords={mapID=37,source="quest_giver",x=0.35,y=0.505},questType="standard"},
[78726] = {id=78726,name="Loving Yourself, Your Way",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=12,mapID=37,description="A full belly is a happy belly! There is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?",objectivesText="Consume treat packages from vendors at the Gala of Gifts. Progress: Have you had your fill of treats? I love the fruits, myself.",starts={{mapID=37,npcID=213262,x=0.35,y=0.505}},ends={{mapID=37,npcID=213262,x=0.35,y=0.505}},coords={mapID=37,source="quest_giver",x=0.35,y=0.505},questType="standard"},
[78727] = {id=78727,name="Loving Yourself, Your Way",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=12,mapID=37,description="While visiting this gala, I am staying at the Lion's Pride Inn at Goldshire. I hear they have some extra beds upstairs. Why not see if you can sleep there for a while? I think I will have a bit of a rest too... Right... here...",objectivesText="Take a nap in the upstairs guest room at the Lion's Pride Inn. Progress: < Ying is quietly snoring.>",starts={{mapID=37,npcID=213262,x=0.35,y=0.505}},ends={{mapID=37,npcID=213262,x=0.35,y=0.505}},coords={mapID=37,source="quest_giver",x=0.35,y=0.505},questType="standard"},
[78729] = {id=78729,name="Raising a Stink",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=12,mapID=21,description="Those clues add up to an ugly story, <name>. That map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic. I've got a guy that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.",objectivesText="Meet Inspector Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.",starts={{npcID=213560}},ends={{mapID=21,npcID=38066,x=0.458,y=0.685}},coords={mapID=21,source="quest_giver",x=0.458,y=0.685},questType="standard"},
[78738] = {id=78738,name="Absent Speaker",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="It is a dark day for the Ringing Deeps , $p. I always knew there was something about the High Speaker that wasn't quite right. Now we have proof. And we need justice. If he has plans for the Awakening Machine, then we've got to stop him.",objectivesText="Meet Speaker Brinthe in the Earthenworks.",starts={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},ends={{npcID=213569,x=0.47,y=0.206,zoneID=14795}},coords={x=0.472,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[78741] = {id=78741,name="Sympathetic Speakers",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I have to stop the High Speaker from making more skardyn. Machine Speaker protocol dictates that one of the foremen in this area should have a key to the Hall of Awakening. Come with me, and we'll track it down!",objectivesText="Look for Machine Speaker Foremen in the Earthenworks with Speaker Brinthe .",starts={{npcID=213569,x=0.47,y=0.206,zoneID=14795}},ends={{npcID=219428,x=0.49,y=0.172,zoneID=14795}},coords={x=0.47,y=0.206,source="quest_giver",zoneID=14795},questType="standard"},
[78742] = {id=78742,name="Battle of the Earthenworks",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="$p! There's a battle afoot! We need to assist Machine Speakers loyal to our cause and move against anyone defending the High Speaker. I'm going to remain and make plans with Adelgonn. I need you to lead our forces while we're containing consequences of the High Speaker's actions in the Earthenworks. This is our first step in deposing him. We're putting a stop to his horrendous crimes once and for all. What do you say, $p? Up for a scrap?",objectivesText="Defeat enemy Machine Speakers, constructs, and help frightened workers in the Earthenworks! Progress: I'll admit: the ability to acquire an army at the drop of a hat has gotten me fairly far in life.",starts={{npcID=213763,x=0.47,y=0.206,zoneID=14795}},ends={{npcID=213763,x=0.47,y=0.206,zoneID=14795}},coords={x=0.47,y=0.206,source="quest_giver",zoneID=14795},questType="standard"},
[78743] = {id=78743,name="Before I Depart",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="I can feel my energy reserves depleting. I will soon not be able to execute my duties. That is why I have Urtago here to take over. Before my systems grind to a halt, I must make sure Mourning Rise is free of kobolds. They have invaded the memorial site I tend and plunder the Unbound shrines and bodies that are there. Maybe it is good you are here. You may have the strength to help us. Please, help Urtago rid the site of kobolds.",objectivesText="Meet Urtago at the Mourning Rise memorial site.",starts={{npcID=213184,x=0.574,y=0.43,zoneID=14717}},ends={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},coords={x=0.574,y=0.43,source="quest_giver",zoneID=14717},questType="standard"},
[78744] = {id=78744,name="Honor Their Memories",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Take these gifts and place them by the past caretakers. Each is a gift honoring their memory. I'd also like us to perform some light groundskeeping to at least maintain the site. Unfortunately, what these kobolds are doing to the memorials will take us weeks to fix. Please do what you can about the kobolds. It would be unwise to leave the gifts unguarded while they are still roaming the area.",objectivesText="Eliminate the kobold infestation and place gifts near the shut-down, past caretakers. Progress: The kobolds cannot be left to desecrate Mourning Rise. The Unbound that rest here are here because they do not want to be disturbed or moved. While they do not wish to be revived, taking their armor and possessions is an insult to earthen culture. We must do something.",starts={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},ends={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},coords={x=0.616,y=0.416,source="quest_giver",zoneID=14717},questType="standard"},
[78745] = {id=78745,name="You No Take Plunder!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="It looks like the kobolds have taken gems and other... body parts off these shutdown earthen. Abominable. Find where the kobolds are holding their plunder, and bring it back to me so I can return it to its rightful place later. This vandalism will not go unchecked!",objectivesText="Recover earthen belongings from piles of plunder. Progress: Were you able to find their plunder?",starts={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.616,y=0.416,source="quest_giver",zoneID=14717},questType="standard"},
[78746] = {id=78746,name="Laws Apply to All",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Desecrating a memorial site is one of our greatest taboos in earthen society. This site is a window to our past, into our memories, and a place of self-reflection where we can commune with those who are no longer here. Still, so many of these kobolds infest Mourning Rise. For their crimes, the kobolds deserve the harshest punishment. They must be culled even further.",objectivesText="Slay kobold invaders in Mourning Rise. Progress: So many of them still infest Mourning Rise.",starts={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.616,y=0.416,source="quest_giver",zoneID=14717},questType="standard"},
[78747] = {id=78747,name="The Great Collapse",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Now that we landed a mighty blow, it is time to make sure that we block their tunnels so they cannot come back. Remember the stuff that Korgran asked about? Explosive sticks --his recipe. I have brought enough to shake a mountain! More than enough for the kobolds. Help me show these kobolds that we will fight for what is ours so they will never come back!",objectivesText="Use the Explosive sticks to destroy Kobold tunnels . Progress: Is it done? Were the tunnels dealt with?",starts={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=14717},questType="standard"},
[78748] = {id=78748,name="Cutting the Wick",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Knowing kobolds, they will have several workmasters, or leaders, running this raid. Find and eliminate these so-called \"workmasters.\" The rest of them will get disorganized, forget why they are here, and hopefully leave us alone.",objectivesText="Find and slay the kobold workmasters. Progress: Were you able to slay all three of them? Their deaths will strike a significant blow to this kobold operation.",starts={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=14717},questType="standard"},
[78749] = {id=78749,name="Who Runs This Fine Establishment?",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="While you were dealing with the tunnels and the workmasters, I saw a peculiar kobold go into a cave to the northwest. The kobolds seemed to respect him more than the others, calling him Grand-Heister Bokk and offering him the food you call \"cheese.\" This makes me think he is the real mastermind. If that kobold is in fact the real Ward of this operation, then we should take the opportunity to strike him down. I will meet you at this cave.",objectivesText="Slay Grand-Heister Bokk .",starts={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},ends={{npcID=213187,x=0.574,y=0.43,zoneID=14717}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=14717},questType="standard"},
[78754] = {id=78754,name="Lost Delivery",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Gundargaz Courier Express EXPEDITED To: Harvester Farnee Durgaz Cabin OPEN WITH CARE: Contains volatile elemental minerals.",objectivesText="Deliver the Abandoned Package to Harvester Farnee at Durgaz Cabin.",starts={{npcID=423987,x=0.555,y=0.565,zoneID=14717}},ends={{npcID=214640,x=0.67,y=0.438,zoneID=14717}},coords={x=0.555,y=0.565,source="quest_giver",zoneID=14717},questType="standard"},
[78755] = {id=78755,name="Playing in the Mud",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Remember when we used that clay and the fire honey to patch up Shalehoof? Let's do that again but bigger! Problem is we've run out of clay. But fortunately, with all the recent seismic activity, a whole avalanche of elementals has been roused out of torpor and are clashing on the eastern beach! Bring me wet, elementally charged silt to use as our restorative substrate!",objectivesText="Gather 20 handfuls of Elementally Charged Silt . Progress: By combining living sand and water, we can create an elemental silt that mimics the underclay's healing properties. Or at least something that comes close to it! Isn't elemental fusion fascinating?",starts={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},ends={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},coords={x=0.67,y=0.474,source="quest_giver",zoneID=14717},questType="standard"},
[78756] = {id=78756,name="Lots and Lots of Fire Honey",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="If Harmot wants to patch this sleeping boulder up and get him out of my pond, I'm all for it. Unfortunately, we used the last of my store of fire honey on Shalehoof's wound. I haven't had time to harvest any from the Cinderwold with all these elementals running amok. Head on down to the wold's edge and bring us some honey. You're going to need a lot.",objectivesText="Find a lot of Fire Honey. Progress: Mind yourself in my forest. Cinderbees are dangerous, but we rely on them for the honey they produce for our mead.",starts={{npcID=214922,x=0.67,y=0.472,zoneID=14717}},ends={{npcID=214922,x=0.67,y=0.472,zoneID=14717}},coords={x=0.67,y=0.472,source="quest_giver",zoneID=14717},questType="standard"},
[78757] = {id=78757,name="Honey and Clay the Pain Away",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Ramoliths! Magnificent, aren't they? One of the finest elemental beasts on the isle. The bad news is they're not immune to injury. Poor Shalehoof here was attacked by awakened elementals in Farnee's pond. The good news is that we have all we need to tend to him. We just have to mix that clay you found with some fire honey and slap it up on ol' Shalehoof's hock! Ready?",objectivesText="Help Harmot prepare Shalehoof's salve. Progress: Much like us earthen, healing something made from rock and stone is no easy task. But the unique properties of the clay you've brought, combined with the fusing properties of the honey makes for an excellent restorative!",starts={{npcID=213691,x=0.67,y=0.438,zoneID=14717}},ends={{npcID=213691,x=0.67,y=0.438,zoneID=14717}},coords={x=0.67,y=0.438,source="quest_giver",zoneID=14717},questType="standard"},
[78758] = {id=78758,name="Pulse Within the Earth",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Before we go and wake up a slumbering mountain giant, it's probably best we get an idea for how deeply asleep he is. Though, if the nerubians burrowing up didn't wake him up, I'm not sure what will. Take these earth shards and plant them on the waterfalls and hills around the lake. Once we've got them set up, I'll be able to get a reading on the giant's health.",objectivesText="Place 4 Tremor Stones around the pond. Progress: Once you've got the shards set up, I can drop the final one here to get a proper read.",starts={{npcID=213691,x=0.67,y=0.438,zoneID=14717}},ends={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},coords={x=0.67,y=0.438,source="quest_giver",zoneID=14717},questType="standard"},
[78759] = {id=78759,name="To Wake a Giant",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="By the Coreway, this stuff packs a punch! Combining healing silt with the molten fusion properties of fire honey has given us a salve that could wake a whole mountain! Which is exactly what you'll do. Take the mixture over to our wounded friend in Farnee's pond, and slap it on his hide! It should be enough to wake him up and alleviate any soreness. Hopefully, anyways.",objectivesText="Apply elemental salve to the mountain giant for Harmot . Progress: This will either wake the giant and patch him up good as new or... Well, let's not talk about the other possibility. Have some faith in the process!",starts={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},ends={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},coords={x=0.67,y=0.474,source="quest_giver",zoneID=14717},questType="standard"},
[78760] = {id=78760,name="Dark Iron from Above",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We've done our best to contain the High Speaker's followers. We've hampered their efforts at destroying or looting anything they can take with them into Hall of Awakening. Now, we just need to deal with the leader of their forces before they can coordinate a more unified resistance. Are you ready to do this, ?",objectivesText="Defeat Supervisor Varric and his forces within the Earthenworks.",starts={{npcID=213763,x=0.47,y=0.206,zoneID=14795}},ends={{npcID=213796,x=0.466,y=0.102,zoneID=14795}},coords={x=0.47,y=0.206,source="quest_giver",zoneID=14795},questType="standard"},
[78761] = {id=78761,name="Into the Machine",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="No time to catch our breath! The High Speaker is fleeing to the earthen's most sacred machine. We need to follow him. Remember, we're doing this for the earthen! For justice! For all the brothers and sisters and comrades who've fallen to the High Speaker's hubris!",objectivesText="Confront the High Speaker inside the Hall of Awakening.",starts={{npcID=213796,x=0.466,y=0.102,zoneID=14795}},ends={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},coords={x=0.466,y=0.102,source="quest_giver",zoneID=14795},questType="standard"},
[78762] = {id=78762,name="Your First Find",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="We've got a find on our hands! Looks like this might be one of my books from undergrad. Hah! Now, your job is to get all that dirt off of it, but you have to be careful. The artifacts we handle are very fragile, and the only thing worse than them staying in the ground is them breaking on the way out. Empowering your elemental will only get you halfway. You'll need to use your environment to keep things in balance so that it's safe to excavate.",objectivesText="Practice excavating on the Outdated Geology Textbook . Progress: What do you think? Having fun yet?",starts={{mapID=2025,npcID=208614,x=0.615,y=0.306}},ends={{mapID=2025,npcID=208614,x=0.615,y=0.306}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.306},questType="standard"},
[78763] = {id=78763,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78764] = {id=78764,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78765] = {id=78765,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78766] = {id=78766,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78767] = {id=78767,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78827] = {id=78827,name="Go Take Candle!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Ksk, ksk! You there! Yes, you! We, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me. Bring us, me, bring me candles ! Yes! No ask question, just go get candles . We are, er, I am professional, yes. Professionals do not ask questions. Only get candles .",objectivesText="Steal candles for the suspicious vent in the Gundargaz Inn. Progress: You have candles ?",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
[78837] = {id=78837,name="Pomp and Dire Circumstance",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I'm seeing legitimate concerns. We have to do something about the nerubians... even if the High Speaker won't. If he won't do something, I will. The High Speaker sent me to the surface because I wasn't \"reasonable.\" I think we should have a chance to... reason... with him. We'll need to go to Gundargaz.",objectivesText="Meet Speaker Brinthe in Gundargaz. Progress: That is... never pleasant.",starts={{npcID=212592,x=0.42,y=0.284,zoneID=14795}},ends={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},coords={x=0.42,y=0.284,source="quest_giver",zoneID=14795},questType="standard"},
[78838] = {id=78838,name="Cogs in the Machine",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Gundargaz is my home. Or at least, it was before the High Speaker saw fit to reassign me above ground. I've missed my home, but it's... changed. As the number of Machine Speakers decreases, we're in a race against time. Lately, we've been especially weary of our assigned tasks, but as always, we must bear our burdens. Let me show you around the area. There are some earthen I would like you to meet.",objectivesText="Accompany Brinthe as they talk to earthen in Gundargaz. Progress: This is not how I remember my home.",starts={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},ends={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},coords={x=0.472,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[78839] = {id=78839,name="Kobold Shoulder",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="The first step to stemming our losses and retaking the mines is straightforward, if unpleasant. Without minions, this Candle King will be less of a threat to Gundargaz. See if you can reduce the swarm, , before hostilities escalate further.",objectivesText="Kill invading kobolds in the Lost Mines. Progress: This should never have happened.",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78860] = {id=78860,name="More Candles!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I, er, we...no, no, I! I have new deal for you, oh shadowy one. More candles ! In return, you get... er... You get more candles ! Then you give to us! To me! candles ! candles ! candles !",objectivesText="Steal more candles for the suspicious vent in the Gundargaz Inn. Progress: You have candles ? More candles ?",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
[78861] = {id=78861,name="Aiding the Accord",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[78863] = {id=78863,name="A Place Beneath the Boughs",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Thanks to you and all the mortals who defended the Emerald Dream, a new World Tree now grows in the Dragon Isles. Amirdrassil 's boughs will be a haven of peace and tranquility, and a place of respite for the kaldorei souls lost at Teldrassil. Tyrande Whisperwind and Shandris Feathermoon are at the tree now. They would share words with you.",objectivesText="Meet Tyrande and Shandris in Amirdrassil .",starts={{mapID=2112,npcID=187678,x=0.583778,y=0.357111}},ends={{mapID=2239,npcID=216067,x=0.512667,y=0.606667}},coords={mapID=2112,source="quest_giver",x=0.583778,y=0.357111},questType="standard"},
[78864] = {id=78864,name="The Returning",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="It is a time of reflection and change, $p. For the world, and for my people. My mother and I have been discussing the roads that led us here... and where those roads will lead in the years to come. Come, let us speak.",objectivesText="Speak with Shandris Feathermoon .",starts={{mapID=2239,npcID=216067,x=0.512667,y=0.606667}},ends={{mapID=2239,npcID=216067,x=0.512667,y=0.606667}},coords={mapID=2239,source="quest_giver",x=0.512667,y=0.606667},questType="standard"},
[78865] = {id=78865,name="Siblings Until the End",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Some time ago, Vyranoth received an unexpected summons... from Iridikron. You will want to hear what he had to say.",objectivesText="Speak with Vyranoth to hear about her meeting with Iridikron. Progress: Iridikron had much to say...",starts={{mapID=2112,npcID=214051,x=0.5576,y=0.3684}},ends={{mapID=2112,npcID=214051,x=0.5576,y=0.3684}},coords={mapID=2112,source="quest_giver",x=0.5576,y=0.3684},questType="standard"},
[78874] = {id=78874,name="Conjured Help",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="If you're looking for food--softy food--I'm afraid we're clean out. Nothing but good ol' rocks and gems here at the moment. It's starting to become a problem, actually. Say... you wouldn't be able to do anything about that, would you? Rustle us up some victuals for the fleshy folk?",objectivesText="Summon food for Innkeeper Brax in the Gundargaz Inn. Progress: You don't want to try a nibble of cobalt?",starts={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},ends={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},coords={x=0.48,y=0.322,source="quest_giver",zoneID=14795},questType="standard"},
[78875] = {id=78875,name="The Unkillable",level=50,requiredLevel=50,faction="horde",expansion=10,zoneID=33,mapID=50,description="I'm bettin' dat ogre Mai'Zoth is behind all dis. He should have died long ago, but his magics still be strong. He be using the altar's centerpiece as a conduit to drain Lukou's power. Recover the centerpiece and prove he's not so unkillable when he doesn't have a loa hostage.",objectivesText="Recover the altar centerpiece from Mai'Zoth. Progress: Did you prove Mai'Zoth isn't unkillable?",starts={{mapID=50,npcID=210091,x=0.663333,y=0.459}},ends={{mapID=50,npcID=210091,x=0.663333,y=0.459}},coords={mapID=50,source="quest_giver",x=0.663333,y=0.459},questType="standard"},
[78876] = {id=78876,name="A Glowing Memento",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="<An unusually persistent ember draws your eye. It glows with a pure, primal heat.> < Vyranoth would be interested in this.>",objectivesText="Bring the Everglowing Ember to Vyranoth in Amirdrassil or the Central Encampment in the Emerald Dream. Provided item:",ends={{mapID=2200,npcID=208506,x=0.508,y=0.628}},coords={mapID=2200,source="quest_giver",x=0.508,y=0.628},questType="raid"},
[78877] = {id=78877,name="Bless These Homes",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Divine presence acknowledged. Every day for as long as my memory serves me, I have walked the routes and lit the incense around our homes. It has ground my joints to dust, but is it an important task. A sacred task. These are dark times we live in--perhaps you could add your own beatitudes to our little rituals?",objectivesText="Bless the incense around Gundargaz. Progress: You do us an honor, bringing your faith into these caverns. Let it bless these machines and those who work with them, just as they bless us in turn.",starts={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},ends={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},coords={x=0.47,y=0.324,source="quest_giver",zoneID=14795},questType="standard"},
[78879] = {id=78879,name="Evoking the Forge",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Harumph! This blasted forge is on its last legs. We'd repair it, but Stonemason Itsak picked up a shift at Ironhaul Station when the Coreway collapsed, and well... There's no one to fix it anymore. If you can figure out a way of getting it running hot again, Gundargaz would be in your debt!",objectivesText="Find a way to stoke the forge outside of Gundargaz. Progress: I'm going to miss Itsak. He made the best end-of-shift rock roasts...",starts={{npcID=213841,x=0.474,y=0.284,zoneID=14795}},ends={{npcID=213841,x=0.474,y=0.284,zoneID=14795}},coords={x=0.474,y=0.284,source="quest_giver",zoneID=14795},questType="standard"},
[78880] = {id=78880,name="The Eastern Kingdoms Cup Begins",level=30,requiredLevel=30,faction="alliance",expansion=10,zoneID=14771,mapID=84,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Stormwind.",starts={{mapID=84,npcID=214031,x=0.618,y=0.7505},{mapID=2339,npcID=220307,x=0.46,y=0.546},{mapID=2339,npcID=220865,x=0.566667,y=0.286},{mapID=2339,npcID=220870,x=0.41,y=0.594}},ends={{mapID=84,npcID=214111,x=0.6,y=0.663}},coords={mapID=84,source="quest_giver",x=0.618,y=0.7505},questType="standard"},
[78881] = {id=78881,name="The Eastern Kingdoms Cup Begins",level=30,requiredLevel=30,faction="horde",expansion=10,zoneID=14771,mapID=85,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Orgrimmar.",starts={{mapID=85,npcID=213769,x=0.5255,y=0.795},{mapID=1165,npcID=214097,x=0.512,y=0.408},{mapID=2339,npcID=220307,x=0.46,y=0.546},{mapID=2339,npcID=220865,x=0.566667,y=0.286},{mapID=2339,npcID=220870,x=0.41,y=0.594}},ends={{mapID=85,npcID=214112,x=0.524,y=0.599}},coords={mapID=85,source="quest_giver",x=0.5255,y=0.795},questType="standard"},
[78890] = {id=78890,name="Emerald Frenzy",level=10,requiredLevel=10,faction="none",expansion=10,objectivesText="Collect Emerald Dewdrops from Frenzied Creatures",starts={{x=0.555,y=0.5,mapID=2200}},ends={{x=0.555,y=0.5,mapID=2200}},coords={mapID=2200,x=0.555,y=0.5},questType="standard"},
[78893] = {id=78893,name="A Scrap of Bronze",level=10,requiredLevel=10,faction="none",expansion=10,description="The vendors of Pandaria do not want the equipment you will find in this timeline. You can convert unwanted equipment into Bronze using the magic of the infinite dragonflight. Use the Unraveling Sands ability and scrap the Unraveling Tunic .",objectivesText="Use the Unraveling Sands ability to summon Unraveling Sands, then place the Unraveling Tunic in the Unraveling Sands to scrap it into Bronze . Progress: You can place unwanted equipment into the Unraveling Sands to obtain additional Bronze for your journey.",questType="standard"},
[78895] = {id=78895,name="A Shadow Over Gundargaz",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="You look dangerous. That's good. We need dangerous. Something is stalking Gundargaz. Something mean. Something... recent. Just before the Coreway collapsed I started getting reports of workers going missing mid-shift. Only thing we've been able to find have been the odd chunk of rock. Fingers, mostly. If you could sniff out what's stalking my town, I'd be in your debt.",objectivesText="Track down whatever is hunting the earthen in Gundargaz. Progress: Life didn't always used to be this exciting.",starts={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},ends={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},coords={x=0.48,y=0.348,source="quest_giver",zoneID=14795},questType="standard"},
[78897] = {id=78897,name="Boom or Blight",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="This place is infested with cave borers. They pose a threat to the great roots that stretch through this place. Yes, the tree provides sustenance for many living things, but this is not some small band of bugs nibbling on a leaf. This is a blight. Their numbers must be culled for the good of the whole. By my oath I am unable to raise a hand to interfere. However... you have sworn no such oath. Will you do what must be done?",objectivesText="Cull 10 worms of the Wormlands. Progress: How fares the blight?",starts={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},ends={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},coords={x=0.422,y=0.426,source="quest_giver",zoneID=14752},questType="standard"},
[78898] = {id=78898,name="Intention vs Instinct",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Cave borers are not social creatures as a rule. Seeing this many gather in one place speaks to intention. A wormcaller of the nerubians must be present. Find them and recover the tool they use to call these worms here. With it we can lead them away in time.",objectivesText="Collect a Singing Stone from Wormcaller Iz'tikrine. Progress: I can sense more worms coming. As if they are drawn to this place.",starts={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},ends={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},coords={x=0.422,y=0.426,source="quest_giver",zoneID=14752},questType="standard"},
[78900] = {id=78900,name="On Cold, Dark Wings",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="You came down the Coreway, right? From up top? They have it easy, those city earthen. Down here, death comes for you from all around. From below. From above. You look like you've killed a fair few beasts in your time. Care to add another to the list?",objectivesText="Track down the Ringing Death in Gundargaz. Progress: Keep quiet, that's my advice.",starts={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},ends={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},coords={x=0.48,y=0.348,source="quest_giver",zoneID=14795},questType="standard"},
[78901] = {id=78901,name="Heeeelllp!!!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Hey! You! Get me down! Away from these worms! Please! I'll pay you! I'll even owe you one! Heck, I'll gladly sell out any cartel member you need dirt on! Just get me down! Also, don't walk too much. They can hear your footsteps. Move from rock to rock if you don't want a swarm coming after you.",objectivesText="Rescue Skedgit Cinderbangs .",starts={{x=0.416,y=0.421,mapID=2255}},ends={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},coords={mapID=2255,source="quest_giver",x=0.408,y=0.398},questType="standard"},
[78902] = {id=78902,name="Delegated Dig",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Okay, I know when I'm beat. So I want to hire you as my Champion of Coin... or coinchamp. This is all a part of my brilliant enterprising venture. See, these worms here are great at rooting out rich minerals like a niffen sniffing out high-quality mushrooms. I'm willing to bet all of my money--and your life--that they found a vein of sivstone. Great stuff, though I doubt a would know how to use it. Tell you what, you bring me a shipment's worth and I'll go halfsies on the profits with ya!",objectivesText="Acquire 25 Chunks of Sivstone. Progress: You get the goods?",starts={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},ends={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},coords={x=0.408,y=0.398,source="quest_giver",zoneID=14752},questType="standard"},
[78915] = {id=78915,name="Squashing the Threat",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I need your help! The massive Shadow-Soured squash have begun to grow all over the place. They're stinky and crawling with nasty mites. Mom and Dad brought in some airships to help us yank them out, but it's risky business with all those bugs. Can you attach ropes to these Shadow-Soured Squash, and the airships can then haul them away without making a mess?",objectivesText="Remove 8 Shadow-Sour Squash and slay 10 Shadow-Sour Mites . Progress: Have you removed all the Squash?",starts={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},ends={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},coords={x=0.636,y=0.338,source="quest_giver",zoneID=14838},questType="standard"},
[78918] = {id=78918,name="Brax's Brass Knuckles",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I have a proposition for you. We get some rowdy patrons here from time to time. Nothing sinister, but our folk work hard and things can get out of hand faster than a dropped hammer. Usually I'd give 'em a considerate knock upside the head to remind them what's what, but I lost my brass knuckles while helping Watcher Toki clear monsters on the town's skirts. Mind fetching my knuckles and administering some love taps?",objectivesText="Kill creatures around Gundargaz to find Brax's Brass Knuckles . Progress: Now which beasts did I punch with those knuckles last...",starts={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},ends={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},coords={x=0.48,y=0.322,source="quest_giver",zoneID=14795},questType="standard"},
[78929] = {id=78929,name="Tricks of the Dark",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Kobyss lurk in the shallows of murky water and snatch any who come near, faster than a viper! And that's just when they hunt alone. In numbers, they are a swarm to be reckoned with. They've been a plague on our outskirt villages since the day we arrived. They eat victims alive, given the chance. We must rescue the villagers that have already been dragged to the water!",objectivesText="Rescue 5 Arathi captives .",starts={{npcID=214378,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=214377,x=0.538,y=0.308,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78932] = {id=78932,name="Fickle Fiendish Fish",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Judging by the glint in your eye, you wish to join Faerin in this madness? To push into the kobyss waters? In the darkness? You are a fool with a death wish. Take as many of those damnable fish out as you can, before they drag you into the depths for their dinner.",objectivesText="Kill 13 kobyss invaders. Progress: We can't abandon the villagers here!",starts={{npcID=214376,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=214377,x=0.538,y=0.308,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78933] = {id=78933,name="The Sweet Eclipse",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I've set out to create a dessert that transcends the ordinary, one that even the most devout followers of the light would savor! To balance the flavors of the desert, between light and shadow, I require ingredients from several areas within the darkness. Please assist me in harvesting the following ingredients: Frog-Kissed Caviar , Darkroot Persimmon and Ethereal Sugar .",objectivesText="Collect 8 Darkroot Persimmon , 30 Frog-Kissed Caviar , and 1 Ethereal Sugar . Progress: Have you found all of the ingredients?",starts={{npcID=206533,x=0.644,y=0.31,zoneID=14838}},ends={{npcID=206533,x=0.644,y=0.31,zoneID=14838}},coords={x=0.644,y=0.31,source="quest_giver",zoneID=14838},questType="standard"},
[78934] = {id=78934,name="Blades of the Arathi",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I trust in your strength. I must ask you to go ahead to reinforce Sina's Yearning. Anduin and I can see my people to safety in Lorel's Crossing. With the darkness and the kobyss, the hearts of my people in Sina's Yearning will be faltering to fear. We can't let them wallow. Light a torch with the Sacred Flame in the center of town and use it to inspire my people's valor. Remind them of their strength. We will catch up with you. May the Flame guide you, my friend.",objectivesText="Light a torch with the Sacred Flame, then rally 6 groups of Arathi in Sina's Yearning.",starts={{npcID=214378,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=221100,x=0.552,y=0.326,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78936] = {id=78936,name="Something's Fishy",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="So you outsiders and Faerin managed to both survive and save the villagers at the beach? We're in trouble, here. The kobyss brought some of their strongest forces to the doorsteps of villagers. We have our hands full just holding the line. If you can take out those monsters, we might be able to turn the tide.",objectivesText="Slay Deepsludger , The Abominable Wavecrasher , and Tidelord Teethwretch in Sina's Yearning. Progress: When we first encountered the kobyss, there were those among us who tried to establish peace with them. But it quickly became apparent that they only see us as food.",starts={{npcID=214376,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=214376,x=0.538,y=0.314,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78937] = {id=78937,name="Shadow upon Shadow",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Faerin 's wide eyes dart around in surprise.> What just happened? Did you see that shadow? And the oil well... it's gone dark? I've never seen anything like this before. Could it be the nearby dawntower? Hurry!",objectivesText="Investigate the nearby dawntower.",starts={{npcID=221100,x=0.552,y=0.326,zoneID=14838}},ends={{npcID=214405,x=0.558,y=0.412,zoneID=14838}},coords={x=0.552,y=0.326,source="quest_giver",zoneID=14838},questType="standard"},
[78938] = {id=78938,name="Champion of the Waterlords",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=51,mapID=32,description="I regret to inform you that a horrific threat awaits your kind within this mortal realm. An Elemental Lord of Fire, Ragnaros, bides his time waiting to strike and burn your Azeroth to its core. We, the elements of water, have waged war eternal with those beings of the lesser elementals. Trust that our warning is no small thing. Prove your conviction! Slay Ragnaros, once and for all!",objectivesText="Defeat Remembered Ragnaros during a Radiant Echoes event. Progress: Ragnaros yet remains, mortal. His foul heat emanates from nearby.",starts={{mapID=32,npcID=214399,x=0.435,y=0.672}},ends={{mapID=32,npcID=214399,x=0.435,y=0.672}},coords={mapID=32,source="quest_giver",x=0.435,y=0.672},questType="standard"},
[78939] = {id=78939,name="The Darkened Flame",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="This... Order of Night, as they call themselves, did some foul ritual to turn the tower's flame to darkness. I know not what. We should investigate.",objectivesText="Investigate the darkened dawntower. Progress: My own people... how could they? <Faerin shakes her head in disbelief.>",starts={{npcID=214405,x=0.558,y=0.412,zoneID=14838}},ends={{npcID=214404,x=0.562,y=0.42,zoneID=14838}},coords={x=0.558,y=0.412,source="quest_giver",zoneID=14838},questType="standard"},
[78942] = {id=78942,name="The Might of Khaz Algar",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The Harbinger thinks she can catch us off guard, but she's a fool if she expects to win this fight. The Algari Offensive stands at your back, . Spare no enemy.",objectivesText="Fight back against the nerubians.",starts={{npcID=214271,x=0.716,y=0.592,zoneID=14838}},ends={{npcID=214274,x=0.646,y=0.618,zoneID=14838}},coords={x=0.716,y=0.592,source="quest_giver",zoneID=14838},questType="standard"},
[78943] = {id=78943,name="Steel and Flames",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Our forces may be able to hold their own, but seeing you in the fray may help their spirits. Take this warhorn. Let it ring out and fill our foes with terror. Once you're done rallying our troops, make your way to your commanders.",objectivesText="Rally 20 Algari Offensive troops.",starts={{npcID=214271,x=0.716,y=0.592,zoneID=14838}},ends={{npcID=214275,x=0.686,y=0.642,zoneID=14838}},coords={x=0.716,y=0.592,source="quest_giver",zoneID=14838},questType="standard"},
[78948] = {id=78948,name="A Light in the Dark",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Something is very wrong. As the battle continues, each side has become more aggressive. Alleria seems to know something - she ran off at one point during the battle. We've been giving chase, but I cannot leave these soldiers to die. She's just ahead, we can reconvene with her together.",objectivesText="Speak with Anduin and chase down Xal'atath.",starts={{npcID=214273,x=0.646,y=0.618,zoneID=14838}},ends={{npcID=220688,x=0.36,y=0.354,zoneID=14838}},coords={x=0.646,y=0.618,source="quest_giver",zoneID=14838},questType="standard"},
[78950] = {id=78950,name="Cutting Off the Legs",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=14838,mapID=2215,description="While we've yet to locate Xal'atath, we've received reports from deeper in the field of certain nerubians giving orders. It won't buy us too much but every action is critical. Take them out. Hopefully that will allow us some breathing room. Speak with Anduin after you are done. He and the Arathi girl went after Alleria.",objectivesText="Slay the nerubian lieutenants. Progress: Speak with Anduin within the Sanguine Grasps.",starts={{npcID=214276,x=0.686,y=0.642,zoneID=14838}},ends={{npcID=214273,x=0.646,y=0.618,zoneID=14838}},coords={x=0.686,y=0.642,source="quest_giver",zoneID=14838},questType="standard"},
[78951] = {id=78951,name="Ever Deeper Shadow",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="When I reached for the Flame, I felt the overwhelming hopelessness and despair that had been poured into it. It pains me, but... my light alone is not enough to banish these shadows. And so, we take a more direct path. If the remaining cultists have withdrawn to Gloomcrag Bower, their combined power must be what's keeping the Flame dark. We must stop them before this darkness spreads.",objectivesText="Slay 10 Order of Night cultists in the cave beneath the Cliffside Beacon. Progress: These were once my people. My allies. My mentors. I once tried to reason with them. Tried to make them see the Light... see that the Light is still within us all. <Faerin's face flickers between sadness and anger.> They wouldn't listen. And they're killing innocents. I can't hesitate. Not anymore.",starts={{npcID=214404,x=0.562,y=0.42,zoneID=14838}},ends={{npcID=214413,x=0.558,y=0.404,zoneID=14838}},coords={x=0.562,y=0.42,source="quest_giver",zoneID=14838},questType="standard"},
[78952] = {id=78952,name="The Final Resistance",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Good work. But before we can leave, there's something else. Down this way are some powerful priests. I think they are summoning something-- something big. No doubt to strike at us above and drive us from the tower itself. It will be dangerous, but we must stop them. Are you with me?",objectivesText="Destroy the Shadow Rift .",starts={{npcID=214413,x=0.558,y=0.404,zoneID=14838}},ends={{npcID=221733,x=0.55,y=0.402,zoneID=14838}},coords={x=0.558,y=0.404,source="quest_giver",zoneID=14838},questType="standard"},
[78954] = {id=78954,name="Restore the Flame",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Do you feel it? Hope, returning? Thank you for your help, . The dawntower's flame remains dark. But this time, I think we'll be able to restore it. Let's meet at the tower.",objectivesText="Help Faerin restore the Holy Flame at the Cliffside Beacon. Progress: I only hope that together, we can kindle a little more light in our little world.",starts={{npcID=221733,x=0.55,y=0.402,zoneID=14838}},ends={{npcID=214404,x=0.562,y=0.42,zoneID=14838}},coords={x=0.55,y=0.402,source="quest_giver",zoneID=14838},questType="standard"},
[78972] = {id=78972,name="Harvest Havoc",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Our parents went off to fight the monsters that invaded our farm. While they are gone, we try to keep the farm running. We have a harvestbot to help with chores, but I keep crashing it into the river. We could finish our chores if you could help us drive the harvestbot!",objectivesText="Control Harvestbot Remy to load 4 Cabbage and 4 Carrots into carts. In addition slay 12 Invasive Beetles. Progress: Have you completed the chores?",starts={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},ends={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},coords={x=0.636,y=0.338,source="quest_giver",zoneID=14838},questType="standard"},
[78978] = {id=78978,name="Raising a Stink",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=1637,mapID=85,description="Those clues add up to an ugly story, <name>. That map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic. I've got a gal that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.",objectivesText="Meet Detective Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.",starts={{npcID=214707}},ends={{mapID=85,npcID=37172,x=0.5,y=0.65}},coords={mapID=85,source="quest_giver",x=0.5,y=0.65},questType="standard"},
[78979] = {id=78979,name="Loving Yourself, Your Way",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="While visiting this gala, I am staying at the Razor Hill inn. It may not look like much, but it is surprisingly comfortable! Why don't you see if they have any extra beds you could use? I think I will have a bit of a rest too... Right... here...",objectivesText="Take a nap in the inn at Razor Hill. Progress: < Ning is quietly snoring.>",starts={{mapID=1,npcID=214591,x=0.418,y=0.162}},ends={{mapID=1,npcID=214591,x=0.418,y=0.162}},coords={mapID=1,source="quest_giver",x=0.418,y=0.162},questType="standard"},
[78980] = {id=78980,name="Take a Look Around",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=14,mapID=1,description="Here at the Gala of Gifts, we have many wonderful artisans crafting gifts just for you and your loved ones. But don't take my word for it--there are plenty of attendees enjoying the festivities as well! Go, speak to the visitors, and see what the artisans have to offer. Maybe you will find the perfect gift!",objectivesText="Meet the vendors and visitors at the Gala of Gifts. Progress: Are you having a good time?",starts={{mapID=1,npcID=214477,x=0.418,y=0.18}},ends={{mapID=1,npcID=214477,x=0.418,y=0.18}},coords={mapID=1,source="quest_giver",x=0.418,y=0.18},questType="standard"},
[78981] = {id=78981,name="Love is in the Air",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=1637,mapID=85,description="Smell these roses! My partner got them for me at the Gala of Gifts. Interested in seeing things yourself? Head to Durotar. There are gifts, and food, and you should taste the chocolate, it's delicious!",objectivesText="Visit the Gala of Gifts in Durotar, near Rocktusk Farm.",starts={{mapID=85,npcID=19175,x=0.545667,y=0.709667},{mapID=85,npcID=19177,x=0.440857,y=0.667714},{mapID=18,npcID=215196,x=0.614,y=0.668},{mapID=2339,npcID=220307,x=0.46,y=0.546}},ends={{mapID=1,npcID=214477,x=0.418,y=0.18}},coords={mapID=85,source="quest_giver",x=0.545667,y=0.709667},questType="standard"},
[78982] = {id=78982,name="I Smell Trouble",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=1637,mapID=85,description="You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it? Well, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away! Are you in? I could use a good partner to solve this.",objectivesText="Use O.D.I.E.'s Remote Control to find clues around Orgrimmar. Progress: Sure, O.D.I.E. can sniff out the clues, but you still gotta piece 'em together.",starts={{mapID=85,npcID=37172,x=0.5,y=0.65}},ends={{mapID=85,npcID=37172,x=0.5,y=0.65}},coords={mapID=85,source="quest_giver",x=0.5,y=0.65},questType="standard"},
[78983] = {id=78983,name="An Unwelcome Gift",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=1519,description="I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent! But let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.",objectivesText="Kill 8 Crown Chemical Co. members around Orgrimmar. Progress: Follow your nose, pal! Anyone who stinks could be a suspect.",starts={{npcID=214707}},questType="standard"},
[78984] = {id=78984,name="Crushing the Crown",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=1637,mapID=85,description="Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver. <Snagglebolt points to the unmarked box.> Bombs. I got bombs. Playtime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.",objectivesText="Use the Artisanal Bon-Bombs to destroy Crown supplies and kill Crown members. Progress: We need to put a stop to this before the Crown pulls off their smelly sabotage.",starts={{mapID=85,npcID=37172,x=0.5,y=0.65}},ends={{mapID=85,npcID=37172,x=0.5,y=0.65}},coords={mapID=85,source="quest_giver",x=0.5,y=0.65},questType="standard"},
[78985] = {id=78985,name="The Stench of Revenge",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=1637,mapID=85,description="We're never gonna see an end to this unless we take on the boss himself. Look, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Orgrimmar if we let him finish his research. You go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.",objectivesText="Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel . Progress: You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.",starts={{mapID=85,npcID=37172,x=0.5,y=0.65}},ends={{mapID=85,npcID=37172,x=0.5,y=0.65}},coords={mapID=85,source="quest_giver",x=0.5,y=0.65},questType="dungeon"},
[78986] = {id=78986,name="Getaway to Scenic Grizzly Hills!",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="Good morrow! Today's special portal is a magical getaway to the majestic forests of Northrend! Although perhaps I could beg you for a favor. You seem the adventurous type. I could use your help in delivering some flowers from Grizzly hills to a beautiful woman named Laverne. I would do it myself but... Well, you see, she is rather intimidating in her beauty.",objectivesText="Take the Scenic Getaway Portal to Grizzly Hills to pick a bouquet of flowers for Laverne. Progress: The mage conjuring portals? <Laverne giggles.> Let me see.",starts={{mapID=1,npcID=214497,x=0.414,y=0.162}},ends={{mapID=1,npcID=214496,x=0.406,y=0.168}},coords={mapID=1,source="quest_giver",x=0.414,y=0.162},questType="standard"},
[78987] = {id=78987,name="Getaway to Scenic Nagrand!",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="Good morrow! Today's special portal is a magical getaway to the great plains of Nagrand! Would you, perchance, be interested in a proposition? I will lend you my camera if you could deliver any photographs you take to my dear friend Karn. He has been adrift in Nagrand as of late, lost in his own thoughts. As stubborn as he is, I'm sure he will appreciate the company. I would do it myself, but I must maintain the portals here.",objectivesText="Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Karn. Progress: How is Karn? When last I saw him, he seemed drowned in regrets and loneliness.",starts={{mapID=1,npcID=214497,x=0.414,y=0.162}},ends={{mapID=1,npcID=214497,x=0.414,y=0.162}},coords={mapID=1,source="quest_giver",x=0.414,y=0.162},questType="standard"},
[78988] = {id=78988,name="Getaway to Scenic Feralas!",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="Good morrow! Today's special portal is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited! Unfortunately, some of our festival attendees who took this portal earlier left their gifts here at the gala. Could you perchance help me return them? I will meet you at the beach and together we shall be able to determine which gifts belong to whom.",objectivesText="Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.",starts={{mapID=1,npcID=214497,x=0.414,y=0.162}},ends={{mapID=1,npcID=214497,x=0.414,y=0.162}},coords={mapID=1,source="quest_giver",x=0.414,y=0.162},questType="standard"},
[78989] = {id=78989,name="The Gift of Self-Care",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="The eyes of a tired adventurer. A <class> that does many great deeds for many people. When was the last time you did a kind gesture for yourself? Perhaps now is the time. Look into your heart. What do YOU desire?",objectivesText="Speak with Ning to discover your heart's desire. Progress: Love is a blessing, especially if it comes from within.",starts={{mapID=1,npcID=214591,x=0.418,y=0.162}},ends={{mapID=1,npcID=214591,x=0.418,y=0.162}},coords={mapID=1,source="quest_giver",x=0.418,y=0.162},questType="standard"},
[78990] = {id=78990,name="The Gift of Relief",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. I saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. Perhaps he has insight to teach you.",objectivesText="Speak to Tokag Bonebreaker at the Gala of Gifts, then relieve your stress in Orgrimmar. Progress: I've seen men die of stress, you don't want to bottle it up every day.",starts={{mapID=1,npcID=214591,x=0.418,y=0.162}},ends={{mapID=1,npcID=214602,x=0.412,y=0.175}},coords={mapID=1,source="quest_giver",x=0.418,y=0.162},questType="standard"},
[78991] = {id=78991,name="The Gift of Relaxation",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="Love is a gift, yes. But it is also a gift that you can give yourself. Sometimes, the best way to love yourself is simply to relax. I met a troll across the Southfury River who seems particularly wise in this regard. Perhaps you could ask her for insights in the art of relaxation.",objectivesText="Speak with Jaz the Reborn about relaxation, then relax by Southfury River in the Northern Barrens. Progress: True love is letting ya guard down. Let yourself relax, you'll see what I mean.",starts={{mapID=1,npcID=214591,x=0.418,y=0.162}},ends={{mapID=10,npcID=214592,x=0.71,y=0.14}},coords={mapID=1,source="quest_giver",x=0.418,y=0.162},questType="standard"},
[78992] = {id=78992,name="Loving Yourself, Your Way",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="If it's a challenge you're after, I think I have an idea. I saw a boastful champion heading toward Razor Hill. You could challenge him to a duel. This would satisfy your desire and perhaps teach him a valuable lesson in humility.",objectivesText="Defeat Poggchug Ragethrower in a duel near the road to Razor Hill. Progress: How fares your challenge?",starts={{mapID=1,npcID=214591,x=0.418,y=0.162}},ends={{mapID=1,npcID=214591,x=0.418,y=0.162}},coords={mapID=1,source="quest_giver",x=0.418,y=0.162},questType="standard"},
[78993] = {id=78993,name="Loving Yourself, Your Way",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,mapID=1,description="A full belly is a happy belly! There is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?",objectivesText="Consume Packages of treats from vendors at the Gala of Gifts. Progress: Have you had your fill of treats? I love the fruits, myself.",starts={{mapID=1,npcID=214591,x=0.418,y=0.162}},ends={{mapID=1,npcID=214591,x=0.418,y=0.162}},coords={mapID=1,source="quest_giver",x=0.418,y=0.162},questType="standard"},
[78996] = {id=78996,name="Weapons and Warriors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Gorloc raiders have been slaughtering these farmers and stealing their pearls. They seek our protection, but we may not be enough. I know of others nearby who can help. Seek them out and request their aid. If they are hesitant, offer them the promise of pearls as payment. We will also need to arm these farmers so they can defend themselves. Search for spare weapons and equipment that they might be able to use. I will go with the farmers and train them as best I can.",objectivesText="Collect 3 weapon crates and recruit 5 warriors from Freywold Village and Dhar Durgaz.",starts={{npcID=214444,x=0.426,y=0.716,zoneID=14717}},ends={{npcID=215201,x=0.498,y=0.766,zoneID=14717}},coords={x=0.426,y=0.716,source="quest_giver",zoneID=14717},questType="standard"},
[78997] = {id=78997,name="Pilfered Pearls",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The pearls that these farmers harvest are their only source of livelihood. Some of these earthen even look at pearl farming as their primary reason for existing. The gorlocs continue to pilfer pearls at every opportunity. As you eliminate the gorlocs, search them for stolen pearls. Let us recover as many as we can.",objectivesText="Retrieve 8 Pilfered Pearls from gorlocs at the Glimmering Shore. Progress: We need to return these pearls to the farmers.",starts={{npcID=215201,x=0.498,y=0.766,zoneID=14717}},ends={{npcID=215201,x=0.498,y=0.766,zoneID=14717},{npcID=215327,x=0.496,y=0.766,zoneID=14717}},coords={x=0.498,y=0.766,source="quest_giver",zoneID=14717},questType="standard"},
[78998] = {id=78998,name="Frontline Farmers",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Most of the farmers are already out in the field, defending their positions. I have trained them as best I could given the circumstances, but they are still wielding farming tools. I need you to distribute the weapons you gathered to those on the frontlines. While it may not markedly improve their combat ability, at least it will boost their confidence that they are not alone in this fight.",objectivesText="Distribute 3 weapon crates to the pearl farmers at Glimmering Shore.",starts={{npcID=215201,x=0.498,y=0.766,zoneID=14717}},ends={{npcID=215327,x=0.496,y=0.766,zoneID=14717}},coords={x=0.498,y=0.766,source="quest_giver",zoneID=14717},questType="standard"},
[78999] = {id=78999,name="Heart of a Hero",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="It seems the gorlocs have been bolstering their forces with summoned elementals. That explains how they were able to overrun the farmers so easily. It will take all of our strength to hold off the colossi already in the field. I need you to stop any new elementals from being created. Elementals of this size and power can only be created by the most powerful of gorloc shaman. Seek them out behind enemy lines and eliminate them. This should end the gorloc threat to the farmers once and for all.",objectivesText="Defeat the three gorloc shaman leaders.",starts={{npcID=215327,x=0.496,y=0.766,zoneID=14717}},ends={{npcID=215420,x=0.504,y=0.786,zoneID=14717}},coords={x=0.496,y=0.766,source="quest_giver",zoneID=14717},questType="standard"},
[79006] = {id=79006,name="Faction Switch",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14663,description="Default",objectivesText="Default",questType="standard"},
[79009] = {id=79009,name="The Harbinger",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger... Let us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.",objectivesText="Meet Khadgar and Alleria in the Chamber of the Guardian in Dalaran. Progress: A Radiant Song, a Dark Heart, and this mysterious Harbinger... What could it all mean?",questType="standard"},
[79010] = {id=79010,name="Door to the Ren'dorei",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=971,description="If this investigation involves the Void, it would be wise to consult the void elves. We must head to Telogrus Rift and report the situation. I'll speak with Umbric. He'll be able to mobilize the Riftwalkers to our cause.",objectivesText="Follow Alleria to Telogrus Rift.",starts={{x=0.314,y=0.418,mapID=629,npcID=215013}},ends={{x=0.314,y=0.418,mapID=629,npcID=215013}},coords={mapID=629,x=0.314,y=0.418},questType="standard"},
[79011] = {id=79011,name="Riftwalker Reports",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=9415,mapID=971,description="The Riftwalkers are tasked with investigating all void activity that appears on Azeroth. A most vital duty, given how dangerous this dark force can be. And I speak from experience. Many of them were sent out on assignment to investigate recent fluctuations. I've been told they just arrived back, but have yet to hear their reports. Would you check in on them while I speak with Alleria?",objectivesText="Gather reports from Riftwalkers in Telogrus Rift. Progress: Let me know when you have those Riftwalker reports.",starts={{x=0.272,y=0.278,mapID=971,npcID=214702}},ends={{x=0.272,y=0.278,mapID=971,npcID=214702}},coords={mapID=971,x=0.272,y=0.278},questType="standard"},
[79012] = {id=79012,name="Cracks in the Void",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=9415,mapID=971,description="Telogrus Rift has always been extremely sensitive to cosmic shifts. It makes for a rather precarious homestead, but the void elves have... few options available to us. The recent influx in void energies has resulted in unstable rifts opening sporadically. And with so many investigating Azeroth, I'm having trouble finding Riftwalkers to deal with them. Could you close any unstable void rifts you find along your path?",objectivesText="Close 5 Unstable Void Rifts in Telogrus Rift. Progress: Normally the Riftwalkers would be the ones to mend these sort of anomalies. But I wouldn't want to distract from their current investigations.",starts={{x=0.272,y=0.278,mapID=971,npcID=214702}},ends={{x=0.272,y=0.278,mapID=971,npcID=214702}},coords={mapID=971,x=0.272,y=0.278},questType="standard"},
[79013] = {id=79013,name="Galakrond's Unrest",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=9415,mapID=115,description="Galakrond's Rest. Where the Dark Heart was first empowered by Iridikron. We don't know what power the relic holds, but we do know that the Harbinger now wields it. And now one of our Riftwalkers is missing, right where it all began. I don't believe this is a coincidence, <name>. Let's travel to Northrend and search the area.",objectivesText="Meet Alleria at Galakrond's Rest in Dragonblight.",starts={{x=0.407,y=0.607,mapID=971,npcID=214698}},ends={{mapID=115,npcID=214634,x=0.566,y=0.39}},coords={mapID=115,source="quest_giver",x=0.566,y=0.39},questType="standard"},
[79014] = {id=79014,name="Walk a Mile in Her Shadows",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=65,mapID=115,description="I don't often work with the Riftwalkers. I prefer to handle missions alone. Still, I will not abandon one of them. I cannot yet sense the Riftwalker's presence. Our best path forward is to retrace her steps. Which means following the shadows.",objectivesText="Uncover the void presence at Galakrond's Rest in Dragonblight.",starts={{mapID=115,npcID=214634,x=0.566,y=0.39}},ends={{mapID=120,npcID=214759,x=0.415,y=0.226}},coords={mapID=115,source="quest_giver",x=0.566,y=0.39},questType="standard"},
[79015] = {id=79015,name="Dark Descension",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=67,mapID=120,description="What are these void spawn doing here? Could it be the Harbinger's doing? Some power of the Dark Heart? Well. I do not mean to stand idly by. We must confront the Riftwalker. I don't think she will see reason now, but perhaps she can tell us something.",objectivesText="Confront the missing Riftwalker. Progress: What would the Harbinger want with Ulduar?",starts={{mapID=120,npcID=214759,x=0.415,y=0.226}},ends={{mapID=120,npcID=214759,x=0.415,y=0.226}},coords={mapID=120,source="quest_giver",x=0.415,y=0.226},questType="standard"},
[79016] = {id=79016,name="Legacy of the Void",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=67,mapID=882,description="Make no mistake, <name>. I know this is a trap. But if there's any chance this leads us to the Harbinger, we must take that risk. Be at the ready. We venture forth.",objectivesText="Travel to the Triad's Conservatory in Eredath.",starts={{x=0.44,y=0.21,mapID=120,npcID=221539}},ends={{mapID=882,npcID=214645,x=0.225,y=0.535}},coords={mapID=882,source="quest_giver",x=0.225,y=0.535},questType="standard"},
[79017] = {id=79017,name="The Path Taken",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=8701,mapID=882,description="These apparitions before us. I believe they're... memories. My memories. Is this the Harbinger's doing? Or mine? We need to explore. Discover why we were led here.",objectivesText="Witness Alleria's memories in Eredath. Progress: Suddenly, this all feels rather personal. The Harbinger must have a grievance against me. Or at least an... interest. Hm.",starts={{mapID=882,npcID=214645,x=0.225,y=0.535}},ends={{mapID=882,npcID=214645,x=0.225,y=0.535}},coords={mapID=882,source="quest_giver",x=0.225,y=0.535},questType="standard"},
[79018] = {id=79018,name="And Be One Traveler, Long I Stood",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=8701,mapID=971,description="I sense another memory ahead. While I'm loath to play along with the Harbinger's game, it's the only path forward for us. Still, we have faced just as many dangerous memories as peaceful ones. Prepare yourself.",objectivesText="Investigate the final memory at the Triad's Conservatory in Eredath.",starts={{x=0.225,y=0.534,mapID=882,npcID=215597}},ends={{x=0.225,y=0.534,mapID=882,npcID=215597}},coords={mapID=882,x=0.225,y=0.534},questType="standard"},
[79019] = {id=79019,name="Defend Telogrus Rift",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=9415,mapID=971,description="No. Not the ren'dorei. Not Telogrus Rift. Not today. <Alleria tightens her grip on her bow.> These ethereal forces are the same we encountered in Ulduar. The Harbinger must command them. I'll go ahead. Engage the enemies here.",objectivesText="Defend Telogrus Rift. Progress: My people can defend themselves, but even they will struggle against such an overwhelming force. We must aid them.",starts={{x=0.286,y=0.238,mapID=971,npcID=214660}},ends={{x=0.286,y=0.238,mapID=971,npcID=214660}},coords={mapID=971,x=0.286,y=0.238},questType="standard"},
[79020] = {id=79020,name="Null and Void",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=9415,mapID=971,description="We must defeat that loathsome apparition of Turalyon. The abomination's presence is intolerable. If left unchecked, it may destroy what remains of Telogrus Rift. I will end it with my own hands.",objectivesText="Defeat the Corrupted Memory of Turalyon in Telogrus Rift.",starts={{x=0.436,y=0.638,mapID=971,npcID=216264}},ends={{x=0.436,y=0.638,mapID=971,npcID=216264}},coords={mapID=971,x=0.436,y=0.638},questType="standard"},
[79021] = {id=79021,name="Radiant Warnings",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=9415,mapID=629,description="So she goes by Harbinger now, does she? How fitting. I no longer feel her presence, but make no mistake. Xal'atath's nefarious games continue. And Alleria is now a pawn upon her board. As are you, champion of fate.",objectivesText="Deliver Locus-Walker 's warning to Khadgar in Dalaran. Progress: Telogrus Rift should no longer tempt Xal'atath. For now.",starts={{x=0.502,y=0.752,mapID=971,npcID=214657}},ends={{x=0.502,y=0.752,mapID=971,npcID=214657}},coords={mapID=971,x=0.502,y=0.752},questType="standard"},
[79022] = {id=79022,name="A Mysterious Signal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2339,description="High Speaker Brinthe has sent an urgent missive for you, . She is eager to assist in the coming war effort, and is investigating a mysterious signal in the Deepforge Golemworks, a defunct golem manufacturing facility in the Ringing Deeps . Can you meet her there and provide your expertise?",objectivesText="Meet Brinthe at the Deepforge Golemworks in the Ringing Deeps .",starts={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},ends={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},coords={x=0.316,y=0.596,source="quest_giver",zoneID=14771},questType="standard"},
[79023] = {id=79023,name="Small Friend, Big Plans",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I tracked down a distress signal that led me to this little maintenance machine. A curious find, but the real treasure is the defunct war golem facility to the southeast. If we can start producing war golems again we'll be able to contribute to the war effort. Unfortunately, it's been overrun by a goblin salvage group. And we'll need to investigate and assess if the facility is functional. Fortunately, I have a plan, and it involves our little friend here. Why don't you introduce yourself?",objectivesText="Introduce yourself to the maintenance machine. Progress: With your assistance, I think we can find a way to clear this place out.",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79024] = {id=79024,name="Factory Recon",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="ZZ-01-47 should be able to make its way in there without drawing too much attention. But be careful! These goblins are hungry for raw materials. If they spot our bot, they won't show it mercy.",objectivesText="Employ ZZ-01-47 to scout the Golem Factory. Progress: Zee-Zee shouldn't be in much danger, as long as she stays away from the big mechs.",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79025] = {id=79025,name="A Plan Comes Together",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We have our work cut out for us, . But I think, with Dagran's help, we can break this down and tackle it piece by piece. Why don't you take us through what we've learned so far.",objectivesText="Go over the plan with Brinthe and Dagran. Progress: We're some of the greatest minds in... well Gundargaz, at least. We can figure this out.",starts={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},ends={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},coords={x=0.47,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[79026] = {id=79026,name="Putting the Works in Waterworks",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15002,mapID=2214,description="Overly enthusiastic kobolds, angry elementals, and a broken-down power plant. This place is in shambles! Do you spot those large wheels on each side? They should be moving, but they're not. We'll need to get those moving again if we want this place to come back to life.",objectivesText="Get the Waterworks running again. Progress: I wonder if we could use this technology to rebuild the Stonewrought Dam? Wouldn't that be something.",starts={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},ends={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},coords={x=0.472,y=0.422,source="quest_giver",zoneID=14795},questType="standard"},
[79027] = {id=79027,name="Elemental Trepidation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="ZZ-01-47 twitches back and forth, sensors scanning unceasingly. They seem afraid of this area, if they're even capable of feeling fear. Maybe clearing out some of the elementals will set them at ease.>",objectivesText="Defeat elementals. Progress: I appreciate what you're doing for Zee-Zee. And they appreciate it, too.",starts={{npcID=216137,x=0.472,y=0.422,zoneID=14795}},ends={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},coords={x=0.472,y=0.422,source="quest_giver",zoneID=14795},questType="standard"},
[79028] = {id=79028,name="We Require More Minerals",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Zee-Zee is ready to help you get the Shadowvein site up and running again.",objectivesText="Get the Shadowvein site up and running. Progress: <Zee-Zee emits an inquisitive beep.>",starts={{npcID=216140,x=0.556,y=0.41,zoneID=14795}},ends={{npcID=230643,x=0.048,y=0.796,zoneID=14795}},coords={x=0.556,y=0.41,source="quest_giver",zoneID=14795},questType="standard"},
[79029] = {id=79029,name="It's Sabotage",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We're back, and we're ready. You and ZZ-01-47 head in and cause some mayhem. Blow stuff up and make a mess that will draw them out of the manufacturing bay. I'll use the commotion to sneak inside. Join me when you're able, and we should have a chance at reactivating the facility and driving them out. We don't need to defeat them all. Defeating the Darkfuse leader supervising this operation should break their resolve. The Darkfuse lackeys will clear out when the coin stops flowing.",objectivesText="Wreak havoc, gain access to the manufacturing bay, and restart the facility.",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=220928,x=0.56,y=0.776,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79030] = {id=79030,name="The Voice of the Speakers",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2214,description="Please take word of our victory to Alleria in Dornogal. I'm sure our allies will be pleased to hear what we can provide for the war effort.",objectivesText="Return to Alleria in Dornogal.",starts={{npcID=220928,x=0.56,y=0.776,zoneID=14795}},ends={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},coords={x=0.56,y=0.776,source="quest_giver",zoneID=14795},questType="standard"},
[79074] = {id=79074,name="Summoning All Soldiers!",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The Artisan's Consortium has struck one final deal with the quartermasters of the Gladiator's Refuge! In addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas! Present this brochure to Calderax to receive two complimentary Trophies of Conquest, on us! - Rabul",objectivesText="Deliver the brochure to Calderax in the Gladiator's Refuge of Valdrakken .",ends={{mapID=2112,npcID=199599,x=0.444667,y=0.366667}},coords={mapID=2112,source="quest_giver",x=0.444667,y=0.366667},questType="standard"},
[79085] = {id=79085,name="A Pile of Fish",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,description="<A pile of fish, perhaps these could be transported by cart back to Seraphine Seedheart.>",objectivesText="Load 4 Fish onto Fish Cart-Pusher.",questType="standard"},
[79087] = {id=79087,name="A Pile of Clams",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,description="<A pile of clams, perhaps these could be transported by cart back to Seraphine Seedheart.>",objectivesText="Load 4 Clams onto Clam Cart-Pusher.",questType="standard"},
[79105] = {id=79105,name="Breach",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. Rescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.",objectivesText="Send civilians to the landing for safety.",starts={{npcID=214908,x=0.502,y=0.504,mapID=2305}},ends={{npcID=214908,x=0.502,y=0.504,mapID=2305}},coords={x=0.502,y=0.504,source="quest_giver",mapID=2305},questType="standard"},
[79106] = {id=79106,name="Rupture",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="Follow me. We'll work together to find any others in need of rescuing.",objectivesText="Save Dalaran . Progress: The nerubians are capturing anyone they can and stringing them up in webs. Make sure to free whoever you find before moving on.",starts={{x=0.357,y=0.713,mapID=2305,npcID=214908}},ends={{x=0.357,y=0.713,mapID=2305,npcID=214908}},coords={mapID=2305,x=0.357,y=0.713},questType="standard"},
[79107] = {id=79107,name="After the Storm",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2339,description="Turalyon and Geya'rah are training our new earthen allies as ground forces. But we will need more than that. We will need the Stormriders. Many were lost in the infiltration of the Stormperch and more to the nerubians. Their leader, Stormward Baelgrim, died valiantly. The surviving Stormriders are being cared for at a triage station nearby. We need to do whatever is necessary to get them and their rooks back in the air. They will be the earthen's most potent weapon in the battles to come.",objectivesText="Check on the Stormriders.",starts={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},ends={{npcID=215039,x=0.374,y=0.82,zoneID=14771},{npcID=215039,x=0.256,y=0.572,zoneID=14717}},coords={x=0.316,y=0.596,source="quest_giver",zoneID=14771},questType="standard"},
[79108] = {id=79108,name="Seeds of Evil",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description=", some of the shadowleaf plants are more... wrong than the rest. I don't know how to describe it better. My idiot brother, Tomothy, was supposed to help me get rid of these, but I haven't seen him and I can't wait. Clearly we don't want these to reproduce so I want you to cull as many as you can find, and then take their seeds. We'll burn those in holy fire to make sure we've cut off the infestation.",objectivesText="Collect Corrupted Shadowleaf Seeds . Progress: Did you cull those plants?",starts={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},coords={x=0.612,y=0.304,source="quest_giver",zoneID=14838},questType="standard"},
[79109] = {id=79109,name="Follow Miral",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Tomothy's lynx, Miral, has been bugging me. I don't know what she wants but it is unusual to see her without my brother. She's a great farm cat, but she's still a cat, so maybe she's just bored with Tomothy today? I don't know. Maybe Tomothy got into some sort of trouble. Can you find out what is bothering her for me?",objectivesText="Discover what is bothering Miral Murder-Mittens . Progress: <Miral looks at you as if expecting something. You are being judged.>",starts={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},ends={{npcID=215041,x=0.602,y=0.212,zoneID=14838}},coords={x=0.612,y=0.304,source="quest_giver",zoneID=14838},questType="standard"},
[79110] = {id=79110,name="Save Tomothy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="<Miral looks at you expectantly then looks at the ruins, then back to you, then to the ruins. You get the sense she wants you to go over there. Perhaps this is where Tomothy got lost?>",objectivesText="Save Tomothy Hillhelm from The Grasping Darkness .",starts={{npcID=215041,x=0.602,y=0.212,zoneID=14838}},ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},coords={x=0.602,y=0.212,source="quest_giver",zoneID=14838},questType="standard"},
[79111] = {id=79111,name="Missing Lynx",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[79114] = {id=79114,name="Beautification Project",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="A fine enough job, for one of your... ilk. If you wish to keep breathing, I suggest you continue to assist us. It may even prove lucrative for you, if you comply. Rak-Ush's former master allowed the stagshells to run feral, and abandoned the hollows to decay. Over time, invasive plants have infested the old stagshell hollows. Find a way to clear them. I don't care how.",objectivesText="Clear the Stagshell Hollow of Overgrown Plants. Progress: It would be unwise to return to me with an unfinished job.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79115] = {id=79115,name="Expert Consultant",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="You alone are no longer sufficient. We require additional assistance, and the jawcrawlers and threadlings also need oversight. The niffen settlement, Mmarl, is not far. However, past forced conscription attempts have failed. Nerubians are now forbidden within the settlement. We need someone to communicate in our stead. Go and barter with the rats. Come back with able bodies.",starts={{npcID=214356,x=0.75,y=0.808,mapID=2255}},ends={{npcID=215037,x=0.772,y=0.644,mapID=2255}},coords={x=0.75,y=0.808,source="quest_giver",mapID=2255},questType="standard"},
[79117] = {id=79117,name="Bright Young Niffen",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="You need swarmhands, huh? Last time the nerubians wanted our help, they tried to force us. They're terrible negotiators! All we wanted was a little quid pro quo. We've got several arachnologists, but most of them are busy keeping the flyers at bay. I'm sure they won't refuse an opportunity to study some swarmbeasts up close and personal! Maybe if you lighten their workload, they'll take you up on your offer.",objectivesText="Find 6 Niffen Arachnologists outside Mmarl to join Rak-Ush. Progress: Have you found anyone yet?",starts={{npcID=215037,x=0.772,y=0.644,zoneID=14752}},ends={{npcID=215037,x=0.772,y=0.644,zoneID=14752}},coords={x=0.772,y=0.644,source="quest_giver",zoneID=14752},questType="standard"},
[79118] = {id=79118,name="Rak-Ush Under New Management",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Well, you got your swarmhands. What are you still doing here? Go on then, you don't need my permission! Make sure the nerubians treat them fairly, now.",objectivesText="Return to Vix'aron in Rak-Ush.",starts={{npcID=215037,x=0.772,y=0.644,zoneID=14752}},ends={{npcID=214356,x=0.75,y=0.808,zoneID=14752}},coords={x=0.772,y=0.644,source="quest_giver",zoneID=14752},questType="standard"},
[79119] = {id=79119,name="It's Rough to Be a Bug!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Anub'azal gave his orders! We are the new masters of Rak-Ush! Yet Vix'aron decided to throw a tantrum and destroy our barn instead. Since this imbecile refuses to follow orders, perhaps you will, overcrawler. Maybe then we will decide not to kill you for eavesdropping. And recompense, I suppose. Go. We are to restore the stagshell hollows and fill them with swarmbeasts.",objectivesText="Clean up the barn in Rak-Ush. Progress: We need this barn in an operational state!",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79120] = {id=79120,name="Beetle in a Haystack",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="There are still feral stagshells on the outskirts of Rak-Ush. This scent grenade should be sufficient in stunning the beasts and alerting the niffen to their location. Once they are stunned, one of the rats will take them back to their hollow. Capture them and bring them back. We will be waiting.",objectivesText="Capture and return six Feral Stagshells to Rak-Ush. Progress: We still require more stagshells.",starts={{npcID=214356,x=0.75,y=0.808,zoneID=14752}},ends={{npcID=214356,x=0.75,y=0.808,zoneID=14752}},coords={x=0.75,y=0.808,source="quest_giver",zoneID=14752},questType="standard"},
[79121] = {id=79121,name="Bug Test",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Oh, I'm sorry, did you think this was a one and done assignment? If you did, Vix'aron would gladly \"show you the door\", as it were. The stagshells will require constant maintenance. Food. Water. Those sorts of things. Loathe as I am to admit it, the niffen are much more skilled at caring for swarmbeasts than Vix'aron or I. They can enlighten you on your duties, if this was not explanation enough.",objectivesText="Speak to Aromash and care for the stagshells in Rak-Ush. Progress: Do not return to me until you have finished your lessons with the niffen.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79122] = {id=79122,name="Scarab Scouting",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The stagshells are of the utmost importance to Anub'azal's war campaign. We have a keen sense of smell, but only the stagshells are able to seek out valuable Kaheti truffles. The truffles are a key ingredient in several... explosive elixirs, as it were. If you desire details, Aromash can give you more.",objectivesText="Use a Rak-Ush Stagshell to find 5 Kaheti truffles. Progress: We need an abundance of truffles to ensure we are properly prepared.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79123] = {id=79123,name="Permanent Hire",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Rak-Ush is beginning to look like a functioning swarmery. The role of delegation has suited me and Vix'aron well. You will continue to aid the niffen. In return, you may keep a portion of the wealth the swarmbeasts produce. Saffrin has more detailed plans around the development of the swarmery. Go speak to him, I have nothing else to say to you.",objectivesText="Speak with Saffrin in Rak-Ush. Progress: You have not spoken to Saffrin yet, have you? Otherwise you would not be here.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=217250,x=0.748,y=0.81,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79124] = {id=79124,name="Conduit of the Southern Storm",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="I'll tell you what I told Baelgrim when we last spoke. The binding of stormrooks is wrong. These creatures are as smart as any earthen. Some I'd say are smarter. But... Lufsela seems to be different. If her stormrook follows her willingly, then perhaps others will make that choice as well if she summons them. To summon rooks, we need Baelgrim's conduit. It's tucked away here somewhere. Have a look around, and maybe ask these pilgrims if they have seen it.",objectivesText="Find the Conduit of the Southern Storm . Progress: Have you found the conduit?",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79125] = {id=79125,name="The Kalimdor Cup Begins",level=30,requiredLevel=30,faction="alliance",expansion=10,zoneID=15969,mapID=84,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Stormwind.",starts={{npcID=214031,x=0.618,y=0.752,zoneID=1519},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220865,x=0.568,y=0.288,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=214111,x=0.6,y=0.66,zoneID=1519}},coords={x=0.618,y=0.752,source="quest_giver",zoneID=1519},questType="standard"},
[79126] = {id=79126,name="The Kalimdor Cup Begins",level=30,requiredLevel=30,faction="horde",expansion=10,zoneID=15969,mapID=85,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Orgrimmar.",starts={{npcID=213769,x=0.528,y=0.794,zoneID=1637},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220865,x=0.568,y=0.288,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=214112,x=0.522,y=0.598,zoneID=1637}},coords={x=0.528,y=0.794,source="quest_giver",zoneID=1637},questType="standard"},
[79127] = {id=79127,name="The Outland Cup Begins",level=30,requiredLevel=30,faction="alliance",expansion=10,zoneID=1519,mapID=87,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Stormwind.",starts={{mapID=87,npcID=214022,x=0.285,y=0.67925},{mapID=84,npcID=214031,x=0.618,y=0.7505},{mapID=1161,npcID=214095,x=0.678,y=0.182},{mapID=2339,npcID=220307,x=0.46,y=0.546}},ends={{mapID=84,npcID=214111,x=0.6,y=0.663}},coords={mapID=87,source="quest_giver",x=0.285,y=0.67925},questType="standard"},
[79128] = {id=79128,name="The Outland Cup Begins",level=30,requiredLevel=30,faction="horde",expansion=10,zoneID=1637,mapID=85,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Orgrimmar.",starts={{mapID=85,npcID=213769,x=0.5255,y=0.795},{mapID=1165,npcID=214097,x=0.512,y=0.408},{mapID=2339,npcID=220307,x=0.46,y=0.546}},ends={{mapID=85,npcID=214112,x=0.524,y=0.599}},coords={mapID=85,source="quest_giver",x=0.5255,y=0.795},questType="standard"},
[79129] = {id=79129,name="Rook Rally",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="Now that we've got the conduit all charged, I suppose it's time we joined everyone on the peak. Thrall talked me through what to expect, but also said summoning the stormrooks will require me to trust my feelings and instincts. An earthen trusting their feelings and instincts. That's... a challenge. You will help me, right? I'm not a fighter, and it looks dangerous up there. If anything happens to me, make sure Shraubendre makes it out safe. Please.",objectivesText="Safeguard the summoning ritual.",starts={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},ends={{npcID=214919,x=0.278,y=0.608,zoneID=14717},{npcID=214919,x=0.38,y=0.708,zoneID=14771}},coords={x=0.256,y=0.572,source="quest_giver",zoneID=14717},questType="standard"},
[79130] = {id=79130,name="The Northrend Cup Circuit",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=495,mapID=2112,description="It is time once again to test your mettle. My bronze colleagues have traveled to Northrend to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit! Are you up to the task?",objectivesText="Fly through Northrend Cup courses. Progress: Have you taken wing today?",starts={{mapID=2112,npcID=206737,x=0.27,y=0.474},{mapID=84,npcID=214111,x=0.6,y=0.663},{mapID=85,npcID=214112,x=0.524,y=0.599}},ends={{mapID=2112,npcID=206737,x=0.27,y=0.474},{mapID=84,npcID=214111,x=0.6,y=0.663},{mapID=85,npcID=214112,x=0.524,y=0.599}},coords={mapID=2112,source="quest_giver",x=0.27,y=0.474},questType="standard"},
[79131] = {id=79131,name="The Northrend Cup Begins",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Skyrider! You just missed Lord Andestrasz . He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Valdrakken.",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61}},ends={{mapID=2112,npcID=206737,x=0.27,y=0.474}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="standard"},
[79132] = {id=79132,name="The Northrend Cup Begins",level=30,requiredLevel=30,faction="alliance",expansion=10,zoneID=1519,mapID=84,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Stormwind.",starts={{mapID=84,npcID=214031,x=0.618,y=0.7505}},ends={{mapID=84,npcID=214111,x=0.6,y=0.663}},coords={mapID=84,source="quest_giver",x=0.618,y=0.7505},questType="standard"},
[79133] = {id=79133,name="The Northrend Cup Begins",level=30,requiredLevel=30,faction="horde",expansion=10,zoneID=1637,mapID=85,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!",objectivesText="Visit Lord Andestrasz in Orgrimmar.",starts={{mapID=85,npcID=213769,x=0.5255,y=0.795},{mapID=1165,npcID=214097,x=0.512,y=0.408}},ends={{mapID=85,npcID=214112,x=0.524,y=0.599}},coords={mapID=85,source="quest_giver",x=0.5255,y=0.795},questType="standard"},
[79134] = {id=79134,name="A Spring Awakening",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=15969,mapID=2112,description="The citizens of Goldshire have reported frequent interruptions to their recent festivities. Something about being overrun by angry... ducks? Perhaps you could look further into this conundrum.",objectivesText="Speak with Zinnia Brooks at Goldshire in Elwynn Forest.",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61},{mapID=2339,npcID=220307,x=0.46,y=0.546}},ends={{mapID=37,npcID=211646,x=0.42,y=0.65}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="standard"},
[79135] = {id=79135,name="Quacking Down",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=14,mapID=1,description="Those dratted ducks! Do you mind scaring them off again? I simply cannot leave my golden egg unattended!",objectivesText="Scare off 10 ducks using the Horn of Honking . Progress: Have you sufficiently shooed those ducks yet?",starts={{mapID=1,npcID=217125,x=0.525,y=0.412}},ends={{mapID=1,npcID=217125,x=0.525,y=0.412}},coords={mapID=1,source="quest_giver",x=0.525,y=0.412},questType="standard"},
[79136] = {id=79136,name="A Spring Awakening",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=15969,mapID=2112,description="The citizens of Razor Hill have reported frequent interruptions to their recent festivities due to a duck infestation, of all things. Perhaps you could look further into this conundrum.",objectivesText="Talk to Sylnaria Fareflame in Razor Hill.",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61},{mapID=2339,npcID=220307,x=0.46,y=0.546}},ends={{mapID=1,npcID=217125,x=0.525,y=0.412}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="standard"},
[79137] = {id=79137,name="The Wall Between Us",level=70,requiredLevel=70,faction="horde",expansion=10,zoneID=4706,mapID=21,description="I know this fight was not ours, <name>. But I thank you for your assistance. It was with the Alliance's assistance that Lordaeron was cleansed and the favor has now been returned. I do not think I can hope for peace. Instead, I will hope that these efforts have led to at least an understanding of the plights of both Gilneans and the Forsaken. Let us meet with Lilian in Pyrewood Village. This celebration is not for us.",objectivesText="Speak with Lilian and Calia in Pyrewood Village.",starts={{mapID=21,npcID=210965,x=0.428,y=0.726}},ends={{mapID=21,npcID=210964,x=0.426,y=0.727}},coords={mapID=21,source="quest_giver",x=0.428,y=0.726},questType="standard"},
[79139] = {id=79139,name="Alone in the Dark",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="My people do not think that this Black Blood is a threat to our world. It has sat dormant for ages, after all. Why should that change now? But the world is changing more quickly than my people realize. The nerubians' decision to extract the Blood for their own ends is proof of that. The nerubians hold a watchtower not far from here. The ones who survived the pit could not have gotten too far. We should give chase immediately.",objectivesText="Investigate the Eye of Ansurek. Progress: <The spider looks at you expectantly.>",starts={{npcID=215113,x=0.358,y=0.582,zoneID=14752}},ends={{npcID=216213,x=0.442,y=0.568,zoneID=14752}},coords={x=0.358,y=0.582,source="quest_giver",zoneID=14752},questType="standard"},
[79140] = {id=79140,name="Goldbricking",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Is this what we are to rely on to help us defeat Xal'atath? The Unbound define themselves by their desertion. And the Oathsworn, for being made of stone, are pretty soft. City life hasn't done them any favors. We've got a lot of work to do. Get down there and give these earthen a taste of what it's like to face a real threat. Try not to knock any \"offline,\" but a maiming here or there would send a strong message to the rest.",objectivesText="Spar with undisciplined earthen trainees. Progress: Don't go easy on them. They're made of stone after all.",starts={{npcID=215187,x=0.332,y=0.634,zoneID=14717}},ends={{npcID=215187,x=0.332,y=0.634,zoneID=14717}},coords={x=0.332,y=0.634,source="quest_giver",zoneID=14717},questType="standard"},
[79145] = {id=79145,name="Metal and Stone",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="While some of these recruits struggle with discipline, most have a strong work ethic. They only need training and the equipment to make the most of it. Earthen weaponsmiths and armorers have been working around the clock to equip this fledgling army. But we could use some help getting the new armaments into the hands of these trainees.",objectivesText="Equip earthen trainees for battle. Progress: Check in with Vindicator Jaelaana. She is in charge of distributing the weapons though she can be rather stingy. Be sure she doesn't send too many off for hand-to-hand training.",starts={{npcID=223205,x=0.332,y=0.634,zoneID=14717}},ends={{npcID=223205,x=0.332,y=0.634,zoneID=14717}},coords={x=0.332,y=0.634,source="quest_giver",zoneID=14717},questType="standard"},
[79146] = {id=79146,name="Ground Pounders",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="The rooks and their chosen riders will need time to bond. Perhaps you should use this time to check in on our other trainees. The Stormriders are the traditional army of the earthen, but many Unbound and Oathsworn have expressed willingness to fight at our side due to help in restoring their machines. Adelgonn , Geya'rah, and Turalyon are busy training them. Go and see if they need any assistance.",objectivesText="Meet with Adelgonn , Geya'rah, and Turalyon.",starts={{npcID=214919,x=0.278,y=0.608,zoneID=14717},{npcID=214919,x=0.38,y=0.708,zoneID=14771}},ends={{npcID=215277,x=0.332,y=0.634,zoneID=14717}},coords={x=0.278,y=0.608,source="quest_giver",zoneID=14717},questType="standard"},
[79147] = {id=79147,name="Flight Training 101",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Now that all of our recruits are present, it's high time we took to the air. See what I did there? High time? No? Right then. We'll be puttin' these rookies through their paces. Startin' with the basics of aerial maneuverin' at speed, we'll do our best to simulate the kind of precision flyin' we might expect below ground. After that, we'll see what these rooks can really do--an I think Thrall and Lufsela have somethin' special cookin'.",objectivesText="Help Kurdran train recruits in aerial maneuvering. Progress: Let's set a good example for these new riders. Lead them through the course as quick as ye can.",starts={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},ends={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},coords={x=0.35,y=0.722,source="quest_giver",zoneID=14717},questType="standard"},
[79148] = {id=79148,name="The Nibelgaz Refinery",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Quickly! Elementals have overrun the Nibelgaz Mine and the refinery crew are trapped down there with them. I am especially worried about my fused, Munderut. His memory is not the best these days. If you are a friend, rescue him and the refinery workers. Here, take this healing clay . It only helps a little, but it should be enough for any injured to make their way back. I wish we had a rejuvenating crystal, but that is the stuff of legends.",objectivesText="Rescue 6 Refinery Workers and look for Munderut.",starts={{npcID=215208,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=215208,x=0.51,y=0.148,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79149] = {id=79149,name="Rampage in the Refinery",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Catastrophe! Oh, this is awful. Awful! Those accursed slag heap elementals are keeping my refinery workers from being able to do their jobs. Duty demands we carry on our work. These delays will not be tolerated. You look competent enough. Go on, get down there and get to work destroying elementals. Production must not be slowed!",objectivesText="Kill 10 Rampaging Elementals . Progress: Well? Did you destroy them? I need my crew back to work immediately!",starts={{npcID=215234,x=0.514,y=0.144,zoneID=14795}},ends={{npcID=215234,x=0.514,y=0.144,zoneID=14795}},coords={x=0.514,y=0.144,source="quest_giver",zoneID=14795},questType="standard"},
[79150] = {id=79150,name="Thespians at the Proscenium",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14776,mapID=2248,description="When I wanted the Unbound to bring their plays to Dornogal, I didn't know what I would be up against. Or that my \"help\" would get in the way. My old friend Brokfor keeps interrupting us with his perfectionism. We try to build a set, but he stops everyone to inspect each nail. We try to paint, he complains the colors do not exactly match... you get the idea. I think Brokfor needs his own project. Maybe... cleaning up the Proscenium? Go ask him to help and keep him occupied.",objectivesText="Help Architect Brokfor clean up the Proscenium. Progress: Have you helped Brokfor straighten up?",starts={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},ends={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},coords={x=0.564,y=0.514,source="quest_giver",zoneID=14717},questType="standard"},
[79156] = {id=79156,name="The Edicts",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="Merrix and Adelgonn will be expecting an update. On my way here, I heard that they're all heading to the Proscenium to commit to the war officially. You should go and brief them on the readiness of the Stormriders. I'd like a moment with Zarein here. But we'll be along soon. And we'll be bringing Baelgrim's spirit with us.",objectivesText="Report to Merrix and Adelgonn. Progress: This is a critical moment for all earthen.",starts={{npcID=214916,x=0.57,y=0.506,zoneID=14717},{npcID=214995,x=0.276,y=0.604,zoneID=14717},{npcID=214916,x=0.318,y=0.61,zoneID=14771}},ends={{npcID=214916,x=0.57,y=0.506,zoneID=14717},{npcID=214916,x=0.318,y=0.61,zoneID=14771}},coords={x=0.57,y=0.506,source="quest_giver",zoneID=14717},questType="standard"},
[79157] = {id=79157,name="Titanic Failsafe",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="So, the titans sent their ancient machines against their disobedient children. Would our creators have us protect the Coreway at the expense of all else? At the expense of Azeroth herself? Are we meant to preside over a road untraveled, leading to the world's dead heart? No, today we are all Unbound, and we will fight for our freedom. For Azeroth!",objectivesText="Defeat the colossal titan construct . Progress: None on this isle will be safe until that titan construct is dealt with. Go!",starts={{npcID=214916,x=0.57,y=0.506,zoneID=14717},{npcID=214916,x=0.318,y=0.61,zoneID=14771}},ends={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},coords={x=0.57,y=0.506,source="quest_giver",zoneID=14717},questType="standard"},
[79158] = {id=79158,name="Seeds of Salvation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="These once obedient harvestbots have run amok and are wreaking havoc in our fields. The success of our community depends on getting our seeds in the ground, but most of the seeds are in the hands of those harvesters! Would you venture into the fields, eliminate any rogue machines, gather the seeds, and finish the planting?",objectivesText="Recover Harvest Seeds and plant 8 seeds in Seed-Ready Soil . Progress: Have you planted the seeds?",starts={{npcID=206441,x=0.652,y=0.28,zoneID=14838}},ends={{npcID=206441,x=0.652,y=0.28,zoneID=14838}},coords={x=0.652,y=0.28,source="quest_giver",zoneID=14838},questType="standard"},
[79159] = {id=79159,name="Dereliction of Duty",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="A moment, if you have one. One of my lieutenants, Shinda Creedpike , did not report in at first bonfire. That may not seem like a large issue to you, but the Arathi in Hallowfall survive only because we follow orders and stand for our brethren. I am not cruel. I do not want to punish a man for his weakness in this terrible environment. Can you find him and bring him back? Take all the time you need.",objectivesText="Find Shinda Creedpike at Mereldar in Hallowfall . Progress: Dawnsurge must have sent you. It seems like my respite is over.",starts={{npcID=215306,x=0.414,y=0.524,zoneID=14838}},ends={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},coords={x=0.414,y=0.524,source="quest_giver",zoneID=14838},questType="standard"},
[79160] = {id=79160,name="Fishing is Good for the Soul",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I used to fish with my mother at the local pond when I was a child. It wasn't the fish that made the experience--my mother was famously terrible at cooking--but the tranquility and bonding time. Perhaps I could find a portion of that peace again here. There's a spot south of Mereldar that the others use to fish. I'll meet you there!",objectivesText="Meet Shinda at the fishing hole. Progress: Maybe I can find peace in the act of fishing.",starts={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},ends={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},coords={x=0.406,y=0.506,source="quest_giver",zoneID=14838},questType="standard"},
[79162] = {id=79162,name="Burnout",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Please return to Commander Dawnsurge and give them my sincere apologies for my absence. I will submit myself for punishment for my trespass after my shift.",objectivesText="Return to Endiri Dawnsurge in Mereldar.",starts={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},ends={{npcID=215306,x=0.414,y=0.524,zoneID=14838}},coords={x=0.406,y=0.506,source="quest_giver",zoneID=14838},questType="standard"},
[79173] = {id=79173,name="Supply the Effort",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="When shadow fell upon our town, many necessary supplies were taken in the cover of darkness. With the light returning, it is time to rebuild, but first, we must retrieve what was lost. Search the surrounding areas, recover any supplies that might be useful.",objectivesText="Recover various stolen items from the surrounding area to satisfy our needs. Progress: Have you recovered the stolen items?",starts={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},ends={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},coords={x=0.632,y=0.294,source="quest_giver",zoneID=14838},questType="standard"},
[79174] = {id=79174,name="Infested Infestation",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="These spore-afflicted beasts at Pillar-nest Vosh been a thorn in our side since setting up Faerin's Advance. They be spreading thick clouds of spores. I never be seeing anything like it! They already attacked once. Won't be long till they attack again. If we got any hope of survivin', we need to cull dere numbers. Go to Pillar-nest Vosh and take some of those spore-afflicted beasts out!",objectivesText="Kill 12 spore-afflicted beasts at Pillar-nest Vosh.",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79175] = {id=79175,name="I Think I'm a Drone Now",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="There, I have extended some goodwill. You have a little goblin friend. I know how much your kind clings to each other for warmth. And now you both will do things for me. First, I will provide you with my pheromone scent mark. It will keep my loyal soldiers from attacking you. It marks you as mine.",objectivesText="Allow Anub'azal to mark you with his pheromones. Progress: Don't waste my time. Are you ready to accept my mark? Step into the pheromone cloud with your <race> friend, and rub it on.",starts={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},ends={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},coords={x=0.454,y=0.198,source="quest_giver",zoneID=14752},questType="standard"},
[79176] = {id=79176,name="Opals and Runes",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="You have certainly made my disaster of a day far less stressful, . For that, you have the thanks of the entire Forgegrounds and those who keep it running. Vokgret winks as she gives you a knowing smile.> Bevrusi was right to send you to me. Do tell her not to be a stranger now. I could use more friends from the Deeps. Here is her liquid opal. Give it to her with my compliments.",objectivesText="Trade the Vial of Liquid Opal for the Speakeasy Passrune from Bevrusi. Progress: Everyone in the city is in need of something, and there is always someone with the means to acquire it.",starts={{npcID=217091,x=0.452,y=0.488,zoneID=14771}},ends={{npcID=217097,x=0.604,y=0.332,zoneID=14771}},coords={x=0.452,y=0.488,source="quest_giver",zoneID=14771},questType="standard"},
[79178] = {id=79178,name="Play Hearthstone!",faction="both",expansion=10,zoneID=13862,mapID=1,description="It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.",objectivesText="Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!",starts={{mapID=1,npcID=215409,x=0.53,y=0.152}},ends={{mapID=1,npcID=215409,x=0.53,y=0.152}},coords={mapID=1,source="quest_giver",x=0.53,y=0.152},questType="standard"},
[79184] = {id=79184,name="It's Hearthstone's Anniversary!",faction="both",expansion=10,zoneID=14,mapID=1,description="\"Hearthstone's been played for ten years, can you believe it? I'm hosting Hearthstone games in Valdrakken, way up in the Seat of the Aspects. Come join us! -Farala, Master of Ceremonies\"",objectivesText="Speak with M.C. Farala in Valdrakken, in the Seat of the Aspects.",ends={{mapID=1,npcID=215409,x=0.53,y=0.152}},coords={mapID=1,source="quest_giver",x=0.53,y=0.152},questType="standard"},
[79186] = {id=79186,name="It's Hearthstone's Anniversary!",level=0,requiredLevel=0,faction="none",expansion=10,description="Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!",objectivesText="Speak with M.C. Farala in Stormwind.",questType="standard"},
[79189] = {id=79189,name="It's Hearthstone's Anniversary!",level=0,requiredLevel=0,faction="none",expansion=10,description="\"Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!",objectivesText="Speak with M.C. Farala in Durotar.",questType="standard"},
[79193] = {id=79193,name="Spinning Spore Spines",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Orsenth sent you? And we are supposedly fused? Why... so I am wearing a medallion. But I have no memory... Well, no time for that. Did you see the spinning spores on your way here? I need the spines that they grow for... I need them for... now what was it again? Oh yes! There is no better instrument for carving out the fine detail that my work as a gem carver requires than those spines. Will you collect some? I will make my way back to the refinery. I am eager to get back and meet this Orsenth.",objectivesText="Collect 150 Spore Spines for Munderut . Progress: Why, what is this now? You're a stranger to these depths, are you not? What are you doing here? <You remind him of all you've spoken of.> Well, what are you waiting for? Go and get me those spines!",starts={{npcID=215209,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=215209,x=0.51,y=0.148,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79194] = {id=79194,name="To the Source",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Orsenth told me you have been instrumental in dealing with the elemental problem here at the mine. I am Keldaz , supervisor for the militia. We came as soon as word of the attack reached us in Gundargaz. The miners you rescued said that the elementals poured out of the northeast mine shaft. I will leave some of my guards here to lend their support and have sent for reinforcements. If you are still willing to help, meet me outside the cave and let us see what we can do to staunch the flow of elementals.",objectivesText="Meet Keldaz outside of the northeastern mine.",starts={{npcID=217474,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=223000,x=0.552,y=0.11,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79196] = {id=79196,name="Renowned with The Severed Threads",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The Weaver has been keeping an eye on you. She has determined you would be a better asset with more resources at your disposal. Come to the Weaver's Lair. I have a parcel waiting for you.",objectivesText="Speak with Lady Vinazian in the Weaver's Lair.",starts={{x=0.553,y=0.412,mapID=2255,npcID=220867}},ends={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},coords={mapID=2255,source="quest_giver",x=0.552,y=0.412},questType="standard"},
[79197] = {id=79197,name="Surface Bound",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14771,mapID=2255,description=", the moment is upon us. We must make haste to the city of Dornogal, where our allies await. Only together do we stand a chance against Harbinger's machinations.",objectivesText="Meet with Moira Thaurissan and your allies in Dornogal in the Isle of Dorn .",starts={{npcID=219252,x=0.556,y=0.44,zoneID=14752}},ends={{npcID=216149,x=0.36,y=0.802,zoneID=14771}},coords={x=0.556,y=0.44,source="quest_giver",zoneID=14752},questType="standard"},
[79199] = {id=79199,name="Renowned with Keg Leg's Crew",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=13644,mapID=2022,description="Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.",objectivesText="Speak with Cataloger Jakes at the Dragonscale Basecamp.",questType="standard"},
[79205] = {id=79205,name="Not Waste, Not Want",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Everything have use, friend. Even things stoneheads throw away and think worthless. Kobolds know better. Go and see what you can find. Need to scavenge lots of scrap. Enough for kobold crafting of new homes!",objectivesText="Collect potentially useful scrap from around the Warrens. Progress: You will be surprised. Kobold crafting is amazing!",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[79206] = {id=79206,name="Broken Memories",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Something about this particular gemstone feels important. Perhaps it would be worthwhile to bring it to Speaker Brinthe .",objectivesText="Bring the Faded Memory Gem to Brinthe. Provided item:",ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.555,y=0.292},questType="standard"},
[79213] = {id=79213,name="The Anachronism",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Insert the batteries into the cylindrical holes on the console. Then, titans willing, we will see what it holds.",objectivesText="Activate the Excavated Console and use the device to defeat the Sargassum Guardian in Golgrin's Reach. Progress: To obtain the power necessary, find an elemental of sufficient size to charge the artifact. If I am right, the titan artifact will do the rest.",starts={{npcID=225478,x=0.616,y=0.702,zoneID=14717}},ends={{npcID=225478,x=0.616,y=0.702,zoneID=14717}},coords={x=0.616,y=0.702,source="quest_giver",zoneID=14717},questType="standard"},
[79216] = {id=79216,name="Web of Manipulation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="This town has been under siege, overrun by spiders! Even when we clear them out, they always return. Something is behind these attacks! A small ledge northeast of Light's Bloom harbors these spiders. Scout out the ledge. Find out what is driving these spiders to attack us, and put an end to it!",objectivesText="Explore the nearby ledge and deal with any threats within. Progress: Have you solved our spider problem?",starts={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},ends={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},coords={x=0.632,y=0.294,source="quest_giver",zoneID=14838},questType="standard"},
[79217] = {id=79217,name="Back to Base",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Getting this factory up and running will be a challenge, but I think we'll figure out something. Let's head back to Gundargaz and consult with a friend of ours. His mind will be a big help to us here.",objectivesText="Meet Brinthe back in Gundargaz.",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79218] = {id=79218,name="Renowned with the Hallowfall Arathi",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Your labors on behalf of our people have not gone unnoticed. Nor will they go unrewarded. Find me in Mereldar.",objectivesText="Speak with Auralia Steelstrike in Mereldar.",starts={{x=0.413,y=0.531,mapID=2215,npcID=213145}},ends={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},coords={mapID=2215,source="quest_giver",x=0.418,y=0.54},questType="standard"},
[79219] = {id=79219,name="Renowned with the Council of Dornogal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="The Council continues to be in your debt, friend. If you visit me in Dornogal, I will give you supplies to reduce that debt.",objectivesText="Speak with Auditor Balwurz in Dornogal.",starts={{x=0.391,y=0.24,mapID=2339,npcID=223728}},ends={{npcID=223728,x=0.392,y=0.242,zoneID=14771}},coords={mapID=2339,source="quest_giver",x=0.393,y=0.244},questType="standard"},
[79220] = {id=79220,name="Renowned with the Assembly of the Deeps",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Good work deserves good reward, yes? Assembly is grateful. Waxmonger Squick is grateful. Show gratefulness with many supplies. Come see Waxmonger Squick in Gundargaz.",objectivesText="Speak with Waxmonger Squick in Gundargaz.",starts={{x=0.433,y=0.328,mapID=2214,npcID=221390}},ends={{npcID=221390,x=0.472,y=0.328,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.452,y=0.328},questType="standard"},
[79221] = {id=79221,name="The Unusual Bug",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Nerubians in Rak-Ush may find this strange little spider of interest.",objectivesText="Deliver this Unusual Bug to Widow Arak'nai in Rak-Ush. Provided item:",starts={{x=0.672,y=0.218,mapID=2215}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={mapID=2255,source="quest_giver",x=0.556,y=0.438},questType="standard"},
[79222] = {id=79222,name="Shadow-Hardened Mainspring",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Speaker Kuldas in Gundargaz.>",objectivesText="Deliver this item to Kuldas in Gundargaz. Provided item:",ends={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.453,y=0.32},questType="standard"},
[79223] = {id=79223,name="Finally, An Archivist!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="So you've got your bearings now? You've felt the dirt? You've smelled the history? Why not celebrate this glorious moment of above average success with... a cap! That's right! Take this token to our beloved provisioner, Aristta. She'll be happy to provide you with one of our all-purpose caps to signify your elevation to Archivist from naive passerby.",objectivesText="Purchase an Archivist's Buckled Cap from Provisioner Aristta. Progress: The cap suits you quite well!",starts={{mapID=2025,npcID=206107,x=0.615,y=0.312}},ends={{mapID=2025,npcID=206107,x=0.615,y=0.312}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[79224] = {id=79224,name="Gathering Intel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2339,description="The Widow Arak'nai sent word via one of those \"weave-rats\" of hers. She has a lead that may be relevant to our cause, and has invited us to investigate. All the training in the world is useless without knowledge of our enemy. My own reconnaissance efforts in Azj-Kahet were met with... mixed results, as you may recall. I admit I am not keen on venturing down there again so soon. Fortunately, reinforcements have arrived with a capable spymaster. Unfortunately, she is... well. You'll see.",objectivesText="Speak with Widow Arak'nai at the Weaver's Lair in Azj-Kahet .",starts={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.316,y=0.596,source="quest_giver",zoneID=14771},questType="standard"},
[79225] = {id=79225,name="The Lost Flame",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Hallowfall Expedition member, its return would help honor the memory of those who bravely gave their lives.> An expedition scout might possess knowledge about this item.>",objectivesText="Deliver the Expedition Tinderbox to Keyrra Flamestonge at the Shadowgrove Vineyards. Provided item:",starts={{x=0.611,y=0.096,mapID=2215}},ends={{npcID=215527,x=0.654,y=0.322,zoneID=14838}},coords={mapID=2215,source="quest_giver",x=0.654,y=0.322},questType="standard"},
[79226] = {id=79226,name="The Big Dig: Traitor's Rest",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13844,mapID=2025,description="Don your cap, put on a pair of sturdy gloves, and grab a snack because Traitor's Rest is ready for Archivists everywhere to sink their history-craving teeth into!",objectivesText="Aid Eadweard Dalyngrigge and the Azerothian Archivists at The Big Dig in Traitor's Rest. Progress: Not every day you unearth ancient dragon mysteries... or even a dragon themselves!",starts={{mapID=2025,npcID=206107,x=0.615,y=0.312},{mapID=2024,npcID=209134,x=0.27,y=0.464}},ends={{mapID=2025,npcID=206107,x=0.615,y=0.312},{mapID=2024,npcID=209134,x=0.27,y=0.464}},coords={mapID=2025,source="quest_giver",x=0.615,y=0.312},questType="standard"},
[79227] = {id=79227,name="A Spider's-Eye View",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2255,description="I have eyes in every crevice of the city save for one that has... eluded me. The Transformatory is the grounds of Ansurek's most precocious minions and treasured pets. It is where the Ascension process was developed. I've only gotten my claws on it recently, thanks to dear Y'tekhi. Much of it remains uncomfortably shrouded. A more legs-on approach is in order. Place shadecasters to collect intel from my scouts, then meet Y'tekhi and your own spymaster Voss in a discreet corner of the district.",objectivesText="Place shadecasters to rendezvous with the Weaver's scouts in the Umbral Bazaar, the Eastern Span, and the Twitching Gorge.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=215626,x=0.696,y=0.716,zoneID=14753}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[79230] = {id=79230,name="Creeping Through Corridors",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2213,description="I've identified three sites of interest to investigate. A stockpile on the east side of the complex, a warehouse in the center, and lastly, that big storehouse with royal Sureki flags outside it. We'll rendezvous there. There's less chance of discovery if we move separately through the area. You may be hidden from most nerubians, but the Ascended will sniff you out. Chuck some of these anger pheromones at them if you get heat, it'll distract them. Stay sharp, stay quiet.",objectivesText="Investigate the western stockpile, central warehouse, and royal stores of the Transformatory, using anger pheromones to distract guards and avoid detection. Progress: Don't let your guard down. Not here.",starts={{npcID=215626,x=0.696,y=0.716,zoneID=14753}},ends={{npcID=215628,x=0.568,y=0.906,zoneID=14753}},coords={x=0.696,y=0.716,source="quest_giver",zoneID=14753},questType="standard"},
[79231] = {id=79231,name="Back to Headquarters! Again!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="You've done truly incredible work! The proof is obvious: you are, in fact, a proper Azerothian Archivist. Meet us all back at our headquarters in Thaldraszus. Eadweard would like codify all your helpful labors and achievements for our group.",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433},{npcID=208362,x=0.172,y=0.164,zoneID=14433},{npcID=207763,x=0.382,y=0.498,mapID=2133},{npcID=208055,x=0.476,y=0.486,mapID=2133}},ends={{npcID=206107,x=0.614,y=0.312,mapID=2025}},coords={x=0.77,y=0.384,source="quest_giver",mapID=2025},questType="standard"},
[79233] = {id=79233,name="Lab Access",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2213,description="As much as I adore skulking in the shadows, the juiciest intel is going to be inside the laboratory of the Grand Splicer. Of course you'll need the proper pheromones once you're in, but we can take care of that with a little biological forgery. The nerubian loyalists here are surely on the invite list. Six of their secretions should be enough to disguise the three of us.",objectivesText="Collect 6 Loyalist Secretions from nerubian loyalists in the Transformatory area. Progress: If you saw me? No you didn't.",starts={{npcID=215637,x=0.696,y=0.72,zoneID=14753}},ends={{npcID=215659,x=0.57,y=0.908,zoneID=14753}},coords={x=0.696,y=0.72,source="quest_giver",zoneID=14753},questType="standard"},
[79234] = {id=79234,name="A Small Bag of Seeds",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Aliya Hillhelm could make use of them.>",objectivesText="Deliver this small bag of seeds to Aliya Hillhelm at the Hillhelm Stead. Provided item:",ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},coords={mapID=2215,source="quest_giver",x=0.612,y=0.305},questType="standard"},
[79237] = {id=79237,name="Making of a Monster",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2213,description="We've got a new objective: Figure out what Ansurek's plans are for this... thing. We'll find our answers inside the laboratory of the Grand Splicer. I'd bet my blades on it. I scouted a maintenance hatch on the roof that you can grapple up to. Y'tekhi brewed up some weird concoction that they claim will get us the proper clearance once inside. Yuck. Meet you in there.",objectivesText="Access the Laboratory of the Grand Splicer via roof hatch, then investigate clues as to the purpose of the First Ascended. Progress: I don't like this. There's something we're still missing here.",starts={{npcID=215628,x=0.568,y=0.906,zoneID=14753}},ends={{npcID=215628,x=0.568,y=0.906,zoneID=14753}},coords={x=0.568,y=0.906,source="quest_giver",zoneID=14753},questType="standard"},
[79239] = {id=79239,name="The Queen's Chains",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Ansurek... that worm, that witless, gutless little-- Y'tekhi growls under their breath, struggling to maintain their composure.> If this is what's become of Neferess, we must free her. She is still our queen. My mistress will know what to do. When the Weaver discovers what they've all done, there will not be a crevice deep enough to escape her wrath.",objectivesText="Destroy Neferess's shackles.",starts={{npcID=215659,x=0.57,y=0.908,zoneID=14753}},ends={{npcID=215661,x=0.786,y=0.574,zoneID=14753}},coords={x=0.57,y=0.908,source="quest_giver",zoneID=14753},questType="standard"},
[79240] = {id=79240,name="Rogue Agent",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2213,description="We lost Y'tekhi . We can worry about the how of it later. Right now, we need to worry about taking them down before they make things worse. I guess we came down here to find out what Xal'atath had up her sleeve. ...I wish we'd minded our own business.",objectivesText="Subdue Y'tekhi . Progress: Hard to think of how this could have gone any worse.",starts={{npcID=215661,x=0.786,y=0.574,zoneID=14753}},ends={{npcID=215662,x=0.786,y=0.398,zoneID=14753}},coords={x=0.786,y=0.574,source="quest_giver",zoneID=14753},questType="standard"},
[79241] = {id=79241,name="Go Loud",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2213,description="So much for keeping this operation quiet. At least now that our cover's blown, we can really mess things up. They're hauling weapons across the south bridge. If we turn those weapons against them, they'll have to resupply their whole army. That'll buy us time, at least. I've identified six weak spots across the convoy. Rig up bombs to all six, then get out of there and watch the fireworks.",objectivesText="Plant 6 Commandeered Nerubian Charges at specified points across the convoy, then remotely detonate them. Progress: They know we're here. May as well make the most of it.",starts={{npcID=215662,x=0.786,y=0.398,zoneID=14753}},ends={{npcID=215625,x=0.556,y=0.44,zoneID=14752}},coords={x=0.786,y=0.398,source="quest_giver",zoneID=14753},questType="standard"},
[79243] = {id=79243,name="Manufactured Mutiny",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2213,description="We don't have the firepower to dismantle their whole manufacturing operation, but what we do have is two leftover vials of anger pheromones. Let's make them count. There's a siege marshal and a quartermaster overseeing the preparations and giving everyone orders. Logistics types, but they still pack a punch. That's where those pheromones come in. Hit them with a vial, and their own armies will turn against them. Take out both, and we watch the operation crumble.",objectivesText="Slay Siege Marshal Tekhzok and Royal Quartermaster Ze'erik . Progress: Those aggression pheromones came in handy... let's make sure not to waste them.",starts={{npcID=215662,x=0.786,y=0.398,zoneID=14753}},ends={{npcID=215625,x=0.556,y=0.44,zoneID=14752}},coords={x=0.786,y=0.398,source="quest_giver",zoneID=14753},questType="standard"},
[79244] = {id=79244,name="News From Below",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2255,description="I could hear the explosions from here. That'll buy us some time. Maybe I'd even be relieved, if this had gone less poorly. Y'tekhi is secured in the back, where they can't overhear anything. Whatever Xal'atath did... it hasn't worn off yet. The Weaver has people looking into it, but the outlook is grim. Alleria is going to want a status report. Good luck.",objectivesText="Inform Widow Arak'nai about what was found in the Transformatory. Then, return to Alleria at Dornogal on the Isle of Dorn. Progress: Nothing to do but keep going.",starts={{npcID=215625,x=0.556,y=0.44,zoneID=14752}},ends={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},coords={x=0.556,y=0.44,source="quest_giver",zoneID=14752},questType="standard"},
[79245] = {id=79245,name="[Unused - Reuse Quest Bit]",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[79256] = {id=79256,name="A Hint of Fear",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="My father thinks that while he and Dagran were dealing with the skardyn tae the south, he caught a sensation o' his old hammer, Fearbreaker. He said it slipped out o' his fingers when Dalaran crashed, and it's been bothering him mightily. That hammer belongs tae the Bronzebeard clan, and has for generations. But he hasn't been himself lately, either. I'm willing tae have a look, so he doesn't worry that he might've missed it. Meet me down at Camp Murroch, and we'll have a quick look around.",objectivesText="Meet Moira Thaurissan outside Camp Murroch.",starts={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},ends={{npcID=215781,x=0.55,y=0.632,zoneID=14795}},coords={x=0.47,y=0.34,source="quest_giver",zoneID=14795},questType="standard"},
[79258] = {id=79258,name="Mineral Water Woes",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="When that magic hammer fell into the Deeps, I knew it could be a formidable weapon against the skardyn menace. Your friend has told me that it's 'particular' about its wielder. Fortunately, I am a hero! And as a hero, I know how to get close to it. We need to have a good mix of pollen and water plastered onto us. That way, the beast standing over it will think we're just like it. That mineral water has to be the exact right temperature to mix with the lashroom dust and blend in.",objectivesText="Acquire the proper-temperature mineral water from the Living Grotto springs.",starts={{npcID=215788,x=0.55,y=0.632,zoneID=14795}},ends={{npcID=215821,x=0.54,y=0.666,zoneID=14795}},coords={x=0.55,y=0.632,source="quest_giver",zoneID=14795},questType="standard"},
[79259] = {id=79259,name="Put On a Good Face",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Berrund here says that the massive beast standing over Fearbreaker is very particular about what kinds of creatures it allows near it. If we blend in, he says, we can get close enough tae nab the hammer. But tae blend in, he says we have tae get covered by the dust an' pollen in the grotto. Those Lashrooms look like they're a good place to start. It all seems suspicious tae me, but fer now, we'll play along until I can recover Fearbreaker and bring it back to my father.",objectivesText="Collect Lashroom Dust from Lashrooms in the Living Grotto. Progress: Have you gathered up that dust? It's the only way you're going to get near that hammer, especially with that creature wandering around.",starts={{npcID=215781,x=0.55,y=0.632,zoneID=14795}},ends={{npcID=215788,x=0.55,y=0.632,zoneID=14795},{npcID=215822,x=0.54,y=0.666,zoneID=14795}},coords={x=0.55,y=0.632,source="quest_giver",zoneID=14795},questType="standard"},
[79260] = {id=79260,name="Epicenter",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="There is the creature standing between us and that magic hammer. It certainly made an impact when it landed here in the Ringing Deeps , didn't it? Look at the size of that crater! With the pollen and water splashed on you like this, you should be able to approach that beast and, theoretically, not be harmed. You'll blend right in with it! But if it does turn aggressive, don't worry, I'll be right behind you. We'll get that hammer out of here safely!",objectivesText="Approach the Verdant Hulk .",starts={{npcID=215822,x=0.54,y=0.666,zoneID=14795}},ends={{npcID=215821,x=0.54,y=0.666,zoneID=14795}},coords={x=0.54,y=0.666,source="quest_giver",zoneID=14795},questType="standard"},
[79261] = {id=79261,name="Boiling Mad",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="That gravel-brained ingrate! He took Fearbreaker and ran off to the north! It's not that I want that hammer for myself. I don't. But it belongs to the Bronzebeard clan. It should be in the hands of someone who respects its power! We need to track him down before he hurts himself or someone else with that hammer!",objectivesText="Track Berrund and Fearbreaker through the Ringing Deeps .",starts={{npcID=215821,x=0.54,y=0.666,zoneID=14795}},ends={{npcID=215824,x=0.56,y=0.5,zoneID=14795}},coords={x=0.54,y=0.666,source="quest_giver",zoneID=14795},questType="standard"},
[79262] = {id=79262,name="Clean Up House",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="It looks like the destruction around the Coreway rattled loose more than just a few stones down here. It's stirred up all sorts o' dark things. If this was a thriving mining operation, it ain't anymore. We need to help the earthen get it under control again, and that means thinning out these beasts.",objectivesText="Slay agitated creatures in the Rumbling Wastes. Progress: I want to get Fearbreaker back, but we need to clear out some of these agitated beasts first.",starts={{npcID=215824,x=0.56,y=0.5,zoneID=14795}},ends={{npcID=215837,x=0.572,y=0.456,zoneID=14795}},coords={x=0.56,y=0.5,source="quest_giver",zoneID=14795},questType="standard"},
[79263] = {id=79263,name="Fault Lines",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Berrund took Fearbreaker for himself. I suppose he thought he could save these people. Be the hero. But ye can't go about doing the wrong thing for the right reasons. I know from experience. If a rock is hollow tae begin with, it never can be solid again, no matter how hard ye try. He's likely tae need saving himself now. Let's find him in this blasted place.",objectivesText="Find Berrund the Gleaming within the Rumbling Wastes. Progress: You found me?",starts={{npcID=215824,x=0.56,y=0.5,zoneID=14795}},ends={{npcID=215836,x=0.572,y=0.456,zoneID=14795}},coords={x=0.56,y=0.5,source="quest_giver",zoneID=14795},questType="standard"},
[79264] = {id=79264,name="These Strong Hands",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Berrund the Gleaming coughs dustily.> I knew I couldn't take the skardyn without some help. I thought, if I just had that magic hammer, then nothing would stop me. I had to have it, you see, or else, maybe I wasn't who I was made to be. But it kept slipping out of my fingers. Like it didn't want anything to do with me. It fell out of my hands at the worst moment and now... It's clearly not mine. It never was. I'm... I'm... sorry.",objectivesText="Witness Moira Thaurissan .",starts={{npcID=215836,x=0.572,y=0.456,zoneID=14795}},ends={{npcID=217598,x=0.572,y=0.456,zoneID=14795}},coords={x=0.572,y=0.456,source="quest_giver",zoneID=14795},questType="standard"},
[79265] = {id=79265,name="Fearbreaker",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="The skardyn have taken over the operations here in the Rumbling Wastes. That's why Berrund thought he needed Fearbreaker . We're going to finish that job before I take the hammer back to Magni. What kind of a queen would I be if I wasn't willing tae put myself in danger for the good of others? Let's get in there and save as many as we can.",objectivesText="Slay skardyn and save earthen in the Rumbling Wastes with Moira Thaurissan .",starts={{npcID=217598,x=0.572,y=0.456,zoneID=14795}},ends={{npcID=216085,x=0.618,y=0.466,zoneID=14795}},coords={x=0.572,y=0.456,source="quest_giver",zoneID=14795},questType="standard"},
[79266] = {id=79266,name="The Bronzebeard Legacy",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Well, we did what we set out tae do... and more. We found Fearbreaker and did some good with it. Now it's time tae bring it back tae Magni. Let's hope Berrund learned a lesson here, but I suspect he'll manage tae get himself in trouble again soon. Hopefully, it'll be fer the right reasons an' with the right support.",objectivesText="Meet Moira Thaurissan in Gundargaz.",starts={{npcID=216085,x=0.618,y=0.466,zoneID=14795}},ends={{npcID=217827,x=0.472,y=0.34,zoneID=14795}},coords={x=0.618,y=0.466,source="quest_giver",zoneID=14795},questType="standard"},
[79267] = {id=79267,name="Wax On, Pot Off",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="If candles are important to kobold society, I have an idea that might disrupt their production... or at least make sure there's an unpleasant surprise waiting for our enemy. Take that cinderbrew. Drop some in those large vats of wax the kobolds are prepping at the top of that hill. It's a powerful explosive. It burns aggressively, so try not to drop any. It should certainly make any candles made with that wax quite feisty, once they're lit.",objectivesText="Sabotage the pots of wax in the Warrens. Progress: Try not to breathe too many of the fumes.",starts={{npcID=212992,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212992,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[79268] = {id=79268,name="Gundrak Fast Track",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.836,y=0.173,mapID=121,npcID=215795}},ends={{x=0.836,y=0.173,mapID=121,npcID=215795}},coords={mapID=121,x=0.836,y=0.173},questType="standard"},
[79269] = {id=79269,name="Gundrak Fast Track - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.836,y=0.173,mapID=121,npcID=215795}},ends={{x=0.836,y=0.173,mapID=121,npcID=215795}},coords={mapID=121,x=0.836,y=0.173},questType="standard"},
[79270] = {id=79270,name="Gundrak Fast Track - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.836,y=0.173,mapID=121,npcID=215795}},ends={{x=0.836,y=0.173,mapID=121,npcID=215795}},coords={mapID=121,x=0.836,y=0.173},questType="standard"},
[79272] = {id=79272,name="Coldarra Climb",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.322,y=0.24,mapID=114,npcID=215825}},ends={{x=0.322,y=0.24,mapID=114,npcID=215825}},coords={mapID=114,x=0.322,y=0.24},questType="standard"},
[79273] = {id=79273,name="Coldarra Climb - Advanced",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.322,y=0.24,mapID=114,npcID=215825}},ends={{x=0.322,y=0.24,mapID=114,npcID=215825}},coords={mapID=114,x=0.322,y=0.24},questType="standard"},
[79274] = {id=79274,name="Coldarra Climb - Reverse",level=10,requiredLevel=10,faction="none",expansion=10,description="Fly through the checkpoint rings marking the course.",objectivesText="Glide through the rings.",starts={{x=0.322,y=0.24,mapID=114,npcID=215825}},ends={{x=0.322,y=0.24,mapID=114,npcID=215825}},coords={mapID=114,x=0.322,y=0.24},questType="standard"},
[79282] = {id=79282,name="The Grand Debut",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14776,mapID=2248,description="The Proscenium is looking amazing! Are you ready to get on stage? Give us a hand as part of the crew, and we'll give you a chance to act. Will you accept this directive?",objectivesText="Complete one Theater Troupe event in The Proscenium. Progress: I haven't seen you on stage yet, <name>. You won't win any fans by standing around!",starts={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},ends={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},coords={x=0.564,y=0.514,source="quest_giver",zoneID=14717},questType="standard"},
[79297] = {id=79297,name="Nightwatch",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Xal'atath is using the Order of Night to serve her whims. I overheard some of the Arathi complaining about a new wave of propaganda that has been put up around Mereldar. Find what you can and deliver it to General Steelstrike . I'll be there as soon as I can. We need to convince her of the severity of this threat.",objectivesText="Collect 8 Order of Night Propaganda . Progress: Anything I can help you with, <name>?",starts={{npcID=218182,x=0.426,y=0.556,zoneID=14838}},ends={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},coords={x=0.426,y=0.556,source="quest_giver",zoneID=14838},questType="standard"},
[79300] = {id=79300,name="The Notebook",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="$p, I need your help. My whole future is on the line! I came to Lightspark to be an airship captain, and I've put in a ton of work to excel here. But my notebook is missing, with my final report! I'm top in the class, but if I don't turn it in soon, I won't be our next airship captain. Please help me find it. I thought I left it out by the canyon where we review each other's skiff piloting, but it wasn't there when I checked. Can you help me look for it?",objectivesText="Help Sophietta look for her notebook.",starts={{npcID=216001,x=0.526,y=0.602,zoneID=14838}},ends={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},coords={x=0.526,y=0.602,source="quest_giver",zoneID=14838},questType="standard"},
[79301] = {id=79301,name="Height Club",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I'm so tired of Edwyn. From the day we all arrived, he's been telling everyone he'll be selected as captain. He's a great flyer--very talented, and he knows his stuff. But his ego gets in the way of treating people as he should. And he knows my grades and flight review scores are higher. But if I can't turn in my report, he'll be the next captain. Take it back from him!",objectivesText="Confront Edwyn about the notebook. Progress: Did you get it back? I'd love to see the look on Edwyn's face...",starts={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},ends={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},coords={x=0.534,y=0.594,source="quest_giver",zoneID=14838},questType="standard"},
[79302] = {id=79302,name="Gone with the Wind",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I can't believe Edwyn threw my report out into the wind. Can you please track down what papers you can find? I'll look for any around the school grounds, you check the valley. This report is already late... But I had some really good insights around airship capabilities. When Headmaster Fynch sees them, maybe he'll still allow me to turn it in. Bring me whatever pages you find!",objectivesText="Recover 10 pages from Sophietta's report. Progress: I hope you found all the pages, <name>!",starts={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},ends={{npcID=225926,x=0.534,y=0.606,zoneID=14838}},coords={x=0.534,y=0.594,source="quest_giver",zoneID=14838},questType="standard"},
[79303] = {id=79303,name="A Principled Principal",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Great work gathering these up. I found a few blowing around up here, so I think we've got all the pages. Let's get this to Headmaster Fynch ! He's probably in the classroom. I sure hope he accepts it. He says he doesn't accept late work, but there were a lot of extenuating circumstances at play here. And if he doesn't, I'll be reporting to Edwyn as my captain. I'm not sure I could do that, after what's happened.",objectivesText="Get Sophietta's report to Headmaster Fynch .",starts={{npcID=225926,x=0.534,y=0.606,zoneID=14838}},ends={{npcID=226074,x=0.528,y=0.592,zoneID=14838}},coords={x=0.534,y=0.606,source="quest_giver",zoneID=14838},questType="standard"},
[79304] = {id=79304,name="Care Package",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="My cousin Sophietta and I came to Hallowfall together as stalwarts. Since arriving, we both lived here in Dunelle's Kindness for years. But she left last year to follow her dream of being one of our airship captains, or at least joining an airship crew. She's a strong person, but I don't know how she's doing. Especially without Innkeeper Valrin's sweetrolls ! She can't get them at Lightspark, the Sky Academy. Will you take these to her, and make sure she's doing alright?",objectivesText="Take the care package to Sophietta Lynflayme at Lightspark Sky Academy. Progress: What's this? Are these for me?",starts={{npcID=217609,x=0.692,y=0.438,zoneID=14838}},ends={{npcID=216001,x=0.526,y=0.602,zoneID=14838}},coords={x=0.692,y=0.438,source="quest_giver",zoneID=14838},questType="standard"},
[79309] = {id=79309,name="Status Report",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Airships give the Arathi Army command of the skies. But roads are the lifeblood of empires. My scouts protect and light the passageways of Hallowfall for our citizens. One such patrol has been late to report their walk of the eastern road. Seek my missing scouts by the sight of smoke or flame. Arathi soldiers know better than to linger in the dark.",objectivesText="Locate the missing Arathi Army scouting party.",starts={{npcID=216061,x=0.704,y=0.45,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.704,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[79310] = {id=79310,name="Seek the Lost",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Guard our ways, repel the dark. Civilize this twisted land. All in the name of our empire. This is the mission of the Arathi Army. A mission I can heed no longer. I am afraid. I won't go back into the dark. Not after what I've seen. If Maevest or any of my other companions survived, they must crave the mercy of a swift death. And I left them to that terror. Tell Captain Trueflame her scouts died in darkness, one and all.",objectivesText="Look for a member of Wayshelm's party. Progress: < Scout Wayshelm gazes into the flames of his campfire.>",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79311] = {id=79311,name="Stem the Flow",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The roads were meant to be lit. But the path was overgrown, the lanterns dark. Swarming, frothing, and reeking with rot. It all happened so fast. By the time we realized the danger, the beasts were upon us. The largest of them was huge and black as night. It is our duty to slay monsters and push back the darkness. But the thought of going back fills with me fear. I've lost my nerve. But you, outsider, can still make this right.",objectivesText="Slay 12 Bloatrot Stingers or Fungal Infestors . Progress: <Scout Maevest's compass gleams in the firelight. Wayshelm has bound it with twine and now wears it around his neck.>",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79312] = {id=79312,name="Mow the Masses",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Maevest and I broke away from the others and fled, their screams left in our wake. Foul muck smothered our lanterns and we stumbled in the dark through knee-high waters. I heard a splash like she had tripped and fallen in, but I couldn't bring myself to look back. Only later did I find the tiny bite marks on my ankles. Be warned, there's something in the water. I took notice of fronds growing from the pools. Swarming insects feast on their sickly nectar. Destroy those plants and starve the beasts.",objectivesText="Cut down 8 Foulnectar Fronds .",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79313] = {id=79313,name="What Grows in the Dark",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="We are told never to walk in the darkness. To carry light wherever we go. The thought of returning this way filled me with dread. But your courage shines with splendor, . At your side, my way is lit. No more hiding. The beast clad in black chitin, the one that killed my friends, dies in that cave. I am with you.",objectivesText="Slay Fallowbarb .",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216061,x=0.704,y=0.45,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79322] = {id=79322,name="What the Duck?",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=12,mapID=37,description="What the--why are all these ducks here? Something has them agitated. They almost knocked over my beautiful golden egg heirloom! We need to clear out these chaotic quackers so we can continue our festivities. I'll keep them from entering the inn, but can you help clear out the rest?",objectivesText="Scare off 10 ducks using the Horn of Honking . Progress: Show those ducks who's boss!",starts={{mapID=37,npcID=211646,x=0.42,y=0.65}},ends={{mapID=37,npcID=211646,x=0.42,y=0.65}},coords={mapID=37,source="quest_giver",x=0.42,y=0.65},questType="standard"},
[79323] = {id=79323,name="A Fowl Concoction",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=12,mapID=37,description="We need to put an end to this duck invasion. While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My precious heirloom was among the items stolen! Please, <name>. I won't stand for these pilfering poultry. I know a mage in Stormwind who might have some ideas on how to handle this.",objectivesText="Speak with Emmery Fiske at the Wizard's Sanctum in Stormwind. Progress: Have you spoken with Emmery yet?",starts={{mapID=37,npcID=211646,x=0.42,y=0.65}},ends={{mapID=37,npcID=211646,x=0.42,y=0.65}},coords={mapID=37,source="quest_giver",x=0.42,y=0.65},questType="standard"},
[79324] = {id=79324,name="To the Waterworks",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Getting the Waterworks up and running is our first objective. Nothing else we do matters if we can't get power to the facility. Meet up with Dagran and ZZ-01-47 once you get there. And try to keep them on the sidelines. I don't want to explain to Moira that her son was injured, or worse, under my care.",objectivesText="Meet up with Dagran and ZZ-01-47 at the Waterworks.",starts={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},ends={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},coords={x=0.47,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[79325] = {id=79325,name="Shadowvein Extraction",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I sent Zee-Zee ahead to the Shadowvein extraction site. From what they transmitted back it looks like the area is swarming with rock worms and covered in this... discharge. I gave them an upgrade while we were waiting for you. I don't know how effective it'll be in battle but the results should be shocking for anyone that tries to threaten them.",objectivesText="Meet up with ZZ-01-47 at the Shadowvein Extraction Site.",starts={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},ends={{npcID=216140,x=0.556,y=0.41,zoneID=14795}},coords={x=0.472,y=0.422,source="quest_giver",zoneID=14795},questType="standard"},
[79327] = {id=79327,name="The Glittering Shard",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Orsenth may be interested in examining this piece of ore.>",objectivesText="Bring the glistening clay to Orsenth near Nibelgaz Mine. Provided item:",starts={{x=0.528,y=0.16,mapID=2214}},ends={{npcID=219042,x=0.51,y=0.148,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.49,y=0.148},questType="standard"},
[79330] = {id=79330,name="Duck Tales",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=12,mapID=37,description="Take this potion, <name>. You should be able to communicate with your feathery friends with it. But don't blame me for any unintended side effects you may experience.",objectivesText="Use the potion to get information from 5 ducks. Progress: Go on now, have a chat with those ducks!",starts={{mapID=37,npcID=216129,x=0.42,y=0.648}},ends={{mapID=37,npcID=211646,x=0.42,y=0.65}},coords={mapID=37,source="quest_giver",x=0.42,y=0.648},questType="standard"},
[79331] = {id=79331,name="Just a Waddle Away",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=12,mapID=37,description="We need to find out where those ducks are hiding our stolen goods! And who this mysterious Daetan is, while we're at it. I convinced Emmery to give me more of that potion. Take it and find my heirloom!",objectivesText="Discover the duck's hiding spot. Progress: Where would those ducks be hiding...",starts={{mapID=37,npcID=211646,x=0.42,y=0.65}},ends={{mapID=37,npcID=211646,x=0.42,y=0.65}},coords={mapID=37,source="quest_giver",x=0.42,y=0.65},questType="standard"},
[79335] = {id=79335,name="One More Tradition",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Before I shut down, I must craft an item that is meaningful to me. As a Stonebound, I worked the mines. I had a lantern I made and used until I lost it in a collapse. I became Unbound shortly after. I wish to forge a new lantern to guide my way through these final moments. The lantern was made of an ore found in small amounts around this area. I used a charged core in the lantern. You can find them in the stormfangs that roam these hills. Gather the materials, and I will forge the lantern.",objectivesText="Gather 5 ore and 5 Charged Cores near Fallside Outpost. Progress: Have you gotten the materials I asked for?",starts={{npcID=213184,x=0.574,y=0.43,zoneID=14717}},ends={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},coords={x=0.574,y=0.43,source="quest_giver",zoneID=14717},questType="standard"},
[79336] = {id=79336,name="The Forging of Memories",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Before its shutdown, we earthen would descend to the Awakening Machine below and renew our cycle. But now, even if it was still working, I would see my cycle broken and be remembered as I am. Korgran lets out a deep sigh.> These hands look strong, but they become heavier with each passing moment. The stiffness in my wrists and elbows will not let me carry the items to the forge. Please, add the right material to the forge as I call them out.",objectivesText="Help Korgran forge his lantern. Progress: Oh, I almost forget. I did ask you to help with forging the lantern, didn't I?",starts={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},ends={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},coords={x=0.57,y=0.424,source="quest_giver",zoneID=14717},questType="standard"},
[79337] = {id=79337,name="The Last Journey",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="This lantern is perfect. Enough of this. It is time! I can feel my memory clouding. We have to get going. Urtago is waiting for us. They will join us on my final journey to Mourning Rise, where we will conduct a ceremony. Korgran forces a smile.> It is nothing fancy, I promise. As I said, it is more symbolic than anything else. My head feels heavy. What was I doing again? Hmm, oh, right! Meeting Urtago !",objectivesText="Wait for Korgran and then regroup with Urtago outside at Fallside Outpost.",starts={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},ends={{npcID=213187,x=0.574,y=0.43,zoneID=14717}},coords={x=0.57,y=0.424,source="quest_giver",zoneID=14717},questType="standard"},
[79338] = {id=79338,name="The Lost Earthen",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="This is horrible! I knew I should have been keeping a closer eye on him. Confusion is the last symptom before a shutdown. Our memory is finite and starts overwriting. The more an earthen exert themselves, the faster their energy depletes and they lose memories. Korgran must be scared not knowing where he is--maybe not even who he is. I am such a boulder head! , please, I think I saw him go east into the trees. Meet me there up the road!",objectivesText="Help Urtago find Korgran. Progress: Were you able to find any sign of Korgran?",starts={{npcID=213187,x=0.574,y=0.43,zoneID=14717}},ends={{npcID=216878,x=0.61,y=0.438,zoneID=14717}},coords={x=0.574,y=0.43,source="quest_giver",zoneID=14717},questType="standard"},
[79339] = {id=79339,name="A Change of Tradition",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="An Unbound earthen can't return to the Coreway, so we have Mourning Rise. But looking at Korgran, remembering our last conversation before... I may not be the Mourning Rise caretaker just yet, but with Korgran's condition, it falls to me to be in charge. As Unbound, we made our own rules and traditions. So what if he doesn't want to stand at Mourning Rise? If a seaside memorial is what Caretaker Korgran wants, that's what he gets. , meet me at the shore to the southeast of here.",objectivesText="Meet Urtago and Korgran by the shore.",starts={{npcID=216878,x=0.61,y=0.438,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.61,y=0.438,source="quest_giver",zoneID=14717},questType="standard"},
[79340] = {id=79340,name="Tools of Declaration",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="As Unbound caretakers, we have a tradition for when a master bequeaths their mantle to their apprentice. Figuratively, of course. To do that, Korgran will need a horn. He would then face me, blow the horn, and the sound signifies his passing the mantle of the Mourning Rise caretaker to me. I saw shalehorns to the west of here. I would be thankful if you could bring me several of their horns. I will choose one that is suitable.",objectivesText="Collect 4 Pristine Horns near Restless Estuary. Progress: Remember, the horns must be in pristine condition.",starts={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.698,y=0.568,source="quest_giver",zoneID=14717},questType="standard"},
[79341] = {id=79341,name="Cleansing Ashes",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The Unbound have a symbolic ceremony of cleansing. We perform it before a shutdown. It is a symbolic process of purification. For it, we need to gather ashenfold , a flower that grows around the isle. We waft the smoke of the burned flowers through the fissures and cracks in our bodies to symbolically remove impurities. We are then ready to embrace our final moments. Urtago looks at Korgran with a hand on her chest. Her face falls.>",objectivesText="Collect 6 ashenfold flowers near Restless Estuary. Progress: Do you have the flowers, <name>?",starts={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.698,y=0.568,source="quest_giver",zoneID=14717},questType="standard"},
[79342] = {id=79342,name="As He Departs",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="It is time for the ceremony, . Please place the bowl of ashenfolds by Korgran and then hand him the horn. Once the ceremony concludes, I will be the new caretaker. Then I will have to say a final farewell to my friend. Korgran will shutdown peacefully, knowing we were here by his side in the place he loved most--something I wish and hope to have when it is my time. My core is mud, but it is a great honor to stand here with him... and with you.",objectivesText="Help Urtago and Korgran perform the ceremony. Progress: It is a bittersweet moment.",starts={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.698,y=0.568,source="quest_giver",zoneID=14717},questType="standard"},
[79346] = {id=79346,name="Chew On That",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Fishing out here is not easy, especially when the spooky sounds of the darkness start to wear on the nerves. I've taken to chewing on the Duskstem from the tall plants nearby. It's sweet and chewy, keeps the jaw busy, and helps me pass the time! If you could lend a hand by gathering some Duskstem with your flying mount, I would be most appreciative.",objectivesText="Collect 20 Duskstem from the tallest plants that grow in the darkness. Progress: Have you collected enough?",starts={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},ends={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},coords={x=0.658,y=0.244,source="quest_giver",zoneID=14838},questType="standard"},
[79349] = {id=79349,name="Entrepreneur, Inc.",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Okay, color me impressed. You are officially my Coinchamp! It's like a champion, only I pay you to do things. A mercenary, only with better branding. You should meet my business partner, Ripsnoodle . He's working out some deals with his own coinchamps with the niffin over at Mmarl. He might have more work for you--though I recommend not buying anything he tries to sell you. You can find Mmarl east of here. Just follow your nose, you can smell it from a mile away.",objectivesText="Find Ripsnoodle in Mmarl.",starts={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},ends={{npcID=216308,x=0.782,y=0.616,zoneID=14752}},coords={x=0.408,y=0.398,source="quest_giver",zoneID=14752},questType="standard"},
[79350] = {id=79350,name="Intro Dummy Quest Week 1 (Text Only)",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79354] = {id=79354,name="The Machine Speakers",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Ah, $p! The of the hour... We were just discussing you. There is some unfinished business for us to attend to, now that the High Speaker's transgressions have been corrected and the Awakening Machine restored once more. Care to stick around?",objectivesText="Watch the conversation between Moira and Speaker Brinthe in Gundargaz.",starts={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},ends={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},coords={x=0.47,y=0.34,source="quest_giver",zoneID=14795},questType="standard"},
[79355] = {id=79355,name="Prisoner Preservation",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="The beasts took our people! Dragged them away when we were gettin' our first rest since our escape! We only just escaped those nerubians. We can't afford ta lose more people. Search Pillar-nest Vosh. It's where all those beasts came from. If we're lucky our people are still alive.",objectivesText="Find 4 Expedition Members. Progress: Survivin' ain't easy, but we gotta keep pushin' on.",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79356] = {id=79356,name="Antifungal Firestarter",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Consider it a professional hunch, but those spores comin' out of those fungal pods and the ones afflictin' all da beasts are connected. Maybe if we destroy da fungal spore pods it'll slow whatever control those fungarians have on da beasts. Take these antifungal firebombs and torch as many fungal spore pods as you can!",objectivesText="Burn 8 Fungal Spore Pods. Progress: Too many strange tings occur this far underground. Watch yourself.",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79357] = {id=79357,name="Removing the Cap",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Aemara's mention of a large fungarian planting fungal pods worries me. Gotta be someting down in dat cave. We can't just be waitin' for the fungarians to attack with a nest of mind-controlled beasts. We gotta prune dat plan before it has a chance to bloom. Get to Pillar-nest Vosh and kill that fungarian leader!",objectivesText="Kill Agaricus Festerbloom .",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79367] = {id=79367,name="A Nebb in Need",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="You! You no spider. Please, must help before spiders come again. Nebb know Chittering Den. Never seen spiders here before. Eat grubs, eat kobolds. But spiders dark things from dark places. Hate light. Can't leave post. You take candles, yes? Light up barricade. Keep spiders away.",objectivesText="Collect the Bundle of Candles and place candles along the barricade. Progress: Keep away dark. Keep away spiders.",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79368] = {id=79368,name="Hair of the Spider",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Light good, but more to do. Spiders came from everywhere. Nebb quick, Nebb heard them. But friend Snubjaw... he bit. Sick now. Nebb might know a way, yes, turn venom into cure. Use bite to cure bite. Bring venom. Hurry now!",objectivesText="Collect 12 Undercrawler Venom . Progress: You have venom?",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79369] = {id=79369,name="Protecting the Harvest",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Nebb young, no see past own snout. If harvest lost, many kobolds lost. Not just Snubjaw . Can no waste time. Kobolds starve if spiders gobble grubs and eggs. Save them, gather eggs. As many as can carry before spiders snatch all.",objectivesText="Collect 20 Grub Eggs . Progress: Bring eggs, we save harvest.",starts={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79370] = {id=79370,name="A Poultice for Poison",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Little venom, little wax... Nebb reaches into his pouch and gives you a handful of thick, pungent wax.> Yes, yes, should work. Finest poultice, family recipe. Hurry now, give to Snubjaw . He feel right better.",objectivesText="Use Nebb's Poultice on Snubjaw . Progress: Poultice fix him right up.",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79371] = {id=79371,name="A Royal Cure",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Poultice no work! Wax right, venom wrong? Yes... yes! Strongest cure need strongest venom. Nebb saw crawler. She queen in red and black, too big to bother with kobolds. Queen smelled juicy grubs and skittered for cave. Now you must follow. Collect royal venom. Please, Snubjaw have little time.",objectivesText="Collect Queen Rickiticka's Venom to make a new poultice for Snubjaw . Progress: Queen venom must work.",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79372] = {id=79372,name="A Clutch of Hope",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Nebb . He and the other Grubtenders would know what to do with it.>",objectivesText="Bring the egg to Nebb . Progress: What this, another egg?",starts={{npcID=423581,x=0.681,y=0.391,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.681,y=0.391,source="quest_giver",zoneID=14795},questType="standard"},
[79440] = {id=79440,name="Recalling the War",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=6757,mapID=554,description="Our operations here are secure. For now, anyway! It is time for you to begin your journey to the past so that we may observe how history unfolded. Speak with Eternus if you have any final questions about our mission. She can show you how these events began.",objectivesText="Ask Eternus to show you the events of the past.",starts={{mapID=554,npcID=218129,x=0.257667,y=0.525}},ends={{mapID=371,npcID=216591,x=0.364,y=0.518}},coords={mapID=554,source="quest_giver",x=0.257667,y=0.525},questType="standard"},
[79448] = {id=79448,name="Leave No Flightstone Unturned",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="It's so exciting to be in Valdrakken! Cuzolth and I have never been here before. And it's everything we hoped it would be. Some of the others have even introduced themselves. They actually thanked us for our work studying Flightstones and Crests. That's every researcher's dream! So I need your help again. Could you find some Flightstones and a new piece of adventuring gear? Then come back to Cuzolth for an upgrade? It would really help us solidify our new position here.",objectivesText="Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 4 equipment using Flightstones . Progress: There's no need to hurry. But if you wouldn't mind hurrying anyway...",starts={{mapID=2112,npcID=216449,x=0.455,y=0.5565}},ends={{mapID=2112,npcID=216449,x=0.455,y=0.5565}},coords={mapID=2112,source="quest_giver",x=0.455,y=0.5565},questType="standard"},
[79453] = {id=79453,name="Awakened Crests, Unlimited Possibilities",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here. Of course, I'm sure you know that Flightstones can only go so far. You need Awakened Crests to upgrade powerful adventuring gear. Much like Flightstones, these Crests are rewarded through many different activities. Awakened Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Bring me fifteen Whelpling's Awakened Crests, and we can help you upgrade some gear further.",objectivesText="Acquire 15 Whelpling's Awakened Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then return to Vaskarn in Valdrakken. Progress: If you're having a hard time finding Whelpling's Awakened Crests, you can search for hidden treasures around the Dragon Isles. There's no shortage of those!",starts={{mapID=2112,npcID=216449,x=0.455,y=0.5565}},ends={{mapID=2112,npcID=216449,x=0.455,y=0.5565}},coords={mapID=2112,source="quest_giver",x=0.455,y=0.5565},questType="standard"},
[79475] = {id=79475,name="Charging Up That Hill",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="Before we use the conduit to summon the stormrooks, we need to recharge it. There are other, gentler ways to do this but... we have to work with what's on hand. The way to the peak is overrun with hostile elementals cast off from the storm. If we send them back to their plane, we can capture their residual energy and re-energize the conduit. While you work on recharging the conduit, we will go ahead and prepare for the ritual at the peak.",objectivesText="Charge the conduit with elemental energy. Progress: Have you finished charging the conduit?",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79476] = {id=79476,name="Heeding the Call",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="Earthen from across the island have been drawn to this place. Kind of a strange coincidence you'd show up now too. Maybe it's because Baelgrim's gone or... a new Stormward's coming. Or it could just be barometric pressure... Bah! There's time enough to spin wild theories later. Right now, we need to assist the pilgrims that have foolishly attempted the summit unprepared. We can't be worrying about them while we try to summon the stormrooks.",objectivesText="Help 8 Stranded Pilgrims on the mountain. Progress: These earthen pilgrims seem intent on reaching the peak. I hope we can keep them safe.",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79477] = {id=79477,name="Strays",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2248,description="Kurdran Wildhammer has come to train the new Stormriders in aerial maneuvers. Thrall says his clan rides gryphons--much like the Stormriders ride stormrooks--so he should be of great help to us. Unfortunately, a few of our new recruits seem to have, uh, wandered off with their stormrooks. I wanted them to have a chance to bond, but it's time to come home. Would you mind rounding them up? Thrall and I are putting together something special for these \"rookies\" lessons.",objectivesText="Round up the stray recruits. Progress: You found those stray rookies yet?",starts={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},ends={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},coords={x=0.256,y=0.572,source="quest_giver",zoneID=14717},questType="standard"},
[79480] = {id=79480,name="Paying Respects",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Please excuse my absence. It was never my intention to turn my back on the Stormriders, then or now. But I needed to come here and pay my respects to Baelgrim. Unfortunately, these blasted nerubians are still lingering. I think they're searching for something, but I don't know what. Whatever their reasons, I cannot abide them lurking where Baelgrim fell.",objectivesText="Clear out nerubian stragglers. Progress: I don't know who or what these nerubians are searching for, but they defile this place with their presence. Clear them out.",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79481] = {id=79481,name="Tending to the Terrified",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="All happen so fast. One moment, we gathering eggs and grubs. Next, spiders swarming. Nebb drag me here, many others trapped. Caught in webs, soon to be feasts. Must save the Grubtenders. We tenders, not fighters. Do not let friends become meals.",objectivesText="Rescue 6 Terrified Grubtenders .",starts={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79504] = {id=79504,name="Dripsy Forgot Her Candle",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Gather round, tenderfoots, and Granny Scribbles tell you story. Story of what happen when Dripsy forgot her candle. Dripsy little tenderfoot, like you, who wander away from tribe...",objectivesText="Relive Granny Scribbles ' story. Progress: You listen too. Maybe learn something.",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79505] = {id=79505,name="Chomps and the Cave-In",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Sit down, stop talk, and Granny Scribbles tell you story. Story that maybe save life one day. About what happen when not listen to old, wise kobold. Like me! Story of Chomps and the cave-in...",objectivesText="Relive Granny Scribbles ' story. Progress: Important pay attention. Following along?",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79507] = {id=79507,name="The Day the Stoneheads Came",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="What? Want scary story? You ask. Granny Scribbles give what want. Maybe then sit still like good tenderfoots. Scariest story Granny know, yes. Story about the day the stoneheads came...",objectivesText="Relive Granny Scribbles ' story. Progress: Hope story not too scary for you.",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79508] = {id=79508,name="Mipsy Mole-Rider",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Time for happy story. Not all days bad. Granny Scribbles gently scratches Ol' Snorler behind his ears.> Tell story of how be friends with moles. Story of Mipsy mole-rider...",objectivesText="Relive Granny Scribbles ' story. Progress: You listening?",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79510] = {id=79510,name="The Wickless Candle",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Now tell story of very far place called \"surface\". New friend from there, yes, so they know what Granny Scribbles talk about. Granny Scribbles nods sagely as she points you out.> Story of how kobold discover it long go, and what find when do. Story of the wickless candle...",objectivesText="Relive Granny Scribbles ' story. Progress: Sound like place you know?",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79511] = {id=79511,name="Identity Crisis",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Hey $p, over here! I just finished speaking with Emberthal. I'm not sure what, but something is bothering her! She had lots of odd questions about visage forms. Could she be ready to choose one? How exciting! I think I saw her head over to the Victorious Visage. You should check on her, I bet you could get her to spill the secret!",objectivesText="Speak with Emberthal in the Victorious Visage.",starts={{mapID=2112,npcID=216946,x=0.403714,y=0.557429}},ends={{mapID=2112,npcID=216945,x=0.295,y=0.4965}},coords={mapID=2112,source="quest_giver",x=0.403714,y=0.557429},questType="standard"},
[79512] = {id=79512,name="Who Are You?",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Perhaps Cindrethresh is right. Still, if I'm to pick a visage, I should at least give it some thought. I just do not fully understand the concept of visage forms. I have heard that visage is supposed to be ones own expression of self. How does one discover what that is? Maybe some of the individuals here in Valdrakken hold the answers. $p, I need you to gather intel. I will remain here. Report back your findings when you are finished.",objectivesText="Speak with 9 Valdrakken Visitors in Valdrakken. Progress: Have you completed your reconnaissance yet?",starts={{mapID=2112,npcID=216945,x=0.295,y=0.4965}},ends={{mapID=2112,npcID=216945,x=0.295,y=0.4965}},coords={mapID=2112,source="quest_giver",x=0.295,y=0.4965},questType="standard"},
[79513] = {id=79513,name="Dragon Isles Adventuring: Being Yourself",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="I worry about Emberthal. Her mood has grown increasingly dark. By sticking to citizens of the city, she is looking for ways she is similar to them, instead of what makes her unique. Perhaps a broader sample size is in order? She needs stories to guide her. There are many such individuals with stories to tell in the Dragon Isles . Go, and speak with them. Would that I could go myself, but the duties of a Scalecommander never rest.",objectivesText="Speak with 8 residents of the Dragon Isles and listen to their stories. Progress: Have you spoken with everyone?",starts={{mapID=2112,npcID=216950,x=0.295,y=0.495}},ends={{mapID=2112,npcID=216950,x=0.295,y=0.495}},coords={mapID=2112,source="quest_giver",x=0.295,y=0.495},questType="standard"},
[79514] = {id=79514,name="Don't Threaten Me With a Good Time",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Emberthal seems worried, but I'm sure she'll come back. And when she does, she'll pick a visage form! Chromie told us all about the celebrations dragons used to have for Visage Day. So, Kalecgos and I are going to blow stuff up! Fireworks, mostly. We'll need some arcane residue to make them, though. Conveniently, there are some arcane elementals just outside the Gardens of Unity that are ripe for the harvest. The three of us have some other preparations to make here in Valdrakken.",objectivesText="Collect 100 Arcane Residue from Volatile Arcana in The Cascades. Progress: These volatile elementals make the perfect base for fireworks!",starts={{mapID=2112,npcID=216967,x=0.295,y=0.495}},ends={{mapID=2112,npcID=216967,x=0.295,y=0.495}},coords={mapID=2112,source="quest_giver",x=0.295,y=0.495},questType="standard"},
[79515] = {id=79515,name="Gather Your Rosebuds",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="Emberthal is quite troubled. It reminds me of a certain bronze dragon when she chose her visage form. Not to worry! Once Emberthal has returned, we shall throw a proper Visage Day celebration. The fireworks are to match the colors of the dragonflights. Each enclave of the city grows special flowers in accordance with that enclave's flight. Three of each color should be enough for the first batch of fireworks.",objectivesText="Collect 3 of each color of Flight Flower in Valdrakken. Progress: We still require more flowers if we are to provide a celebration worthy of dragons.",starts={{mapID=2112,npcID=216951,x=0.3032,y=0.4644}},ends={{mapID=2112,npcID=216951,x=0.3032,y=0.4644}},coords={mapID=2112,source="quest_giver",x=0.3032,y=0.4644},questType="standard"},
[79521] = {id=79521,name="Seizing Evidence",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Councilward Merrix has authorized trade goods from the Deeps to be transported through this depot. However, we have received a tip that more than crafting materials are being sent and received here. Dornogal observes strict rules about what we trade and with whom. All commerce must serve the Edicts, not the interests of individuals. We do not abide unsanctioned trading. We have started going through the crates here to find smuggled goods, but we haven't found anything--yet. Help us take a look.",objectivesText="Collect 3 Seized Shipments . Progress: The tip we received was from a highly reliable source. There must be something here.",starts={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},ends={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},coords={x=0.498,y=0.494,source="quest_giver",zoneID=14771},questType="standard"},
[79522] = {id=79522,name="Withheld Information",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="There has to be something we're missing. The tip we received was from a very reliable source. We have no reason to believe we were being misled. The Councilward will want us to get to the bottom of this, and I refuse to disappoint him. We haven't been able to get any additional information out of the workers, but maybe you'll have more luck. Speak to the ones we have detained here, and see if you can learn anything.",objectivesText="Interrogate 5 Line Workers to gather information on the shipments. Progress: Someone here has to know something.",starts={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},ends={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},coords={x=0.498,y=0.494,source="quest_giver",zoneID=14771},questType="standard"},
[79523] = {id=79523,name="Something Hidden",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="So, they have built extra compartments in the crates to hide extra items, eh? That explains how they have been smuggling goods into and out of Dornogal without our auditors knowing. Excellent work, ! But now the fun part of our job: those crates will have to be broken open and the smuggled goods taken into evidence. Smash the bottoms out of the crates and bring anything you find back to me.",starts={{npcID=219394,x=0.498,y=0.494,mapID=2339}},ends={{npcID=219394,x=0.498,y=0.494,mapID=2339}},coords={x=0.498,y=0.494,source="quest_giver",mapID=2339},questType="standard"},
[79525] = {id=79525,name="Report to the Councilward",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Those receipts you found... Steelvein is a known smuggler that we've been chasing for a long time. The Councilward will be pleased to finally have solid evidence on his activities, and maybe even on his whereabouts. Bring these receipts to Merrix immediately. He will want to study them in detail. He said he was heading back to his office, so you should be able to find him at the Councilward's Rise. I'll package up the rest of the evidence to be brought to him later. Good work today.",objectivesText="Take Steelvein's receipts to Merrix at the Councilward's Rise in Dornogal.",starts={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},ends={{mapID=2339,npcID=219394,x=0.498,y=0.495}},coords={x=0.498,y=0.494,source="quest_giver",zoneID=14771},questType="standard"},
[79526] = {id=79526,name="Sedition",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="MERRIX is CORRUPT! STEELVEIN is WEAK! They cannot protect the earthen! They do not care about them! They spit upon the Edicts! MERRIX was BRIBED to reopen Steelvein's smuggling operation! Steelvein HIDES behind MERRIX 's authority! They are taking from YOUR pockets to line THEIRS! DO NOT TRUST THEIR LIES!",objectivesText="Speak to Merrix at the Councilward's Rise in Dornogal. Provided item:",starts={{npcID=429303,x=0.459,y=0.473,zoneID=14771}},ends={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},coords={x=0.459,y=0.473,source="quest_giver",zoneID=14771},questType="standard"},
[79527] = {id=79527,name="Damage Mitigation",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Obstorn has confirmed that Ardgrin, the overseer in charge of my supply line that runs from the Deeps into Dornogal, is the one who tipped off my peacekeepers. It is therefore also my opinion that Ardgrin is the one who penned this sedition. He must have sent his workers upstairs to post them around the city. It is imperative that we remove them before these rumors spread further. Tear them down for me.",objectivesText="Tear down 8 Seditious Posters in Dornogal. Progress: I would not have these rumors spreading any farther than they already have.",starts={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},ends={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},coords={x=0.556,y=0.058,source="quest_giver",zoneID=14771},questType="standard"},
[79528] = {id=79528,name="Dispelling Rumors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Many of my peacekeepers have already caught wind of Ardgrin's sedition. I am told some are losing faith in my integrity as Councilward, believing that I have been taking bribes from smugglers to bolster my own coffers. I can provide proof that no such transactions have taken place--clearly--but we need to stop them from murmuring amongst themselves and giving the rumors power. Lies become truths through repetition. If you find any discussing the matter, kindly disperse them.",objectivesText="Disperse 6 Murmuring Peacekeepers in Dornogal. Progress: I can assuage their fears later. For now, we just need to prevent the situation from worsening.",starts={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},ends={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},coords={x=0.556,y=0.058,source="quest_giver",zoneID=14771},questType="standard"},
[79529] = {id=79529,name="Forcing My Hand",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="I do not know if Ardgrin merely intended to sabotage me or if he wanted to force a confrontation. Either way, a confrontation he will have. I believe this situation can be rectified peacefully, but I cannot do it as the Councilward. Steelvein has never appeared in the stone, but he must now. I will parlay with Ardgrin in the Deeps and this situation will be concluded. I would have you accompany me, but there are some things I want you to know before that. Help me prepare and I will speak with you.",objectivesText="Help Merrix disguise himself as Steelvein .",starts={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},ends={{npcID=219475,x=0.556,y=0.056,zoneID=14771}},coords={x=0.556,y=0.058,source="quest_giver",zoneID=14771},questType="standard"},
[79530] = {id=79530,name="Bad Business",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,mapID=2339,description="I have not been to the Deeps since their machines shut down. Obstorn will have to guide us to Ardgrin's depot. Once there, I will attempt a conversation. If Ardgrin is not amenable, which I suspect will be the case, we will respond with equal force. Our goal is to bring him back into the fold, not to beat him into submission. Ruling by fear only breeds resentment. We will meet you in the Deeps. Come swiftly--and, of course, speak of this to no one.",objectivesText="Meet Steelvein in the Ringing Deeps near Hallowfall Gate, then confront Overseer Ardgrin.",starts={{npcID=219475,x=0.556,y=0.056,zoneID=14771}},ends={{npcID=220192,x=0.424,y=0.24,zoneID=14795}},coords={x=0.556,y=0.056,source="quest_giver",zoneID=14771},questType="standard"},
[79532] = {id=79532,name="Tinker, Tailor, Soldier, Spider",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2255,description="I must thank you again for rescuing little Spindle from her predicament, my morsel. As a reward for your work, I would like to let you take loom and direct the weave of my newest tapestry. Meesk the Venomtongue threatens my weave-rats. He slanders my Queen. And he lends creedence to Ansurek's campaign of misinformation without a single thought to the consequences. I believe it is time that I sent Meesk and his ilk a message. Go into the city and find out as much as you can about our 'Venomtongue.'",objectivesText="Gather rumors about Meesk the Venomtongue from the denizens of the Umbral Bazaar. Progress: Mm... Do hurry, my little morsel. I do not want little Meesk to run off before he has the chance to sample the fruits of his labor.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=227428,x=0.534,y=0.692,zoneID=14752},{npcID=227428,x=0.62,y=0.126,zoneID=14753},{npcID=227428,x=0.63,y=0.118,zoneID=14753}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[79538] = {id=79538,name="Smelly Shrubberies",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Jenni here says she's got some creepers attackin' the goblins. I haven't seen any myself, but I do smell opportunity! We've got our own anti-creeper perfume. It's the same recipe we use for the incense around town. Rub it on, and everything stays away! I'm sure we can sell some to the goblins. But I'm out of materials--smellsage branches, specifically. If you gather some for me, I'll cut you in on the profits!",objectivesText="Collect Smellsage bush branches for Rhubarn . Progress: If you smell feet, you're in the right spot.",starts={{npcID=216996,x=0.778,y=0.628,zoneID=14752}},ends={{npcID=216996,x=0.778,y=0.628,zoneID=14752}},coords={x=0.778,y=0.628,source="quest_giver",zoneID=14752},questType="standard"},
[79539] = {id=79539,name="Electrifying!",level=78,requiredLevel=78,faction="none",expansion=10,zoneID=14752,mapID=2255,description="You wanna help the Venture Company? And you don't mind being disposable? Okay, listen up. When we moved in here, there were no monsters in town. But now we're finding dead workers, chewed up. It's bad for business. Fortunately, I've got a way to make money off this: an electrocution helmet. I call it my Debugger Hat . Take the latest model for a test run outside town. Kill the bugs. The niffen will see you, see that Debugger Hat at work, and know it's got good reviews.",objectivesText="\"Advertise\" the Debugger Hat by hitting Noth swarmites with it outside of Mmarl. Progress: It oughta just kill 'em, but who knows? You might see other results, too.",starts={{npcID=216994,x=0.778,y=0.628,zoneID=14752}},ends={{npcID=216994,x=0.778,y=0.628,zoneID=14752}},coords={x=0.778,y=0.628,source="quest_giver",zoneID=14752},questType="standard"},
[79540] = {id=79540,name="The Party's Over",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Nope, nope, nope! Look, I'm used to dealing with the additives in our swimming hole and keeping things at \"marginally safe\" levels, but spiders emerging to chew us to death? That's a hard pass from me. This is OUR place, why are they buggin' us?",objectivesText="Investigate the pool area in Mmarl.",starts={{npcID=217402,x=0.776,y=0.596,zoneID=14752}},ends={{npcID=216996,x=0.778,y=0.628,zoneID=14752}},coords={x=0.776,y=0.596,source="quest_giver",zoneID=14752},questType="standard"},
[79541] = {id=79541,name="Burn It With Fire",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="So the goblins removed the incense the niffen used to keep those creepy pests out... because it smelled bad? Honestly, I'm not surprised. Maybe we can show them that they need to work together. Leading by example! Here, I'll lend you a flamethrower. I know mine works, without weird... chicken-like effects. Head in, clear out the nests, and put the right incense back in there!",objectivesText="Burn the Pillar-nest Hearts and replace the incense in the Mmarl cave. Progress: The cave is just up ahead.",starts={{npcID=217029,x=0.778,y=0.628,zoneID=14752}},ends={{npcID=216994,x=0.778,y=0.628,zoneID=14752}},coords={x=0.778,y=0.628,source="quest_giver",zoneID=14752},questType="standard"},
[79542] = {id=79542,name="The Councilward's Summons",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,mapID=2339,description="Councilward Merrix requests your presence in his office. He received the documents you left and would like to discuss the Steelvein situation with you further. Saradi regards you as if she is unimpressed. She also seems to be an earthen of few words.>",objectivesText="Meet Merrix at the Councilward's Rise in Dornogal. Progress: I am pleased you made it. The suspense was eroding me away.",starts={{npcID=225426,x=0.46,y=0.474,zoneID=14771},{npcID=225426,x=0.474,y=0.326,zoneID=14795}},ends={{npcID=217069,x=0.552,y=0.062,zoneID=14771}},coords={x=0.46,y=0.474,source="quest_giver",zoneID=14771},questType="standard"},
[79543] = {id=79543,name="Dornogal's Benefactor",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="You are in a unique position, . A position to learn. You met those who would bring this \"Bender of Edicts\" to justice, but what of the people of Dornogal? What do the earthen think of this Steelvein fellow? Humor me. Take the smuggled goods you intercepted and bring them to their intended recipients. Tell them the items are a gift from a \"mutual friend.\" You might be surprised to learn who benefits from these... illicit deeds.",objectivesText="Distribute smuggled goods around Dornogal.",starts={{npcID=217069,x=0.552,y=0.062,zoneID=14771}},ends={{npcID=217095,x=0.492,y=0.262,zoneID=14771}},coords={x=0.552,y=0.062,source="quest_giver",zoneID=14771},questType="standard"},
[79544] = {id=79544,name="Security Through Trade",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="If we're to solve this quarrel between Steelvein and Ardgrin amicably, then we'll need to make some new friends. One of Ardgrin's employees, Obstorn, frequents a cinderbrew speakeasy here in Dornogal. Only Machine Speakers may enter it. Even as Councilward, I am not able to access it. However, there are others in the city who can. Bevrusi , a Gundargaz trader, should be able to give you access. If you can grease her palm, she may be able to supply you access.",objectivesText="Convince Bevrusi to give you access to the cinderbrew speakeasy. Progress: Do I know you?",starts={{npcID=217095,x=0.492,y=0.262,zoneID=14771}},ends={{npcID=217072,x=0.554,y=0.502,zoneID=14771}},coords={x=0.492,y=0.262,source="quest_giver",zoneID=14771},questType="standard"},
[79545] = {id=79545,name="The Market Reeve of the Forgegrounds",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="I've heard liquid opal tastes remarkable but no matter how often I peruse the auctions here, it's never for sale. It's quite rare. Luckily for you, there is one person who can find the stuff. Vokgret , the market reeve of the Forgegrounds. Nothing circulates in the city's flow of trade without her knowledge. I don't often try to do business with one as... connected as her. But you'll have no qualms about it, I'm sure! At this hour, you'll find her over by the inn.",objectivesText="Acquire a Vial of Liquid Opal from Vokgret . Progress: < Vokgret speaks without looking up from her paperwork.> The city certainly is a busy place.",starts={{npcID=217072,x=0.554,y=0.502,zoneID=14771}},ends={{npcID=217091,x=0.452,y=0.488,zoneID=14771}},coords={x=0.554,y=0.502,source="quest_giver",zoneID=14771},questType="standard"},
[79546] = {id=79546,name="The Machine Speakeasy",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Machine Speakers are odd and secretive units, some prone to paranoia. Even so, the grievance they have against Steelvein must be smoothed over. As you have seen in the Forgegrounds, their quarrel with a single smuggler has put the entire city at risk. As Councilward, I will not stand for it. Let us go talk to Ardgrin's employee, Obstorn, and see if he can deliver a diplomatic message to his overseer in the Deeps. I will meet you in the tunnels.",objectivesText="Enter the speakeasy in the tunnels below Dornogal then confront Obstorn. Progress: I would have us exchange words, not blows.",starts={{npcID=217097,x=0.604,y=0.332,zoneID=14771}},ends={{npcID=219566,x=0.62,y=0.384,zoneID=14771}},coords={x=0.604,y=0.332,source="quest_giver",zoneID=14771},questType="standard"},
[79552] = {id=79552,name="Hot Wax",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Oh. Fire bees bit bigger than Janky expect. Look mean. Other hives meaner, though. This best spot. You go grab wax. Janky stay here to...supervise. Yes!",objectivesText="Collect 12 Fire Bee Wax from the Cinderwold. Progress: Is fire bee wax hot enough to melt self?",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[79553] = {id=79553,name="A Natural Remedy",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="We stabilized most of the injured. But many of the earthen you saved need more help. Nerubians often fight with corrosive poisons that eats away even our stone bodies. Fungarian flesh has long been used by our healers for its medicinal powers. The fungarian takeover of the quarry is one unexpected boon to our situation, one we will adapt to. Adelgonn looks grimly proud.> One we will adapt to. As the Unbound always do. But I can't leave Ebona's side. Will you help me?",objectivesText="Collect 10 Fungarian Chunks in the Orecreg. Progress: Please, hurry. The nerubian poison will deal irreversible damage given enough time. If it erodes enough of their frame or seeps into their memory gem... Then we may not be able to save them.",starts={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},ends={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},coords={x=0.418,y=0.726,source="quest_giver",zoneID=14717},questType="standard"},
[79554] = {id=79554,name="Holy Hydrocarbons",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="These devotional candles might be of interest to Janky the kobold candlesmith in Gundargaz.",objectivesText="Collect Devotional Candles for Janky in Gundargaz. Progress: What smell like new candle?",ends={{npcID=216598,x=0.476,y=0.332,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.455,y=0.332},questType="standard"},
[79555] = {id=79555,name="Deep Wax Galactic",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14752,mapID=2214,description="While sourcing it may not be pleasant, this waxy substance seems like it might make a fine candle. Janky the candlesmith in Gundargaz might be interested in this.",objectivesText="Collect Waxy Excretions and bring them to Janky in Gundargaz. Progress: What bring Janky ?",starts={{x=0.794,y=0.765,mapID=2255}},ends={{npcID=216598,x=0.476,y=0.332,zoneID=14795}},coords={mapID=2214,source="quest_giver",x=0.455,y=0.332},questType="standard"},
[79556] = {id=79556,name="On the Job Training",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Stoneheads use steam to run whole place. Have lava, have water, make sense. Repairs not going well, we hear. No new parts from factory. \"Against rules\" to use scrap, been told. A lot. Help get old machines work. We watch, learn. Maybe not get yelled at for helping.",objectivesText="Help Steamwarden Hurlt repair the steamworks. Progress: How go?",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79558] = {id=79558,name="Feathered Fiend",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=14,mapID=1,description="The trinket appears to be a Noblegarden decoration of sorts. You should return this to the festivities at Razor Hill.",objectivesText="Bring the Noblegarden Trinket to Sylnaria Fareflame at Razor Hill.",ends={{mapID=1,npcID=217125,x=0.525,y=0.412}},coords={mapID=1,source="quest_giver",x=0.525,y=0.412},questType="standard"},
[79559] = {id=79559,name="The Verdigrease Knight",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Think you brave? Been looking for brave, but not find much. Not sure you count, look like tenderfoot who run home to granny if scrape knee. How about way to prove it? You hit me as hard as can. Try kill me. If I not dead, then I get kill you, later. Not look like it take more than one chop for you. Deal?",objectivesText="Slay the Verdigrease Knight . Progress: Going to run away?",starts={{npcID=230841,x=0.68,y=0.804,zoneID=14795}},ends={{npcID=218864,x=0.668,y=0.786,zoneID=14795}},coords={x=0.68,y=0.804,source="quest_giver",zoneID=14795},questType="standard"},
[79561] = {id=79561,name="Lord of the Giants",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Can tell you not new to questing. Fell many beasts in your time, am sure, like good knight must. Greasebaddaden , king of giant slimes, lair nearby. Perfect chance to prove valor to court! Has giant fork jammed in head, can't miss. You know what do.",objectivesText="Slay Greasebaddaden , King of the Giants. Progress: Big, have fork in head. Know him when see him.",starts={{npcID=218866,x=0.668,y=0.786,zoneID=14795}},ends={{npcID=218866,x=0.668,y=0.786,zoneID=14795}},coords={x=0.668,y=0.786,source="quest_giver",zoneID=14795},questType="standard"},
[79563] = {id=79563,name="Lady of the Lake",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Shown great bravery. Humbility. Honor. Would make good Knight of Brown Table. Only task left now is most sacred. Beseech Lady of Lake for blessing. She will judge whether worthy or not. Lake in back of cave. More pond, really, but no tell her that. Puddle Lady not have same ring.",objectivesText="Gain the Lady of the Lake 's blessing. Progress: Not far, just in back of cave.",starts={{npcID=218837,x=0.668,y=0.784,zoneID=14795}},ends={{npcID=218837,x=0.668,y=0.784,zoneID=14795}},coords={x=0.668,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[79564] = {id=79564,name="The Verdigrease Knight Returns",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Am back, as promise. Hear you now brave knight. Ready fulfill your end of oath? My turn strike YOU down. Kneel.",objectivesText="Kneel before the Verdigrease Knight and accept his reprisal. Progress: Make choice.",starts={{npcID=216566,x=0.668,y=0.786,zoneID=14795}},ends={{npcID=216566,x=0.668,y=0.786,zoneID=14795}},coords={x=0.668,y=0.786,source="quest_giver",zoneID=14795},questType="standard"},
[79565] = {id=79565,name="Janky Candles",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2248,description="With new candle almost ready, now all need is to set up stall! Bring quality candle at good price to people! That Janky guarantee. Only problem is not have stall. You talk to Bosh in Gun-dar-ghaz for me? He have everything we need. May need barter, but you talk good! Make him give parts. Meet you down there!",objectivesText="Acquire the parts Janky needs to build his stall in Gundargaz. Progress: Got parts?",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=216598,x=0.476,y=0.332,zoneID=14795}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[79574] = {id=79574,name="The Second Front",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Our reinforcements are already inbound. These spiders just decided where our next wall will go. Clear a landing zone for General Steelstrike .",objectivesText="Signal the landing zone.",starts={{npcID=217133,x=0.294,y=0.416,zoneID=14752}},ends={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},coords={x=0.294,y=0.416,source="quest_giver",zoneID=14752},questType="standard"},
[79575] = {id=79575,name="What the Duck?",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=14,mapID=1,description="I cannot work under these conditions! Something has all these silly ducks in an uproar--they nearly upended my precious golden egg! These chaotic quackers simply must be dealt with! I can keep them from entering the inn, but will you please help clear out the rest?",objectivesText="Scare off 10 ducks using the Horn of Honking . Progress: Shoo! Shoo! ...have you shooed them all yet?",starts={{mapID=1,npcID=217125,x=0.525,y=0.412}},ends={{mapID=1,npcID=217125,x=0.525,y=0.412}},coords={mapID=1,source="quest_giver",x=0.525,y=0.412},questType="standard"},
[79576] = {id=79576,name="A Fowl Concoction",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=14,mapID=1,description="My egg! My precious egg! While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My beautiful golden heirloom was among the items stolen! Enough is enough. We simply must put an end to this duck invasion. Please, <name>. These pilfering poultry must be stopped! Fortunately, I know a mage in Orgrimmar who might just have a solution for us.",objectivesText="Speak with Tethris Dewgazer at the Pathfinder's Den in Orgrimmar. Progress: Have you spoken with Tethris yet?",starts={{mapID=1,npcID=217125,x=0.525,y=0.412}},ends={{mapID=1,npcID=217125,x=0.525,y=0.412}},coords={mapID=1,source="quest_giver",x=0.525,y=0.412},questType="standard"},
[79577] = {id=79577,name="Duck Tales",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=14,mapID=1,description="Take this potion, <name>. Drink it, and you should be able to chit chat with those feathery fiends. Oh, but if you happen to experience any... unintended side effects, don't blame me.",objectivesText="Use the potion to get information from 5 ducks. Progress: Have they said anything interesting?",starts={{mapID=1,npcID=217147,x=0.525,y=0.41}},ends={{mapID=1,npcID=217125,x=0.525,y=0.412}},coords={mapID=1,source="quest_giver",x=0.525,y=0.41},questType="standard"},
[79578] = {id=79578,name="Just a Waddle Away",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=14,mapID=1,description="We simply must find out where those ducks are hiding our stolen goods--and my precious egg! Oh, and who this mysterious Daetan is, of course. I convinced Tethris to give me more of that potion. Take it and bring back my golden heirloom!",objectivesText="Discover the duck's hiding spot. Progress: Where would those ducks be hiding...",starts={{mapID=1,npcID=217125,x=0.525,y=0.412}},ends={{mapID=1,npcID=217125,x=0.525,y=0.412}},coords={mapID=1,source="quest_giver",x=0.525,y=0.412},questType="standard"},
[79579] = {id=79579,name="That Airspace is Mine(d)!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Our advantage is air superiority. The nerubians are threatening that with their mines. Your mount is more maneuverable than our skiffs. Get in the air and take those mines out. I will deploy what resources I can to provide you some blessings to improve your capabilities.",objectivesText="Fly through 5 nerubian mines while under the effects of Holy Lance. Progress: Our priests are powerful with the Light but lack the air speed you and your resources can achieve.",starts={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},ends={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},coords={x=0.276,y=0.45,source="quest_giver",zoneID=14752},questType="standard"},
[79580] = {id=79580,name="Offensive Counter",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="I will not yield this ground. Get out there and kill anything with more than two legs!",objectivesText="Slay 12 nerubians.",starts={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},ends={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},coords={x=0.276,y=0.45,source="quest_giver",zoneID=14752},questType="standard"},
[79625] = {id=79625,name="Not Quite Dead",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="I am General Anub'azal . I loathe having little bipeds like you in the Siegehold. However, that is no longer up to me. Zev'kall is pushing me out of my own military stronghold, and collecting overcrawlers to boot! The Queen has deemed him High General, but he is unnatural, warped, and unfit. This will not stand! I have decided to use you and your kind against Zev'kall. And yes, you will get something out of it. Search that rubbish pile there. You will see.",objectivesText="Examine the spoils pile in Siegehold. Progress: Go on, check the pile of rubbish.",starts={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},ends={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},coords={x=0.454,y=0.198,source="quest_giver",zoneID=14752},questType="standard"},
[79627] = {id=79627,name="Wine and Die",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2255,description="I can see it now, morsel. The pattern of our newest weave is laid bare before my mind. Meesk is well-guarded. He believes himself to be safe. That is where his weakness lies. Go to the city. Procure a bottle of his favorite drink and present it to him as a gift from your benefactor. Once he is sufficiently wooed by your affable charms, bring him to the High Hollows for his well-earned reward. I trust you, . And if you lay our threads out properly, I can guarantee you quite the show.",objectivesText="Find a way to charm Meesk the Venomtongue .",starts={{npcID=227428,x=0.534,y=0.692,zoneID=14752},{npcID=227428,x=0.62,y=0.126,zoneID=14753},{npcID=227428,x=0.63,y=0.118,zoneID=14753}},ends={{npcID=216298,x=0.628,y=0.226,zoneID=14753}},coords={x=0.534,y=0.692,source="quest_giver",zoneID=14752},questType="standard"},
[79630] = {id=79630,name="Searching the Web",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Oh, thank the hollows! You look like someone that can help. It's just horrible! Terrible! A tragedy! My husband has gone missing! We were just wedded yesterday! It was such a wonderful ceremony... But when we were to retire for the evening, he disappeared. Please, could you find him and bring him home to me?",objectivesText="Locate Arax'ne 's husband, Klaskin in the Umbral Bazaar. Progress: Please, I need help!",starts={{npcID=217356,x=0.64,y=0.16,zoneID=14753}},ends={{npcID=217355,x=0.478,y=0.132,zoneID=14753}},coords={x=0.64,y=0.16,source="quest_giver",zoneID=14753},questType="standard"},
[79631] = {id=79631,name="Klaskin's Great Escape",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Silken threads, I'm saved! It's incredibly important that I make it back home without my wife seeing me. I took off after our wedding last night, and if she sees me, she's going to kill me! If the guards catch me, they'll surely alert Arax'ne . Will you help me avoid the guards and get back home?",objectivesText="Return Klaskin to Arax'ne in the Umbral Bazaar. Progress: Please hurry!",starts={{npcID=217355,x=0.478,y=0.132,zoneID=14753}},ends={{npcID=217356,x=0.64,y=0.16,zoneID=14753}},coords={x=0.478,y=0.132,source="quest_giver",zoneID=14753},questType="standard"},
[79633] = {id=79633,name="The Weaver's Legacy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,mapID=2213,description="Oh, this is exciting! A meeting with someone who commands even overcrawlers to do their bidding. I have been waiting for a moment like this. Ah, I won't have to go too far though, will I? I am meant to host some up-and-coming Sureki socialites for dinner later tonight.",objectivesText="Bring Meesk the Venomtongue to meet the Weaver.",starts={{npcID=216298,x=0.628,y=0.226,zoneID=14753}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.628,y=0.226,source="quest_giver",zoneID=14753},questType="standard"},
[79641] = {id=79641,name="Wipe Away Their Smiles",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="The kobyss grow bold if they feel they can defile our Veneration Grounds. I think we should collect their teeth to wipe the smiles off their faces. Come! My brother and I will cleanse our lands from this filth. Try to keep up!",objectivesText="Collect kobyss teeth from slain kobyss. Progress: Let's see them smile now!",starts={{npcID=217424,x=0.29,y=0.618,zoneID=14838}},ends={{mapID=2215,npcID=217424,x=0.3475,y=0.4805}},coords={x=0.29,y=0.618,source="quest_giver",zoneID=14838},questType="standard"},
[79642] = {id=79642,name="Stave Them Off",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Without their magical weapons, the kobyss casters won't be able to use their foul necromancy. Steal their staves so we might toss them into the Sacred Flame and be done with them.",objectivesText="Collect 5 Darkwater staves. Progress: Did you find any Darkwater Staves?",starts={{npcID=217426,x=0.31,y=0.556,zoneID=14838}},ends={{mapID=2215,npcID=217426,x=0.303333,y=0.576}},coords={x=0.31,y=0.556,source="quest_giver",zoneID=14838},questType="standard"},
[79643] = {id=79643,name="Dreaded Dreadfang",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="My brother and I have dealt heavy blows to the kobyss, , but you could have done more. The most foul kobyss of them all has yet to taste my blade. If we take out their leader, the rest will flee back into the waters from which they came. Let's take the head of Dreadfang!",objectivesText="Kill Dreadfang the Merciless . Progress: Ready to kill some kobyss?",starts={{npcID=221492}},ends={{npcID=217424,x=0.29,y=0.618,zoneID=14838}},coords={mapID=2215,source="quest_giver",x=0.3475,y=0.4805},questType="standard"},
[79644] = {id=79644,name="Go to the Priory",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I... I do not have the words. Theleon... I will take h-his body. They will know what to do at the priory. Oh, brother... It was not supposed to end like this...",objectivesText="Meet Sister Etna Blayze at the Priory of the Sacred Flame.",starts={{npcID=217424,x=0.29,y=0.618,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.29,y=0.618,source="quest_giver",zoneID=14838},questType="standard"},
[79645] = {id=79645,name="Sweet-Sting Infestation",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Poor Theleon. I gave him some of his first lessons in combat. I'll see him to his final pyre. But first, you. I've been trying to fight back an infestation of sweet-stings harassing our wine-making operations. I need someone else to finish them off while I tend to Theleon's remains. Be fast and clever and bring me some of their venom as you take care of things. We'll turn that into a poison for the nesting sites and be done with the nuisance.",objectivesText="Collect 10 vials of Wasp Venom. Progress: Did you kill those things?",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79646] = {id=79646,name="Memorial Wine",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Oh, Theleon. He always did follow his big brother into anything. While we prepare Theleon for his final rest, would you please help Brother Abealard with a batch of Memorial Wine for the service?",objectivesText="Make Memorial Wine with Brother Abealard. Progress: Did you help Brother Abealard?",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79647] = {id=79647,name="Burning Reflections",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Sybaestan could use your support now. His little brother was his best friend. Only death could separate them... and it has. He is not taking it well. It is customary to burn written memories of the deceased. By committing them to the flames, we let go our heartache and let the warmth of memory heal us. It is a bittersweet time. You were with Theleon at the end, too. That might help Sybaestan.",objectivesText="Help Sybaestan mourn his brother. Progress: The ritual helps ease the hearts of many.",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79648] = {id=79648,name="Missing Somebody",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="Theleon was a good one, but now we must commit his body to the Flames. Sybaestan is in no shape to bear his brother. Would you collect his remains from among those others awaiting their final rest?",objectivesText="Collect Theleon's remains. Progress: You're strong and you have the distance Sybaestan lacks right now.",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79649] = {id=79649,name="Sacred Flame Inquisition",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="All the dead are missing? How can that be? They were all laid out in preparation for their pyres. Who would want to move them? Someone must have seen something. Go ask anyone in the area who might have seen something and I'll go talk to some of the upper clergy. We'll get to the bottom of this and return our dead so they can be properly tended to.",objectivesText="Interrogate the local clergy. Progress: Did you find anything out?",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79650] = {id=79650,name="Priory of the Sacred Flame: A Brother's Grief",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14954,mapID=2215,description="I fear that the Prioress may be behind our missing dead-- and our missing baron. Sybaestan has disappeared as well and I don't believe in coincidences. She and Sybaestan have taken our recent losses hard. I fear what their overwhelming grief might be doing to their souls. We must confront them and bring them back to sanity... If we can. Tell General Steelstrike what you have learned. We might need her backup. I'll be waiting for you here.",objectivesText="Confront Prioress Haelsey Murrpray inside the Priory of the Sacred Flame. Progress: We must confront the prioress.",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="dungeon"},
[79651] = {id=79651,name="Trade Partners",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Have you visited Mmarl? It's a trade town to the southeast of here. Try some of Corby's barbeque while you're over there!",objectivesText="Check out Mmarl.",starts={{npcID=223754,x=0.558,y=0.436,zoneID=14752}},ends={{npcID=217029,x=0.778,y=0.628,zoneID=14752}},coords={x=0.558,y=0.436,source="quest_giver",zoneID=14752},questType="standard"},
[79655] = {id=79655,name="Hallowfall Arathi",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79659] = {id=79659,name="The Severed Threads",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79679] = {id=79679,name="Muddled Mind in the Mine",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="The workers said they saw Munderut near the back of the mining area. Please find him and tell him that I said he needs to report back in. He might not remember me, or that I am his fused. Tell him to look down at his chest, at the medallion he wears. His memory of our time together fades in and out these days, but the medallion tells of our story and bond forever.",objectivesText="Look for Munderut in Nibelgaz Mine.",starts={{npcID=215208,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=215209,x=0.51,y=0.148,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79680] = {id=79680,name="Pipe Patching",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Earthquake do number on old pipes. Many start leaking steam everywhere. Especially ones too tall to reach. Fourman Grimes points up to the pipes stretching from Gundargaz to the surface.> Stoneheads not have \"approved replacements,\" but we not have time wait. Take glue and seal leaks with flappy-flying thing. Made of only best bugs, boiled myself. Will do for today.",objectivesText="Fly near the leaks in steam pipes above Gundargaz to seal them with kobold-provided glue. Progress: Try not glue self to pipe, yes?",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79681] = {id=79681,name="Plumber Power",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Not all leaky pipes accessible from outside. Some inside tunnels run all under Gundargaz. Tunnels small for stoneheads, but kobolds love tunnel! Just need someone to show layout. You, someone. Check with crew boss if have problems. He help go over maps.",objectivesText="Use the Tunnel Access to plot the steam pipe routes through Gundargaz. Progress: Get lost?",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79682] = {id=79682,name="Critical Pressure!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Pressure still too high! Something else wrong, not just old pipes. Open main release before something burst. Not have time for manuals. Consequences for deal with later!",objectivesText="Open the main release valve and deal with whatever happens. Progress: Find problem?",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79683] = {id=79683,name="Home Is Where the Candle Is",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Exciting to have new place call home, . Not quite settled, though. We not know Gundargaz. Gundargaz not know us. Time to fix both! Find out how help here. Teach new friends about us. Kobolds clever and friendly, so should be easy! Start with help three kobolds. Fourman Grimes want get to work right away. She very task oriented. Granny Scribbles tell you lot about kobold culture. And Janky want set up new business in town, sell candle to Gundargaz.",objectivesText="Assist Fourman Grimes, Janky, and Granny Scribbles.",starts={{npcID=213152,x=0.47,y=0.34,zoneID=14795},{npcID=222803,x=0.47,y=0.332,zoneID=14795}},ends={{npcID=213152,x=0.47,y=0.34,zoneID=14795},{npcID=222803,x=0.47,y=0.332,zoneID=14795}},coords={x=0.47,y=0.34,source="quest_giver",zoneID=14795},questType="standard"},
[79686] = {id=79686,name="Concerning Fungarians",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Log Entry: 235-18-7 Date: Fabrication Quarter Cycle Observation: Fungarians exhibit accelerated growth and increased territorial aggression. Spore dispersal seems to have quadrupled compared to previous recorded rates.",objectivesText="Collect the remaining research notes and return them to their owner in the Freywold Village. Progress: Did you find something interesting?",starts={{npcID=428135,x=0.358,y=0.771,zoneID=14717}},ends={{npcID=218729,x=0.414,y=0.714,zoneID=14717}},coords={x=0.358,y=0.771,source="quest_giver",zoneID=14717},questType="standard"},
[79691] = {id=79691,name="Monsters in the Dark",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The local quarry was an active source of clay and ore for us until the fungarians took over some time ago. We were worried about the fungarians encroaching upon the village, but there's something more. Multiple sightings of a creature much larger than our native wildlife have been reported at night. Combined with villager Modhina's disappearance, I fear this is no coincidence. She visited the quarry recently and hasn't returned. We would be in your debt if you searched the tunnels.",objectivesText="Slay the Ashen Stonestalker in Gemvein Tunnels. Progress: You do us a great service by making our lands safe.",starts={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},ends={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},coords={x=0.422,y=0.732,source="quest_giver",zoneID=14717},questType="standard"},
[79692] = {id=79692,name="Buried, Not Forgotten",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Several suns ago, my friend Modhina ventured into the quarry cave. She wanted to find rare ore for Hreka, to help her craftsmanship. Modhina was excited, I remember. A rare feeling for earthen. She hasn't returned. The fungarians prevent us from searching the area. It would mean a great deal to us if you could look for her. I didn't know it was possible to spend so much of the day thinking about what if's.",objectivesText="Find Modhina and her belongings in Gemvein Tunnels. Progress: Be careful. I fear more sinister things lurk in these tunnels.",starts={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},ends={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},coords={x=0.422,y=0.732,source="quest_giver",zoneID=14717},questType="standard"},
[79693] = {id=79693,name="Play Hearthstone!",faction="alliance",expansion=10,zoneID=13862,mapID=1,description="It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.",objectivesText="Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!",starts={{mapID=1,npcID=215409,x=0.53,y=0.152}},ends={{mapID=1,npcID=215409,x=0.53,y=0.152}},coords={mapID=1,source="quest_giver",x=0.53,y=0.152},questType="standard"},
[79694] = {id=79694,name="Play Hearthstone!",faction="horde",expansion=10,zoneID=13862,mapID=1,description="It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.",objectivesText="Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!",starts={{mapID=1,npcID=215409,x=0.53,y=0.152}},ends={{mapID=1,npcID=215409,x=0.53,y=0.152}},coords={mapID=1,source="quest_giver",x=0.53,y=0.152},questType="standard"},
[79701] = {id=79701,name="The Cavalry is Here",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Baelgrim quakes with fury.> These cursed nerubians. Attacking a triage site! So many wounded and defenseless... and yet, it looks like you outlanders are putting up a fight! Let's grind every last one of the bugs back into the ground.",objectivesText="Repel the nerubian attack at the Proscenium.",starts={{npcID=217766,x=0.564,y=0.48,zoneID=14717}},ends={{npcID=217766,x=0.564,y=0.48,zoneID=14717}},coords={x=0.564,y=0.48,source="quest_giver",zoneID=14717},questType="standard"},
[79703] = {id=79703,name="Hope, An Anomaly",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Hreka looks through the things you retrieved, one by one.> So you risked your life to find our friend. Modhina is gone, then. Her notes are about the rare ore from the cave. Melted down, it becomes a beautiful glaze for pottery. What can I do? I'm no fighter. I can't avenge her. Besides, her body has already been reclaimed by the earth. That much is certain by the state of her memory gem fragment. What can I do now, but make a pot? Will you help me?",objectivesText="Make a piece of pottery with Hreka . Progress: A lifetime spent making pottery. Is this my titan given fate? Then why do I still wonder?",starts={{npcID=217961,x=0.418,y=0.708,zoneID=14717}},ends={{npcID=217961,x=0.418,y=0.708,zoneID=14717}},coords={x=0.418,y=0.708,source="quest_giver",zoneID=14717},questType="standard"},
[79710] = {id=79710,name="A Fin of Every Kind",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Oh! My! LEGS! You're perfect! Yes! You're a perfect, little, unassuming biped for my work. Alchemy is my trade, and an alchemist is only as good as their ingredients. See these kobyss below? I've been camped out here for weeks observing them. They seem tougher than average kobyss. My conclusion? They must be made of stronger stuff! And I want that stuff! Here's a sack. Fill it up! Fill it up with their innards! As much as you can carry!",objectivesText="Fill up the Kobyss Innards Sack. Progress: Is that really as much as you can carry?",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79711] = {id=79711,name="That's Pretty Gross",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="familiar-looking appendage from the silt. It doesn't seem particularly kobyss, but perhaps a unique specimen will earn you an increased reward from Al'kubian .>",objectivesText="Bring the Familiar-Looking Appendage back to Al'kubian . Progress: Ooooh! What is this?",starts={{npcID=443995,x=0.597,y=0.692,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.597,y=0.692,source="quest_giver",zoneID=14752},questType="standard"},
[79713] = {id=79713,name="Moonlight Gutter Swim",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="An Ascended's leg... A kobyss tribe feasting one or two dozen trueborns or skitterlings, perhaps even a sageform such as myself... But an Ascended is a different story. Let us approach this as intellectuals, and use the tools at our disposal to collect more data. What tools do we have? You. You are the tool. An intellectual tool of kobyss disposal. Dive into the lake's depths. Slay the largest of these creatures or their pets. And of course, bring me their innards.",objectivesText="Collect Liverseeker's Intestines and Leg Chewer's Stomach . Progress: Any profits I gain from my work goes directly to scientific and alchemical research. As in, I use the profits for myself, and I am an alchemical scientist.",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79714] = {id=79714,name="Rescuing the Food",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=5723,mapID=2255,description="While awaiting your innards-bestowing return, I observed some fascinating activity below. A consistent train of kobyss are dragging the limp bodies of my kin from the lake's waters and westerly into their cavern. My conclusion? Nerubians are being hunted and stored in the lake for consumption by these beasts. It's not so much for research than it is for civic duty, but I would reward you might be able to save from their fate.",objectivesText="Rescue 5 Captive Kaheti.",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79715] = {id=79715,name="Grand, Gutsy Solutions",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="I require one final piece of data. These beasts think. They organize. They coordinate. To be characteristically honest, there's nothing worse than an amphibian with an abacus. My final task for you: Bring me the brain of the biggest beast. I need it fresh, and preferably non-liquified. And, you know, perhaps it will slow them down as well.",objectivesText="Collect the Brain of Grand Gluttony. Progress: Have you got it? Is it leaking?",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79716] = {id=79716,name="The History Beneath Us",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The titan console is a huge find. And look at these ruins! There has tae be more here! But goin' out into the site is dangerous. Accordin' to Brinthe, now that the titan vault has been unearthed, elementals have come. Elementals dunnae like order magic, an' titan relics just ooze the stuff. They're on a rampage! Can ye go out there an' get some relics back from the elementals? We need tae preserve what we can!",objectivesText="Collect 20 Shattered Relic Fragments from elementals in Golgrin's Reach. Progress: Have ye found anythin' yet?",starts={{npcID=225453,x=0.616,y=0.702,zoneID=14717}},ends={{npcID=225453,x=0.616,y=0.702,zoneID=14717}},coords={x=0.616,y=0.702,source="quest_giver",zoneID=14717},questType="standard"},
[79717] = {id=79717,name="Means of Ingress",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Ah, look at you! Just the sort of rogue element I need. My name is Ar'syn , and I am something of a connoisseur for the fine arts and histories of our people. It is my intent to enter the Royal Preservatory--that's that large enclave just over there-- and rob it blind. But gracious, the guards will never let me get close enough to survey their security! If only I had someone to help me find a somewhat more subtle way into the building. Ar'syn looks at you meaningfully.>",objectivesText="Survey three potential entryways into the Royal Preservatory. Progress: Well, what do you think? I think you'll find that even the Preservatory itself is quite the work of art in its own right... Though that does mean it will prove rather vexing to infiltrate.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79718] = {id=79718,name="Skeins Street Irregulars",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="I would like nothing more than to go in and take a few of these pompous Sureki royalists out. It would make our infiltration that much easier, and it would serve them right for trampling upon our history. But I cannot get close without bringing a whole host of guards down upon the Skeins. You, though? No one will bat an eye at wanton violence if it comes from an overcrawler. Why not get in there and thin them out a bit? Oh, don't give me that look. You were going to do it anyway.",objectivesText="Slay Sureki agents around the Royal Preservatory. Progress: You needn't worry about any moral quandaries here. The craven Sureki would do the same to you thrice over.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79721] = {id=79721,name="Fire in the Hole",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Who are you? But of course, another outlander! I'm Wenbrandt , tamer of cinderbees and creator of cinderbrew. Wenbrandt squares himself up as if you should be impressed.> I had brought barrels of cinderbrew to help the injured. I thought drinking it would ease their pain, but for most it just caused more... burning... pain... I refuse to let my brew go to waste. Maybe it can be weaponized. The nerubians are just bugs after all--organic and flammable. This burrow here is a perfect test subject.",objectivesText="Use cinderbrew to repel the nerubian attack in the Proscenium. Progress: Go drop a few on the nerubians. Let's see what happens.",starts={{npcID=212295,x=0.566,y=0.52,zoneID=14717}},ends={{npcID=212295,x=0.566,y=0.52,zoneID=14717}},coords={x=0.566,y=0.52,source="quest_giver",zoneID=14717},questType="standard"},
[79723] = {id=79723,name="Repatriation by Subtraction",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Ansurek and her ilk are so short-sighted. They think that by filling our museum with trophies of their recent conquests instead of relics of our own history, we will be less inclined to remember where we came from. Well, they are probably right--in the long term, at least. History has a habit of bending towards the voice of its teller. But that is where we come in, . Those relics that the Sureki forces stole? It's time to steal them back.",objectivesText="Loot six Pillaged Trophies from the Royal Repository. Progress: Well, <name>? I'm sure the place is filled with a queen's ransom.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79724] = {id=79724,name="A Titanic Expedition!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Our merchant friend told us about some small islands off the northeast coast called \"The Three Shields.\" Apparently, there was a lot of titan activity there long ago. To me, the \"activity\" sounded like titan research and development. Exciting stuff! Tuberros and I are going there to check it out. Tharessa, my new Algari Expedition trainee, is coming along to see true professionals at work. Care to join us?",objectivesText="Meet Rannan at The Three Shields.",starts={{npcID=217763,x=0.588,y=0.282,zoneID=14717}},ends={{npcID=217657,x=0.778,y=0.302,zoneID=14717}},coords={x=0.588,y=0.282,source="quest_giver",zoneID=14717},questType="standard"},
[79725] = {id=79725,name="Not a Heating Pack",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Tharessa has done some reconnaissance for us and found the gorlocs are digging up artifacts and... cuddling with them. I think it means that the artifacts emit heat? Maybe that means some artifacts are still functioning? Imagine--the titans created technology to shape worlds, and now a fish uses it to warm their fins. Hah! The gorlocs won't give them up, and I don't want to be a Rannan-kabob either. I hate to ask because they just want to be warm, but could you do something about them?",objectivesText="Rannan wants you to kill 12 gorlocs. Progress: Did you get them? I thought I saw one sneak by a moment ago...",starts={{npcID=217657,x=0.778,y=0.302,zoneID=14717},{npcID=217828,x=0.78,y=0.302,zoneID=14717}},ends={{npcID=217828,x=0.78,y=0.302,zoneID=14717}},coords={x=0.778,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79726] = {id=79726,name="\"Cataloguing\"",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="As ya know, we are here to collect some titan shinies, artifacts, whatever! And Rannan thinks the more shinies--er, you know what I mean--the better chance we have figurin' out something about the titans. That'll make Rannan happy, but it'll also ensure I have some extras to take to my store back home. My wife, Perisimona, is waiting for 'em back in Loamm. I can't go back empty handed!",objectivesText="Recover 7 titan artifacts . Progress: You get some good shinies yet?",starts={{npcID=217656,x=0.778,y=0.302,zoneID=14717}},ends={{npcID=217656,x=0.778,y=0.302,zoneID=14717}},coords={x=0.778,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79727] = {id=79727,name="Because It's Shiny",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="While these two were ordering you around, I thought I would do something useful and make sure the gorlocs were not going to surprise us here on the beach. None of them seemed interested in us, but then I saw one huge gorloc. It killed off some smaller gorlocs then took off. It had something glowing in its claw though! It had to be an artifact. And it looked like it was working! We've got to get it back. By \"we\" I mean \"you.\" Larger-than-average gorlocs are above my Dragonscale pay grade.",objectivesText="Retrieve the artifact from the huge gorloc. Progress: Were you able to get the artifact?",starts={{npcID=217659,x=0.78,y=0.302,zoneID=14717}},ends={{npcID=217659,x=0.78,y=0.302,zoneID=14717}},coords={x=0.78,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79728] = {id=79728,name="It's Probably Nothing",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="You found a buzz orb! ...Er, that's what the niffen call it. I just kind of went with it. It's still in a good condition. Still buzzing, humming, and warm to the touch! I haven't seen one since we were in Zaralek Cavern! , you should see if we can get it to work. I will stand back here, just in case it is, um, not friendly. Nothing to worry about, I'm sure.",objectivesText="Interact with the titan orb. Progress: Yes, yes! It will be very exciting to hear what you have discovered.",starts={{npcID=217828,x=0.78,y=0.302,zoneID=14717}},ends={{npcID=217828,x=0.78,y=0.302,zoneID=14717}},coords={x=0.78,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79729] = {id=79729,name="Educate Yourself",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="The Relics of Founding have always been the centerpieces of the Preservatory's collection. Together, those four artifacts tell our most reverent tale--that of the founding of Azj-Kahet, and of our people's rejection of our Old Masters. With luck, they will still be inside the Preservatory. Once you are inside, I want you to tamper with the shadecasters in front of each of the relics. Make sure that their messages are heard by anyone nearby--whether they wish to listen or not.",objectivesText="Tamper with the shadecasters in front of each of the four Founding Relics.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79730] = {id=79730,name="Dogged Pursuit",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="But of course, simply stealing the relics isn't enough. We need to teach the Queen's pet burrow-worms a lesson in futility, or they will simply start the whole process again! That shouting buffoon near the central passage is Rez'kal, a member of Ansurek's personal academic entourage. He's... not very bright, but he makes up for it with enough strength to send either of us through a wall. I'm not inclined to go toe to toe with the big oaf today. Would you mind overmuch doing one last favor for me?",objectivesText="Defeat Royal Broker Rez'kal . Progress: Be careful, <name>. What Rez'kal lacks in acuity he makes up for in scarab-headed stubbornness.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79944] = {id=79944,name="Raging Rifts",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="The elementals are coming from inside that cave. We only made it part of the way in before needing to retreat. I could see some flickering within, some strange glowing thing that looked almost like a tear in space from which the elementals poured forth! We managed to close one of these portals, but there are more. I need to stay with Nanthaz. It is up to you now, if you can manage. Destroy the rifts and find their source. I suspect it lies deeper within the cave.",objectivesText="Destroy 4 rifts and find their source within the cave. Progress: Destroy what rifts you come across, but above all, find their source! I suspect you will find it deep inside the nearby cave. The miners you rescued spoke of breaking through to a crystal-filled room, and of the elementals pouring forth from within.",starts={{npcID=223000,x=0.552,y=0.11,zoneID=14795}},ends={{npcID=223000,x=0.552,y=0.11,zoneID=14795}},coords={x=0.552,y=0.11,source="quest_giver",zoneID=14795},questType="standard"},
[79954] = {id=79954,name="Spiders!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Why, hello there, little $pr. You seem like you might be able to assist me. You see, my dear mate Ami'thax fell onto a sharp dagger. Her body was taken to Pillar-nest Xesh, just below where we stand. Xesh is used to dispose of all sorts of bodies that we never speak of again. Unfortunately I have need to speak of Ami'thax, because she had the key to my new High Hollows burrow on her when she died. Dreadful timing, really. Would you go and fetch it? Do beware of the spiders, I need my key.",objectivesText="Find Ag'thax 's missing key in Pillar-nest Xesh. Progress: Don't let the spiders eat you before you escape with my key.",starts={{npcID=217255,x=0.774,y=0.684,zoneID=14753}},ends={{npcID=217255,x=0.774,y=0.684,zoneID=14753}},coords={x=0.774,y=0.684,source="quest_giver",zoneID=14753},questType="standard"},
[79955] = {id=79955,name="...And Now I'm Arachnophobic",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Who is there? Someone? Did I imagine you? I am Albert . I was a Pathfinder once. Now that I'm blind, I see no path. It seems wrong to call myself Pathfinder Henson. I can hear, though. I can hear them eating. They eat the fresh parts. My eyes. My insides. It hurts all the time. They do not want my rotten pieces. The decayed parts are all I have left. The worst of me. I wasn't alone here, I had fellow Pathfinders. I keep hearing sobbing from the walls. Do you hear them too?",objectivesText="Locate Albert 's friends in the walls.",starts={{x=0.668,y=0.549,mapID=2216,npcID=217640}},ends={{x=0.668,y=0.549,mapID=2216,npcID=217640}},coords={mapID=2216,x=0.668,y=0.549},questType="standard"},
[79956] = {id=79956,name="Legs in the Ceiling",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="I don't require vengeance on my behalf, but I would like vengeance for all of my friends that were eaten. I didn't think the Horror of Xesh was real, but she is. Xishirra. A shadow of a nightmare, making a brood of monsters while she stays out of reach. The horror is ancient, and beyond us, but we can still make her pay! Pull hard on a web strand if you need to, and deal with whatever comes. We'll escape after some justice is had!",objectivesText="Pull on the spider thread if the spiders are not already attacking, and kill whatever comes.",starts={{x=0.699,y=0.633,mapID=2216,npcID=217640}},ends={{x=0.699,y=0.633,mapID=2216,npcID=217640}},coords={mapID=2216,x=0.699,y=0.633},questType="standard"},
[79957] = {id=79957,name="Maggots in your Eyes",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Albert is no longer alive. All that remains is his head, still full of maggots. Taking him back to the Pathfinders seems like the right thing to do.>",objectivesText="Take Albert's head to the Pathfinders in Faerin's Advance. Progress: Whose head is that?",starts={{x=0.687,y=0.623,mapID=2216,npcID=217994}},ends={{npcID=211708,x=0.592,y=0.192,zoneID=14752}},coords={mapID=2255,source="quest_giver",x=0.592,y=0.192},questType="standard"},
[79989] = {id=79989,name="An Ancient Awakening",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13646,mapID=2024,description="The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks. That amount of unstable energy being released could be catastrophic. Shall we continue?",objectivesText="Empower the Waygate.",starts={{mapID=2024,npcID=189764,x=0.4968,y=0.344}},ends={{mapID=2022,npcID=189066,x=0.472,y=0.902}},coords={mapID=2024,source="quest_giver",x=0.4968,y=0.344},questType="standard"},
[79998] = {id=79998,name="Mite Not Right",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,mapID=2248,description="This not good. Fancy fire bees have mites! Janky seen this before. Hive get infested, good bugs get sucked dry. End bad. Need do something! Blast bees with smoke. Makes bees sleepy but mites hate! When jump off, you squish before they bite bees again.",objectivesText="Cleanse fire bees of their infestation with Janky 's scented smoke and kill the offending mites. Progress: Many mites left?",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[79999] = {id=79999,name="Igniting Hope",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="One dawntower has fallen, but a faint glimmer of hope remains with the smaller keyflame atop the wall. The shattered remnants needed to sustain that light were taken by the nerubians. Gather the remnants from nerubians you slay, and help ignite a beacon of hope!",starts={{npcID=213116,x=0.684,y=0.45,mapID=2215}},ends={{npcID=213116,x=0.684,y=0.45,mapID=2215}},coords={x=0.684,y=0.45,source="quest_giver",mapID=2215},questType="standard"},
[80000] = {id=80000,name="Beebiter",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Mites kill fire bees. No good! Janky hate mites. Bite you when not even stealing wax. Not even make wax! Give bees chance. Kill biggest, bite-iest mite before eats more bees.",objectivesText="Slay Beebiter . Progress: How feel about being on fire? Good?",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[80004] = {id=80004,name="Crab Grab",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,mapID=2215,description="<The arrival of the kobyss has kept the Arathi from working these shores. Delivering a cage full of fresh crabs could aid citizens in need of food.>",objectivesText="Collect 12 Shadowtide crabs from the waters off the Faded Shore.",starts={{npcID=424347,x=0.615,y=0.174,zoneID=14838}},ends={{npcID=206150,x=0.632,y=0.294,zoneID=14838},{npcID=206441,x=0.652,y=0.28,zoneID=14838}},coords={x=0.615,y=0.174,source="quest_giver",zoneID=14838},questType="standard"},
[80012] = {id=80012,name="Skyriding",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,description="This land is more vast than I remember. However, a good scholar always prepares for contingencies. Two of the most airborne dragons have agreed to aid our cause. They will provide a winged mount so you may cover more ground. I will send you to Lord Andestrasz . He shall instruct you further.",objectivesText="Take Moratari 's portal to Lord Andestrasz . Progress: All things come with practice.",starts={{mapID=371,npcID=218468,x=0.342667,y=0.375333}},ends={{mapID=371,npcID=218469,x=0.652,y=0.372}},coords={mapID=371,source="quest_giver",x=0.342667,y=0.375333},questType="standard"},
[80013] = {id=80013,name="How to Glide with Your Dragon",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,description="Let us start with the basics. If you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding. First, call upon your drake, or our Red Drake friend here can give you a lift. Then, fly through the rings and land at the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.",objectivesText="Summon your dragonriding mount, or mount the Red Drake . Then glide through the rings and land in the target area. Progress: Well done, <name>.",starts={{mapID=371,npcID=218469,x=0.652,y=0.372}},ends={{mapID=371,npcID=218470,x=0.6508,y=0.3456}},coords={mapID=371,source="quest_giver",x=0.652,y=0.372},questType="standard"},
[80015] = {id=80015,name="How to Dive with Your Dragon",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,description="Gliding will get you to where you want to go. But what if you want to get there faster? Diving after jumping from somewhere high will give you a speed boost. As long as you fly well, you can conserve your momentum and gain some height after a dive. Fly through the rings to the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.",objectivesText="Dive then glide through the rings and land in the target area. Progress: Well done, <name>.",starts={{mapID=371,npcID=218469,x=0.652,y=0.372}},ends={{mapID=371,npcID=218470,x=0.6508,y=0.3456}},coords={mapID=371,source="quest_giver",x=0.652,y=0.372},questType="standard"},
[80016] = {id=80016,name="The Need For Higher Velocities",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,description="Sometimes you'll need to travel longer distances. If you don't need to travel up and over any obstacles, using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky. Follow the rings again to your destination and use Surge Forward when prompted to maintain your speed. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.",objectivesText="Fly through the rings and land in the target area. Progress: Well done, <name>.",starts={{mapID=371,npcID=218469,x=0.652,y=0.372}},ends={{mapID=371,npcID=218470,x=0.6508,y=0.3456}},coords={mapID=371,source="quest_giver",x=0.652,y=0.372},questType="standard"},
[80017] = {id=80017,name="The Need For Higher Altitudes",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,description="To gain height, use Skyward Ascent. Follow the rings again to your destination, using Skyward Ascent when you need upward momentum. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.",objectivesText="Fly through the rings and land in the target area. Progress: Well done, <name>.",starts={{mapID=371,npcID=218469,x=0.652,y=0.372}},ends={{mapID=371,npcID=218470,x=0.6508,y=0.3456}},coords={mapID=371,source="quest_giver",x=0.652,y=0.372},questType="standard"},
[80018] = {id=80018,name="Fashionable Flying",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,description="You have learned all I can teach you. But flying isn't just about getting to your destination--it's about getting there in style! Use the Rostrum of Transformation behind you to customize your drake's appearance.",objectivesText="Use the Rostrum of Transformation. Progress: How do you like your look?",starts={{mapID=371,npcID=218469,x=0.652,y=0.372}},ends={{mapID=371,npcID=218469,x=0.652,y=0.372}},coords={mapID=371,source="quest_giver",x=0.652,y=0.372},questType="standard"},
[80022] = {id=80022,name="Calling the Stormriders",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="I know the Unbound can repair and unblock the Coreway expediently--but I also know the nerubians. If they see an opportunity for an ambush, they will take it. With our backs turned and our focus on the Coreway, we are prime targets. I need to rally my Stormriders and form a perimeter around Dornogal in case of an attack from within or from without. Meet me outside of the Stormperch. I will call upon my troops there.",objectivesText="Meet Baelgrim outside the Stormperch, then speak with him to follow him into The Rookery. This challenge may be completed solo or with up to 3 party members. Progress: Baelgrim is right. We need to defend the Unbound while they work on the Coreway.",starts={{npcID=212747,x=0.358,y=0.526,zoneID=14771}},ends={{npcID=212746,x=0.36,y=0.526,zoneID=14771}},coords={x=0.358,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[80058] = {id=80058,name="Kobold Kleanup",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="New home little shabby. Not good, full of fun stuff and good bits shabby. Old, everybody died and now it fall apart shabby. We help! Lots of kobolds, now, so we make place presentable for stonehead friends. Make feel like home. You help, too. Grab broom, get going!",objectivesText="Clean up Gundargaz. Progress: How go?",starts={{npcID=216568,x=0.478,y=0.354,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.478,y=0.354,source="quest_giver",zoneID=14795},questType="standard"},
[80069] = {id=80069,name="Tears of Teldrassil",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="I have carried this weight long enough. It has finally come time to put my family to rest. Even if I never found my sister... < Kelestra wipes away tears and takes a deep breath.> I must gather barrowstones to place at their final resting place. But I simply cannot carry that many stones. Maybe I ask too much of a stranger, but would you assist me? I know having someone beside me will make this more endurable.",objectivesText="Follow Kelestra and collect barrowstones to help her memorialize her family. Progress: < Kelestra looks distraught, and her hands are shaking.> I can not parse my feelings. My sister is alive, but a traitor. And what did he mean she deserved her fate? Please Koroleth, let this finally be our time to reunite.",starts={{mapID=2239,npcID=218623,x=0.7255,y=0.7305}},ends={{mapID=2239,npcID=218697,x=0.728,y=0.795}},coords={mapID=2239,source="quest_giver",x=0.7255,y=0.7305},questType="standard"},
[80071] = {id=80071,name="Fact Finding",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="I must speak with the Primalists. I don't understand why she would turn her back on us. Koroleth saved my life at Teldrassil. I owe it to her to find out the truth. <name>, I realize this might be awkward, but will you help me? I can no longer bear this alone.",objectivesText="Meet Kelestra at the Twilight Watchtower.",starts={{mapID=2239,npcID=218697,x=0.728,y=0.795}},ends={{mapID=2239,npcID=218698,x=0.336,y=0.188}},coords={mapID=2239,source="quest_giver",x=0.728,y=0.795},questType="standard"},
[80072] = {id=80072,name="A Primalist Point of View",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="Warden Malathra has granted us permission to speak with the Primalists. They might have switched sides, but the wardens are keeping a close eye on them. < Kelestra begins to look distressed.> I'm going to talk to the Warden more. Could you handle the Primalists? All of this about Koroleth is just happening so suddenly. I feel we should gather as much information as we can.",objectivesText="Speak to the reformed Primalists about Koroleth. Progress: I want to talk to them, but I don't even know where to begin.",starts={{mapID=2239,npcID=218698,x=0.336,y=0.188}},ends={{mapID=2239,npcID=218698,x=0.336,y=0.188}},coords={mapID=2239,source="quest_giver",x=0.336,y=0.188},questType="standard"},
[80073] = {id=80073,name="Bones of a Bygone Battle",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="After speaking with the warden, I learned the Battle of the Barrier where my sister fell took place east of here, on the shores of the Ohn'ahran Plains. I understand her body was washed out to sea and never recovered. It's possible the tide brought her remains back to shore at some point. Will you help me look for her? Each member of my family has a necklace with this distinct design. It will identify Koroleth's body. I would like to lay her to rest with the family she loved.",objectivesText="Search the shoreline of the Ancient Bough for Koroleth's remains. Progress: Is this the necklace you found?",starts={{mapID=2239,npcID=218698,x=0.336,y=0.188}},ends={{mapID=2239,npcID=218701,x=0.888,y=0.208}},coords={mapID=2239,source="quest_giver",x=0.336,y=0.188},questType="standard"},
[80075] = {id=80075,name="A Barrow Den Burial",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="All that is left to do is to gather my sister's remains and bring them to the barrow den. Please meet me there, <name>. I could use a friend.",objectivesText="Meet Kelestra outside the barrow den at the Fields of Reverie.",starts={{mapID=2239,npcID=218701,x=0.888,y=0.208}},ends={{mapID=2239,npcID=218785,x=0.722,y=0.72}},coords={mapID=2239,source="quest_giver",x=0.888,y=0.208},questType="standard"},
[80077] = {id=80077,name="Sins of the Sister",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15105,mapID=2239,description="This druid is trying to convince Malfurion not to let me bury my sister here with the rest of my family. He won't even let me get a word in. < Kelestra tightly clutches the straps of her backpack holding her sister's remains.> I know I have asked a lot of you already. Could you talk to them? Perhaps they might listen to you?",objectivesText="Speak with Malfurion Stormrage about Koroleth's remains. Progress: <Malfurion is deep in thought.>",starts={{mapID=2239,npcID=218785,x=0.722,y=0.72}},ends={{mapID=2239,npcID=218629,x=0.722,y=0.72}},coords={mapID=2239,source="quest_giver",x=0.722,y=0.72},questType="standard"},
[80082] = {id=80082,name="Back to Gundargaz",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="We may not have overthrown the Candle King, but our work here has surely relieved some of the pressure facing Gundargaz. And it's made us more than a few new allies, as well. Our new friends will not be forgotten, on my word as Speaker. There is a...regrettable amount of available housing in Gundargaz as of late. It will be nice to feel the city come to life again, and we can certainly use the manpower. Shall we bring them home, ?",objectivesText="Return to Gundargaz.",starts={{npcID=212992,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=218715,x=0.47,y=0.332,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[80096] = {id=80096,name="The Shovel in the Stone",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Now, friend, we quest for blade of legend! Whoever pull from stone it stuck in destined for greatness. Only problem is that it very stuck. In very big rock. No idea how even get there, really. Come! We try you hand at fate!",objectivesText="Recover the legendary kobold shovel Excavator . Progress: Pull with knees, not with back.",starts={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},ends={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},coords={x=0.668,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[80144] = {id=80144,name="The Holey Grail",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Holey Grail , one of very best relics, lost for long time, . Very old, very powerful. Would mean a lot if could find. Set you grand quest for to search for Holey Grail ! Try start with Fishcan . He old as dirt, might know something. Seek him by pools to north-east.",objectivesText="Find the Holey Grail . Progress: Got Grail?",starts={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},ends={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},coords={x=0.668,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[80145] = {id=80145,name="The Motherlode",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="<Zee-Zee's internals begin to hum softly as their projector reaches the appropriate operating temperature.>",objectivesText="Activate the remaining crushers in the Shadowvein cave. Progress: <Zee-Zee looks up at you.>",starts={{npcID=230643,x=0.048,y=0.796,mapID=2214}},ends={{npcID=230643,x=0.048,y=0.796,mapID=2214}},coords={x=0.048,y=0.796,source="quest_giver",mapID=2214},questType="standard"},
[80175] = {id=80175,name="The Last Mage",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I want you to check in on someone. He's a mage... the only one of us who is. All the others died in the crash. He's trying to make a portal to the Empire, so we can get reinforcements and have a way to and from home. We all know it's a lost cause, but he still hasn't given up. Maybe meeting a seasoned traveler like you will give him the reality check he needs. Check on him, will you?",objectivesText="Find Wenren Althal in Beledar's Bounty.",starts={{npcID=215335,x=0.404,y=0.508,zoneID=14838}},ends={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},coords={x=0.404,y=0.508,source="quest_giver",zoneID=14838},questType="standard"},
[80176] = {id=80176,name="Arcane Trickles",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="I've almost got it! I'm making a new kind of teleportation spell to get us back home to the Empire. These crabs might just be the key. They're practically radiating arcane teleportation magic! I need more samples to study. Take this focus, it will let you see traces of the arcane. There aren't many other arcane sources around here, so any you see should lead you straight to the affected crabs!",objectivesText="Obtain 5 Arcane-Suffused Organs from Shore Crawlers near Mereldar. Progress: Have you found the crabs? They'll be near water. That focus should let you see the trails of arcane dust they leave behind.",starts={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},ends={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},coords={x=0.488,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[80177] = {id=80177,name="Arcane Experiments",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="This is it! The energy crackling from these crabs is charged with teleportation magic! I just need to extract it and adjust the formula-- I can do this, my new friend! I just need another hand. Help me test this?",objectivesText="Help Wenren with his experiments.",starts={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},ends={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},coords={x=0.488,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[80178] = {id=80178,name="A Murder Most Foul",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="<Somebody didn't want Wenren to finish his spell. Find out who.>",objectivesText="Investigate Wenren's murder. Progress: <The body is still warm.>",starts={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},ends={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},coords={x=0.486,y=0.646,source="quest_giver",zoneID=14838},questType="standard"},
[80179] = {id=80179,name="Finding Justice",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="<The pieces fit together to form a simple, but dark picture. The Order of Night did not want Wenren to create a portal back to the Empire. No doubt reinforcements and supplies would hinder their mission. So, someone stabbed him, burned his research, and smashed his tools. But with this arcane focus in hand, you can see a faint trail of arcane residue. Did some arcane dust get on the perpetrator? Follow the trail and find out.>",objectivesText="Track down Wenren's killer.",starts={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},ends={{npcID=215335,x=0.404,y=0.508,zoneID=14838}},coords={x=0.486,y=0.646,source="quest_giver",zoneID=14838},questType="standard"},
[80184] = {id=80184,name="Preserving in Battle",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="There is much to learn on the battlefield, even in lesser coordinated environments. Go ahead and give it a try.",objectivesText="Obtain Honor in Random Battlegrounds. Progress: You haven't finished quite yet.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80185] = {id=80185,name="Preserving Solo",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Battling on your own will build strength and courage. Display your solo capabilities in small battles, then return to me.",objectivesText="Complete 12 rounds of Solo Shuffle. Progress: Finish off what you set to do then return.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80186] = {id=80186,name="Preserving in War",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Partaking in large-scale conflicts will hone your ability to look at the larger picture. Go off and garner that experience, then come back to see me.",objectivesText="Obtain Honor in Epic Battlegrounds. Progress: Complete what you have set off to do.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80187] = {id=80187,name="Preserving in Skirmishes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Part of training is repetition. I am told there are others out there like yourself that partake in small-scale skirmishes. Go off and find training partners to battle against, then return to me. Let us see what you can prove, then return to me.",objectivesText="Obtain Honor from Arena Skirmishes. Progress: Practice makes perfect. Finish off the tasks then return.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80188] = {id=80188,name="Preserving in Arenas",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Fast paced and coordinated combat is a mighty test for the strongest combatants. Find others to battle alongside you to fight worthy opponents in the arena.",objectivesText="Obtain Honor in Rated Arenas while in a Party. Progress: You have not finished what you set off to do yet.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80189] = {id=80189,name="Preserving Teamwork",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="The ability to strategize with others to take objectives is key to becoming a strong warrior. Go onto the battlefield, then return to me.",objectivesText="Obtain Honor in Rated Battleground Blitz or in Rated Battlegrounds. Progress: Finish off what you set to do then come back.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80196] = {id=80196,name="Extract a Gem",level=10,requiredLevel=10,faction="none",expansion=10,description="Any gem can be removed from your equipment using the Extract Gem ability. The gem will not be destroyed. Extract a gem now.",objectivesText="Extract the Chipped Deadly Sapphire from your equipment.",questType="standard"},
[80197] = {id=80197,name="Combine Gems",level=10,requiredLevel=10,faction="none",expansion=10,description="Prismatic gems can be combined to create a more powerful gem. Combine three Deadly Chipped Sapphires to create a Flawed Deadly Sapphire that grants additional Critical Strike when socketed.",objectivesText="Use three Deadly Chipped Sapphires to combine them into a Flawed Deadly Sapphire.",questType="standard"},
[80202] = {id=80202,name="Hot Pollenate-o",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Important to make sure not take too much. Make sure hive healthy so can come back. Bees eat pollen, yes? So fire bees eat fire pollen? Yes. Bring fire pollen to bees. Grow strong. Bee productive. Check edge of hive for flowers bees not get to yet. When catch fire, you got good one.",objectivesText="Gather pollen from Pollen Rich Cinderblooms and return it to nearby bees before it goes out. Progress: Just a little bit on fire. You tough, you be okay.",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[80203] = {id=80203,name="Social Clues",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="The Weaver sent you, yes? I arrived to petition the Magistrate's approval for Ascension--to infiltrate high society, of course. But he's missing. A rather large inconvenience. I need to ask around. You're just what I've been waiting for! You may pretend to be my... servant. Pet? Whatever makes it more palatable to you. I so rarely get to work alongside a friend. We will have fun together, fellow spy.",objectivesText="Help Orator Tx'itk ask around to find the Magistrate. Progress: I have a few old friends who recently Ascended. Surely, one of them has heard something they would be willing to share. For old time's sake. And if not, maybe jealousy in seeing my fashionable new pet will inspire them to offer up what they know.",starts={{npcID=219357,x=0.714,y=0.442,zoneID=14753}},ends={{npcID=221092,x=0.656,y=0.402,zoneID=14753}},coords={x=0.714,y=0.442,source="quest_giver",zoneID=14753},questType="standard"},
[80204] = {id=80204,name="Espionage and Ventriloquism",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="The Puppetmaster is our best lead for finding the Magistrate. But is it just me, or did those puppets seem... horrifically lifelike? If this artist is behind the Magistrate's disappearance, he certainly isn't just off to see a puppet show. We should investigate the Puppetmaster's workshop. Question him, or at least ransack his things. Just a bit. Until we find something useful. You'll have to keep playing your rather undignified role in this charade. But it will pay off for us.",objectivesText="Investigate the Puppetmaster's Workshop. Progress: < Orator Tx'itk lowers her voice.> Something isn't right here. Play along just a while longer. Let's see what else we can find.",starts={{npcID=221092,x=0.656,y=0.402,zoneID=14753}},ends={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},coords={x=0.656,y=0.402,source="quest_giver",zoneID=14753},questType="standard"},
[80205] = {id=80205,name="Pulling Strings",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Just think of it! Overcrawlers, war prisoners, civilians, fellow nerubians, important nobility being kidnapped and turned into puppets right under the Magistrate's nose. It's horrific--and exactly what I needed! If we save the Magistrate from this fate, he'll owe me. Not just for saving his life, but to keep quiet about all this. We're off to the theater, then. If you can keep the Puppetmaster occupied, I'll free High Elevator Etak'kaht from his grasp. Hopefully he's not part of the show yet.",objectivesText="Confront the Puppetmaster to rescue High Elevator Etak'kaht .",starts={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},ends={{npcID=221088,x=0.714,y=0.454,zoneID=14753}},coords={x=0.656,y=0.402,source="quest_giver",zoneID=14753},questType="standard"},
[80206] = {id=80206,name="Marionette Mercy",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="It's perfect! The Puppetmaster is so interested in adding you to his collection, he literally invited us to go rescue the Magistrate. I don't want to imply I've been using you as bait this entire time, but... Let's just say certain calculated risks have paid off. Even such a skilled artist must have a way to correct potential errors. There has to be an antitoxin of sorts for that paralytic around here somewhere! Find it. And perhaps we test it before we go use it on the Magistrate. Just in case.",objectivesText="Find the Puppetmaster's Antiparalytic Serum . Progress: I would worry we're taking too long, but considering how dramatic that Puppetmaster is, I can't imagine he'll start the show without us. We should be prepared for something... rather unpleasant at that theater.",starts={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},ends={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},coords={x=0.656,y=0.402,source="quest_giver",zoneID=14753},questType="standard"},
[80207] = {id=80207,name="How Scandalous!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Did you see anything? I was just at the Forgegrounds picking up a jewelry commission and all of a sudden everyone was shouting like the Coreway was under attack--again. But it was not that... Some peacekeepers were heading towards the depot--where crafting shipments are sent up from the Deeps. I bet it's something to do with the machine speakers! The peacekeepers ushered everyone away before I could see what had happened. But maybe you can sneak a glimpse?",objectivesText="Investigate the disturbance near the Forgegrounds in Dornogal .",starts={{npcID=219393,x=0.626,y=0.218,zoneID=14771}},ends={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},coords={x=0.626,y=0.218,source="quest_giver",zoneID=14771},questType="standard"},
[80209] = {id=80209,name="An Oddball in Dornogal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="We have received reports that an eccentric Arathi is accosting our citizens. We have little experience with outsiders and my superiors are wary of a diplomatic incident. I have been tasked with finding this \"Lamplighter\" and resolving his concerns. You have worked with the Arathi before - can you assist me? I have a list of earthen who have reported the Lamplighter. You can interview half the list. Between us, we can hopefully locate the Arathi before he troubles more citizens.",objectivesText="Interview Concerned Dornogal Citizens to locate the Arathi Lamplighter.",starts={{npcID=222224,x=0.544,y=0.194,zoneID=14771}},ends={{npcID=222268,x=0.67,y=0.186,zoneID=14771}},coords={x=0.544,y=0.194,source="quest_giver",zoneID=14771},questType="standard"},
[80210] = {id=80210,name="Found Around the Unbound",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2339,description="This Lamplighter is looking for his fellow Arathi. The foreman says he directed an Arathi shipwright to Freywold Village. My superiors insist that Peacekeepers do not leave Dornogal... but per their orders, I must assist Kaerter. And to do that, I have no choice but to leave the city. It is decided then. If you are willing, please meet us at Freywold Village. Your continued aid would be appreciated.",objectivesText="Meet Peacekeeper Leif outside Freywold Village.",starts={{npcID=222268,x=0.67,y=0.186,zoneID=14771}},ends={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},coords={x=0.67,y=0.186,source="quest_giver",zoneID=14771},questType="standard"},
[80211] = {id=80211,name="The Pillage of Freywold Village",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The Arathi shipwright was here but has moved on with most of her entourage. She had left a few Arathi behind but... Soon after the shipwright left, earthen started disappearing. The villagers suspected the Arathi but had no proof. Then one day, the remaining Arathi left town in the middle of the night. The locals said the Arathi stayed at the inn. Can you look there for any clues as to where the Arathi are now? Given the villagers' hostility, the Lamplighter and I shall remain here for the moment.",objectivesText="Search for clues as to where the Arathi went. Progress: I am attempting to convince the villagers that the Lamplighter is not involved in these disappearances. Did you find anything useful?",starts={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},ends={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},coords={x=0.426,y=0.71,source="quest_giver",zoneID=14717},questType="standard"},
[80212] = {id=80212,name="The Abductors' Obstructors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The Order of Night is clearly interested in our resources. They have abducted earthen to harvest for them and may continue taking others. We must stop them. The next largest earthen settlement is Rambleshire. If the Order needs more workers, they might have gone there to get them. Go on ahead . I must first speak with Kaerter about why the Arathi are doing this.",objectivesText="Meet Peacekeeper Leif at Rambleshire.",starts={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},ends={{npcID=222353,x=0.574,y=0.3,zoneID=14717}},coords={x=0.426,y=0.71,source="quest_giver",zoneID=14717},questType="standard"},
[80213] = {id=80213,name="Holy Fire in Rambleshire",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="I'm certain there are still Order folks sneaking around here. Now they might be carrying messages on them, just like the clues you found in Freywold. You and I are gonna find out. Here, take these thuribles. They might look like tiny incense burners, but I've enchanted them with Sacred Flame. Just throw one down and you'll get a big bang with a bright flash! Should be enough to stun anyone sneaking around. Just don't throw one at me! Got it?",objectivesText="Use Flashfire Thuribles to reveal Order of Night forces in Rambleshire, eliminate them, and search them for clues. Progress: Alright, I'll admit it, the little Pebble is pretty useful. He knows more about the earthen and the surface than I ever will. Anyway, did you find anything?",starts={{npcID=222352,x=0.574,y=0.3,zoneID=14717}},ends={{npcID=222356,x=0.62,y=0.306,zoneID=14717}},coords={x=0.574,y=0.3,source="quest_giver",zoneID=14717},questType="standard"},
[80214] = {id=80214,name="A Time to Kill at the Lumber Mill",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Alright, let me see if I get all of this. The shipwright brings an entourage up here to get lumber for airships. But the shipwright is actually Order of Night, along with most of her group. So they murder the loyal Arathi, kidnap earthen, and force them to run the lumber mill up here. And now we gotta deal with the Order AND whoever their new friends are. C'mon, let's head to the mill. We got a lot of bad guys to kill and time's wastin'.",objectivesText="Meet Lamplighter Kaerter outside of Skolzgal Mill.",starts={{npcID=222356,x=0.62,y=0.306,zoneID=14717}},ends={{npcID=222360,x=0.67,y=0.312,zoneID=14717}},coords={x=0.62,y=0.306,source="quest_giver",zoneID=14717},questType="standard"},
[80215] = {id=80215,name="Ungirthin' the Earthen",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="While I do enjoy beating the black blood out of nerubians, we must save the earthen prisoners first. I saw they're being held by Arathi ball and chain. Someone like you should be able to shatter them pretty quick. Just... do that thing you do! Oh, and we should split up to cover more ground. Yeah Leif's gonna complain, but he's always complaining anyway.",objectivesText="Free 8 Abducted Lumberjacks.",starts={{npcID=222360,x=0.67,y=0.312,zoneID=14717}},ends={{npcID=222360,x=0.67,y=0.312,zoneID=14717},{npcID=222362,x=0.658,y=0.246,zoneID=14717}},coords={x=0.67,y=0.312,source="quest_giver",zoneID=14717},questType="standard"},
[80216] = {id=80216,name="Concealed in the Weald",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The nerubians seem to be in league with the Arathi. Many of them are guarding the mill, but I am sure there are more than we can see. We cannot allow such a large enemy force to operate unimpeded this close to Rambleshire. The nerubians attacked and destroyed large sections of Dornogal not too long ago. The Order of Night Arathi are abducting and enslaving our people. We must eliminate as many of them as we can. Preferably all of them.",objectivesText="Eliminate Shadowsilk forces at the Skolzgal Mill. Progress: The more enemies we eliminate, the safer we will all be.",starts={{npcID=222358,x=0.67,y=0.312,zoneID=14717}},ends={{npcID=222362,x=0.658,y=0.246,zoneID=14717}},coords={x=0.67,y=0.312,source="quest_giver",zoneID=14717},questType="standard"},
[80217] = {id=80217,name="A Lamplight for the Shipwright",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="Where is Kaerter now? Did he go off on his own again? We've rescued the earthen and eliminated many hostile forces, but our task is not yet complete. Shortly before you arrived, we spotted a group of Arathi traveling up this hill. One of them was identified as the Arathi shipwright. The shipwright is the leader here. Losing her will cripple their efforts to utilize the mill. Head up the hill and find her before she can escape.",objectivesText="Confront the Arathi shipwright.",starts={{npcID=222362,x=0.658,y=0.246,zoneID=14717}},ends={{npcID=222363,x=0.66,y=0.238,zoneID=14717}},coords={x=0.658,y=0.246,source="quest_giver",zoneID=14717},questType="standard"},
[80218] = {id=80218,name="Up to No Good Down in Silkwood",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,mapID=2248,description="The Order is moving the wood through the nerubians. Leif said he saw the shipwright leave the cave and head down to the beach. The nerubian tunnel must be down there. You're going to have to seal that Flameforsaken passage. While slinking around, I noticed the Order brought explosive barrels with them. Find a few and use them to blow the tunnel. Get going . I'll be right behind you.",objectivesText="Collect Silkwood Explosive Barrels, then destroy the nerubian tunnel at Silkwood Grotto. Progress: Did you take out the tunnel?",starts={{npcID=222364,x=0.66,y=0.238,zoneID=14717}},ends={{npcID=222365,x=0.654,y=0.204,zoneID=14717}},coords={x=0.66,y=0.238,source="quest_giver",zoneID=14717},questType="standard"},
[80219] = {id=80219,name="Dornogal Drift",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,objectivesText="Glide through the rings.",starts={{x=0.435,y=0.117,mapID=2339,npcID=219542}},ends={{x=0.435,y=0.117,mapID=2339,npcID=219542}},coords={mapID=2339,x=0.435,y=0.117},questType="standard"},
