[82335] = {id=82335,name="Crystals",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=213145,x=0.412,y=0.53,mapID=2215}},ends={{npcID=213145,x=0.412,y=0.53,mapID=2215}},coords={x=0.412,y=0.53,source="quest_giver",mapID=2215},questType="standard"},
[82338] = {id=82338,name="Absent Errand",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2255,description="Do you remember the logbook you discovered in Zev'kall's office? It contained critical information about Zev'kall's misuse of our people. I gave it to my assistant, Anub'okki, to bring to the historians in the Skeins. But I have not heard back from Anub'okki. I suspect foul play. See if anyone in the Skeins will admit to having seen him!",objectivesText="Seek out Anub'azal 's student in the Skeins of Nerub'ar.",starts={{npcID=223765,x=0.474,y=0.228,zoneID=14752},{npcID=224345,x=0.55,y=0.412,zoneID=14752}},ends={{npcID=223760,x=0.41,y=0.334,zoneID=14753}},coords={x=0.474,y=0.228,source="quest_giver",zoneID=14752},questType="standard"},
[82339] = {id=82339,name="An Honorless Kill",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2213,description="If it will get you out of here sooner, I will tell you what I saw. I did not see what happened to Anub'okki. But I can tell you that corpses are dumped into Pillar-nest Xesh to be forgotten about. The cleanup crew dragged Anub'okki out of here not long ago. If you hurry, you may be able to examine the remains before they are gone.",objectivesText="Recover the logbook and discover what happened to Anub'okki. Progress: Did you find Anub'okki?",starts={{npcID=223760,x=0.41,y=0.334,zoneID=14753}},ends={{npcID=224345,x=0.55,y=0.412,zoneID=14752}},coords={x=0.41,y=0.334,source="quest_giver",zoneID=14753},questType="standard"},
[82340] = {id=82340,name="Loss of Limb",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Happy greetings! I am Mr. Sunflower , and this is my tea room and therapy space. It is a safe place for everyone! I wonder if you might be willing to help a patient of mine. Vi'azl is deathly afraid of creatures with fewer limbs. I think it has grown into a deep phobia of dismemberment. I'm trying to get to the bottom of this diagnosis. Would you speak to him, and demonstrate that you, who do not have eight limbs, are not so terrifying after all?",objectivesText="Assist Mr. Sunflower in Vi'azl 's therapy session. Progress: Vi'azl must have some terrible trauma related to creatures with fewer limbs. We must help him.",starts={{x=0.633,y=0.374,mapID=2216,npcID=223723}},ends={{x=0.633,y=0.374,mapID=2216,npcID=223723}},coords={mapID=2216,x=0.633,y=0.374},questType="standard"},
