[84582] = {id=84582,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14752,mapID=2255,starts={{npcID=464929,x=0.568,y=0.391,mapID=2255}},ends={{npcID=464929,x=0.568,y=0.391,mapID=2255}},coords={x=0.568,y=0.391,source="quest_giver",mapID=2255},questType="standard"},
[84583] = {id=84583,name="A Hozen On My Back",level=10,requiredLevel=30,faction="both",expansion=10,zoneID=440,mapID=71,description="Hello, . I don't suppose I could trouble you again? A strange couple has been causing trouble near the edge of the petting area. Perhaps you could convince the hozen to stop shouting at our guests.",objectivesText="Confront the boisterous hozen.",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440}},ends={{npcID=229749,x=0.618,y=0.504,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[84588] = {id=84588,name="Operation Toy Rescue",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=440,mapID=71,description="Nooo! A sneaky thief has taken some of my friends' toys! You're a good sleufer now, right? Can you halp my friend Yennu find his stolen toy? You'll find him on the Dragon Isles.",objectivesText="Find the missing toys. Progress: Did you find da toys?",starts={{npcID=226684,x=0.632,y=0.524,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=440},questType="standard"},
[84595] = {id=84595,name="The Case of the Fur-Getting Wikket",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Riko has had enough of these blikkety tik-digglers! All Kiryn wants is to be a furry-haver, and these mankers won't give any! Kiryn says Riko needs to stop jabberings. Says taking their furries is \"stealing.\" You a helpful wikket? Find Kiryn a furry friend! Better take notes so wikket don't get stuck.",objectivesText="Find a companion pet for Riko and Kiryn. Progress: If wikket can't find a furry, Riko will have to be a stickypaw.",starts={{npcID=229749,x=0.618,y=0.504,zoneID=440}},ends={{npcID=229749,x=0.618,y=0.504,zoneID=440}},coords={x=0.618,y=0.504,source="quest_giver",zoneID=440},questType="standard"},
[84616] = {id=84616,name="Celebrate Good Fun!",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15913,mapID=71,description="Welcome to the Bronze Celebration! We invite you to enjoy our myriad of events. You might choose to mirror your pet and run around our playground. You could participate in one of our big events like Fashion Frenzy or Mount Mania. A different event begins every 15 minutes. Or you might fancy yourself a challenge. If so seek out Chromie as she cleans up her Codex to prepare for her tours. Any event will do, as long as you are having fun!",objectivesText="Participate in activities around the celebration and tasks put forward by those visiting. Progress: Are you enjoying our fine celebration?",starts={{npcID=223877,x=0.628,y=0.506,zoneID=440}},ends={{npcID=223877,x=0.628,y=0.506,zoneID=440}},coords={x=0.628,y=0.506,source="quest_giver",zoneID=440},questType="standard"},
[84619] = {id=84619,name="Ooker Dooker Literature Club",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="The hozen in the Bilge Rat crew are master scavengers. For years, they've been visiting this island, snatching up anything that might be of value. Among their spoils are many research materials that could help unlock the history of this place. Infiltrate their camp, board their ships, and recover whatever books, scrolls, and documents you can find.",objectivesText="Acquire various writing from the Bilge Rat ships and landing area. Progress: Did you find anything worth reading?",starts={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},ends={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},coords={x=0.708,y=0.398,source="quest_giver",zoneID=10416},questType="standard"},
[84621] = {id=84621,name="Squire's Spurs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="You come to Campalot to pledge fealty? Become Knight of the Brown Table? Not have look of tenderfoot, but even bravest knight start as squire. Earn spurs. Learn humility. Prove you have learned it in same way. See what can do to help around castle. Might be good example to other squires, too.",objectivesText="Help out around Campalot. Progress: Hmm, think missed spot.",starts={{npcID=218864,x=0.668,y=0.786,zoneID=14795}},ends={{npcID=218864,x=0.668,y=0.786,zoneID=14795}},coords={x=0.668,y=0.786,source="quest_giver",zoneID=14795},questType="standard"},
[84624] = {id=84624,name="Sandy Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Alyx would appreciate the supplies returned.>",objectivesText="Return the Sandy Celebration Crate to Alyx . Progress: Yes?",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},coords={mapID=71,source="quest_giver",x=0.63,y=0.502},questType="standard"},
[84625] = {id=84625,name="Surprisingly Pristine Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Alyx would appreciate the supplies returned.>",objectivesText="Return the Surprisingly Pristine Celebration Crate to Alyx . Progress: Yes?",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},coords={mapID=71,source="quest_giver",x=0.63,y=0.502},questType="standard"},
[84627] = {id=84627,name="Three Heads of the Deep",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="The reach of these creatures is truly frightening! I have encountered them countless times in the Imperial waters. I know their strategies well, and I have a plan to deal with them. My scouts have pinpointed the location of three of their leaders. Eliminate them, and we'll seize the advantage.",objectivesText="Eliminate Warlord Thresh , Extractor Silsai, and Nereu of the Silent Wave Progress: Have you eliminated their leaders?",starts={{npcID=227796,x=0.694,y=0.428,zoneID=10416}},ends={{npcID=227796,x=0.694,y=0.428,zoneID=10416}},coords={x=0.694,y=0.428,source="quest_giver",zoneID=10416},questType="standard"},
[84638] = {id=84638,name="Trouble in the Highlands",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=2339,description="Both Geya'rah and Danath have received word of unrest in the Arathi Highlands--civil unrest in Stromgarde, and raids on Mag'har and Stromic outposts. Danath and Geya'rah are returning to their homes, Stromgarde and Hammerfall, to defuse tensions. I asked to accompany them. I have long wanted to reconnect myself and my people to the Arathi. I also want to learn more about the Horde. Geya'rah was willing, but... Danath took some convincing. Though, I may have implied you were joining me...",objectivesText="Travel to the Arathi Highlands via the portal in Dornogal.",starts={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},ends={{npcID=234662,x=0.204,y=0.392,zoneID=15716}},coords={x=0.46,y=0.494,source="quest_giver",zoneID=14771},questType="standard"},
[84639] = {id=84639,name="Torches and Tar",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="We've been attacked before. But this time... This was different. They didn't want livestock, grain, or money. They took torches and some barrels of tar we use to fix our roofs. I don't know what they're going to do with it, but... I can guess. They're going to burn something down. You need to stop them before they do another homestead harm!",objectivesText="Retrieve 10 Stolen Torches from Defias bandits and 10 Barrels of Tar from Newstead Farm. Progress: I hope whatever they're planning doesn't involve my neighbors. Or Stromgarde!",starts={{x=0.205,y=0.393,mapID=2372,npcID=230174}},ends={{x=0.205,y=0.393,mapID=2372,npcID=230174}},coords={mapID=2372,x=0.205,y=0.393},questType="standard"},
[84640] = {id=84640,name="Emblematic of Things to Come",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="unfamiliar emblem . The emblem looks like a rising sun with long rays emanating from it. The sun and rays are colored red. Perhaps Danath can identify it.>",objectivesText="Bring the Unfamiliar Emblem to Danath Trollbane at Newstead Farm. Provided item:",questType="standard"},
[84641] = {id=84641,name="Ill Tidings",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="A Defias attack. The theft of tar and torches. A group called the Red Dawn recruiting here in the heart of the Highlands... Stromgarde was right to send a missive asking for my return. What is going on here? I placed Colonel Nials in charge after Marran's foolishness led to her imprisonment. I must head to Stromgarde and speak with Nials immediately.",objectivesText="Meet Danath Trollbane at the gates of Stromgarde Keep.",starts={{x=0.204,y=0.392,mapID=2372,npcID=234662}},ends={{x=0.204,y=0.392,mapID=2372,npcID=234662}},coords={mapID=2372,x=0.204,y=0.392},questType="standard"},
[84643] = {id=84643,name="Curfew Kerfuffle",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="I'm glad for your help. Between deployments to Khaz Algar, responding to threats in the Highlands, and desertion, we simply don't have enough soldiers to enforce order. Marran's supporters are causing trouble throughout the city. They're stealing supplies, harassing people--you name it. We've enacted a curfew, but Marran's supporters are openly defying it. As my deputies, go around and tell the troublemakers to go home. If they get rowdy, you have my permission to teach them a lesson.",objectivesText="Deal with 15 Marran Supporters in Stromgarde. Progress: I understand that curfews are unpopular, but we really need one right now.",starts={{x=0.193,y=0.563,mapID=2372,npcID=235041}},ends={{x=0.193,y=0.563,mapID=2372,npcID=235041}},coords={mapID=2372,x=0.193,y=0.563},questType="standard"},
[84645] = {id=84645,name="Deputy Delivery",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Trade in Stromgarde has broken down. We're short on goods and workers because of the attacks. Nials was too busy, so I took it upon myself to write official requests for aid. Most are simple and straightforward--writs for supplies and such for the Stromic army. The desist writ for Joseph is different. He is loudly blaming everyone not human for our woes. Someone needs to officially tell him to shut his yap before he starts a riot. As my deputies, would you enforce my requests for aid?",objectivesText="Deliver Brewston's request writs to people in Stromgarde. Progress: I know some won't be happy with what we're requesting of them, but it's what's best for Stromgarde and its people.",starts={{x=0.193,y=0.563,mapID=2372,npcID=235041}},ends={{x=0.193,y=0.563,mapID=2372,npcID=235041}},coords={mapID=2372,x=0.193,y=0.563},questType="standard"},
[84649] = {id=84649,name="Marran Trollbane",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="I am Colonel Veronica Nials , and I am in command of Stromgarde in Lord Trollbane's absence. I'm sure while aiding our people you've heard the name \"Marran\" in Stromgarde. Lady Marran Trollbane is Danath's niece. She was briefly regent while Lord Danath Trollbane campaigned for troops for Khaz Algar. Her actions during his absence led him to imprison her when he returned. That said, Lord Trollbane felt Faerin should speak to her. Perhaps to get... perspective. I can take you to her if you wish.",objectivesText="Observe the meeting between Faerin Lothar and Marran Trollbane in the barracks of Stromgarde Keep.",starts={{x=0.175,y=0.595,mapID=2372,npcID=229940}},ends={{x=0.175,y=0.595,mapID=2372,npcID=229940}},coords={mapID=2372,x=0.175,y=0.595},questType="standard"},
[84650] = {id=84650,name="Finding Refuge at Refuge Pointe",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="If you want to find Lord Trollbane and tell him your theory about Lady Marran, the missive called him to Hammerfall, far to the east of here. He may have stopped at Refuge Pointe on the way--it's a Stromic encampment about halfway to the orc town. Because of the frequent bandit attacks in the area, I believe he meant to stop and check in with our people there. You might catch up with him there.",objectivesText="Look for Danath at Refuge Pointe in the Arathi Highlands . Progress: It's good to see humans and orcs banding together to help one another. If only the Arathi here could have seen what I did at Khaz Algar.",starts={{x=0.175,y=0.595,mapID=2372,npcID=229940}},ends={{x=0.175,y=0.595,mapID=2372,npcID=229940}},coords={mapID=2372,x=0.175,y=0.595},questType="standard"},
[84651] = {id=84651,name="A Familiar Face",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Early on, these attacks on our settlements seemed to be pockets of bandits competing for resources. Now they are better coordinated. As if they are working together as a group. That's bad news for everyone. But rivals don't come together without a strong leader. And without them, they will fall. If you're willing, find the leader of this attack on Refuge Pointe and eliminate them.",objectivesText="Defeat the leader of the attack on Refuge Pointe. Progress: Go. I will protect these people until your return.",starts={{x=0.409,y=0.535,mapID=2372,npcID=236815}},ends={{x=0.409,y=0.535,mapID=2372,npcID=236815}},coords={mapID=2372,x=0.409,y=0.535},questType="standard"},
[84652] = {id=84652,name="Supply Run",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Stromgarde's troops are in Khaz Algar and it cannot protect its outlying settlements. Hammerfall does what it can to help, but we too fight in Khaz Algar. We've taken many injured Stromic refugees to Hammerfall, but feeding them all has strained our resources. But there may be a way to help more people. Vikki told me Refuge Pointe is a supply depot for nearby settlements. If we can get our hands on some supplies, we can care for more refugees in Hammerfall.",objectivesText="Collect 4 Supply Crates from Refuge Pointe.",starts={{x=0.409,y=0.535,mapID=2372,npcID=236815}},ends={{x=0.409,y=0.535,mapID=2372,npcID=236815}},coords={mapID=2372,x=0.409,y=0.535},questType="standard"},
[84653] = {id=84653,name="DEPRECATED",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15716,mapID=14,description="<You find another one of the strange rings. This time from a Scarlet Crusade member.> <You should talk to Faerin about it. This is getting suspicious.>",objectivesText="Bring the Scarlet Ring to Faerin in the Arathi Highlands .",questType="standard"},
[84656] = {id=84656,name="Onward to Hammerfall",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15716,mapID=14,description="First an attack on Newstead Farm by Defias, now an attack on Refuge Pointe by these Scarlet Crusaders. Different groups of bandits, but both speak of this \"Red Dawn\" and carry the same emblem. Also, Joseph is directly involved. This all seems connected... and it leads back to Marran. Danath needs to know what's going on. If he's not here, he should already be at Hammerfall. We should head there as soon as possible.",objectivesText="Meet Faerin Lothar at Hammerfall in the Arathi Highlands .",starts={{x=0.408,y=0.535,mapID=2372,npcID=230815}},ends={{x=0.408,y=0.535,mapID=2372,npcID=230815}},coords={mapID=2372,x=0.408,y=0.535},questType="standard"},
[84657] = {id=84657,name="Return to Stromgarde",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Eitrigg was right. The Red Dawn are trying to start a conflict between the Horde and the Alliance. We need to get back to Stromgarde and tell Colonel Nials that Danath has been kidnapped. She will surely commit all her resources to a search! Come, . There's no time to waste!",objectivesText="Return to Stromgarde and enlist Colonel Nials's aid in finding Danath.",starts={{x=0.415,y=0.614,mapID=2372,npcID=231828}},ends={{x=0.415,y=0.614,mapID=2372,npcID=231828}},coords={mapID=2372,x=0.415,y=0.614},questType="standard"},
[84658] = {id=84658,name="Finding Family",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Where's my mama? My papa? Ellie ? I was followin' Mr. Gresham and Clarabelle when we saw the bandits. He grabbed me up and we ran here. I don't know where Mama and Papa and Ellie are. Can you find them for us? Clarabelle is starting to get worried...",objectivesText="Discover the fates of Marshall Wiltshire, Sharon Wiltshire, and Ellie at Newstead Farm. Progress: Ellie must be so scared!",starts={{x=0.205,y=0.396,mapID=2372,npcID=231748}},ends={{x=0.205,y=0.396,mapID=2372,npcID=231748}},coords={mapID=2372,x=0.205,y=0.396},questType="standard"},
[84659] = {id=84659,name="The Search for Faerin",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="I saw Faerin being taken away, but couldn't follow without them seeing me. She's probably being held in another building. Go find her. Hopefully, she's still alive... And see if you can find any more information on the Red Dawn. There's no way we should have been overwhelmed so quickly. Colonel Nials and Lady Trollbane must have installed their cronies everywhere. The more information we have, the more we can use against them when we fight back.",objectivesText="Search the structures in Stromgarde for Faerin and information on the Red Dawn. Progress: Have you found Faerin?",starts={{x=0.177,y=0.603,mapID=2372,npcID=238012}},ends={{x=0.177,y=0.603,mapID=2372,npcID=238012}},coords={mapID=2372,x=0.177,y=0.603},questType="standard"},
[84664] = {id=84664,name="Making the Underworld Go Round",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Hey there, 'Overcrawler.' You're lookin' more than a little out of your element there. You get run over by an airship or something? Whatever. Doesn't matter. Take it from one outsider to another, if you're going to survive down here you're gonna need to learn the rules of the road. Gold's all well and good where you came from, but down here you're gonna need Kej, and lots of it. Now here. Consider this a token of good will from Lady Pedipalps up there. Go get yourself something nice.",objectivesText="Spend Kej at one of the vendors in the Weaver's Lair. Progress: What, you allergic to retail therapy or something? Get out there and live a little!",starts={{npcID=223754,x=0.558,y=0.436,zoneID=14752}},ends={{npcID=223754,x=0.558,y=0.436,zoneID=14752}},coords={x=0.558,y=0.436,source="quest_giver",zoneID=14752},questType="standard"},
[84667] = {id=84667,name="The G.O.L.E.M. of Progress",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="The citizens of Undermine cry out for help! They need protection! They need joy! They need to get by! As an inventor, I've spent my life building somethin' that'll solve our people's problems, and it's just about ready for a test run. I'm calling it my Goblin Optimal Livability Enhancement Machine, or G.O.L.E.M. for short! Find some problems and take it out for a spin- and take my son with you! Pitz doesn't have an inventor's bone in his body, but certainly he can yak it up with the neighbors.",objectivesText="Tour the Vatworks with the G.O.L.E.M. and solve problems for Gart Pocketz, \"Cranky\" Nan, and the children of Undermine . Progress: Pops is really over the moon about this G.O.L.E.M. thing. I hope it works out for him.",starts={{npcID=230554,x=0.274,y=0.622,zoneID=15347}},ends={{npcID=231517,x=0.37,y=0.53,zoneID=15347}},coords={x=0.274,y=0.622,source="quest_giver",zoneID=15347},questType="standard"},
[84672] = {id=84672,name="Garbage Day",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="My old man's got all these crazy ideas about helping the world... I dunno. It's all a bit over my head, but I guess that's why I was never the inventor he wanted me to be. Still, I've got some thoughts on how to solve problems around here. Like those dang rodents getting litter all over the streets! It might not revitalize the spirit of the community or whatever, but I bet people would be happier if we cleaned up the streets.",objectivesText="Collect 12 pieces of litter and use the G.O.L.E.M.'s incinerator function to dispose of them. Progress: Toxic fumes? Nah, that's just what Undermine smells like!",starts={{npcID=230555,x=0.276,y=0.62,zoneID=15347}},ends={{npcID=231517,x=0.37,y=0.53,zoneID=15347}},coords={x=0.276,y=0.62,source="quest_giver",zoneID=15347},questType="standard"},
[84673] = {id=84673,name="World's Okayest Inventor",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="I'm... not the inventor my old man is. Or much of an inventor at all, really. My masterwork is over by the wall there, but to be honest, there's a lot of work that still needs to be done to get it to do... anything. But this! This could be my big chance to prove to Pops that I've got what it takes to make him proud! All we need to do is actually, uh, figure out how to repair this thing. How hard could it be?",objectivesText="Help Pitz repair the G.O.L.E.M. Progress: Is it... working?",starts={{npcID=231517,x=0.37,y=0.53,zoneID=15347}},ends={{npcID=231517,x=0.37,y=0.53,zoneID=15347}},coords={x=0.37,y=0.53,source="quest_giver",zoneID=15347},questType="standard"},
[84674] = {id=84674,name="The G.O.L.E.M. Goes Berserk!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="The G.O.L.E.M.'s gone berserk! Haywire! Bonkers! I gotta go chase it down--who knows what kinda trouble an invention that powerful could cause! Plus, imagine how mad my old man would be if we lost it! I hate to ask you to clean up my messes, but someone's gotta hang back and get everything in order again. Could you do that?",objectivesText="Calm the chaos caused by the G.O.L.E.M. Progress: Pitz! Has anyone seen Pitz?",starts={{npcID=231517,x=0.37,y=0.53,zoneID=15347}},ends={{npcID=232180,x=0.398,y=0.614,zoneID=15347}},coords={x=0.37,y=0.53,source="quest_giver",zoneID=15347},questType="standard"},
[84675] = {id=84675,name="Showdown in the Attic",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="I've been so blind! Everything's falling apart! The neighborhood is worse off than ever, and the G.O.L.E.M.'s to blame! And my boy, my dear Pitz... He ran into this building to try and stop the contraption. I was so hard on him, and now I might never see him again... You gotta find him. And stop that thing once and for all.",objectivesText="Rescue Pitz and destroy the G.O.L.E.M. Progress: My hubris... that's the first thing they tell you in inventor school! Why didn't I listen!",starts={{npcID=232180,x=0.398,y=0.614,zoneID=15347}},ends={{npcID=232180,x=0.398,y=0.614,zoneID=15347}},coords={x=0.398,y=0.614,source="quest_giver",zoneID=15347},questType="standard"},
[84683] = {id=84683,name="Into the Gutter",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="What're you doing here? Sabotagin'? I can understand that. Things are way out of hand. But if we explode this pipe here, it'll get even worse. Black Blood everywhere. Maybe together we could come up with somethin' real to do. Meet me in Gutterville. We'll talk more, away from these awful slimes!",objectivesText="Meet Pamsy in Gutterville.",starts={{npcID=225591,x=0.696,y=0.84,zoneID=14795}},ends={{npcID=225772,x=0.714,y=0.836,zoneID=14795}},coords={x=0.696,y=0.84,source="quest_giver",zoneID=14795},questType="standard"},
[84684] = {id=84684,name="Ratts' Race",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14752,mapID=2339,description="I saw a vulpera acting very suspicious. She seemed... on edge. I think I saw a knife at her side and a look of dark magic in her eyes. She noticed me staring and immediately fled. Is she a wanted criminal? She... dropped this. Here.",objectivesText="Track down Ratts. Progress: <Ratts seems to have dropped this gem in her haste.>",starts={{npcID=230042,x=0.55,y=0.288,zoneID=14771}},ends={{npcID=466128,x=0.561,y=0.18,zoneID=14752}},coords={x=0.55,y=0.288,source="quest_giver",zoneID=14771},questType="standard"},
[84693] = {id=84693,name="Weaver's Lair Profession Table",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="Present this token to Ak'itaz in the Weaver's Lair to have your own personal profession table constructed.",objectivesText="Speak with Ak'itaz in the Weaver's Lair. Provided item:",ends={{npcID=230202,x=0.566,y=0.46,zoneID=14752}},coords={mapID=2255,source="quest_giver",x=0.566,y=0.46},questType="standard"},
[84700] = {id=84700,name="Pacts Below",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2339,description="This weave-rat carries a note upon its body. It's addressed to you, from the Widow Arak'nai . \"Dearest morsel, Myself and the other members of our Severed Threads triumvirate request your presence. Azj-Kahet itself is on the precipice of an evolution, but we'll need your... unique methods if we're to see it through. And, as always, the rewards to you and your cause will be quite magnificent.\"",objectivesText="Go to the Widow Arak'nai in the Weaver's Lair.",starts={{npcID=230098,x=0.462,y=0.5,zoneID=14771}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.462,y=0.5,source="quest_giver",zoneID=14771},questType="standard"},
[84701] = {id=84701,name="The Speaker",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="So there is someone else who has experienced something close to what I experienced. Yet it is not the same. I must speak with him.",objectivesText="Speak to Magni in Dornogal .",starts={{npcID=227499,x=0.422,y=0.272,zoneID=14771}},ends={{npcID=227503,x=0.356,y=0.816,zoneID=14771}},coords={x=0.422,y=0.272,source="quest_giver",zoneID=14771},questType="standard"},
[84704] = {id=84704,name="A Different Point of View",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Danath is not here. Faerin says he journeyed to Hammerfall because we requested a meeting. I sent no such message to him nor anyone else. I will dispatch outriders immediately to search for him. While we wait for their return... You and Karga's quick thinking may have saved our human refugees. We had just run out of food to give them. Distribute the crates directly to them. I'm sure they will be grateful for the food inside.",objectivesText="Place 4 Supply Crates next to Arathi Refugees taking shelter in Hammerfall.",starts={{x=0.697,y=0.392,mapID=2372,npcID=230145}},ends={{x=0.697,y=0.392,mapID=2372,npcID=230145}},coords={mapID=2372,x=0.697,y=0.392},questType="standard"},
[84705] = {id=84705,name="Withering the Witherbark",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="The Witherbark have always been an annoyance since I have been here. But now? Something has stoked their ire. They are attacking human settlements. Perhaps the Red Dawn is again to blame. Eitrigg has ordered us to try to help the humans they attack. We have stepped up our patrols and welcomed refugees. But we need someone to go to their village and bloody the Witherbark's noses. They're overconfident. They think they can get away with attacking our outriders! Make them think twice about that.",objectivesText="Slay 15 Witherbark trolls at Witherbark Village.",starts={{x=0.544,y=0.632,mapID=2372,npcID=230151}},ends={{x=0.544,y=0.632,mapID=2372,npcID=230151}},coords={mapID=2372,x=0.544,y=0.632},questType="standard"},
[84706] = {id=84706,name="Crime Family",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This Syndicate human came to us hoping to trade information for a rescue mission. The Syndicate is a recent thorn in our side, so I had half a mind to cut him down where he stood. But he claims to have vital information, and with this news of Danath's disappearance... it might be worth the risk to do as he asks. He has three brothers being held captive inside Witherbark Village. Go in, find them, and if they're alive, extract them.",objectivesText="Save Crestor, Holt, and Perry from the Witherbark trolls in Witherbark Village. Progress: You'd better move quickly. Witherbark don't keep prisoners for long.",starts={{x=0.544,y=0.632,mapID=2372,npcID=230151}},ends={{x=0.544,y=0.632,mapID=2372,npcID=230151}},coords={mapID=2372,x=0.544,y=0.632},questType="standard"},
[84707] = {id=84707,name="To See a Troll",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="There's no word from the outriders yet, but Eitrigg has not told Geya'rah of Danath's disappearance. I have told him we would go and give her the news. She's at Go'Shek Farm dealing with a Witherbark troll attack. Eitrigg says they've become increasingly aggressive recently. I can't help but think of the history there--of the Troll Wars and Arathi battles. But I admit I see them differently now after learning more about the Horde. Let's go. We can look for Danath while we're out there.",objectivesText="Meet Overlord Geya'rah at Go'Shek Farm.",starts={{x=0.695,y=0.328,mapID=2372,npcID=231764}},ends={{x=0.695,y=0.328,mapID=2372,npcID=231764}},coords={mapID=2372,x=0.695,y=0.328},questType="standard"},
[84708] = {id=84708,name="The Syndicate Strikes Back",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This human is claiming the Syndicate scum are going to attack Hammerfall! Another day I would not be concerned. But with the outriders dealing with the Witherbark and searching for Danath, Hammerfall is undefended! Let's go . We must defend our home!",objectivesText="Meet Overlord Geya'rah at Hammerfall.",starts={{x=0.544,y=0.632,mapID=2372,npcID=230151}},ends={{x=0.544,y=0.632,mapID=2372,npcID=230151}},coords={mapID=2372,x=0.544,y=0.632},questType="standard"},
[84709] = {id=84709,name="Hammerfall Down",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Eitrigg growls in frustration.> I was such a fool! I should not have sent away those outriders. Without them, the Syndicate have overrun Hammerfall. And were it not for my fool heart... The \"refugees\" turned out to be Syndicate spies, curse their greasy hides... But now you're here. Now, we can force the Syndicate out. Eliminate their soldiers and save any trapped civilians. Those spies have had enough of my open hand. Now they'll suffer my fists!",objectivesText="Eliminate Syndicate soldiers and save trapped civilians in Hammerfall. Progress: The Syndicate... I haven't seen them in this number in many years.",starts={{x=0.697,y=0.409,mapID=2372,npcID=231770}},ends={{x=0.697,y=0.409,mapID=2372,npcID=231770}},coords={mapID=2372,x=0.697,y=0.409},questType="standard"},
[84710] = {id=84710,name="Once Bitten Twice Shy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15716,mapID=14,description="I caught a glimpse of who was leading the attack. It looks like Joseph the Enlightened may be less full of hot air than we thought he was. Is he now part of the Syndicate? I thought he was part of the \"Crusade.\" I suppose it doesn't matter. If we want to stop the attack, we'll have to take him out.",objectivesText="Defeat Joseph the Enlightened in Hammerfall. Progress: I fully expect him to run away again like the coward he is.",starts={{x=0.698,y=0.41,mapID=2372,npcID=231771}},ends={{x=0.698,y=0.41,mapID=2372,npcID=231771}},coords={mapID=2372,x=0.698,y=0.41},questType="standard"},
[84711] = {id=84711,name="Danath's Disappearance",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="My outriders discovered a destroyed caravan on the road. Around it were the bodies of Stromic soldiers. It could be Danath's escort. Or it could be another hapless group. Either way, we must investigate. Let us hope Danath is not among the dead.",objectivesText="Meet Overlord Geya'rah at the Arathi Highlands crossroads.",starts={{x=0.684,y=0.306,mapID=2372,npcID=231803}},ends={{x=0.684,y=0.306,mapID=2372,npcID=231803}},coords={mapID=2372,x=0.684,y=0.306},questType="standard"},
[84712] = {id=84712,name="False Flag",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This was not done by simple bandits. This spot was chosen specifically for an ambush. And these troops were taken down quickly and efficiently. If Danath was heading to Hammerfall, this road is the most direct route. That makes it predictable. We must search for Danath among the dead and find out what happened here. Leave no stone left unturned.",objectivesText="Investigate the area for clues as to Danath's disappearance.",starts={{x=0.415,y=0.616,mapID=2372,npcID=231829}},ends={{x=0.415,y=0.616,mapID=2372,npcID=231829}},coords={mapID=2372,x=0.415,y=0.616},questType="standard"},
[84713] = {id=84713,name="Fallen Fortress",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="If Danath's kidnappers want to keep him from prying eyes, Ar'gorok is the perfect place. It's been abandoned for years, but its buildings still stand. All the \"Red Dawn\" could be there and no one would be the wiser. We must find Danath quickly, $p. Hammerfall is vulnerable and tensions are high. A missing leader is just the excuse Marran needs to start a war.",objectivesText="Meet Eitrigg at Ar'gorok.",starts={{x=0.415,y=0.614,mapID=2372,npcID=231826}},ends={{x=0.415,y=0.614,mapID=2372,npcID=231826}},coords={mapID=2372,x=0.415,y=0.614},questType="standard"},
[84714] = {id=84714,name="From Ironforge With Love",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="This \"Red Dawn\" is occupying the fortress of Ar'gorok. Bandits of all types and bands have taken refuge here under their banner. And I'm sure they've brought their spoils with them. It may help calm tensions if we recover the goods they've stolen and return them to their rightful owners in the Arathi Highlands . See if they are carrying anything with them.",objectivesText="Collect 20 Stolen Ironforge Supplies from Red Dawn troops within Ar'gorok. Progress: Who knows what we will find. What they've stolen could have come from here in the Arathi Highlands , or as far as the Horde or Alliance capitals.",starts={{x=0.279,y=0.257,mapID=2372,npcID=231833}},ends={{x=0.279,y=0.257,mapID=2372,npcID=231833}},coords={mapID=2372,x=0.279,y=0.257},questType="standard"},
[84715] = {id=84715,name="The Search for Danath",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="Using Ar'gorok as a base was clever. Very clever. It looks like the bulk of their forces are here. If Danath is alive, I'm certain they would keep him here. Search the buildings for him. And look for any information on this Red Dawn that you can. Anything might be helpful in taking them down. Let's hope Danath is alive. If he isn't, a long and bloody conflict is ahead of us.",objectivesText="Search the structures in Ar'gorok for Danath and information on the Red Dawn. Progress: Danath is here but we need a key to open the door!",starts={{x=0.278,y=0.256,mapID=2372,npcID=231832}},ends={{x=0.278,y=0.256,mapID=2372,npcID=231832}},coords={mapID=2372,x=0.278,y=0.256},questType="standard"},
[84716] = {id=84716,name="Returning to Stromgarde",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="While feigning sleep, I heard the guards brag about the Red Dawn's plans for Stromgarde. My kidnapping was just the start. Colonel Nials--after all these years! She will be the one to turn the key and free Marran, my niece, to do as she wishes and start a coup! Marran will lead Stromgarde's army and the Red Dawn to Hammerfall to secure the Highlands for \"Strom.\" We must gather our allies... and confront these traitors!",objectivesText="Meet your allies at Stromgarde Keep.",starts={{x=0.279,y=0.343,mapID=2372,npcID=230154}},ends={{x=0.279,y=0.343,mapID=2372,npcID=230154}},coords={mapID=2372,x=0.279,y=0.343},questType="standard"},
[84717] = {id=84717,name="Rise of the Red Dawn",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15716,mapID=14,description="Danath and Eitrigg ran ahead to confront Marran. They hope if they stop her, they can end the coup--and the bloodshed. But after seeing Joseph the Enlightened 's handiwork first hand... Despite how unorthodox he may be, he's still a danger. And I hate to say it, but I would relish the chance to finally take that underhanded cretin down. He's blocking our path up ahead at city hall. Let's take him down and then help Danath and Eitrigg end this war.",objectivesText="Defeat Joseph the Enlightened and help Danath and Eitrigg .",starts={{x=0.194,y=0.591,mapID=2372,npcID=231837}},ends={{x=0.194,y=0.591,mapID=2372,npcID=231837}},coords={mapID=2372,x=0.194,y=0.591},questType="standard"},
[84719] = {id=84719,name="The Expedition Awaits",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Greetings, ! Are you here to answer the Siren Isle 's call to adventure? Recently, a goblin salvage team discovered an isle with a strange \"singing crystal\" at its center. Like the goblins, the Arathi of Hallowfall have taken a keen interest in this crystal--as have we. We've been preparing an expedition to the isle! Most of the expedition has gone ahead, but the goblins last vessel is set to leave momentarily. If you hurry, you can catch them before they leave and join us!",objectivesText="Meet Skaggit by the East Gate of Dornogal.",starts={{npcID=232132,x=0.418,y=0.262,zoneID=14771}},ends={{npcID=230235,x=0.732,y=0.06,zoneID=14771}},coords={x=0.418,y=0.262,source="quest_giver",zoneID=14771},questType="standard"},
[84720] = {id=84720,name="To the Siren Isle!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2339,description="The Siren Isle is a myst'ry. A potentially profitable one. My crew thought they hit it big when they found a deserted island with some strange, singin' crystal... Turns out, everyone in Dornogal is interested in unclaimed \"strange singin' crystals.\" Both the Arathi and earthen scrambled quick an' were off before we could even charter a zeppelin! Fortunately for us, Ricket and crew have gone ahead to set up. We're the last to depart, an' I'm itchin' to go. What're we waitin' on?",objectivesText="Speak with Skaggit to journey to the Siren Isle .",starts={{npcID=230235,x=0.732,y=0.06,zoneID=14771}},ends={{npcID=230238,x=0.694,y=0.482,zoneID=10416}},coords={x=0.732,y=0.06,source="quest_giver",zoneID=14771},questType="standard"},
[84721] = {id=84721,name="To Scan a Crystal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="In order to understand the \"singing crystal\" at the heart of the island, we will need some special machinery. We have forged a device to scan its exposed facets, but the crystal's energies are far too complex to read. It has a highly unusual energy signature. The goblins and Arathi seem keen to contribute, so let us proceed with their help. Take my toolbox and retrieve the prototype and the components the Arathi and goblins have prepared.",objectivesText="Assist Bargus by collecting the earthen prototype , the Arathi's focus and the goblin's power source. Progress: Normally, our technology is quite capable when it comes to crystals and the energies found within them. But the energies found here are anomalous and don't synchronize with our technology...",starts={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},ends={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},coords={x=0.676,y=0.42,source="quest_giver",zoneID=10416},questType="standard"},
[84722] = {id=84722,name="Facet-nating Signals",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="Intriguing! These radiant remnants from the Arathi seemed to have given our device the necessary focus it needed. All that remains is to attune it properly to its size. In order to attune to the signal, we'll need to set up some pylons around the site. There is testing to initiate, . Follow me if you would like to assist me.",objectivesText="Meet Bargus by the Crystal and help him set up the pylons. Progress: Once the pylons are operational, I should be able to triangulate the signal.",starts={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},ends={{npcID=231140,x=0.48,y=0.438,zoneID=10416}},coords={x=0.676,y=0.42,source="quest_giver",zoneID=10416},questType="standard"},
[84723] = {id=84723,name="Buried Secrets",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15827,mapID=2369,description="These ruins are... quite old. Well, old by most outlanders' standards. Which begs the question: was finding this chamber the unfriendly outlanders' directive, or was it finding the tablet? One clue is that my readings suggest energy is flowing through the tablet as a conduit rather than originating from it. Shall we take a closer look? Perhaps investigation will yield some answers--and the source of the energy readings.",objectivesText="Investigate the ruins and find the source of the signal.",starts={{npcID=230271,x=0.488,y=0.182,zoneID=10416}},ends={{npcID=231143,x=0.402,y=0.702,zoneID=15827}},coords={x=0.488,y=0.182,source="quest_giver",zoneID=10416},questType="standard"},
[84724] = {id=84724,name="The Radiant Vault",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="This vault... this crystal... Who made this place? Who lived here? And who is this \"Cyrce\" we keep seeing mentioned on the tablets? When we set off to learn about the crystal, I did not anticipate discovering the remnants of an ancient civilization far beneath the earth. Bargus ruffles his wiry moustache before glancing at you.> This bears closer examination, don't you think?",objectivesText="Investigate the Crystal Shrine. Progress: It would seem we've made quite the discovery...",starts={{npcID=231143,x=0.402,y=0.702,zoneID=15827}},ends={{npcID=230351,x=0.712,y=0.442,zoneID=10416}},coords={x=0.402,y=0.702,source="quest_giver",zoneID=15827},questType="standard"},
[84725] = {id=84725,name="The Circlet Calls",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="Angorla peers at you from over her spectacles with excitement.> Can you hear it, ? This small, humble citrine is calling out to the circlet... just as the Siren Crystal called out to you and to all of us. I am uncertain what will happen when you reunify them... but there's only one way to find out. Place the circlet upon your finger and socket the citrine into the setting.",objectivesText="Equip Cyrce's Circlet and socket the Windsinger's Runed Citrine into the Singing Wind Socket. Then, remove the Windsinger's Runed Citrine from the socket. Progress: Have you placed the citrine into the circlet, <name>?",starts={{npcID=228074,x=0.712,y=0.442,zoneID=10416}},ends={{npcID=228074,x=0.712,y=0.442,zoneID=10416}},coords={x=0.712,y=0.442,source="quest_giver",zoneID=10416},questType="standard"},
[84726] = {id=84726,name="Uncovered Mysteries",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15827,mapID=2369,description="Angorla takes your hand in hers and examines the crystal-embedded circlet closely.> Can you feel the energy humming through it, ? The circlet feels... awake. Perhaps more secrets lie around the isle, waiting for you to uncover them. Dawn encouraged us to explore and learn about this isle, but I've got my work cut out for me here. Why don't you see what other secrets you can find?",objectivesText="Uncover hidden secrets around the Siren Isle . Progress: What have you found? Another treasure, perhaps?",starts={{npcID=228074,x=0.712,y=0.442,zoneID=10416}},ends={{npcID=228074,x=0.712,y=0.442,zoneID=10416}},coords={x=0.712,y=0.442,source="quest_giver",zoneID=10416},questType="standard"},
[84727] = {id=84727,name="The Second Signal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="An unexpected development. The energy signature appears to have a secondary source--and it is just north of here. Curiosity activated. Judging from the estimated size of the crystal, I theorize it might be a secondary exposed facet. Further investigation is required. Follow me.",objectivesText="Follow Bargus north.",starts={{npcID=231140,x=0.48,y=0.438,zoneID=10416}},ends={{npcID=233501,x=0.434,y=0.286,zoneID=10416}},coords={x=0.48,y=0.438,source="quest_giver",zoneID=10416},questType="standard"},
[84728] = {id=84728,name="Reforged Anew",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="The cracked citrine you found seems to be a perfect fit for one of the sockets found in the ring, yet... Angorla sockets the shard into the ring, the citrine wiggles loose and pops out.> The ring appears to be rejecting the piece. If we can repair the citrine and stabilize the energy within the shard, perhaps the ring will accept it? Since you've been so helpful with Bargus, care to lend another hand?",objectivesText="Help Angorla repair the Citrine. Progress: A fractured citrine is hardly an obstacle!",starts={{npcID=228074,x=0.712,y=0.442,zoneID=10416}},ends={{npcID=228074,x=0.712,y=0.442,zoneID=10416}},coords={x=0.712,y=0.442,source="quest_giver",zoneID=10416},questType="standard"},
[84730] = {id=84730,name="An Armored Charge",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="The inorganic material of this island is peculiar. The effects of salt water and years of storm erosion have enriched the minerals of this place. And enriched minerals are exactly the type of material an Ordinant seeks to infuse into new armaments. Bring me a considerable amount of storm-flecked debris from the isle's myriad of creatures. I would like to see if they are suitable for my craft.",objectivesText="Collect 50 storm-flecked debris . Debris can be looted from creatures across the Siren Isle . Progress: Have you found any storm-flecked debris ? It should be somewhat plentiful here if you're willing to look.",starts={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},ends={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},coords={x=0.676,y=0.42,source="quest_giver",zoneID=10416},questType="standard"},
[84735] = {id=84735,name="Truth of the Dark Irons",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=440,mapID=71,description="Few know the truth of the Dark Iron clan. Even fewer have seen it for themselves. The Timewalkers have agreed to take us back. They will send us to the time when our clan lost its emperor. And in doing so, I hope I can show you everything that came from that defeat. The good. The bad... Will you see the truth for yourself?",objectivesText="Defeat Emperor Dagran Thaurissan in the Return to Blackrock Depths raid. Progress: I will guide you along your path. Though the end of it... I don't know if I can bear to witness that again, champion.",starts={{npcID=229494,x=0.63,y=0.496,zoneID=440}},ends={{npcID=229494,x=0.63,y=0.496,zoneID=440}},coords={x=0.63,y=0.496,source="quest_giver",zoneID=440},questType="standard"},
[84740] = {id=84740,name="Bridge to Nowhere",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Are you heading to the dunes? I'm looking for my sister, Shahata. I don't know if she's alive, but I have to find her. The only place I can think to start the search is our village. K'aresh is nothing like I remember. I need landmarks--anything I can recognize to navigate by. Take this echo surveyor . It will reveal traces of the past--hopefully enough for me to orient us.",objectivesText="Use the Echo Surveyor to help Om'fennad find his way.",starts={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},ends={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},coords={x=0.544,y=0.636,source="quest_giver",zoneID=15336},questType="standard"},
[84741] = {id=84741,name="Signs in the Sands",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Things are starting to feel familiar. I think I know the way back to my village. I should tell you... I'm not just looking for my sister. Our mother died when I was studying in the cities. Shahata buried her under her favorite tree, but I wasn't there. I swore I would come home to conduct the funeral rites, but I didn't make it in time. I have left my oath unfulfilled for far too long. I owe it to mother to at least try now. Come--let's search the village.",objectivesText="Follow Om'fennad to his village. Progress: This can't be it! There must be something left.",starts={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},ends={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},coords={x=0.544,y=0.636,source="quest_giver",zoneID=15336},questType="standard"},
[84756] = {id=84756,name="The Toy Thief",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=440,mapID=71,description="My toy! It's been stolen! We have to figure out da culprit before they take more toys!",objectivesText="Discover the toy thief. Progress: Did you find my toy?",starts={{npcID=226684,x=0.632,y=0.524,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=440},questType="standard"},
[84759] = {id=84759,name="Ill-met in Starlight",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I used to practice what I would say when I saw my brother again. Then I stopped believing I would... He's been away all this time, and now he comes to ask for heirlooms? I dug our mother's grave beside her favorite tree. Alone. He should have come back then, I don't have time to help him ease his conscience now. If you two are so set on talking, at least have the sense not to do it in the open. Come to my camp--we'll speak there.",objectivesText="Meet Shahata at her camp.",starts={{npcID=230789,x=0.606,y=0.542,zoneID=15336}},ends={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},coords={x=0.606,y=0.542,source="quest_giver",zoneID=15336},questType="standard"},
[84760] = {id=84760,name="A Friendly Warning",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Before the Devouring, the Sufaadi were priests. There were customs of courtesy and charity. Those were erased with the rest of K'aresh . If the Wastelanders think I won't retaliate, they'll never stop targeting me. I think you understand the value of a show of force. Kill their leaders--let it be a warning for the others.",objectivesText="Slay Soulbinder Sabeel and Duelist Xaheen . Progress: Hard to believe they were once priests.",starts={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},ends={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},coords={x=0.764,y=0.552,source="quest_giver",zoneID=15336},questType="standard"},
[84761] = {id=84761,name="Toil and Trespass",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Fennad picked a poor time to ask for my help. I'm leaving as soon as I recover my supplies from the Sufaadi. I was passing through when they attacked, and they could have killed me if Ruya hadn't carried me off. I followed them back to Sufaad, but there are too many for me to deal with. If you help me recover my supplies, I'll see what I can do to help Fennad.",objectivesText="Recover Shahata 's stolen supplies. Progress: Hopefully they haven't used everything up.",starts={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},ends={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},coords={x=0.764,y=0.552,source="quest_giver",zoneID=15336},questType="standard"},
[84762] = {id=84762,name="We Are Our Words",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I had a necklace that our mother beaded. The Sufaadi took it when they robbed me. Things from old K'aresh are rare. If the Sufaadi haven't traded it, it'll be with their other valuables. I was planning to leave it behind. Sentimentality isn't worth risking your life, but you kept your word--which is more than I can say for my brother. Help me recover the necklace and it's yours.",objectivesText="Help Shahata recover her mother's necklace. Progress: What happened? Where's Fennad?",starts={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},ends={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},coords={x=0.764,y=0.552,source="quest_giver",zoneID=15336},questType="standard"},
[84765] = {id=84765,name="Of Bonds and Boughs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="All that time in Tazavesh, all I could think about was coming home. Now it's only brought more grief. Even if the surveyor wasn't damaged, I still have nothing to trace back to our mother's grave. Om'fennad glances around the cave.> See these markings? This was a shrine to the Exchange. I guess it's a fitting place to finally say goodbye. Would you be willing to help one last time? Nothing dangerous--just light some incense .",objectivesText="Help Om'fennad and Shahata honor their mother.",starts={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},ends={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},coords={x=0.544,y=0.636,source="quest_giver",zoneID=15336},questType="standard"},
[84767] = {id=84767,name="Charred Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,mapID=71,description="Alyx would appreciate the supplies returned.>",objectivesText="Return the Charred Celebration Crate to Alyx . Progress: Yes?",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440},{npcID=234262,x=0.504,y=0.386,zoneID=14771}},coords={mapID=71,source="quest_giver",x=0.63,y=0.502},questType="standard"},
[84773] = {id=84773,name="Crystalized Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Alyx would appreciate the supplies returned.>",objectivesText="Return the Crystallized Celebration Crate to Alyx . Progress: Yes?",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},coords={mapID=71,source="quest_giver",x=0.63,y=0.502},questType="standard"},
[84776] = {id=84776,name="A Call to Delves",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="There are many treasures to be found in the delves around our land. Perhaps some could be of use to you.",objectivesText="Complete 5 Delves in Khaz Algar. Progress: Beware of whatever lurks in these delves.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[84779] = {id=84779,name="Lorewalking: The Blade's Gambit",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,mapID=84,description="Though now only a blade of little power, Xal'atath was not idle. In the aftermath of the Legion invasion, tensions between the Horde and the Alliance erupted into the Fourth War. Xal'atath took advantage of the many forces at play in the war in a gambit to restore her power...",objectivesText="Listen to Lorewalker Cho to learn the story of Xal'alath during the Fourth War.",starts={{npcID=231891,x=0.642,y=0.162,zoneID=1519},{npcID=231891,x=0.542,y=0.566,zoneID=1637},{npcID=231891,x=0.496,y=0.316,zoneID=14771}},ends={{npcID=231891,x=0.642,y=0.162,zoneID=1519},{npcID=231891,x=0.542,y=0.566,zoneID=1637},{npcID=231891,x=0.496,y=0.316,zoneID=14771}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[84781] = {id=84781,name="Master of Secrets",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=6757,mapID=554,starts={{x=0.431,y=0.414,mapID=554,npcID=16445}},ends={{x=0.431,y=0.414,mapID=554,npcID=16445}},coords={mapID=554,x=0.431,y=0.414},questType="standard"},
[84782] = {id=84782,name="Lorewalking: The Blade's Past",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,mapID=84,description="Many years ago, a stone tablet from Stormsong Valley made its way into my library. It took years to break the cipher and translate the fragments of runes etched into it. I will tell you what we have pieced together. A tale of yet more treachery...",objectivesText="Listen to Cho to learn the story of Xal'alath in Ny'alotha.",starts={{npcID=231891,x=0.642,y=0.162,zoneID=1519},{npcID=231891,x=0.542,y=0.566,zoneID=1637},{npcID=231891,x=0.496,y=0.316,zoneID=14771}},ends={{mapID=84,npcID=231891,x=0.642,y=0.162}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[84784] = {id=84784,name="Lorewalking: The Blade's Nemeses",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2383,description="Lord N'Zoth calls now upon his brethren to aid in Xal'atath's defeat. You have been chosen to make the way for them to arrive. You know what to do.",objectivesText="Activate the 3 Ritual Obelisks to summon Yogg-Saron , C'Thun , and Y'Shaarj . Progress: Do not waste Lord N'Zoth's time.",starts={{x=0.525,y=0.731,mapID=2381,npcID=230321}},ends={{x=0.525,y=0.731,mapID=2381,npcID=230321}},coords={mapID=2381,x=0.525,y=0.731},questType="standard"},
[84787] = {id=84787,name="The Drain",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,starts={{x=0.579,y=0.693,mapID=2369}},ends={{x=0.579,y=0.693,mapID=2369}},coords={mapID=2369,x=0.579,y=0.693},questType="standard"},
[84789] = {id=84789,name="Lorewalking: The Blade's Downfall",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,mapID=84,description="They are ready. The Lords hold Xal'atath within the keep. You are the pebble to trigger the avalanche of their power. To end Xal'atath . Go. Join them.",objectivesText="Confront Xal'atath .",starts={{x=0.525,y=0.731,mapID=2381,npcID=230321}},ends={{npcID=231891,x=0.642,y=0.162,zoneID=1519},{npcID=231891,x=0.542,y=0.566,zoneID=1637},{npcID=231891,x=0.496,y=0.316,zoneID=14771}},coords={mapID=84,source="quest_giver",x=0.642,y=0.162},questType="standard"},
[84820] = {id=84820,name="By Oath and Blood",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="After the Devouring, I didn't think I'd see Fennad again. At first, it was easier to stay angry at him for leaving than to grieve. Then it was easier to forget, to only focus on surviving the next day. Seeing him again brought everything back. Oath-breaker... He had forsaken his oath to come home, but family is the first oath we're born to. What would it make me if I abandoned him now? He's my brother--by oath and by blood. I won't leave him to the Sufaadi.",objectivesText="Rescue Om'fennad .",starts={{npcID=230233,x=0.764,y=0.552,zoneID=15336}},ends={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},coords={x=0.764,y=0.552,source="quest_giver",zoneID=15336},questType="standard"},
[84821] = {id=84821,name="Biological Quintainment",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Have earned spurs, now time use them! Slimes run off with joust dummies, but that just make for moving target. Better practice! Mount noble mole steed by gate, get eye with lance, ride down slime. Important skill for any knight, yes.",objectivesText="Lance target dummy carrying slimes from mole-back. Progress: Watch out for big ones. Kick you good!",starts={{npcID=218866,x=0.668,y=0.786,zoneID=14795}},ends={{npcID=218866,x=0.668,y=0.786,zoneID=14795}},coords={x=0.668,y=0.786,source="quest_giver",zoneID=14795},questType="standard"},
[84822] = {id=84822,name="To Iskaara",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13646,mapID=2024,description="Let's get these kids back to Iskaara, eh? I'll meet you there.",objectivesText="Meet Hemet Nesingwary in Iskaara.",starts={{npcID=234745,x=0.188,y=0.398,zoneID=13646}},ends={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},coords={x=0.188,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
[84826] = {id=84826,name="Eco-Dome: Rhovan",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I will not make excuses for what we did. I will carry the responsibility of it for the rest of my existence. Alleria will come to understand why it was necessary. When she sees the power of the All-Devouring, she will understand. We will need at least two more Reshii Ribbons to bring enough of a force to bear against Dimensius. My friend Om'bera is a holder of a ribbon. She works in Eco-Dome: Rhovan on the next island. Let us gather her to our cause.",objectivesText="Meet Locus-Walker at Eco-Dome: Rhovan.",starts={{npcID=230811,x=0.47,y=0.544,zoneID=15336}},ends={{npcID=230288,x=0.71,y=0.58,zoneID=15336}},coords={x=0.47,y=0.544,source="quest_giver",zoneID=15336},questType="standard"},
[84827] = {id=84827,name="The Shattered Dome",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Eco-Dome: Rhovan was shattered by a falling chunk of void glass, destroying the structure and scattering its caretakers. They have returned to recover whatever equipment, flora, or fauna can be salvaged before the wastes claim them. Search the ruins to find any clues of Overseer Om'bera 's fate. We must have her Reshii Ribbon! Om'resh and I will search the impact crater.",objectivesText="Search Eco-Dome: Rhovan for Om'bera . Progress: Could Om'bera still be somewhere within the wreckage?",starts={{npcID=230288,x=0.71,y=0.58,zoneID=15336}},ends={{npcID=230288,x=0.71,y=0.58,zoneID=15336}},coords={x=0.71,y=0.58,source="quest_giver",zoneID=15336},questType="standard"},
[84831] = {id=84831,name="The Rhovan Infestation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="When the meteor struck, Om'bera and I tried to salvage what we could. Without the dome's shield, we were soon beset upon by scavengers of the Great Dark Beyond. We fled and were separated. Such creatures are not of K'aresh , and hostile to the stable biomes we sought to achieve. We need to clear these invasive creatures to find our equipment, and Om'bera.",objectivesText="Kill 10 invasive creatures in Eco-Dome: Rhovan. Progress: This was once a thriving eco-dome of the Trust. Our research worked toward the restoration of K'aresh .",starts={{npcID=230294,x=0.71,y=0.58,zoneID=15336}},ends={{npcID=230294,x=0.71,y=0.58,zoneID=15336}},coords={x=0.71,y=0.58,source="quest_giver",zoneID=15336},questType="standard"},
[84834] = {id=84834,name="Tempest Clefts",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="The Wastelanders were once the oracles of the Worldsoul of K'aresh . They were so proud and strident about their oaths. Now they scavenge the ruins like animals. Even rats have their uses. Gather void cleft essences for me. I have an idea of how we might sway the fallen oracles to our cause.",objectivesText="Bring 6 Void Cleft Essences to Xal'atath in the Tempest Fields. Progress: Many denizens of the Void are voracious consumers of energy. They greedily flock to pockets of coalesced energy like moths to a flame.",starts={{npcID=233878,x=0.64,y=0.47,zoneID=15336}},ends={{npcID=233878,x=0.64,y=0.47,zoneID=15336}},coords={x=0.64,y=0.47,source="quest_giver",zoneID=15336},questType="standard"},
[84835] = {id=84835,name="The Drowned Lair",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,starts={{x=0.274,y=0.625,mapID=2369}},ends={{x=0.274,y=0.625,mapID=2369}},coords={mapID=2369,x=0.274,y=0.625},questType="standard"},
[84836] = {id=84836,name="Shuddering Hollow",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,starts={{x=0.455,y=0.416,mapID=2369}},ends={{x=0.455,y=0.416,mapID=2369}},coords={mapID=2369,x=0.455,y=0.416},questType="standard"},
[84838] = {id=84838,name="Enemies of Enemies",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="The Wastelanders have made camp in the ruins of old K'aresh . A sanctuary from the ravenous beasts of the Void that stalk the wastes of K'aresh . A bulwark against outsiders. If a hostile entity were to enter their camp, you could defeat it--then they would respect you. Take the void energy you gathered into the ruined tower north of here. Be ready!",objectivesText="Place the coalesced void energy in the Castigar. Progress: You are not welcome here, stranger.",starts={{npcID=233878,x=0.64,y=0.47,zoneID=15336}},ends={{npcID=230645,x=0.612,y=0.392,zoneID=15336}},coords={x=0.64,y=0.47,source="quest_giver",zoneID=15336},questType="standard"},
[84848] = {id=84848,name="Before the Void",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="You've impressed these Wastelanders with your violent prowess, my champion. Well done. Now let me do my work. I know what these former oracles want. They dream of hearing the Song of K'aresh once more. I must make them believe it is possible, then pull on that string of desire. Soon we will have our army, and another Reshii Ribbon. First, let's return the Tabiqa ritual dagger.",objectivesText="Convince Soul-Scribe to join forces.",starts={{npcID=230634,x=0.612,y=0.392,zoneID=15336}},ends={{npcID=230292,x=0.63,y=0.39,zoneID=15336}},coords={x=0.612,y=0.392,source="quest_giver",zoneID=15336},questType="standard"},
[84855] = {id=84855,name="Dead Silence",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Dimensius's power is so great that even shattered, his aura radiates a power debilitating to mortal life. It is why the K'areshi were changed to beings of energy--it was the only way we could survive his presence. I had hoped my scouts could find a path that was safe for you and your compatriots to enter the manaforge. Raz'ida , Lo'shah , and Yanhal should have met us by now. Find them for me. Their information is vital to our defense against the All-Devouring.",objectivesText="Find the scouts at Overlook Zo'Shuul.",starts={{npcID=230806,x=0.482,y=0.366,zoneID=15336}},ends={{npcID=234106,x=0.482,y=0.366,zoneID=15336}},coords={x=0.482,y=0.366,source="quest_giver",zoneID=15336},questType="standard"},
[84856] = {id=84856,name="Where the Void Gathers",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="With Locus-Walker's Reshii Ribbon, I can transmute your flesh to energy. It won't hurt much. You will have the ability to travel within Dimensius's aura without being destroyed. There you can search for a path into the manaforge. You will travel in Untethered Space as a creature of energy, ignored by the Shadowguard. Their void beasts however... stay well away or be devoured. Talk to me when you are ready. Time is of the essence.",objectivesText="Search Shadow Point in Untethered Space with Xal'atath 's help. Progress: We will need more than one Reshii Ribbon if we want to reach Dimensius with a force capable of stopping his emergence.",starts={{npcID=233946,x=0.482,y=0.366,zoneID=15336}},ends={{npcID=233946,x=0.482,y=0.366,zoneID=15336}},coords={x=0.482,y=0.366,source="quest_giver",zoneID=15336},questType="standard"},
[84857] = {id=84857,name="Eco-Dome: Primus",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Xal'atath is correct. We need more than my one Reshii Ribbon to get a force to Dimensius. There is an eco-dome south of here. The founder of the Trust is there, overseeing its operation. She acquired the domes from the Consortium. She claims they will be the key to restoring K'aresh . I am skeptical anything will be safe now that Dimensius stirs. She was a member of the Ravel and possesses a Reshii Ribbon. Surely she would lend it to us.",objectivesText="Meet Locus-Walker at Eco-Dome: Primus.",starts={{npcID=234106,x=0.482,y=0.366,zoneID=15336}},ends={{npcID=230811,x=0.47,y=0.544,zoneID=15336}},coords={x=0.482,y=0.366,source="quest_giver",zoneID=15336},questType="standard"},
[84858] = {id=84858,name="System Restart",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="My Reshii Ribbon is all that is keeping this dome and its systems from collapsing. This eco-dome took too much of my fortune to build just for the Shadowguard to destroy it. They have sabotaged many of our control consoles, risking a complete ecological collapse. Find Engineer Om'loof and help him restart our environmental support system while I monitor the rest of the facility.",objectivesText="Help Engineer Om'loof in Eco-Dome: Primus. Progress: This eco-dome will fail if the environmental support system stops. We must stabilize it!",starts={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84859] = {id=84859,name="Damage Report 101",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Just like Engineer Om'loof, I have hired more well-regarded, highly trained, expensive management consultants from cartel Om. Two of them have not reported in. Are they dead, or just distracted again? Find botanist Om'nittar and shield technician Om'door . Get their damage reports. I need to know if the attack caused any lasting damage to my dome.",objectivesText="Find botanist Om'nittar and shield technician Om'door and bring their reports to Ve'nari . Progress: I hire the best. I am sure Om'nittar and Om'door have the information I need.",starts={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84860] = {id=84860,name="Eco-Stabilizing",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The Shadowguard attack caused chaos and disarray in this dome. Several control consoles have powered down, and my consultants are stretched thin reviving their assigned biomes and systems. This is where you come in, . It's an easy, but critical job. Find the disabled consoles and make sure they restart.",objectivesText="Activate the disabled control consoles in Eco-Dome: Primus. Progress: Are all the consoles operational? No? Go switch them on!",starts={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84861] = {id=84861,name="This Is Our Dome!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="We may have driven the saboteurs out of the dome and repaired its systems, but that doesn't mean the Shadowguard is done with my domes. They're still hiding at the perimeter, trying to find a way to harvest the vast amounts of expensive energy needed to power the eco-dome. I need you to fight them off. Then maybe this attack will truly end.",objectivesText="Kill 7 Shadowguard around Eco-Dome: Primus. Progress: Did you get them all? Or are there still Shadowguard hiding around the perimeter, damaging my dome?",starts={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84862] = {id=84862,name="Void Alliance",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="We can't have you patrolling the perimeter of this dome, like the city watch fighting attackers in perpetuity. We need a permanent solution so we can continue with our noble quest. Take these crystals. They've been attuned to the eco-dome's defense magics. Just place them near strategic parts of the perimeter to strengthen the magical defenses. What? This time it's no trick. If this dome explodes, I'll never get to destroy Dimensius.",objectivesText="Place 4 Xal'atath defenses around Eco-Dome: Primus. Progress: Have you placed the crystals I gave you? Ve'nari won't give up her ribbon until her dome is secure.",starts={{npcID=230825,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=230825,x=0.47,y=0.546,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84863] = {id=84863,name="Counter Measures",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I cannot relinquish my Reshii Ribbon just yet, . Not while the Shadowguard assaults my eco-dome from their camp in Serrated Peaks. Take the fight to them! If you decimate their forces, they will stop this assault. Bring Locus-Walker's apprentice, Alleria. She looks like she knows how to handle herself in a fight. She also keeps staring daggers at the Harbinger, and I don't have time to play peacemaker between those two.",objectivesText="Kill 12 Shadowguard forces in Serrated Peaks. Progress: The Shadowguard are still attacking. Did you decimate their numbers yet?",starts={{npcID=230814,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=232642,x=0.543,y=0.467,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84864] = {id=84864,name="Her Dark Side",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="An ethereal army runs on its energy siphons. Interrupt the flow of energy by destroying their siphon tower, and the army will pull back. It's one of their weaknesses as minions. Normally I wouldn't share the secrets of their defeat, but they betrayed me and will forever live with the consequences. The siphon has a control console that can be overloaded to collapse the system. It will be shielded by a void barrier. Alleria can remove it for you.",objectivesText="Destroy the Ethereal Siphon in Serrated Peaks. Progress: Now the Shadowguard will have to retreat.",starts={{npcID=230825,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=232642,x=0.543,y=0.467,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84865] = {id=84865,name="Divide and Conquer",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Of all the assets on the field of battle, the troops are the most expendable. I've sent enough to their destruction to know this as a fact. If we are to safeguard this dome for Ve'nari and get her Reshii Ribbon, we should destroy their cannons. Those cannons are easily worth the lives of all of their soldiers. Destroy them and their commanders will sound the retreat. Most field commanders would never admit this as it's bad for morale, but you seem like the type that can handle uncomfortable truths.",objectivesText="Destroy 3 Shadowguard Cannons in Serrated Peaks. Progress: Taking out these cannons will force the Shadowguard's retreat. I would not listen to Xal'atath 's ideas on ethics of command, though.",starts={{npcID=230825,x=0.47,y=0.546,zoneID=15336}},ends={{npcID=232642,x=0.543,y=0.467,zoneID=15336}},coords={x=0.47,y=0.546,source="quest_giver",zoneID=15336},questType="standard"},
[84866] = {id=84866,name="To Purchase Safety",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I need to focus on the mission. Regardless of my doubts about our companions, the Shadowguard are a scourge. We should slay their Shadow-Captain so they cannot easily return to Eco-Dome: Primus. Ve'nari would lend her Reshii Ribbon to our cause, and we would discover if my trust in Locus-Walker was well placed. I will not let my doubts stay my bow on the battlefield, . You can trust me to hunt these followers of Dimensius.",objectivesText="Kill Shadow-Captain Lakheesh .",starts={{npcID=232642,x=0.543,y=0.467,zoneID=15336}},ends={{npcID=237705,x=0.542,y=0.454,zoneID=15336}},coords={x=0.543,y=0.467,source="quest_giver",zoneID=15336},questType="standard"},
[84867] = {id=84867,name="Stalking Stalkers",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I've planted the seed, yet Soul-Scribe still hesitates. Her daughter Narathe is more receptive. She might be able to give us the nudge that's needed to win the Wastelanders over. Daughters are useful. Go with Narathe . Win over their tribe. I will stay here and continue to work on Soul-Scribe 's will.",objectivesText="Find a way to sway the Wastelanders. Progress: I will do what my oaths dictate, but I am not convinced that your plan is the way to go.",starts={{npcID=230658,x=0.63,y=0.39,zoneID=15336}},ends={{npcID=230292,x=0.63,y=0.39,zoneID=15336}},coords={x=0.63,y=0.39,source="quest_giver",zoneID=15336},questType="standard"},
[84868] = {id=84868,name="A Whiff of Help",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="You seem quite equipped for solving secrets now! As much as I expect Maru would want to come with you, she's far too young. Fortunately, we Tuskarr have an incense that lets our souls communicate across long distances. I keep a stock of it on me if you need. As a friend of Maru , I will only charge you for the cost of materials.",objectivesText="Purchase and use a Spiritual Incense from Benatauk . Progress: Have you tried the incense?",starts={{npcID=226766,x=0.632,y=0.524,zoneID=440}},ends={{npcID=226766,x=0.632,y=0.524,zoneID=440}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=440},questType="standard"},
[84869] = {id=84869,name="Hunting on Glass",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="Violent scavengers of the Void have been drawn to Dimensius's aura to feast upon the scraps he will leave behind. This presents a problem for our Wastelander friends. Scavenging is their job. They could handle these beasts--I would not be seeking to ally with them if they couldn't. But why not give them a gift, and show them you are their equal--no, their superior in combat?",objectivesText="Kill 4 Void Terrors and 8 Unreal Observers . Progress: Dimensius's power grows and the Wastelanders are feeling the pinch. Let us ease the pressure for them a bit.",starts={{npcID=233878,x=0.64,y=0.47,zoneID=15336}},ends={{npcID=233878,x=0.64,y=0.47,zoneID=15336}},coords={x=0.64,y=0.47,source="quest_giver",zoneID=15336},questType="standard"},
[84876] = {id=84876,name="The Oasis",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Soul-Scribe would fight for us, even die for our cause. Yet she still denies us her Reshii Ribbon. She sees it as a tool of the Ravel, and her oaths are getting in the way of our mission. If she could feel the presence of the Worldsoul K'aresh once again, she would give anything to protect him--even the ribbon. The Oasis is the Trust's eco-dome that has a stable biome. The perfect place to commune with a Worldsoul, if one still exists.",objectivesText="Meet Xal'atath at the Oasis eco-dome. Progress: Our research here is essential to the future of K'aresh . That we have stabilized this area means that we can replicate this feat in other domes--perhaps even heal the shattered remains of K'aresh .",starts={{npcID=230658,x=0.63,y=0.39,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.63,y=0.39,source="quest_giver",zoneID=15336},questType="standard"},
[84879] = {id=84879,name="Restoring Hope",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="This dome is a reasonable facsimile of K'aresh . We will find no better place for Soul-Scribe to hear the Worldsoul's song. And yet, as Dimensius grows in power, even the Oasis succumbs to the Void. I can feel the rifts tearing open. Their energies will disrupt this delicate ritual. Unfortunately they'll need to be closed so Soul-Scribe can be convinced.",objectivesText="Cleanse the eco-dome of invasive elements. Progress: The Void creeps further and further into K'aresh every day. Dimensius's power grows ever stronger.",starts={{npcID=230738,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230738,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[84882] = {id=84882,name="Deck Dismay",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Gather up the cards that got scattered around the area and I will be forever grateful!",objectivesText="Collect the missing cards. Progress: How's it going? Have you found all my missing cards?",starts={{x=0.639,y=0.524,mapID=71,npcID=230838}},ends={{npcID=230838,x=0.638,y=0.522,zoneID=440}},coords={mapID=71,source="quest_giver",x=0.638,y=0.522},questType="standard"},
[84883] = {id=84883,name="K'aresh That Was",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The Tabiqa has not been attempted for thousands of years. It was clear that the Devouring War destroyed K'aresh . And yet, looking at this dome... they have recreated so much that I thought lost forever--fresh water, clean air, even the zaranit flowers I thought extinct. Does the Harbinger speak the truth? No. I didn't break my oath and abandon the Worldsoul. K'aresh is gone.",objectivesText="Gather materials for the ritual. Progress: Did you find the components for the Tabiqa ritual? Do they even still exist?",starts={{npcID=230739,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230739,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[84885] = {id=84885,name="Working for G.E.T.A.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Attention: Protect the Citizens of Undermine AND get paid! Profit-seeking bounty hunters encouraged to check in at the local G.E.T.A. office for more information.",objectivesText="Inquire at the local G.E.T.A. office in the Vatworks Progress: Do you need something, <name>? I don't have time for idle chit-chat.",starts={{npcID=456747,x=0.427,y=0.529,zoneID=15347},{npcID=467447,x=0.39,y=0.305,zoneID=15347}},ends={{npcID=228393,x=0.33,y=0.522,zoneID=15347}},coords={x=0.427,y=0.529,source="quest_giver",zoneID=15347},questType="standard"},
[84891] = {id=84891,name="G.E.T.A. The Radioactive Rat",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="We got a report here of some big, radioactive rat that was chased into a nearby sewer. Not only is it highly aggressive, it's terrible for the environment. Hey, don't look at me like that. Us Underminers care about that stuff even if the big cartels don't. I put the location of the sewer entrance on your map. Hopefully, one of these lunks will get off their butts and join you there.",objectivesText="Defeat the Radioactive Rat Progress: Once you're finished, come back here, and I'll make sure you're adequately compensated.",starts={{npcID=228393,x=0.33,y=0.522,zoneID=15347}},ends={{npcID=228393,x=0.33,y=0.522,zoneID=15347}},coords={x=0.33,y=0.522,source="quest_giver",zoneID=15347},questType="standard"},
[84892] = {id=84892,name="G.E.T.A. The Crocodilian",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Did you know that crocodiles can grow indefinitely? Well, the owner of this crocodile didn't. And when it got too big, it was released. Normally these crocodiles make their way out of the Undermine . But this one decided it liked the taste of goblins and stayed. If you're up for it, the people of Undermine could use someone brave to face it. Are you game?",objectivesText="Defeat the Crocodilian Progress: Who's afraid of a big ol' croc, you say?",starts={{npcID=228393,x=0.33,y=0.522,zoneID=15347}},ends={{npcID=228393,x=0.33,y=0.522,zoneID=15347}},coords={x=0.33,y=0.522,source="quest_giver",zoneID=15347},questType="standard"},
[84893] = {id=84893,name="G.E.T.A. The Captain",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="This is a unique one. Some cave skippers got into the Undermine sewers and are starting to populate, causing all sorts of problems. It looks like an especially big one is organizing them somehow. We've taken to calling him \" the Captain .\" Make sure his reign of finned, eye-bulging terror ends today.",objectivesText="Defeat the Captain Progress: Be careful, <name>. From what we can tell, The Captain doesn't work alone.",starts={{npcID=228393,x=0.33,y=0.522,zoneID=15347}},ends={{npcID=228393,x=0.33,y=0.522,zoneID=15347}},coords={x=0.33,y=0.522,source="quest_giver",zoneID=15347},questType="standard"},
[84894] = {id=84894,name="G.E.T.A. 2",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[84896] = {id=84896,name="The Next Dimension",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="By the Songs of K'aresh , I will join you to face the Shadowguard and Dimensius in battle. Let those that would prey on Untamed K'aresh fear his followers! My scouts have tracked your comrades setting a foothold in Shadowguard territory. They will need our assistance. K'aresh lives! Our cause is just! Our oaths are unbroken!",objectivesText="Meet with Soul-Scribe in Shan'dorah on K'aresh .",starts={{npcID=230786,x=0.744,y=0.304,zoneID=15336}},ends={{npcID=230818,x=0.602,y=0.29,zoneID=15336}},coords={x=0.744,y=0.304,source="quest_giver",zoneID=15336},questType="standard"},
[84897] = {id=84897,name="The Calm Before We Storm",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Narathe is right. We are fortunate that void elves have experience battling the Shadowguard. The wastes of K'aresh are merciless, and the battle to come will be as well. I hope they are prepared for a brutal fight. These will not be the scattered scouts they are used to fighting on Telogrus. You should ensure they are ready for the battle to come.",objectivesText="Check in with Alleria and the void elves at Shan'dorah on K'aresh . Progress: We have spent a long time preparing for this moment. I will not let it slip.",starts={{npcID=230818,x=0.602,y=0.29,zoneID=15336}},ends={{npcID=231443,x=0.606,y=0.28,zoneID=15336}},coords={x=0.602,y=0.29,source="quest_giver",zoneID=15336},questType="standard"},
[84898] = {id=84898,name="The Sands of K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="My people have fought across every inch of the ruins of our world. We gave our oath to King Salhadaar and he rewarded us by sending the Shadowguard to hunt us down. Salhadaar is long dead, but we knew the Shadowguard would return. In the long years that followed, we secreted caches of weapons so we would always be able to raise a blade in defiance.",objectivesText="Collect 3 Weapons Caches from the nearby sands of the Shatter Gorge on K'aresh . Progress: Have you gathered all of the weapons caches in the sand?",starts={{npcID=231443,x=0.606,y=0.28,zoneID=15336}},ends={{npcID=231446,x=0.552,y=0.302,zoneID=15336}},coords={x=0.606,y=0.28,source="quest_giver",zoneID=15336},questType="standard"},
[84899] = {id=84899,name="Shadowguard Diffusion",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="With or without Xal'atath, the Shadowguard have long been a thorn in my side. It would be wise to take out as many as we can on this rock. I still do not trust her, but we must focus on the enemy we can defeat right now. Do not relent, . If you see any Shadowguard, cut them down. A battle against them today saves us a battle against them tomorrow.",objectivesText="Defeat Shadowguard in the sands of the Shatter Gorge surrounding Shan'dorah on K'aresh . Progress: We still have many to defeat before we can progress.",starts={{npcID=230817,x=0.606,y=0.28,zoneID=15336}},ends={{npcID=231444,x=0.55,y=0.304,zoneID=15336}},coords={x=0.606,y=0.28,source="quest_giver",zoneID=15336},questType="standard"},
[84900] = {id=84900,name="Like a Knife Through Aether",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="Very good, my champion. You are a swift and sharp blade of destruction. We will put all that power to use now. We will slaughter the Shadowguard that seek to raise Dimensius, and the machines created to feed his insatiable hunger. The Shadowguard must have a Reshii Ribbon among their spoils. As we destroy their garrisons, look for this final ribbon. It is our way forward to kill a Void Lord.",objectivesText="Stop the Shadowguard ethereals at Shadow Point: Darkmend in K'aresh . Progress: A few more of these and we might even have a chance. Do not relent, <name>. You are capable of this and so much more.",starts={{npcID=231445,x=0.55,y=0.304,zoneID=15336}},ends={{npcID=231476,x=0.486,y=0.266,zoneID=15336}},coords={x=0.55,y=0.304,source="quest_giver",zoneID=15336},questType="standard"},
[84902] = {id=84902,name="Adverse Instantiation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Turning into beings of energy was a choice we made when we had no other option. In the time since then, we have become reliant on consuming energy to survive. The Shadowguard are feeding that power to Dimensius. His hunger is infinite, and he will drain the energy from K'aresh to fuel his re-emergence. We must destroy this machinery that feeds him, .",objectivesText="Disable 6 Shadowguard Power Pylons in Shadow Point on K'aresh . Progress: Are they all dealt with?",starts={{npcID=231487,x=0.486,y=0.266,zoneID=15336}},ends={{npcID=231492,x=0.482,y=0.194,zoneID=15336}},coords={x=0.486,y=0.266,source="quest_giver",zoneID=15336},questType="standard"},
[84903] = {id=84903,name="Until the Sands Bleed Void",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I have fought Shadowguard on Eredath, Telogrus, and now on K'aresh . They are a thorn that should be plucked from the cosmos. That they should follow the very monster that threatened their world proves they are a scourge. Though, perhaps I am no better, fighting alongside Xal'atath. I will grapple with that contradiction later. For now, I intend for us to put an end to them, .",objectivesText="Kill Shadowguard in Shadow Point on K'aresh . Progress: Spare no remorse for their kind. They would do far worse.",starts={{npcID=231488,x=0.486,y=0.266,zoneID=15336}},ends={{npcID=231493,x=0.482,y=0.194,zoneID=15336}},coords={x=0.486,y=0.266,source="quest_giver",zoneID=15336},questType="standard"},
[84904] = {id=84904,name="And We Will Answer",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="This is unthinkable. Heretical! The Shadowguard have captured my warriors and are converting them into new troops for Dimensius--forcing an oath to serve the All-Devouring as the Void fills their being. Free them, . We cannot let this last any longer. I will send Narathe to aid you in this fight. She knows how to untether the souls of oath-breakers.",objectivesText="Rescue Captured Wastelanders in Shadow Point on K'aresh . Progress: Once an ethereal embraces the shadow, they are lost forever.",starts={{npcID=231486,x=0.486,y=0.266,zoneID=15336}},ends={{npcID=231491,x=0.482,y=0.194,zoneID=15336}},coords={x=0.486,y=0.266,source="quest_giver",zoneID=15336},questType="standard"},
[84905] = {id=84905,name="To Walk Among Shadow",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="We must continue disabling or destroying these buildings. I am loathe to destroy the technology of my people, but when used for such dire purpose, there is no choice! From here on out, hold nothing back. Let us raze the works of the Shadowguard.",objectivesText="Help Locus-Walker disable Shadow Point: Torment at Shadow Point on K'aresh .",starts={{npcID=231492,x=0.482,y=0.194,zoneID=15336}},ends={{npcID=231506,x=0.482,y=0.192,zoneID=15336}},coords={x=0.482,y=0.194,source="quest_giver",zoneID=15336},questType="standard"},
[84906] = {id=84906,name="Nexus Regicide",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Now is the time, . We must not hesitate. They will send their strongest to defend this last manaforge. We will find Nexus-Prince Azir there and we will end him before we take this battle to Dimensius. Xal'atath or no Xal'atath, we have what we need to do this. Just one final kill. Let us not dally. Make haste.",objectivesText="Defeat the leader of the Shadowguard in Shadow Point: Apotheosis on K'aresh .",starts={{npcID=231505,x=0.482,y=0.19,zoneID=15336}},ends={{npcID=231521,x=0.442,y=0.182,zoneID=15336}},coords={x=0.482,y=0.19,source="quest_giver",zoneID=15336},questType="standard"},
[84908] = {id=84908,name="Stormrider's Honors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Champion, though you are no Stormrider, you may yet be worthy of the Stormrider's armor. Find Stormrider Bruelda if you wish to claim this honor.",objectivesText="Speak with Stormrider Bruelda in Dornogal.",ends={{npcID=225347,x=0.352,y=0.382,zoneID=14771}},coords={mapID=2339,source="quest_giver",x=0.352,y=0.384},questType="standard"},
[84909] = {id=84909,name="Ghostly Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Alyx would appreciate the supplies returned.>",objectivesText="Return the Ghostly Celebration Crate to Alyx . Progress: Yes?",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},coords={mapID=71,source="quest_giver",x=0.63,y=0.502},questType="standard"},
[84910] = {id=84910,name="The Tabiqa",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="My followers long for the days when they were oracles. They yearn to hear the Song of K'aresh . I am a realist. The evil of the Ravel, of Dimensius--they have destroyed the beauty that was our Worldsoul. But you have gathered the items for the Tabiqa. So I will attempt it. When I hear the void of K'aresh 's absence, there will be consequences.",objectivesText="Help Soul-Scribe with the ritual. Progress: It has been too long since we were this close to K'aresh . It is but an echo of what once was, but the memories that it brings back...",starts={{npcID=230739,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230787,x=0.744,y=0.304,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[84914] = {id=84914,name="Valorstones",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,starts={{npcID=223726,x=0.392,y=0.24,mapID=2339}},ends={{npcID=223726,x=0.392,y=0.24,mapID=2339},{npcID=221390,x=0.472,y=0.328,mapID=2214}},coords={x=0.392,y=0.24,source="quest_giver",mapID=2214},questType="standard"},
[84915] = {id=84915,name="Clearing the Dunes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The deserts here were never safe, but there was still beauty--birdsong, herds of animals, and the desert would bloom from horizon to horizon after a storm. Now it's a wasteland. I barely took two steps off the docks before being chased by some monster. I need to get out there. If you could cull the worst of those creatures, I'd feel much safer.",objectivesText="Slay 8 dune creatures. Progress: Is it safe yet?",starts={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},ends={{npcID=230159,x=0.544,y=0.636,zoneID=15336}},coords={x=0.544,y=0.636,source="quest_giver",zoneID=15336},questType="standard"},
[84923] = {id=84923,name="A Bird's Tale",level=10,requiredLevel=30,faction="both",expansion=10,zoneID=440,mapID=71,description="I've heard that Reshad has a new story to tell involving his bird companion, Percy. Speak with him if you would like to discover the tale.",objectivesText="Find Reshad near the stage.",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440}},ends={{npcID=228273,x=0.642,y=0.512,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[84924] = {id=84924,name="A Bird's Tail",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="I've told many tales in my days, but my companion Percy has a tale of his own to tell. Would you care to learn about it? I will give you a clue on where to start. From there, you must find the clues that Percy has left behind to discover his story. You can have this feather that Percy left behind as well. Look closely and you may find more clues. Perhaps a bird of your own may help you on your journey.",objectivesText="Learn about Percy's adventures by finding his feathers. Progress: Have you discovered Percy's tale?",starts={{npcID=228273,x=0.642,y=0.512,zoneID=440}},ends={{npcID=228273,x=0.642,y=0.512,zoneID=440}},coords={x=0.642,y=0.512,source="quest_giver",zoneID=440},questType="standard"},
[84925] = {id=84925,name="Rallying All Rapscallions!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha",objectivesText="Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal .",ends={{npcID=219215,x=0.554,y=0.77,zoneID=14771}},coords={mapID=2339,source="quest_giver",x=0.555,y=0.77},questType="standard"},
[84932] = {id=84932,name="A Legacy of Destruction",level=10,requiredLevel=30,faction="both",expansion=10,zoneID=440,mapID=71,description="Adventurer! A dragon whelpling recently showed up in the pet playground and has been causing all sorts of chaos. Could you go talk to him and see if you can sort out the issue?",objectivesText="Find the dragon whelpling at the pet playground.",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440}},ends={{npcID=231029,x=0.618,y=0.498,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[84933] = {id=84933,name="From Ashes to Wisdom",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="I will become the great and powerful Deathwing! Cower before my strength! You there! Do you wish to join me, the next Deathwing, on an epic adventure?",objectivesText="Show Voidfire the destruction of Deathwing. Progress: I want to get followers to do my bidding! Like a cult!",starts={{npcID=231029,x=0.618,y=0.498,zoneID=440}},ends={{mapID=71,npcID=231029,x=0.618,y=0.498}},coords={x=0.618,y=0.498,source="quest_giver",zoneID=440},questType="standard"},
[84934] = {id=84934,name="A Dark Descent",level=80,requiredLevel=80,faction="none",expansion=10,objectivesText="Venture forth into the Maw.",questType="standard"},
[84935] = {id=84935,name="Excising the Incursion",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="The Devouring Host must have somehow followed us here. I don't know what they could want with a place like this, but I can't imagine the Void is suddenly infused with benevolent purpose. We can't allow this incursion to get out of hand. Slay as many of them as you can manage. Enough to thin their numbers, at least.",objectivesText="Slay aberrations of the Devouring Host in the Planes of Torment.",starts={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84936] = {id=84936,name="To Cleanse Shadow's Stain",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="These monstrosities certainly wasted no time once they arrived. They are snatching up souls left and right and drowning them in void magics. Take my holy symbol. It should be potent enough to drive away the shadows that cling to any lingering souls.",objectivesText="Use the Redeemer's Sigil to cleanse voidwarped souls in the Planes of Torment. Progress: Are the souls here just convenient targets? Or are they what drew the Host here to begin with?",starts={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84937] = {id=84937,name="Distant Echoes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="Can you hear it? There's a strange sound echoing in the distance. Given where we are, I would assume it's a trick. Or worse, a trap. But it feels... I don't know how to describe it, but I feel calmer for hearing it. Like I'm in control. This is going to sound mad, but I think--I think we should follow it. I don't know where it could be coming from, but my instincts are telling me to trust it. We should follow its trail.",objectivesText="Find the source of the strange melody. Progress: <Sylvanas eyes you up and down. She says nothing.>",starts={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231033,x=0.268,y=0.378,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84938] = {id=84938,name="Chaos Control",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="These are no mere embodiments of Void. They move with precision and purpose. They have taken up a defensive position within the Tremaculum. No doubt they intend to expand their presence and shore up their defenses, now that they have a foothold. All the better. It means they will all be gathered in one place. Break their ranks. Show no mercy.",objectivesText="Stem the tide of the Devouring Host within the Tremaculum. Progress: I don't have to tell you how dangerous it would be to let outside forces meddle in the Maw for overlong. We need to excise them sooner rather than later.",starts={{npcID=231033,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231033,x=0.268,y=0.378,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84939] = {id=84939,name="Mad Space",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="It doesn't matter how many of these void monstrosities we kill. We have to deal with the source, or they'll just keep coming. Traveling across the rift is not an easy feat in the best of times. If we can find the places where they've been able to tear through and close them, then we should be able to cut off their reinforcements. Lead the way. I'll be at your back the entire time.",objectivesText="Collapse 5 Unstable Void Rifts . Progress: This place is swarming with servants of the Void. Stay on your guard.",starts={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84940] = {id=84940,name="Friendly Competition",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="See, Ricket offered to dig it up, but the Arathi expedition lady didn't seem too keen on that. Gave 'er an earful. Could hear it from the airship. Yeesh. Bargus , the earthen \"ordinant\"--whatever that means-- proposed scanning the crystal to help us \"understand it better.\" I don't need to understand it. All I need's my cut. But I'm fine layin' low and doin' what they want. Go talk to Bargus at the earthen camp. See how they're comin' along an' if we can help.",objectivesText="Seek out Bargus in the camp.",starts={{npcID=230238,x=0.694,y=0.482,zoneID=10416}},ends={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},coords={x=0.694,y=0.482,source="quest_giver",zoneID=10416},questType="standard"},
[84941] = {id=84941,name="Cave Barging",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="Unless it is a convergence of coincidence, whoever these large outlanders are, they appear to also be interested in the crystal's signal--and the location of its origin. We earthen do not often take stock in coincidences. Engage your defense protocols, . These outlanders are not hospitable like your people.",objectivesText="Find the source of the energy signature.",starts={{npcID=233501,x=0.434,y=0.286,zoneID=10416}},ends={{npcID=230271,x=0.488,y=0.182,zoneID=10416}},coords={x=0.434,y=0.286,source="quest_giver",zoneID=10416},questType="standard"},
[84942] = {id=84942,name="The Final Hazard",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="With their lesser rifts closed, the Devouring Host will be hard-pressed to muster any reinforcements. But if we don't deal with their leader, then they'll just open more. Above, in the parapets... There's no mistaking it. I can feel a force of Void drawing everything toward it, even all the way from down here. That's where we'll find our mark, without a doubt.",objectivesText="Slay the Living Gateway atop the Tremaculum. Progress: All that's left to do is deal with their commander. I just really wish he'd picked a slightly lower vantage.",starts={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231033,x=0.268,y=0.378,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84944] = {id=84944,name="Preludes and Preparations",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="As you are no doubt aware, ferrying souls beyond the bounds of the Maw is no easy task. This is not a place from whence souls are meant to ascend. Our resources are limited, but I have devised a way to ensure the relative safety of the souls I retrieve--though I will require materials. Fetch for me the reeds that grow in the silt of the Gorgoa River, soulthread from the cloaks of the wandering specters, the hide of a soul-eater... Ah. And mawrat teeth . We mustn't forget the mawrat teeth .",objectivesText="Collect Gorgoa Reeds , Soulthreads , a Pristine Soul-Eater Hide , and 50 Mawrat Teeth . Progress: Have you gathered the reagents?",starts={{npcID=231033,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231030,x=0.268,y=0.378,zoneID=11400},{npcID=238519,x=0.304,y=0.186,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84945] = {id=84945,name="Repent of the Highborne",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="The reagents are gathered, and the lingering souls have been put at ease for the moment. We do not have long. Stand back, while I send them to where they are meant to dwell.",objectivesText="Observe the Ritual of Sending. Progress: <Sylvanas stands silently.>",starts={{npcID=231033,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=231033,x=0.268,y=0.378,zoneID=11400}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84946] = {id=84946,name="Returning to Life",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=1543,description="When I decided to come here, I have to admit that I wasn't sure what I would find. There's no disputing the terrible things that Sylvanas has done, and it's a burden that she will have to bear for the rest of her days. But seeing her, like this... Come. We've been here too long as it is. The weight of this place is starting to get to me.",objectivesText="Return to K'aresh. Progress: Let's make haste. We don't belong here.",starts={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},ends={{npcID=233567,x=0.608,y=0.924,zoneID=15781}},coords={x=0.268,y=0.378,source="quest_giver",zoneID=11400},questType="standard"},
[84947] = {id=84947,name="Determination",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=1543,description="Hold a moment. Arator will be fine for a few moments longer. Let him travel alone for a moment. I wish to speak to you. Privately.",objectivesText="Speak with Sylvanas. Progress: It would be unwise to linger here.",starts={{npcID=233463,x=0.262,y=0.318,zoneID=11400}},ends={{npcID=233463,x=0.262,y=0.318,zoneID=11400}},coords={x=0.262,y=0.318,source="quest_giver",zoneID=11400},questType="standard"},
[84949] = {id=84949,name="The Eleventh Hour",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2472,description="It's high time we got back to Azeroth. I think we've done all we can do when it comes to mustering the Windrunners for whatever is to come.",objectivesText="Return to Vereesa in Dornogal . Progress: We should get going. I've done enough dimension-traveling for one day, I think.",starts={{npcID=233567,x=0.608,y=0.924,zoneID=15781}},ends={{npcID=233568,x=0.398,y=0.79,zoneID=14771}},coords={x=0.608,y=0.924,source="quest_giver",zoneID=15781},questType="standard"},
[84956] = {id=84956,name="A Shadowy Invitation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="$p, I've received word from my mentor, Locus-Walker . He warns of a Shadowguard plot that requires our aid. I wonder if he has finally tracked down Xal'atath. Come to the Foundation Hall in Dornogal. We must speak immediately.",objectivesText="Meet Locus-Walker at the Foundation Hall in Dornogal.",starts={{npcID=227758,x=0.422,y=0.27,zoneID=14771}},ends={{npcID=233603,x=0.42,y=0.27,zoneID=14771}},coords={x=0.422,y=0.27,source="quest_giver",zoneID=14771},questType="standard"},
[84957] = {id=84957,name="Return to the Veiled Market",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2339,description="I have been retained by the K'aresh Trust--a coalition of both broker and ethereal cartels who seek to reclaim K'aresh . The Trust is in desperate need of one of your skills, . The Shadowguard assaults our city and threatens the work of the eco-dome project. Please accompany me.",objectivesText="Accompany Locus-Walker and Alleria to Tazavesh.",starts={{npcID=233603,x=0.42,y=0.27,zoneID=14771}},ends={{npcID=233706,x=0.596,y=0.836,zoneID=15781}},coords={x=0.42,y=0.27,source="quest_giver",zoneID=14771},questType="standard"},
[84958] = {id=84958,name="Beasts Unbound",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="I am Ta'ka , supplier of rare creatures destined to repopulate my homeland. At least, I was until some of them escaped their translocation cages! This cannot stand! These creatures are vital. If you could assist me with capturing them, I'd be quite appreciative. Engage them in combat and subdue them. The capture device I've provided will automatically translocate them back to my care once they are on the verge of defeat.",objectivesText="Defeat escaped creatures in Tazavesh to return them to Ta'ka . Progress: Have you finished capturing the escaped beasts?",starts={{npcID=230954,x=0.568,y=0.73,zoneID=15781}},ends={{npcID=230954,x=0.568,y=0.73,zoneID=15781}},coords={x=0.568,y=0.73,source="quest_giver",zoneID=15781},questType="standard"},
[84959] = {id=84959,name="Lost Lines of Defense",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="This is not a good day! Not at all. My whole shipment of barrier projectors was ransacked! Most of them are gone, and it seems whatever the culprits didn't take, they destroyed. These barrier projectors are essential for securing the wild places on K'aresh , and even the city of Tazavesh. Our efforts are in jeopardy! Please, if you can find any of my shipments it would help us get our efforts back on track.",objectivesText="Collect 8 Stolen Barrier Projectors for Ba'ver . Progress: Have you located my barrier projectors?",starts={{npcID=230955,x=0.532,y=0.644,zoneID=15781}},ends={{npcID=230955,x=0.532,y=0.644,zoneID=15781}},coords={x=0.532,y=0.644,source="quest_giver",zoneID=15781},questType="standard"},
[84960] = {id=84960,name="The Darkness Among Us",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Alleria, ... Have you sensed it? The Void lingers in all of this. Whoever is pulling the strings is cloaked in shadow, hiding from us. Come, let's seek them out and drag them into the light before they strike.",objectivesText="Investigate the Void Presence and locate the culprits behind the many troubles in Tazavesh. Progress: We need to find the hidden Shadowguard, <name>.",starts={{npcID=233706,x=0.596,y=0.836,zoneID=15781}},ends={{npcID=230604,x=0.596,y=0.834,zoneID=15781}},coords={x=0.596,y=0.836,source="quest_giver",zoneID=15781},questType="standard"},
[84961] = {id=84961,name="Barriers to Entry",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Those barrier projectors we recovered? We need them now. Place them at key points to reinforce the city shield and block more portals from forming. Move swiftly, . This may be our only chance to stop the Shadowguard from flooding in.",objectivesText="Place 8 Barrier Projectors around Tazavesh. Progress: Did you place the barrier projectors ? We need to slow down the invasion. Quickly!",starts={{npcID=234596,x=0.54,y=0.632,zoneID=15781}},ends={{npcID=234483,x=0.375,y=0.399,zoneID=15781}},coords={x=0.54,y=0.632,source="quest_giver",zoneID=15781},questType="standard"},
[84963] = {id=84963,name="Sealing the Shadows",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="No, no, no! The Shadowguard are ransacking the city and our defenses are crumbling! We even invested in new security golems after the city was last breached, but we haven't had time to activate them. Wait... I have an idea. The Shadowguard--some of them must have looted entropic cores that we can use to activate the golems. Please, you must take them down and retrieve those cores. We need to get those golems online to protect our investments! Uh, I mean, our city!",objectivesText="Collect 5 Saturated Entropic Cores from Shadowguard within Tazavesh. Progress: Got those cores that Om'en wanted?",starts={{npcID=234601,x=0.54,y=0.634,zoneID=15781}},ends={{npcID=234483,x=0.375,y=0.399,zoneID=15781}},coords={x=0.54,y=0.634,source="quest_giver",zoneID=15781},questType="standard"},
[84964] = {id=84964,name="Heroes Among Shadow",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="! These people may not be my own, but we cannot stand by while the Shadowguard cut them down. You and I, we can make a difference! We need to get out there, rescue the civilians, and bring them to safety. The city may be in chaos, but we can still be the shield they need.",objectivesText="Rescue 8 Tazavesh Civilians . Progress: The people are still out there, <name>!",starts={{npcID=234602,x=0.538,y=0.632,zoneID=15781}},ends={{npcID=234483,x=0.375,y=0.399,zoneID=15781}},coords={x=0.538,y=0.632,source="quest_giver",zoneID=15781},questType="standard"},
[84965] = {id=84965,name="Core Contributions",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="The entropic cores we collected will be crucial in our defense. Use the entropic cores to activate the market guardians scattered around the city. Once reactivated, these golems will join our fight and help us push back the invaders. Time is of the essence, . The fate of Tazavesh rests in your hands.",objectivesText="Activate 5 Market Guardians scattered around Tazavesh. Progress: Any of the guardians we activate should help stabilize the situation.",starts={{npcID=234483,x=0.375,y=0.399,mapID=2472}},ends={{npcID=234483,x=0.375,y=0.399,mapID=2472}},coords={x=0.375,y=0.399,source="quest_giver",mapID=2472},questType="standard"},
[84967] = {id=84967,name="The Shadowguard Shattered",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="The commander of the Shadowguard, Shadowlord Al'zar , has assaulted this shelter of the Trust. I am preoccupied with assisting these injured brokers. I dare not leave, or their soul's energy will pour out. I must depend on you, . Venture forth and eliminate Shadowlord Al'zar . His demise will cripple the Shadowguard's assault on Tazavesh. The fate of the city rests on your shoulders.",objectivesText="Kill Shadowlord Al'zar in Tazavesh. Progress: Go. We will come as soon as we can.",starts={{npcID=234620,x=0.376,y=0.744,zoneID=15781}},ends={{npcID=234620,x=0.376,y=0.744,zoneID=15781}},coords={x=0.376,y=0.744,source="quest_giver",zoneID=15781},questType="standard"},
[84972] = {id=84972,name="Chipping the Void",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Greetings. I am Driruj . I think you could help with a project of mine. The nearby expanse of purple-hued crystal is ripe with potential. The void-infused glass could have many uses, from being a spell reagent to being melted down for crafts. I can't get near it myself, but someone like you will have no trouble at all! Bring me back some samples of the void glass so I can assess their worth to future buyers.",objectivesText="Collect 6 Void Glass Samples from the Clefts of Unreality. Progress: I am preparing to move off world before what's left of K'aresh crumbles away. There are many potential uses, and therefore potential markets, for this newly created void glass. Potential equals profit, and profit means I can make a new life on a less volatile world.",starts={{npcID=231162,x=0.766,y=0.342,zoneID=15336}},ends={{npcID=231162,x=0.766,y=0.342,zoneID=15336}},coords={x=0.766,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[84973] = {id=84973,name="Of Motes and Husks",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Regrettably, the void glass was too unstable. However, I have another idea. I believe I can stabilize the glass, but only at the moment of its creation. First, I need motes from the wyrms outside the eco-dome to power my device. While you're out there, hunt down some of those krolusks as well. Their husks can be ground down to make a pleasing beverage for which the folk in Shattrath will pay the highest of prices.",objectivesText="Collect 4 Dune Wyrm essences and 6 Krolusk shells. Progress: Anything can be turned into profit, if you have the right market. It's all about knowing your buyers and finding that which they most desire. I still think the void glass will be the most lucrative for me, but it needs to be able to hold together more solidly.",starts={{npcID=231162,x=0.766,y=0.342,zoneID=15336}},ends={{npcID=231162,x=0.766,y=0.342,zoneID=15336}},coords={x=0.766,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[84974] = {id=84974,name="Shards of Hope",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I still believe void-infused glass is my ticket out of here. The problem lies in the creation process itself. The motes you brought me can help stabilize the glass with the help of void energy. Lucky for us, there are numerous void surges on the edges of the glass crevasse. I have charged a device with the motes. All you need to do is channel void energy through it! Stand where a surge is about to happen and then collect the glass that's formed. Easy! Oh, it might tingle a bit...",objectivesText="Collect 20 Void Shards. Progress: There are many potential uses, and therefore potential markets, for newly created void glass. If we can get this right, I should be set up comfortably in a new home by week's end! If you hold the device while standing in the void surges, the energy from the motes should help create more stable fragments.",starts={{npcID=231162,x=0.766,y=0.342,zoneID=15336}},ends={{npcID=231162,x=0.766,y=0.342,zoneID=15336}},coords={x=0.766,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[84985] = {id=84985,name="Not Ready on Set",level=10,requiredLevel=30,faction="both",expansion=10,zoneID=11510,mapID=71,description="Oh , I am glad to see you again. My superiors have informed me that I'm responsible not only for the guests here, but for everyone putting on celebrations! Now I'm hearing that Dapperdew in Ardenweald is trying to put on a new play and running into problems. Would you mind checking in on the situation? I can hardly manage this celebration, let alone whatever is happening in the Shadowlands.",objectivesText="Find Dapperdew in Ardenweald.",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440}},ends={{npcID=171743,x=0.414,y=0.448,zoneID=11510}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[84993] = {id=84993,name="Devourer Attack: The Oasis",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,objectivesText="Defend against the devourer attack",questType="standard"},
[84996] = {id=84996,name="Vereesa's Tale",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=14717,mapID=2248,description="We came here so Vereesa could get closer to the source of her visions. Unfortunately, it has only made them stronger, not clearer. But this is her story. She should be the one to tell it.",objectivesText="Hear Vereesa Windrunner 's tale.",starts={{npcID=231039,x=0.286,y=0.446,zoneID=14717}},ends={{npcID=233252,x=0.266,y=0.422,zoneID=14717}},coords={x=0.286,y=0.446,source="quest_giver",zoneID=14717},questType="standard"},
[84997] = {id=84997,name="What Might Come",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=14717,mapID=2248,description="Thank you for coming with us, . I'm long overdue in saying goodbye to my dear Rhonin.",objectivesText="Witness Vereesa's ceremony.",starts={{npcID=233252,x=0.266,y=0.422,zoneID=14717}},ends={{npcID=233314,x=0.266,y=0.424,zoneID=14717}},coords={x=0.266,y=0.422,source="quest_giver",zoneID=14717},questType="standard"},
[84998] = {id=84998,name="Bringer of the Void",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=14717,mapID=2248,description="Go with... Arator. Slay... their leader.",objectivesText="Slay Voidbringer Aqu'lir .",starts={{npcID=233314,x=0.266,y=0.424,zoneID=14717}},ends={{npcID=233314,x=0.266,y=0.424,zoneID=14717}},coords={x=0.266,y=0.424,source="quest_giver",zoneID=14717},questType="standard"},
[85001] = {id=85001,name="Blessings Be Upon You",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,mapID=2248,description="These innocents were simply trying to clean up the ruins, but the cultists are slaughtering them. We must come to their aid! Champion, I am certain that you and I can do this if we work together.",objectivesText="Help Arator to rescue 8 Dalaran Custodians from the clutches of the Twilight's Blade. Progress: These poor souls are imperiled through no fault of their own!",starts={{npcID=233312,x=0.266,y=0.424,zoneID=14717}},ends={{npcID=233312,x=0.266,y=0.424,zoneID=14717}},coords={x=0.266,y=0.424,source="quest_giver",zoneID=14717},questType="standard"},
[85002] = {id=85002,name="Off to Tazavesh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2248,description="It's imperative we seek my mother's counsel. But before we can do that, we'll have to find her. Last I heard, she was out hunting in the Great Dark Beyond on a world known as K'aresh. Lucky for us, I thought ahead and asked Khadgar for a portal scroll to go directly there. I'll meet you on the other side.",objectivesText="Regroup with Arator in Tazavesh, the Veiled Market, on K'aresh.",starts={{npcID=233312,x=0.266,y=0.424,zoneID=14717}},ends={{npcID=231266,x=0.602,y=0.914,zoneID=15781}},coords={x=0.266,y=0.424,source="quest_giver",zoneID=14717},questType="standard"},
[85003] = {id=85003,name="Restoring Operational Efficiency",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Locus-Walker was brought into the Trust to handle such a violent crisis of the Void. He says you are some kind of hero or champion. Good. We are in need of such a thing. Tazavesh is under threat from the Void. The Shadowguard! They threaten the work of the Trust and my reputation as an administrator.",objectivesText="Help the brokers of Tazavesh by assisting with their issues.",starts={{npcID=230604,x=0.596,y=0.834,zoneID=15781}},ends={{npcID=230604,x=0.596,y=0.834,zoneID=15781}},coords={x=0.596,y=0.834,source="quest_giver",zoneID=15781},questType="standard"},
[85006] = {id=85006,name="Those We Have Lost",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Ah, traveler! This was one of the first locations to show a response to our attempts to rejuvenate the land. We're actively studying why it happened at this location in particular. I have another experiment I wish to run, but I need some extra sources of power. The souls that litter the dunes are unfortunately lost, but we may let them serve one last time by using their energy.",objectivesText="Collect Flickering Essence . Progress: How did the collecting go?",starts={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},ends={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},coords={x=0.518,y=0.648,source="quest_giver",zoneID=15336},questType="standard"},
[85007] = {id=85007,name="Extended Reach",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I'm very curious on why the influence of this restoration stopped where it did, as are my fellow colleagues. We set up some devices at the edge of the dunes to track the fluctuation in various energy types. They have probably sat out there long enough for an initial reading. Could you go gather that info for me?",objectivesText="Gather readings from the Broker Pylons. Progress: Hopefully the devices were easy to find?",starts={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},ends={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},coords={x=0.518,y=0.648,source="quest_giver",zoneID=15336},questType="standard"},
[85008] = {id=85008,name="Machinations of Memory",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Well, the readings aren't anything to be concerned about... So we'll move on to the next step of my experiment. This console here is the central piece of our system to rejuvenate the area. I'm hoping that if we hook it up to a significant charge, it may stabilize the area even more. Could you help me set up the energy containers as I adjust the machine?",objectivesText="Interact with the console. Progress: Yes?",starts={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},ends={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},coords={x=0.518,y=0.648,source="quest_giver",zoneID=15336},questType="standard"},
[85009] = {id=85009,name="Those We Have Yet to Save",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The fauna here seem to be the same in shape as what would have been found nearby when K'aresh was still intact, but they are acting rather oddly for their species. I wonder if we could give them one last push and fully bring them into being. Take the last of the energy. I have a device that should let you channel it into them.",objectivesText="Recharge 6 Flickering Ephemera . Progress: Have you finished our experiment?",starts={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},ends={{npcID=231314,x=0.518,y=0.648,zoneID=15336}},coords={x=0.518,y=0.648,source="quest_giver",zoneID=15336},questType="standard"},
[85011] = {id=85011,name="Where in K'aresh is Alleria Windrunner?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="While you were on your way, I took the liberty to ask around. These brokers seem friendly enough, but be warned... part of the city is still under attack by a group of ethereals known as the Shadowguard. I managed to get a lead on a few traders who might have crossed paths with my mother recently. We should go before her trail runs cold.",objectivesText="Discover the location of Alleria Windrunner by asking around Tazavesh, the Veiled Market. Progress: <Umbric looks at you with curiosity.>",starts={{npcID=231266,x=0.602,y=0.914,zoneID=15781}},ends={{npcID=234263,x=0.512,y=0.198,zoneID=15781}},coords={x=0.602,y=0.914,source="quest_giver",zoneID=15781},questType="standard"},
[85018] = {id=85018,name="Packets of Promises",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I will not wait a moment longer. I have arranged for transport outside of the dome, and it will be arriving soon. Will you meet me outside? I have one last thing I would ask of you.",objectivesText="Talk to Driruj . Progress: Driruj is a fool! He's likely to burn through his wrappings with his hot-headedness. He'll be back.",starts={{npcID=231162,x=0.766,y=0.342,zoneID=15336}},ends={{npcID=231161,x=0.766,y=0.342,zoneID=15336}},coords={x=0.766,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85019] = {id=85019,name="An Outcast's Request",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I felt it. Something happened in that dome. Something--no... someone... My friend, I do not know your name or where you came from, but this is it! It has to be! The ruined town of Sufaad to the southeast of here was where I resided as a Wastelander. Please go there and bring back my scepter, prayer book, and ceremonial bowl. There was no time to pack. I just ran, so the items could be anywhere within the town.",objectivesText="Retrieve Outcast Hizfran 's belongings from North Sufaad. Progress: Once I have my belongings, I will be able to walk the path of the old ways. It is time to retake my true oath.",starts={{npcID=231422,x=0.776,y=0.398,zoneID=15336}},ends={{npcID=231422,x=0.776,y=0.398,zoneID=15336}},coords={x=0.776,y=0.398,source="quest_giver",zoneID=15336},questType="standard"},
[85020] = {id=85020,name="The Blood of K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="In the old days, we used certain deep-mined salts in cleansing processes and rituals. As you can see around you, mining is no longer valid, as these fragile rocks are hanging on to each other. On the day of the Devouring of K'aresh , a never-before-seen mineral surfaced. The Blood of K'aresh is a blue mineral with some deposits to the west of here. Even though K'aresh is dying, I should follow the old traditions to the end. Please collect deposits from sand striders or veins and bring them to me.",objectivesText="Collect 20 Blood of K'aresh deposits . Progress: Although the Blood of K'aresh may not have existed prior to the Devouring like other minerals, it came from within our world and thus should still be usable for the process.",starts={{npcID=231422,x=0.776,y=0.398,zoneID=15336}},ends={{npcID=231422,x=0.776,y=0.398,zoneID=15336}},coords={x=0.776,y=0.398,source="quest_giver",zoneID=15336},questType="standard"},
[85021] = {id=85021,name="Cleansing the Void",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Now that you have brought me all that I need, the ritual of return can begin. You see, stranger, the items you recovered were stowed in my hovel for over a hundred thousand years. The Void that surrounds us leaves its mark on everything it touches. While grinding the mineral removed the impurities of the Void, I still need to cleanse myself and the items. Please help me with the ritual. I do not foresee any distractions or issues. We are very close now.",objectivesText="Help Outcast Hizfran with the ritual of return. Progress: Almost there, stranger... <name>. That is your name, is it not?",starts={{npcID=231422,x=0.776,y=0.398,zoneID=15336}},ends={{npcID=231699,x=0.778,y=0.394,zoneID=15336}},coords={x=0.776,y=0.398,source="quest_giver",zoneID=15336},questType="standard"},
[85022] = {id=85022,name="Priest of the Old Ways",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description=", I suspect that a living manifestation of the Void came out of myself and the items. I cannot, with good conscience, take on the mantle of a priest of the old ways while these manifestations are out there. I have a final request for you. Go find these creatures and slay them. Then, I will be able to reassume the mantle of priest.",objectivesText="Slay 3 void manifestations. Progress: One step, <name>. One last step.",starts={{npcID=231699,x=0.778,y=0.394,zoneID=15336}},ends={{npcID=231774,x=0.778,y=0.392,zoneID=15336}},coords={x=0.778,y=0.394,source="quest_giver",zoneID=15336},questType="standard"},
[85025] = {id=85025,name="Operation Toy Rescue",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=440,mapID=71,description="A sneaky thief has taken some of my friends' toys! You're a good sleufer now, right? Can you help my friend Yennu find his stolen toy? You'll find him on da Dragon Isles.",objectivesText="Find the missing toys.",starts={{npcID=226684,x=0.632,y=0.524,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=440},questType="standard"},
[85027] = {id=85027,name="Lorewalking: The Protectorate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15969,mapID=84,description="I have long been curious about the ethereals, who first came to Pandaria when the Mists parted. A mysterious group, they are reticent to speak of their history... but I am perhaps more persistent than most in my inquiries. So! Who are these strangers? What do we know of their history? We must piece it together, it seems. But our tale begins in Outland, where a hero joined a group of ethereals in Netherstorm to aid them with their cause.",objectivesText="Follow Cho's guidance to learn about the ethereals.",starts={{npcID=232441,x=0.642,y=0.162,zoneID=1519},{npcID=232441,x=0.542,y=0.566,zoneID=1637},{npcID=232441,x=0.496,y=0.316,zoneID=14771}},ends={{mapID=84,npcID=232441,x=0.642,y=0.162}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[85028] = {id=85028,name="Lorewalking: The Brokers",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=10565,mapID=84,description="The ethereals are most fascinating indeed, but in my studies I have encountered another race of creatures who share many similarities with the ethereals. I feel we should speak of them as well--the brokers. They share a nomadic nature, a desire to collect rare and unusual antiquities, and a penchant for trade. Yet the brokers do not exist on Azeroth. Instead, they dwell in the Shadowlands... the land of death.",objectivesText="Follow Cho's guidance to learn about the brokers.",starts={{x=0.284,y=0.472,mapID=882,npcID=231702}},ends={{npcID=232441,x=0.642,y=0.162,zoneID=1519},{npcID=232441,x=0.542,y=0.566,zoneID=1637},{npcID=232441,x=0.496,y=0.316,zoneID=14771}},coords={mapID=84,source="quest_giver",x=0.642,y=0.162},questType="standard"},
[85029] = {id=85029,name="Lorewalking: Locus-Walker",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15969,mapID=2393,description="While the Protectorate of Outland may have stopped Dimensius and Salhadaar, the Ethereum remained. And as Salhadaar had wished, they chose to embrace the Void. Not just embrace it--become it. It twisted them into shadows of themselves, consumed with the pursuit of power. But there was one ethereal, Locus-Walker, that sought to harness the Void for more altruistic purposes. His history is entwined with an elf from our world--Alleria Windrunner.",objectivesText="Follow Cho's guidance to learn about void ethereals.",starts={{x=0.601,y=0.317,mapID=109,npcID=231702}},ends={{x=0.601,y=0.317,mapID=109,npcID=231702}},coords={mapID=109,x=0.601,y=0.317},questType="standard"},
[85032] = {id=85032,name="What Is Left of Home",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath . I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal. We can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.",objectivesText="Speak to citizens of Tazavesh and members of the Trust. Progress: There will be a day when K'aresh is restored.",starts={{npcID=231128,x=0.378,y=0.744,zoneID=15781}},ends={{npcID=230700,x=0.342,y=0.108,zoneID=15781}},coords={x=0.378,y=0.744,source="quest_giver",zoneID=15781},questType="standard"},
[85035] = {id=85035,name="Locus-Walker, Telogrus Ranger",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=9415,mapID=84,description="I apologize for interrupting your conversation, mortal. But it was your discussion that drew Ve'nari's attention. She hears much, after all--especially when her name is involved. I have been sent with an object for you to deliver to Locus-Walker . He is an ethereal that dwells within Telogrus Rift. I believe the \"void elves\" of your world also reside there. There is no need to travel. I will provide a portal to where you must go. Will you assist her in this task?",objectivesText="Deliver Ve'nari's device to Locus-Walker in Telogrus Rift. Progress: Why have the Shadowguard come here, of all places?",starts={{npcID=234111,x=0.64,y=0.16,zoneID=1519},{npcID=234111,x=0.542,y=0.568,zoneID=1637},{npcID=234111,x=0.494,y=0.312,zoneID=14771}},ends={{npcID=231706,x=0.274,y=0.282,zoneID=9415}},coords={x=0.64,y=0.16,source="quest_giver",zoneID=1519},questType="standard"},
[85036] = {id=85036,name="Veni Vidi Ve'nari",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,mapID=84,description="A broker sent you with this device? And they were sent to you by Ve'nari? This does not bode well.",objectivesText="Witness the conversation with Locus-Walker . Progress: I have much to think about, my friend--and much to add to my studies!",starts={{npcID=231706,x=0.274,y=0.282,zoneID=9415}},ends={{npcID=232441,x=0.642,y=0.162,zoneID=1519},{npcID=232441,x=0.542,y=0.566,zoneID=1637},{npcID=232441,x=0.496,y=0.316,zoneID=14771}},coords={x=0.274,y=0.282,source="quest_giver",zoneID=9415},questType="standard"},
[85037] = {id=85037,name="That's a Wrap",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The possibilities have begun to narrow. We are on the cusp of victory. Are you ready, my champion, to fulfill your oath against Dimensius? Xal'atath chuckles.> Very well. I have some promises of my own to keep. Let us formalize our defense against Dimensius by the platform toward the manaforge.",objectivesText="Speak to Xal'atath to assemble the Reshii Ribbons . Progress: What is Xal'atath 's game here? She had ample opportunity to trick us.",starts={{npcID=231520,x=0.442,y=0.184,zoneID=15336}},ends={{npcID=231522,x=0.428,y=0.214,zoneID=15336}},coords={x=0.442,y=0.184,source="quest_giver",zoneID=15336},questType="standard"},
[85039] = {id=85039,name="Compromised Containment",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Somehow, an artifact in the Menagerie has broken open, unleashing a swarm of furious arcane creatures. They're wreaking havoc, and havoc is bad for the project. I need someone capable of getting this situation under control with no questions asked. If you can get down there, clear your way through the creatures, and seal that artifact... I'll make it worth your while.",objectivesText="Kill Arcane Creatures and seal the Unstable Artifact . Progress: Have you completed your assignment?",starts={{npcID=231564,x=0.566,y=0.728,zoneID=15781}},ends={{npcID=231564,x=0.566,y=0.728,zoneID=15781}},coords={x=0.566,y=0.728,source="quest_giver",zoneID=15781},questType="standard"},
[85043] = {id=85043,name="The Toy Thief",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=440,mapID=71,description="My toy! It's been stolen! We have to figure out who da culprit is before they take more toys!",objectivesText="Discover the toy thief. Progress: Did you find my toy?",starts={{npcID=226684,x=0.632,y=0.524,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=440},questType="standard"},
[85044] = {id=85044,name="DEPRECATED",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[85047] = {id=85047,name="A Pirate Predicament",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="I was recently made aware of a small group of Booty Bay Buccaneers who have landed and set up camp just outside the celebration area to the north. Pirates aren't inherently a problem, per se, but they do introduce an element of chaotic unpredictability. I know you're busy, but would you mind checking on them to see if they need any assistance?",starts={{npcID=232405,x=0.63,y=0.502,mapID=71},{npcID=232406,x=0.63,y=0.502,mapID=71},{npcID=232407,x=0.63,y=0.502,mapID=71},{npcID=232408,x=0.63,y=0.502,mapID=71}},ends={{npcID=231413,x=0.608,y=0.448,mapID=71}},coords={x=0.63,y=0.502,source="quest_giver",mapID=71},questType="standard"},
[85052] = {id=85052,name="A Lucrative Opportunity",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Most fortuitous greetings, offworlder! I have been stuck for an eon at this post checking manifests one after another. This is not real trade. Real trade is done on the streets of Tazavesh! It just so happens that a contact of mine from your world was unloading waste cargo. I bought the whole supply. Expired storage contracts of some sort. However, I know better than to be trading without a permit. It would bring good fortune to my endeavor to have your help with this. Can I count on you, ?",objectivesText="Seek out Cartel Boss Xy'eolm in Tazavesh on K'aresh .",starts={{npcID=231674,x=0.48,y=0.246,zoneID=15781}},ends={{npcID=232008,x=0.504,y=0.192,zoneID=15781}},coords={x=0.48,y=0.246,source="quest_giver",zoneID=15781},questType="standard"},
[85053] = {id=85053,name="Obtaining Permits",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="There is a difference between securing a permit and securing permission to sell in Tazavesh. Xy'vez is a licensed dealer. He can buy and sell as he pleases in accordance with the authorities. However, I am glad he knows his place. If you are on my streets, you need my permission. Not everyone knows this. Cartel Ba likes to test the waters. I'll award your permission if you teach them a lesson.",objectivesText="Obtain permission for Vaultkeeper Xy'vez in Tazavesh. Progress: Have you done what I asked?",starts={{npcID=232008,x=0.504,y=0.192,zoneID=15781}},ends={{npcID=232008,x=0.504,y=0.192,zoneID=15781}},coords={x=0.504,y=0.192,source="quest_giver",zoneID=15781},questType="standard"},
[85054] = {id=85054,name="Articles of Acquisition",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Take this ledger to Xy'vez. Let him know I expect dinars upfront and on time. There are to be no discrepencies between my records and his, do you understand? You may head to the market to inform him. Knowing traders like him, he'll have already found a spot to set up shop. This venture has my blessing. Don't let it become unprofitable or we'll be seeing each other again, offworlder.",objectivesText="Return to Vaultkeeper Xy'vez in the market of Tazavesh on K'aresh . Progress: Do we have good news, offworlder?",starts={{npcID=232008,x=0.504,y=0.192,zoneID=15781}},ends={{npcID=232057,x=0.448,y=0.358,zoneID=15781}},coords={x=0.504,y=0.192,source="quest_giver",zoneID=15781},questType="standard"},
[85055] = {id=85055,name="Expired Goods",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Now then, on to business. I hear tale that your world is full of heroes on adventure. And where there's adventurers, there's need for storing their treasures. Always. Thus, you have turned to our kin to keep them safely deposited between realms. Yet not one of you read the contract. We have since ceased such services and returned goods to their owners. You and I, , are selling opportunities to purchase what remains. Blind of course. Help me prepare.",objectivesText="Help Vaultkeeper Xy'vez prepare the void storage vaults for sale in Tazavesh on K'aresh . Progress: Always so much to prepare before a first sale.",starts={{npcID=232057,x=0.448,y=0.358,zoneID=15781}},ends={{npcID=232057,x=0.448,y=0.358,zoneID=15781}},coords={x=0.448,y=0.358,source="quest_giver",zoneID=15781},questType="standard"},
[85059] = {id=85059,name="A Piece of the Action",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,mapID=2369,description="Game on table look like fun. But Skaggit no want Jack to play. Maybe you can? Sneak in and put a bet down. We see who wins!",objectivesText="Contribute to an event on the Siren Isle Command Map. Progress: Did you put down a bet?",starts={{npcID=227817,x=0.694,y=0.436,zoneID=10416}},ends={{npcID=227817,x=0.694,y=0.436,zoneID=10416}},coords={x=0.694,y=0.436,source="quest_giver",zoneID=10416},questType="standard"},
[85060] = {id=85060,name="Pirate Foods and Superstitions",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5287,mapID=71,description="Our trusty cook, Cooktholomew, was lost at sea. Quite tragic that was, but now all the more tragic for us here! We don't dare set sail again without the lucky feast ol' Cooktholomew would prepare for us before each voyage. We've tried to make out his scribbles, but alas, we only managed to make the ink run. Me matey here swears he heard Cooktholomew say once he only brought copies out to sea. If that be true, the originals must be back in Booty Bay, somewhere near his bunk!",objectivesText="Help the Booty Bay Buccaneers figure out how to recreate Cooktholomew's lucky feast. Progress: Cooktholomew and I have spun many a yarn talking about words and language. He was a lot deeper than most folk around here gave him credit for.",starts={{npcID=231413,x=0.608,y=0.448,zoneID=440}},ends={{npcID=105637,x=0.412,y=0.732,zoneID=5287}},coords={x=0.608,y=0.448,source="quest_giver",zoneID=440},questType="standard"},
[85071] = {id=85071,name="Skyrocketing Sprint",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.39,y=0.287,mapID=2346,npcID=231793}},ends={{x=0.39,y=0.287,mapID=2346,npcID=231793}},coords={mapID=2346,x=0.39,y=0.287},questType="standard"},
[85075] = {id=85075,name="To Stormsong",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=9042,mapID=2371,description="We have need of more species to help pollinate. I have studied your world, and I believe your bees in Stormsong Valley will be best. Not the fire ones though. Too dangerous. Bring back some bees and we can see if they are suitable. Take this communicator in case I need to contact you.",objectivesText="Travel to Stormsong Valley in Kul Tiras to get some bees for Ve'nari . Progress: Where did you come from?",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231919,x=0.484,y=0.612,zoneID=15336},{npcID=231919,x=0.724,y=0.698,zoneID=9042}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85076] = {id=85076,name="Don't Bee Crazy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="Something is agitating the bees, and I suspect it's these honey-crazed maulers ! Take some down and see if it helps. Even if it doesn't, you're doing the world a favor. They are completely out of control!",objectivesText="Slay 10 maulers in the Highland Flats and Mildenhall Meadery. Progress: The poor bees...",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85077] = {id=85077,name="Sticky Fingers",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="Stormsong has some of the biggest and best pollinators on Azeroth--when they aren't angry at least. If you are looking to take these, you'll need to try to calm them down. It looks like their honey is being stolen. Try to take some honey back from those honey... blob... things? Can't hurt right? Sorry. I'm more of a plant person than a bee person. They just come with the territory!",objectivesText="Collect 7 Honey Globules at the Mildenhall Meadery. Progress: Did you get the honey?",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85078] = {id=85078,name="Bee in the Bonnet",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="While you were out, I scouted some of the smaller bee hives . They all look like they've suffered damage. We should investigate them. Maybe that's the cause of their aggression?",objectivesText="Investigate 4 Bee Hives . Progress: What could have driven something to destroy so many hives?",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85079] = {id=85079,name="Such a Sleebee-head",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="We need to deal with the hive guardians one way or another if we are going to investigate this place. I do hope we don't have to kill them.",objectivesText="Tranquillize or slay 5 Hive Guardians . Progress: We should keep as many bees alive as possible.",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85080] = {id=85080,name="An Un-Bee-lievable Solution",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="If we can save the smaller bees, they can join the queen's colony. I just wish we had some way of capturing or transporting them. Do you have any ideas? Perhaps that friend of yours has something? If you come across any of the larger bees... I worry they may be beyond saving. Do what you have to do.",objectivesText="Collect the Anima Vacuum and use it to vacuum up 15 Honey Bees. Progress: Have you rescued the bees?",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85081] = {id=85081,name="Beehemian Rhapsody",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="We need a way to lure out the queen so we can take her away from here. Oh! The honey you gathered earlier! Put that out to lure her, then catch her in this ventilated jar. You said you were after bees? I think she'd be a great fit.",objectivesText="Place the Honey Pot and use it to lure out and rescue the Queen Bee. Progress: If we can get her to safety, and bring some of her hive, they can rebuild.",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85082] = {id=85082,name="To K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="We've secured the queen and apparently sent some bees to K'aresh. So... How do we get there?",objectivesText="Return to the Oasis on K'aresh.",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85083] = {id=85083,name="Photogra-Bee",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="The bees seem to be doing very well in this new environment. They are even starting to pollinate the plants here. We should document it. It's not science if you don't write it down. You'll find them mostly around the plants.",objectivesText="Document 10 Honey Bees. Progress: Have you documented the bees?",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85084] = {id=85084,name="Bee Strong",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="It's taking the hive a while to get up and running, and they are low on honey . Thankfully, you gathered plenty of honey back in Stormsong! Could you feed the queen?",objectivesText="Feed the Queen Bee. Progress: I think the bees will do well here.",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85096] = {id=85096,name="Skyrocketing Sprint - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.39,y=0.287,mapID=2346,npcID=231793}},ends={{x=0.39,y=0.287,mapID=2346,npcID=231793}},coords={mapID=2346,x=0.39,y=0.287},questType="standard"},
[85097] = {id=85097,name="The Heaps Leap",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.338,y=0.762,mapID=2346,npcID=231879}},ends={{x=0.338,y=0.762,mapID=2346,npcID=231879}},coords={mapID=2346,x=0.338,y=0.762},questType="standard"},
[85098] = {id=85098,name="The Heaps Leap - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.338,y=0.762,mapID=2346,npcID=231879}},ends={{x=0.338,y=0.762,mapID=2346,npcID=231879}},coords={mapID=2346,x=0.338,y=0.762},questType="standard"},
[85099] = {id=85099,name="Scrapshop Shot",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.392,y=0.114,mapID=2346,npcID=231893}},ends={{x=0.392,y=0.114,mapID=2346,npcID=231893}},coords={mapID=2346,x=0.392,y=0.114},questType="standard"},
[85100] = {id=85100,name="Scrapshop Shot - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.392,y=0.114,mapID=2346,npcID=231893}},ends={{x=0.392,y=0.114,mapID=2346,npcID=231893}},coords={mapID=2346,x=0.392,y=0.114},questType="standard"},
[85101] = {id=85101,name="Rags to Riches Rush",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.255,y=0.421,mapID=2346,npcID=231900}},ends={{x=0.255,y=0.421,mapID=2346,npcID=231900}},coords={mapID=2346,x=0.255,y=0.421},questType="standard"},
[85102] = {id=85102,name="Rags to Riches Rush - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.255,y=0.421,mapID=2346,npcID=231900}},ends={{x=0.255,y=0.421,mapID=2346,npcID=231900}},coords={mapID=2346,x=0.255,y=0.421},questType="standard"},
[85109] = {id=85109,name="Renowned with the K'aresh Trust",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Traveler, your aid to K'aresh will never be forgotten. You have our deepest gratitude. As a token of our appreciation, we have prepared a gift for you. Seek out Om'sirik in Tazavesh. He will see that it reaches your hands.",objectivesText="Speak with Om'sirik in Tazavesh.",starts={{x=0.406,y=0.292,mapID=2472,npcID=235252}},ends={{npcID=235252,x=0.406,y=0.292,zoneID=15781}},coords={mapID=2472,source="quest_giver",x=0.406,y=0.292},questType="standard"},
[85151] = {id=85151,name="In Her Shadow",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The two of you fell into the trap I set for Shadowlord Vesheen . I need to know what his orders are from Salhadaar and what he knows about Xal'atath's plans. Now, the three of us are going to sneak into this camp and see what we can discover. We're not here to fight--just some reconnaissance. I don't want him to know that I'm after him.",objectivesText="Sneak with Alleria through the camp at the Fracture of Laacuna to uncover clues about Shadowlord Vesheen . Progress: I keep retracing my steps and all I've uncovered are whispers that Xal'atath has a force amassing somewhere out in the void. I have further suspicions, but there's more to uncover.",starts={{npcID=231987,x=0.552,y=0.278,zoneID=15336}},ends={{npcID=231987,x=0.552,y=0.278,zoneID=15336}},coords={x=0.552,y=0.278,source="quest_giver",zoneID=15336},questType="standard"},
[85155] = {id=85155,name="Do You Have a Spare?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Now that we know where Vesheen is, I need a cage to put him in so I can get my answers. And I know just the person who will provide us with one. Ve'nari . You'll find her in the eco-dome called the Oasis. It's on the island off to the east. Do what you must and don't take no for an answer, .",objectivesText="Travel to the Oasis and convince Ve'nari to provide you with a cage.",starts={{npcID=231987,x=0.552,y=0.278,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.552,y=0.278,source="quest_giver",zoneID=15336},questType="standard"},
[85174] = {id=85174,name="Get Out There",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="You all saw what Gallywix can do. These weapons, this Black Blood--we have to cut him off at the source. Revilgaz, you've gotta kill their shipments coming out of your HQ. And Grimla, Venture Co. has to be involved for Nikki the Fixer to be so well-armed. Split up. , I want you with me. I've got a newsman, Dirk, you'll want to talk to in Tailgate Park. We'll need hearts and minds to take back this city. I'll be there soon.",objectivesText="Speak with Dirk Greasedealer in Tailgate Park.",starts={{npcID=225523,x=0.398,y=0.242,zoneID=15347}},ends={{npcID=226660,x=0.486,y=0.408,zoneID=15347}},coords={x=0.398,y=0.242,source="quest_giver",zoneID=15347},questType="standard"},
[85184] = {id=85184,name="Repossession is Nine-Tenths of the Law",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="A cage you say? Of course, I have one. But, it's not free. I'll need something in return. Several somethings. I believe the saying in your world is, \"You scratch my back, I'll scratch yours.\" To my point, there are Wastelanders occupying the nearby ruins. They are illegally hoarding relics of historic importance which belong to all the K'areshi. I want you to repossess them. Take my portation tags to make it all easier. However else would you carry so many? Your backpack isn't that big.",objectivesText="Use Ve'nari 's portation tags to repossess 10 Ancestral K'areshi Relics.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85185] = {id=85185,name="Those As Well",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="There are any number of stolen smaller, but still significant artifacts in the ruins at North Sufaad. While you're out there, I see no reason why you should not also retrieve them for me. I'm certain I can make the transaction worth your time. I trust this isn't beneath you... so long as the payment is sufficient.",objectivesText="Recover 6 Lesser K'areshi Artifacts from Wastelanders at North Sufaad. Progress: These lesser artifacts can also be of great importance. To the K'areshi people, of course.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85186] = {id=85186,name="A Cage for Alleria",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I do so love a bit of intrigue. Please hurry back and let me know how everything plays out with this new Shadowguard lieutenant. Actually, I might just come pay you a visit. I'm sure Alleria will get all the answers she's after this time...",objectivesText="Deliver Ve'nari's Package to Alleria at Shan'dorah. Progress: Do you have the cage? I hope Ve'nari didn't make you jump through too many hoops. Nothing's for free with her. Nothing.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=232110,x=0.608,y=0.282,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85189] = {id=85189,name="Our Day in Court",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Another series of miscellaneous and legally questionable tasks done well, ! You should really consider going into this line of work full time... whatever line of work this is exactly. I'll grab the Gnomes's signatures, and meet you back at my office. Normally I'd be willing to give you a ride, but I've got a personal errand to run first. You'll see.",objectivesText="Meet Marty Zoomcart at his office in Hovel Hill.",starts={{npcID=226894,x=0.558,y=0.348,zoneID=15347}},ends={{npcID=227018,x=0.386,y=0.338,zoneID=15347}},coords={x=0.558,y=0.348,source="quest_giver",zoneID=15347},questType="standard"},
[85190] = {id=85190,name="Settled Dust",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=40,mapID=2346,description="I'm surprised Shaw showed up in person. I thought he'd send an agent or somethin', but... maybe I should start expectin' better of people. I made sure Renzik got looked after. Got the respect he deserves. This chest took me a long time to make. A lot of tiny tools. I'm not used to detail work like that, but I got it done pretty good. I'm sure he could still pick the lock like nothin', but... Let's get him sent back home to Stormwind, yeah?",objectivesText="Speak to Gazlowe to return Renzik's ashes to Mathias Shaw.",starts={{npcID=232822,x=0.424,y=0.514,zoneID=15347}},ends={{npcID=234783,x=0.3,y=0.86,zoneID=40}},coords={x=0.424,y=0.514,source="quest_giver",zoneID=15347},questType="standard"},
[85191] = {id=85191,name="Cut After Cut",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=40,mapID=52,description="Renzik was one of my finest agents--but more than that, he was a friend. He wasn't an agent of the Stormwind crown begrudgingly fulfilling a mission in Undermine . He worked for Stormwind, but he loved Undermine . His people were his home. Not us. Help me gather up some of Renzik's things he left here. They should go back to Undermine , along with him.",objectivesText="Collect Renzik's belongings around the Westfall Lighthouse. Progress: Renzik never opened up all the way, but I saw what I needed to through the cracks.",starts={{npcID=234783,x=0.3,y=0.86,zoneID=40}},ends={{npcID=234783,x=0.3,y=0.86,zoneID=40}},coords={x=0.3,y=0.86,source="quest_giver",zoneID=40},questType="standard"},
[85192] = {id=85192,name="Coming Home",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=52,description="Renzik would want his ashes returned to Undermine . I know that for certain, and I would like to do my friend one last favor by seeing it done. I'm sure he'll like it far more than being stuffed under a marble slab in the Stormwind cemetery, far away from his people. Let's go, .",objectivesText="Meet Gazlowe and Mathias Shaw on the upper stairs of the Scrapshop in Undermine . Progress: Knowin' he always thought of Undermine as a home... That's somethin'. I could've learned a lot more from him.",starts={{npcID=234783,x=0.3,y=0.86,zoneID=40}},ends={{npcID=234801,x=0.392,y=0.234,zoneID=15347}},coords={x=0.3,y=0.86,source="quest_giver",zoneID=40},questType="standard"},
[85195] = {id=85195,name="Pirate Gastronomy",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=210,description="Here are Cooktholomew's notes deciphered. Even though this still looks strange, I am positive I deciphered it correctly. I was able to work out how much of everything you need, but it looks like he had his own names for different ingredients, so... good luck!",objectivesText="Use Rosa's Boonful Banquet translation notes to search for the ingredients. Progress: Don't ya worry. We're a patient bunch, we are.",starts={{npcID=105637,x=0.412,y=0.732,zoneID=5287}},ends={{npcID=231413,x=0.608,y=0.448,zoneID=440}},coords={x=0.412,y=0.732,source="quest_giver",zoneID=5287},questType="standard"},
[85196] = {id=85196,name="Tag, You're It",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Vesheen is up in the Khiyed Ruins to the north. The fool thinks he's so clever, but he's about to find out who he is dealing with. Wear him down and then place Ve'nari's tag on him. It will teleport him into the cage here. I'll stay here to make sure the cage works. Hurry, , before he realizes we're on to him!",objectivesText="Weaken Shadowlord Vesheen and then place Ve'nari's Portation Tag on him to teleport him into Alleria's cage. Progress: He's going to tell me everything. Too much is riding on this for half measures.",starts={{npcID=232110,x=0.608,y=0.282,zoneID=15336}},ends={{npcID=233885,x=0.608,y=0.28,zoneID=15336}},coords={x=0.608,y=0.282,source="quest_giver",zoneID=15336},questType="standard"},
[85208] = {id=85208,name="A Pirate Missive",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5287,mapID=71,description="There you are, . Someone named Scowling Rosa wants to see you in Booty Bay.",objectivesText="Pick up the notes from Scowling Rosa in Booty Bay.",starts={{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440}},ends={{npcID=105637,x=0.412,y=0.732,zoneID=5287}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[85212] = {id=85212,name="A Void Test of Wills",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="This will be dangerous. I intend to use the Void to break his will and extract what I can from his mind. , stand ready to assist. First, we'll set up some ritual devices. Then, listen for my instructions. One false move could mean our doom.",objectivesText="Assist Alleria in her void contest to break Shadowlord Vesheen 's will. Progress: It seems our war against the Void is never-ending.",starts={{npcID=233885,x=0.608,y=0.28,zoneID=15336}},ends={{npcID=233980,x=0.608,y=0.28,zoneID=15336}},coords={x=0.608,y=0.28,source="quest_giver",zoneID=15336},questType="standard"},
[85213] = {id=85213,name="Off to Tazavesh, Again",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2371,description="Now that we've helped my mother, it's time to continue on. Arator seems choked up at the idea of leaving his mother again so soon.> Ve'nari helped us before. I know it's dangerous, but maybe she can get us into the Maw to find Sylvanas?",objectivesText="Work with Arator and Ve'nari to decide how best to proceed. Progress: Well, hello there. Again.",starts={{npcID=233980,x=0.608,y=0.28,zoneID=15336}},ends={{npcID=232124,x=0.604,y=0.93,zoneID=15781}},coords={x=0.608,y=0.28,source="quest_giver",zoneID=15336},questType="standard"},
[85214] = {id=85214,name="Here Goes Something",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11400,mapID=2472,description="Getting you into the Maw to visit his auntie, Sylvanas, can be done... but at no small risk to Arator . Under no circumstance should he linger there. However, that is your business. I am in the business of keeping my slates clean, and this is something I can do for you. The engine of Tazavesh can power a gateway and allow the two of you to break into that dreadful place.",objectivesText="Use the power of the city to open a gateway to the Maw.",starts={{npcID=232124,x=0.604,y=0.93,zoneID=15781}},ends={{npcID=231030,x=0.268,y=0.378,zoneID=11400}},coords={x=0.604,y=0.93,source="quest_giver",zoneID=15781},questType="standard"},
[85229] = {id=85229,name="Rallying All Rapscallions!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha",objectivesText="Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal .",ends={{npcID=219215,x=0.554,y=0.77,zoneID=14771}},coords={mapID=2339,source="quest_giver",x=0.555,y=0.77},questType="standard"},
[85238] = {id=85238,name="Stranger on the Steps",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Please! We have to stop the Naakroans. Three of us were sent by cartel Om to install a research machine. It was only meant to help study extinct plants. At first, the Wastelanders were polite, even curious--until we tried to leave. They forced us to modify the machine. Om'musa refused and they killed him. Om'baladh and I obeyed. We should have refused as well. Once we finished, the Wastelanders let their guards down. Om'baladh said to run, so I did. He was right behind me. Please--find him.",objectivesText="Find Om'baladh . Progress: Oh, my friends. What have we done?",starts={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},ends={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},coords={x=0.57,y=0.572,source="quest_giver",zoneID=15336},questType="standard"},
[85239] = {id=85239,name="A New Devouring",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="This isn't a temple anymore--it's an abattoir. They tear souls from captives to power their rituals. Right now, they're pouring stolen energy into our machine. I think I know why. With the modifications we made, overloading the device with arcane energy will create a massive feedback loop. It'll disrupt our technomancy across K'aresh . The eco-domes will fail. Tazavesh will be defenseless. We'll be just another feast for the Naakroans. If you can disrupt their rituals, it will buy us time.",objectivesText="Disrupt the Naakroan rituals. Progress: Stop the rituals. End the suffering of their captives.",starts={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},ends={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},coords={x=0.57,y=0.572,source="quest_giver",zoneID=15336},questType="standard"},
[85240] = {id=85240,name="Only Hunger Remains",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="They think Xal'atath has returned for them--that their worship will be rewarded. They'll consume everything to prove their devotion to her. We came here for peace--to rebuild our shattered home. We have to protect the future, $p. It's all we have left. These Wastelanders are massing to raid the eco-domes. If they manage to bring down the shields, they'll pick them clean. Don't give them that chance.",objectivesText="Slay Naakroan Wastelanders. Progress: We won't let them take what we've built.",starts={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},ends={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},coords={x=0.57,y=0.572,source="quest_giver",zoneID=15336},questType="standard"},
[85241] = {id=85241,name="A Once-Proud Priest",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Their leader conducts the last ritual site. Issam the Unraveler ... I saw him live up to that name. If he uses our echo machine against us, he and his followers will tear through everything. We'll all be offerings to their absent \"god.\" Slay him and end his ritual. We can't allow a second Devouring.",objectivesText="Slay Issam the Unraveler . Progress: Killing him should stop the ritual. It has to.",starts={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},ends={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},coords={x=0.57,y=0.572,source="quest_giver",zoneID=15336},questType="standard"},
[85242] = {id=85242,name="Seasonal Refresher",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="We're back tae uncovering more things within delves! Let's get ye up to speed on new items we've found first. Then I've got some concerning information tae talk about.",objectivesText="Learn about Season 2 of Delves from the Delver's Documents, then purchase supplies from Reno Jackson and Sir Finley Mrrgglton.",starts={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={x=0.476,y=0.444,source="quest_giver",zoneID=14771},questType="standard"},
[85243] = {id=85243,name="I Want My Hat Back",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="Ye may have noticed a change in me fashion. Some goblin went and took me hat! And all the treasures we had collected so far! I'll tell ye how it all went down.",objectivesText="Listen to Brann's story of how he lost his treasures and his hat.",starts={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={x=0.476,y=0.444,source="quest_giver",zoneID=14771},questType="standard"},
[85244] = {id=85244,name="Defeating the Underpin",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15991,mapID=2339,description="This blasted \"Underpin\" took me hat! Along with all the curios we collected. It's time tae get some vengeance. We got tae get stronger if we're going tae take him down. I know he's somewhere in Undermine when yer ready tae tackle him. I'll be right there with you!",objectivesText="Increase your item level to challenge the Underpin in his tier 8 delve within Undermine.",starts={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={x=0.476,y=0.444,source="quest_giver",zoneID=14771},questType="standard"},
[85249] = {id=85249,name="A Bee Test",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=9042,mapID=2371,description="I will send your... guest... to the Atrium to handle the bees. You should check on her. No doubt she needs assistance.",objectivesText="Meet Botanist Alaenra at the Atrium.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231919,x=0.484,y=0.612,zoneID=15336},{npcID=231919,x=0.724,y=0.698,zoneID=9042}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85252] = {id=85252,name="Lorewalking: Children of the Blood",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15969,mapID=84,description="The blood elves of the Eastern Kingdoms have only taken up that name in recent years. Once, they were known as highborne, or high elves--but no more. Would that it were a pleasant tale, but in truth the name reflects upon those who have fallen and lost their lives... an unthinkable number. The blood elves, or sin'dorei, will never forget that loss. Let us remember them as well.",starts={{npcID=234616,x=0.642,y=0.162,zoneID=1519},{npcID=234616,x=0.542,y=0.566,zoneID=1637},{npcID=234616,x=0.496,y=0.316,zoneID=14771},{npcID=234616,x=0.586,y=0.708,zoneID=15969}},ends={{npcID=234616,x=0.642,y=0.162,zoneID=1519},{npcID=234616,x=0.542,y=0.566,zoneID=1637},{npcID=234616,x=0.496,y=0.316,zoneID=14771},{npcID=234616,x=0.586,y=0.708,zoneID=15969}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[85254] = {id=85254,name="Lorewalking: Children of the Void",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15969,mapID=84,description="The void elves... so strange. There is very little difference between a void elf and a blood elf, other than what they have chosen to wield. Yet to their former kin, they are anathema--no longer considered a blood elf at all, and no longer welcome in their former home. Let us explore how, and why, this came to be.",starts={{npcID=234616,x=0.642,y=0.162,zoneID=1519},{npcID=234616,x=0.542,y=0.566,zoneID=1637},{npcID=234616,x=0.496,y=0.316,zoneID=14771},{npcID=234616,x=0.586,y=0.708,zoneID=15969}},ends={{npcID=234616,x=0.642,y=0.162,zoneID=1519},{npcID=234616,x=0.542,y=0.566,zoneID=1637},{npcID=234616,x=0.496,y=0.316,zoneID=14771},{npcID=234616,x=0.586,y=0.708,zoneID=15969}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[85255] = {id=85255,name="Tranquila-Bee",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="I think we should start prepping to move the bees into the Oasis. I'd like to tag them so we can monitor the hive. Bees don't tend to stand still for long. We'll need to tranquilize and tag them. I tagged the queen. Would you tag the honey bees?",objectivesText="Tranquilize and tag 10 bees in Eco-Dome: Primus in K'aresh.",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85256] = {id=85256,name="Botany, Finally",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="The bees are doing well and have no negative interactions with the local fauna. But what about the flora? I have some cuttings of plants from the Oasis. Would you gather some cuttings from this dome so I can compare them?",objectivesText="Collect 10 K'aresh Flora Cuttings . Progress: I'm terribly excited to work on plants again. It's been quite a while now. Get it? Bee-n?",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85257] = {id=85257,name="Primus Buzzness",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=942,description="Alright. Let's get these bees into Eco-Dome: Primus for the next round of tests!",objectivesText="Meet Botanist Alaenra in Eco-Dome: Primus.",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[85258] = {id=85258,name="Oh Honey Honey",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The hive has settled in quite well. I'd like to do a quick honey check though. The pollen in these plants is quite different, and it should change the honey quite a bit. We need to make sure it's working for the hive. It should be fine based on the experiments in the earlier domes. Best to check though, right?",objectivesText="Collect 8 Honeycombs and then pet the Queen Bee in the Oasis. Progress: Have you collected the honeycomb ?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[85259] = {id=85259,name="Waggle Dance",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Alaenra requested that I pass on a message. \"Hey, Om'talad . I'm going to dance for the bees so they know where the new flowers are. Can you ask to do the same?\" Odd, but please feel free to... frolic.",objectivesText="Dance for the bees in the Oasis.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85260] = {id=85260,name="Hiving a Hard Day",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="I just spotted a few bees flop to the ground. I think they've overworked themselves trying to get at the new plants. They'll be fine. They're just tired. Could you help me pick them up and bring them back to the hive?",objectivesText="Pick up 10 Overworked Honey Bees and return them to the hive. Progress: Poor bees! Handle them carefully.",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[85261] = {id=85261,name="Bee Roll",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Ah, there you are. It's time for documentation! We need to keep track of how the bees are doing in the Oasis. I've filled out the paperwork already. Perhaps you could get me some photos of the bees in action?",objectivesText="Document 10 Honey Bees and the Queen Bee . Progress: Have you gotten some good shots?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[85262] = {id=85262,name="The Royal Procession",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Hmm, your photos make me think the hive is ready to swarm! This is the ultimate goal of any hive--birth a new queen and create a new hive. It does mean our queen needs to move to a new location, but there is plenty of eco-dome to go around, right? Can you help her find a new location?",objectivesText="Help the Queen Bee find a new hive location. Progress: Have you gotten the old queen settled in?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[85383] = {id=85383,name="Applied Mixology",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Allow me to introduce myself, traveler. I am known as Ba'kril. As you know, my people do not imbibe as yours do. My proposal is simple: help me concoct a new energy drink and I shall allow you to use it free of charge. It will most certainly make you a hero amongst heroes. Is that not worth the risk? I have acquired various potent energy sources. Infuse them into the berry juice cocktail and let us see how potent we can make it.",objectivesText="Concoct an energy drink infused with various power sources. Progress: On the soul of K'aresh , I make my oath to you, traveler. We will create the finest, most powerful infused concoction ever seen. With it, you will have the power of ten devourers! <Ba'kril grumbles something under his breath about Tazavesh's leadership.> Of course, there will be just a pinch of profit on the side for me.",starts={{npcID=232351,x=0.438,y=0.524,zoneID=15781}},ends={{npcID=232351,x=0.438,y=0.524,zoneID=15781}},coords={x=0.438,y=0.524,source="quest_giver",zoneID=15781},questType="standard"},
[85384] = {id=85384,name="Market Research",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Since I never doubted our success, I took the liberty of making further preparations. I have arranged for a couple of volunteers. I want to see our new energy drink in action before you imbibe it, . May I call you ? Of course I can. We're partners now. You will find the volunteers lounging on the high terraces of the city. Tazavesh has many such comfortable areas for visitors like yourself.",objectivesText="Speak with the volunteers to test the new energy drink. Progress: We are both certain to profit from this venture, <name>, regardless of the outcome.",starts={{npcID=232351,x=0.438,y=0.524,zoneID=15781}},ends={{npcID=232351,x=0.438,y=0.524,zoneID=15781}},coords={x=0.438,y=0.524,source="quest_giver",zoneID=15781},questType="standard"},
[85394] = {id=85394,name="An Eye for Trouble",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="If we were to consider the silver lining here, it is that we now know our concoction works. Just not on whom we wished. I do not suppose you have it in you to defeat this empowered version of the creature? It is only our reputations and the future of Tazavesh at stake. Another chance to prove you truly are as mighty as they say.",objectivesText="Defeat Bakishroth the Empowered and save Tazavesh! Progress: Is it done, <name>?",starts={{npcID=232351,x=0.438,y=0.524,zoneID=15781}},ends={{npcID=232351,x=0.438,y=0.524,zoneID=15781}},coords={x=0.438,y=0.524,source="quest_giver",zoneID=15781},questType="standard"},
[85409] = {id=85409,name="Snitches Get Stitches",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I thought we could talk here in Gutterville, but it feels tense. They're all Venture Company, but I don't recognize a lot of 'em. Word is, Gallywix sent down a bunch of workers who are sympathetic to him so they could spy on us. Clear out some of these turncoats. If any of them report to Overseer Gozzic that we're working against the pipeline, he'll go after my people.",objectivesText="Remove the Venture turncoat spies in Gutterville. Progress: The spies are everywhere, I tell ya.",starts={{npcID=225772,x=0.714,y=0.836,zoneID=14795}},ends={{npcID=225772,x=0.714,y=0.836,zoneID=14795},{npcID=232491,x=0.722,y=0.822,zoneID=14795}},coords={x=0.714,y=0.836,source="quest_giver",zoneID=14795},questType="standard"},
[85410] = {id=85410,name="Undermine's Long Shadow",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="These engineers have been through a lot. Let's make sure they're good. Maybe they can shed some light on Undermine.",objectivesText="Speak with Pamsy's engineers. Progress: There's a lot of information to chew on.",starts={{npcID=225599,x=0.702,y=0.894,zoneID=14795}},ends={{npcID=225599,x=0.702,y=0.894,zoneID=14795}},coords={x=0.702,y=0.894,source="quest_giver",zoneID=14795},questType="standard"},
[85429] = {id=85429,name="Overwhelm Them",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="There's an audit coming up. My employer, Xy Imports, will be audited. Again. I need this audit to go badly. It must be worse than the last. Can you help me? We have a shipment of small devourers that would cause a lot of trouble if they were to escape or go missing. Break open their crates. Business needs to be overwhelmed just like last time.",objectivesText="Break 8 Xy Imports Crates on the docks in Tazavesh.",starts={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},ends={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},coords={x=0.504,y=0.388,source="quest_giver",zoneID=15781},questType="standard"},
[85430] = {id=85430,name="Mandatory Time Off",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="If my colleagues knew of my plan, they would be in danger of discharging their oaths as good employees. Besides that, they are far too excellent at their jobs. Take these. They're devices of my own creation. When placed near my colleagues, it will create an illusion of them working. They will be able to step away and rest. And the business will be under even more pressure without them.",objectivesText="Place 7 Illusion Devices . Progress: I had to become good at illusions for this job. It was the only way to make it tolerable. Maybe now I can use those skills to help others for once.",starts={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},ends={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},coords={x=0.504,y=0.388,source="quest_giver",zoneID=15781},questType="standard"},
[85431] = {id=85431,name="Drain Their Resources",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="We've made good progress, but we need more disorganization. I've redirected a particularly large shipment of anima in the form of a devourer. Kill it and bring its anima core to me. The anima itself is not important--rather, the fact that it can be stolen. My boss will have more to answer for in the audit when his books are in disarray.",objectivesText="Collect Overflowing Anima Core from Respleth the Hungerer outside Tazavesh. Progress: The Xy Imports associates transporting this anima are expecting a--ah--broker of sorts to relieve them of their charge. They will give you no trouble.",starts={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},ends={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},coords={x=0.504,y=0.388,source="quest_giver",zoneID=15781},questType="standard"},
[85432] = {id=85432,name="Confuse Their Contacts",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="When our imports are delayed or lost, the most direct impact is on Tazavesh businesses. Take this illusion pin. It will make you appear as a Xy Imports employee. Tell the businesses their shipments are delayed indefinitely. My boss cannot ignore downstream pressure forever.",objectivesText="Speak with market vendors in Tazavesh. Progress: This is not the first time the market vendors have dealt with my boss's failings. I only hope it is the last.",starts={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},ends={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},coords={x=0.504,y=0.388,source="quest_giver",zoneID=15781},questType="standard"},
[85433] = {id=85433,name="Eyes on Us",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="I can hear Coordinator Xy'thir raging about the slide in business already. We're ready. Go to Port Authority Zo'rau . Tell them you represent an invested party and that the audit should be moved up. And there's one more thing I need you to do. Speak with me before you go.",objectivesText="Speak with Port Authority Zo'rau in Tazavesh. Progress: This is more important than I can say, <name>. But I cannot break my oath. Deliver the pin to Zo'rau.",starts={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},ends={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},coords={x=0.504,y=0.388,source="quest_giver",zoneID=15781},questType="standard"},
[85434] = {id=85434,name="On a Technicality",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="It's time. I cannot tell you what to expect, $p. I only hope this is the last day I must keep such a dreadful oath. Let us hurry. Port Authority Zo'rau has already begun questioning Coordinator Xy'thir .",objectivesText="Confront Coordinator Xy'thir in Tazavesh. Progress: <Xy'nell is silent before Coordinator Xy'thir .>",starts={{npcID=232498,x=0.504,y=0.388,zoneID=15781}},ends={{npcID=233942,x=0.524,y=0.38,zoneID=15781}},coords={x=0.504,y=0.388,source="quest_giver",zoneID=15781},questType="standard"},
[85438] = {id=85438,name="Or Else",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Am I glad I found you, ! My boss, Kraz Torquewrench, sent me to find you, and he don't take no for an answer, yanno? I thought I was gonna have to cash out and move futher underground, but here you are! Anyway, the boss's little girl is getting married, and he told me he wanted you, specifically, to help him \"finalize\" some \"details,\" with her intended and who's attendin'--if you get my meanin'.",objectivesText="Speak with Kraz Torquewrench in Hovel Hill.",starts={{npcID=233235,x=0.44,y=0.498,zoneID=15347}},ends={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},coords={x=0.44,y=0.498,source="quest_giver",zoneID=15347},questType="standard"},
[85444] = {id=85444,name="Found Family",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,description="This crew trusted me. They're my family. We gotta see if any of them survived. I have other engineers who ain't here. They must have fled into the field. Razi , Keets , and Glizza are out there. Find 'em. Bring 'em home.",objectivesText="Rescue Pamsy 's last engineers from the Writhing Fields. Progress: Don't leave those engineers out there to die.",starts={{npcID=228214,x=0.706,y=0.886,zoneID=14795}},ends={{npcID=225598,x=0.704,y=0.886,zoneID=14795}},coords={x=0.706,y=0.886,source="quest_giver",zoneID=14795},questType="standard"},
[85449] = {id=85449,name="Phase Shift",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="As soon as the ethereals attacked, phase resonance tore open rifts throughout the area. The rifts are gone, but the ethereals can return while the resonance remains. That is how they call more soldiers and communicate with their commanders. We need to destroy that resonance. It may earn us the ire of whoever is behind this attack, but I gladly invite them to stop us.",objectivesText="Destroy 4 Phase Resonance in the Vatworks. Progress: We need to destroy that resonance if we are to stop this attack.",starts={{npcID=225669,x=0.294,y=0.694,zoneID=15347},{npcID=232660,x=0.33,y=0.688,zoneID=15347}},ends={{npcID=232660,x=0.33,y=0.688,zoneID=15347}},coords={x=0.294,y=0.694,source="quest_giver",zoneID=15347},questType="standard"},
[85450] = {id=85450,name="Evacuation Plan",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="We cannot let the ethereals find the Dark Heart before we do. Gazlowe needs to be informed. We must gather our forces and find the Dark Heart--quickly!",objectivesText="Regroup with Gazlowe in Steamwheedle Laboratories. Progress: We need to get to the bottom of this.",starts={{npcID=232660,x=0.33,y=0.688,zoneID=15347}},ends={{npcID=229261,x=0.27,y=0.718,zoneID=15347}},coords={x=0.33,y=0.688,source="quest_giver",zoneID=15347},questType="standard"},
[85451] = {id=85451,name="The Burning of Hammerfall",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=15716,mapID=14,description="The Syndicate has put Hammerfall to torch! And the cowards are using pyromancers to feed the flames. But we can save our huts if we get to them quickly. Fight through the Syndicate bandits to a building and then blow this horn. A Hammerfall shaman will come to put out the fire!",objectivesText="Use the Hammerfall Horn at each main structure in Hammerfall to summon a shaman and put out the flames.",starts={{x=0.696,y=0.41,mapID=2372,npcID=231768}},ends={{x=0.696,y=0.41,mapID=2372,npcID=231768}},coords={mapID=2372,x=0.696,y=0.41},questType="standard"},
[85459] = {id=85459,name="Anima Reclamation Program",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="The eco-domes run on anima. While you are out in K'aresh, if you see any devourers--kill them and return with their anima. You will be compensated.",objectivesText="Collect 20 Devourer Anima in K'aresh. Progress: Our reserves are in no immediate danger, but it is better to be safe than sorry, is it not?",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85460] = {id=85460,name="Ecological Succession",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15336,mapID=2371,objectivesText="Help the Oasis Complete repeatable quests Return anima from a devourer assault",starts={{x=0.741,y=0.326,mapID=2371}},ends={{x=0.741,y=0.326,mapID=2371}},coords={mapID=2371,x=0.741,y=0.326},questType="world"},
[85461] = {id=85461,name="Food Run",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2371,description="Our latest food shipment for the animals was taken by an ethereal raid in Tazavesh. I would like you to reacquire it.",objectivesText="Reacquire 15 Stolen Food Shipments from ethereals in Tazavesh. Progress: Have you acquired the food?",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85462] = {id=85462,name="A Challenge for Dominance",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Our slateback alpha has been getting a bit... testy recently. I believe he is looking for a challenge. You are the most combat capable of us. Go give him one.",objectivesText="Challenge the Slateback Alpha . Progress: Do try to avoid damaging it permanently.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85465] = {id=85465,name="Play Ball",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="This thorntail kit has been begging me for attention all morning. It is quite charming, but I have work I need to get done! I think it needs to burn some energy off. Take this ball and go play with it.",objectivesText="Catch a ball 10 times while playing with your Thorntail Kit. Progress: < Om'talad absentmindedly pets the thorntail kit.>",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85470] = {id=85470,name="Root Redux",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Some of the lapbugs are getting stuck in the tree roots again. If left to their own devices they will eventually eat their way out, but it would be easier if you offered your assistance.",objectivesText="Detangle 10 Stuck Lapbugs . Progress: They're very cute, but not exactly... bright.",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[85471] = {id=85471,name="Renowned with the Gallagio Loyalty Rewards Club",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15522,description="The Gallagio appreciates your continued loyalty! We've got some extra supplies for only our most honored of High Rollers. Come see us for your gift!",objectivesText="Speak with Paula Piranha inside the Liberation of Undermine .",starts={{npcID=235617}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
[85476] = {id=85476,name="Buried Tweasure",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Hello friend! You won't believe it, but I heard there's a hidden tweasure somewhere in Tanaris! I'm suuuper sneaky and managed to get a copy of the first riddle. And you're so good at solving them tat I want to give it to you!",objectivesText="Find the buried treasure. Progress: Go find the tweasure!",starts={{npcID=226684,x=0.632,y=0.524,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.632,y=0.524,source="quest_giver",zoneID=440},questType="standard"},
[85477] = {id=85477,name="Lost and... Found?",level=10,requiredLevel=30,faction="both",expansion=10,zoneID=440,mapID=71,description="I am so overwhelmed. A group of folks were here a little while ago, all complai... I mean, submitting lost-item notices with great passion, but all at the same time. I tried to take down all the details, but in the stress of the moment, I fear they're all jumbled. I have this collection of items that have been found over the day, and I'm fairly sure these are the items those folks were talking about. Do you think you could use my notes and figure out which item belongs to each person?",objectivesText="Deliver the lost items to their correct owners. Progress: How's it going? Have you found the owners of all the lost items?",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[85481] = {id=85481,name="Ridge Racer",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Our Slateback Alpha needs to burn off some energy. I believe he is looking for a race. He seems to enjoy you the most. Would you race with him?",objectivesText="Race the Slateback Alpha . Progress: Some of the brokers have placed bets for this race.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85503] = {id=85503,name="A Surprising Investigation",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Well, look who's back to solve more cases. It seems that Chromie has been fiddling with time again and some imposters have popped up around the celebration area. All you need to do is identify who doesn't belong and send them to Chromie. This should be a breeze for you.",objectivesText="Solve the case given to you by Detective Jones. Progress: How goes it?",starts={{npcID=226796,x=0.61,y=0.506,zoneID=440}},ends={{npcID=233012,x=0.662,y=0.41,zoneID=440}},coords={x=0.61,y=0.506,source="quest_giver",zoneID=440},questType="standard"},
[85523] = {id=85523,name="Mildewed Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,mapID=71,description="Alyx would appreciate the supplies returned.>",objectivesText="Return the Mildewed Celebration Crate to Alyx . Progress: Oh, I am so busy. But what can I help you with?",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},coords={mapID=71,source="quest_giver",x=0.63,y=0.502},questType="standard"},
[85529] = {id=85529,name="Past Glory",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Marran's\"Red Dawn\" has left the city and peace has returned to Stromgarde. At least for now. Faerin left for the countryside. She said she wanted to check on Newstead and Refuge Point, but I think she wanted to get out of Stromgarde. She came here with such enthusiasm. I should not have tempered it so harshly. I feel in the end it was I who needed to learn a lesson. We should check in on her.",objectivesText="Speak to Faerin at High Perch. Progress: <Faerin looks lost in thought as she again gazes at Thoradin's Wall.>",starts={{x=0.216,y=0.65,mapID=2372,npcID=232986}},ends={{x=0.216,y=0.65,mapID=2372,npcID=232986}},coords={mapID=2372,x=0.216,y=0.65},questType="standard"},
[85531] = {id=85531,name="Earth-Encrusted Gem",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,mapID=2255,starts={{npcID=223750,x=0.552,y=0.412,mapID=2255}},ends={{npcID=220867,x=0.552,y=0.412,mapID=2255},{npcID=223750,x=0.552,y=0.412,mapID=2255}},coords={x=0.552,y=0.412,source="quest_giver",mapID=2255},questType="standard"},
[85532] = {id=85532,name="The Wealth of a Kingdom",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,mapID=2255,starts={{npcID=223750,x=0.552,y=0.412,mapID=2255}},ends={{npcID=220867,x=0.552,y=0.412,mapID=2255},{npcID=223750,x=0.552,y=0.412,mapID=2255}},coords={x=0.552,y=0.412,source="quest_giver",mapID=2255},questType="standard"},
