[85769] = {id=85769,name="The Party Must Go On",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Arrived at the Gallagio Fireworks Delivered to Gallagio Patio Fireworks Delivered to Plunder Party Fireworks Delivered to Blackwater Marina Docks",questType="standard"},
[85780] = {id=85780,name="Right Where We Want Him",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Gallywix is down, but he ain't out. The Gallagio is built like a fortress. If we want to keep him from threatening Undermine , or Azeroth, we gotta figure out how to get him outta there. Meet me and the other bosses back at the Incontinental Hotel.",objectivesText="Return to the Incontinental Hotel and speak with Gazlowe.",starts={{npcID=235238,x=0.57,y=0.446,zoneID=15347}},ends={{npcID=233482,x=0.434,y=0.51,zoneID=15347}},coords={x=0.57,y=0.446,source="quest_giver",zoneID=15347},questType="standard"},
[85804] = {id=85804,name="The Parent Trap",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2472,description="I'm happy to help in any way that I can. To find Alleria, you must fly far north from here. She's hunting a new Shadowguard lieutenant in the hope of extracting information from him. Last I heard, she was on the outskirts of a place called the Fracture of Laacuna.",objectivesText="Locate Alleria Windrunner at the Fracture of Laacuna. Progress: It is good to see both of you, especially my beautiful son.",starts={{npcID=234263,x=0.512,y=0.198,zoneID=15781}},ends={{npcID=231987,x=0.552,y=0.278,zoneID=15336}},coords={x=0.512,y=0.198,source="quest_giver",zoneID=15781},questType="standard"},
[85805] = {id=85805,name="Renowned with the Cartels of Undermine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Thanks for the hard work there, pal! We've got some supplies prepped for you in the hotel. Come grab 'em from Smaks Topskimmer .",objectivesText="Speak with Smaks Topskimmer in the Incontinental Hotel.",starts={{x=0.438,y=0.508,mapID=2346,npcID=231409}},ends={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},coords={mapID=2346,source="quest_giver",x=0.436,y=0.505},questType="standard"},
[85806] = {id=85806,name="Exalted with the Bilgewater Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="You done good for the Bilgewater when they needed you. They won't forget that. Talk to Rocco Razzboom , he'll take care of ya.",objectivesText="Speak with Rocco Razzboom at the Scrapshop.",starts={{x=0.3915,y=0.2219,mapID=2346,npcID=231406}},ends={{npcID=231406,x=0.39,y=0.22,zoneID=15347}},coords={mapID=2346,source="quest_giver",x=0.39,y=0.22},questType="standard"},
[85807] = {id=85807,name="Exalted with the Blackwater Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="The Blackwater Cartel is sailing smooth thanks to you. Boatswain Hardee has readied yer cut o' the plunder... that is to say, a respectable reward for your work.",objectivesText="Speak with Boatswain Hardee at the Port Authority.",starts={{x=0.632,y=0.172,mapID=2346,npcID=231405}},ends={{npcID=231405,x=0.632,y=0.168,zoneID=15347}},coords={mapID=2346,source="quest_giver",x=0.632,y=0.165},questType="standard"},
[85808] = {id=85808,name="Exalted with Darkfuse Solutions",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Helpin' the Darkfuse ain't real popular, so they want to say thanks. They gotta do it quiet like, so find Stitch Lowdown down in the sewers near Hovel Hill.",objectivesText="Speak with Sitch Lowdown in the sewers near Hovel Hill.",starts={{x=0.308,y=0.382,mapID=2346,npcID=231396}},ends={{npcID=231396,x=0.306,y=0.388,zoneID=15347}},coords={mapID=2346,source="quest_giver",x=0.305,y=0.388},questType="standard"},
[85809] = {id=85809,name="Exalted with the Steamwheedle Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="The Steamwheedle Cartel wants to thank you for all the work you have done. Observe all safety protocols and see Lab Assistant Laszly for a reward.",objectivesText="Speak with Lab Assistant Laszly at Steamwheedle Laboratories.",starts={{x=0.276,y=0.728,mapID=2346,npcID=231408}},ends={{npcID=231408,x=0.272,y=0.724,zoneID=15347}},coords={mapID=2346,source="quest_giver",x=0.272,y=0.724},questType="standard"},
[85810] = {id=85810,name="Exalted with Venture Co.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Venture Co. is ready to pay dividends on all the work you've done for us. Speak to Shredz the Scrapper for your reward.",objectivesText="Speak with Shredz the Scrapper at Venture Plaza.",starts={{x=0.532,y=0.726,mapID=2346,npcID=231407}},ends={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},coords={mapID=2346,source="quest_giver",x=0.532,y=0.725},questType="standard"},
[85827] = {id=85827,name="Glinting and Gleaming",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15347,mapID=2346,starts={{npcID=231409,x=0.436,y=0.508,mapID=2346}},ends={{npcID=231409,x=0.436,y=0.508,mapID=2346}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[85862] = {id=85862,name="A Prince's Duty",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2418,description="It's a big day, lad. We've got a parade of the troops, a visiting contingent from Ironforge, and I hear word your father--er, King Terenas--will be here to oversee everything. It's days like today that you've been forged for, Arthas. Inspire your men. Prove yourself. Whip these troops into shape. No doubt Muradin has been itching for a brawl as well...",objectivesText="Spar with the troops in Lordaeron Garrison. Progress: You are the best our kingdom has to offer, my son. Make us look good in front of our guests!",starts={{x=0.341,y=0.841,mapID=2418,npcID=233752}},ends={{x=0.341,y=0.841,mapID=2418,npcID=233752}},coords={mapID=2418,x=0.341,y=0.841},questType="standard"},
[85869] = {id=85869,name="Many Jobs, Handle It!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Shipping & Handling is tryin' out a new driver incentive program. Do some jobs and let's see how it goes eh?",objectivesText="Complete 10 jobs for Shipping & Handling. Progress: Get back to work. Chop chop!",starts={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},ends={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},coords={x=0.436,y=0.508,source="quest_giver",zoneID=15347},questType="standard"},
[85871] = {id=85871,name="Lorewalking: The Blade's Forces",level=10,requiredLevel=10,faction="both",expansion=10,mapID=2383,description="Xal'atath brings with her an army of shadows and tricks. They are nothing to our evolved forms! You have been chosen--blessed with power by N'Zoth to serve as his champion. Go now and destroy them!",objectivesText="Defeat Xal'atath's forces.",starts={{x=0.525,y=0.731,mapID=2381,npcID=230321}},ends={{x=0.525,y=0.731,mapID=2381,npcID=230321}},coords={mapID=2381,x=0.525,y=0.731},questType="standard"},
[85873] = {id=85873,name="Another Shadowy Invitation",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="$p, do you like paperwork and forms as much as I do? Then let us dispense with the expedited entry to Tazavesh and experience once more the joy of jumping through bureaucratic hoops and paying bribes as is the tradition of all great broker stories. WARNING! COMPLETING THIS QUEST WILL REQUIRE YOU TO FINISH CHAPTER 1 OF THE 11.2 CAMPAIGN!",objectivesText="Meet Locus-Walker in the Foundation Hall in Dornogal.",questType="standard"},
[85876] = {id=85876,name="Reading the Runes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15827,mapID=2369,description="My curiosity is still not terminated, . I would like to know more about these vrykul and why they came to this land. Bargus 's wiry brows knit together and his mustache bristles as he thinks.> The tablets you found were by far the best source of information on the vrykul and whoever this \"Cyrce\" is. Perhaps there are additional tablets we missed? I have my ordained duties here, but please examine them and report back to me.",objectivesText="Examine various Rune-Carved Tablets within the Forgotten Tomb.",starts={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},ends={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},coords={x=0.676,y=0.42,source="quest_giver",zoneID=10416},questType="standard"},
[85878] = {id=85878,name="O' Thanagor",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=4820,mapID=84,description="You are the Lich King. The whole of Azeroth is arrayed against you. Show them what it means to be king.",objectivesText="Defeat the usurpers atop Icecrown Citadel.",ends={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},coords={mapID=84,source="quest_giver",x=0.642,y=0.162},questType="standard"},
[85879] = {id=85879,name="Reduce, Reuse, Resell",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="The guys over at S.C.R.A.P. could use some extra hands this week. You want a piece of the pie, go find one of their reps named Carlo out in the field and see if he's got any work for you. But if you find a piece of pie in any of those trash piles, don't, uh... Don't actually eat it. I hope that kinda goes without sayin'.",objectivesText="Complete 3 S.C.R.A.P. jobs in Undermine . Progress: What d'you need, instructions? Big trash piles. Shovel. Get at it.",starts={{npcID=231409,x=0.436,y=0.508,zoneID=15347},{npcID=237659,x=0.266,y=0.374,zoneID=15347}},ends={{npcID=231409,x=0.436,y=0.508,zoneID=15347},{npcID=237659,x=0.266,y=0.374,zoneID=15347}},coords={x=0.436,y=0.508,source="quest_giver",zoneID=15347},questType="standard"},
[85884] = {id=85884,name="Lorewalking: The Prince Who Would Be King",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=65,mapID=84,description="Before I can tell you the story of the Lich King, we must learn about who he was before he put on his crown. Before he pulled that cursed sword from the depths of Frostmourne Cavern. We must talk about the prince who was promised the world, and the people who championed his cause. We must start in Lordaeron, many years ago, on a day of pomp and circumstance.",objectivesText="Hear the story of Prince Arthas Menethil.",starts={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},ends={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[85885] = {id=85885,name="Lorewalking: No King Rules Forever",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15969,mapID=84,description="What makes a king? Is it his crown? Is it the sharpness of his sword? The coldness of his heart? Perhaps the undying servitude of his people? Just as it is difficult to say when a sapling becomes a tree, or a mountain becomes a hill, so too is it difficult to know when exactly Arthas Menethil passed into memory, and the Lich King was born. Where do we draw the line between man and monster?",objectivesText="Listen to the story of the Lich King.",starts={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},ends={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[85900] = {id=85900,name="Breakneck Bolt",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.262,y=0.53,mapID=2346,npcID=233917}},ends={{x=0.262,y=0.53,mapID=2346,npcID=233917}},coords={mapID=2346,x=0.262,y=0.53},questType="standard"},
