[85904] = {id=85904,name="Casino Cruise",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,objectivesText="Glide through the rings.",starts={{x=0.395,y=0.539,mapID=2346,npcID=233919}},ends={{x=0.395,y=0.539,mapID=2346,npcID=233919}},coords={mapID=2346,x=0.395,y=0.539},questType="standard"},
