[88879] = {id=88879,name="Honored with Venture Co.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Venture Co. is ready to pay dividends for your assistance. Speak to Shredz the Scrapper for your reward.",objectivesText="Speak with Shredz the Scrapper at Venture Plaza.",starts={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},ends={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},coords={x=0.532,y=0.726,source="quest_giver",zoneID=15347},questType="standard"},
[88880] = {id=88880,name="Revered with Venture Co.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Venture Co. is ready to pay dividends for your assistance. Speak to Shredz the Scrapper for your reward.",objectivesText="Speak with Shredz the Scrapper at Venture Plaza.",starts={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},ends={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},coords={x=0.532,y=0.726,source="quest_giver",zoneID=15347},questType="standard"},
[88881] = {id=88881,name="Exalted with Venture Co.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Venture Co. is ready to pay dividends for your assistance. Speak to Shredz the Scrapper for your reward.",objectivesText="Speak with Shredz the Scrapper at Venture Plaza.",starts={{x=0.532,y=0.726,mapID=2346,npcID=231407}},ends={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},coords={mapID=2346,source="quest_giver",x=0.532,y=0.725},questType="standard"},
[88901] = {id=88901,name="Dastardly Duos Reward",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[88903] = {id=88903,name="Faceless Mask of Vengeance",level=80,requiredLevel=80,faction="both",expansion=10,description="Blood begets blood, and the weight of the fallen lingers in the air like a whispered curse. Those who stand witness to your wrath feel it creeping into their bones, driving them to strike harder, desperation masquerading as courage. Vengeance does not end violence. It only feeds the storm.",objectivesText="Return the Faceless Mask of Vengeance to the altar within a Horrific Vision. Progress: Place the Faceless Mask of Vengeance on the altar.",questType="standard"},
[88916] = {id=88916,name="Radiant Incursion: Sureki's End",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,mapID=2215,description="Credible intel has revealed the Sureki are regrouping for another assault. Now we take the fight to them! The Flame's Radiance have rallied at Faerin's Advance, and prepare to strike at the Sureki forces amassing in northern Azj-Kahet . Be warned, soldier. The Sureki in \"Arathi's End\" are greater in number and power. Should you require aid, our Sacredites in the field should be equipped with potions to assist you.",objectivesText="Assist the Flame's Radiance and disrupt the Sureki forces at Arathi's End. Progress: We must not let them gather strength. Now is the time to strike!",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=241100,x=0.606,y=0.186,zoneID=14752}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[88945] = {id=88945,name="Radiant Incursion: Rak-Zakaz",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,mapID=2215,description="The nerubian allies you and Lady Faerin made in Azj-Kahet have proven resourceful... for now. According to their intel, Sureki sympathizers have begun to rally at Rak-Zakaz and aid their fallen queen's loyalists in their renewed assaults. Regroup with our forces at Faerin's Advance and cut off their reinforcements!",objectivesText="Assist the Flame's Radiance and disrupt the Sureki forces at Rak-Zakaz. Progress: By disrupting operations at Rak-Zakaz, we cut off their reinforcements and discourage any sympathizers to their cause.",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=241100,x=0.606,y=0.186,zoneID=14752}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[88947] = {id=88947,name="Undermined Delves",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,description="There's more tae do in delves, ! Meet me in Dornogal. There's loads to discuss!",objectivesText="Meet Brann Bronzebeard within Dornogal.",starts={{x=0.476,y=0.443,mapID=2339,npcID=206017}},ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={mapID=2339,source="quest_giver",x=0.475,y=0.445},questType="standard"},
[88970] = {id=88970,name="LFGDungeons - 11.2 The War Within - Raid Finder - 1st",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[88974] = {id=88974,name="Eco-Stability",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Speakin' o' eggs, I checked an' Ember has laid her clutch. It's almost time ta hatch some babies! Meet me back at tha nest an' we can welcome our first snakelets ta K'aresh.",objectivesText="Help with hatching the snakelets.",starts={{x=0.759,y=0.342,mapID=2371,npcID=231820}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={mapID=2371,source="quest_giver",x=0.758,y=0.342},questType="standard"},
[88975] = {id=88975,name="Spooked Slitherin' Snakes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="Somethin' has the snakes agitated again. Spooked even. How would ye feel about taking me flute back out there and calming 'em down?",objectivesText="Use Hemet's Soothin' Flute to soothe 15 Agitated Snakes . Progress: Sweet music to me ears.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88976] = {id=88976,name="The Hope of K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="It is finished. By all measurements, the eco-system in the Oasis is fully stable. While there will always be things we can help with, it would survive if we left it alone. Take some time and speak with everyone. Congratulate them. Good work should be properly acknowledged. Speak with me when you are done.",objectivesText="Talk to your team in the Oasis.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[88980] = {id=88980,name="Who You Gonna Call?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="We could do with more slateback essence . I imagine that the opportunity to keep the sand of K'aresh safe would be right up your alley, yes? Just bring me back what you find after you are done.",objectivesText="Collect 10 Slateback Essence in Untethered Space on K'aresh. Progress: You have the essence?",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[88981] = {id=88981,name="Nesting Upkeep",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="It's time to refresh Ember, Indigo, an' the snakelet's nest. Gotta keep our K'areshi snakes comfy. Don't worry 'bout carrying anything down there. Just like last time, we'll use one o' Ve'nari's portation tags for that.",objectivesText="Refresh the nest of the two named snakes and their snakelets. Progress: Everything good with 'em? Aren't the snakelets just adorable?",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[89016] = {id=89016,name="Members Only",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235617,zoneID=15522}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
[89018] = {id=89018,name="Loyal Customer: Silver",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235617,zoneID=15522}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
[89019] = {id=89019,name="Loyal Customer: Gold",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235617,zoneID=15522}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
