[89021] = {id=89021,name="Loyal Customer: Black",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235617,zoneID=15522}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
