[89393] = {id=89393,name="Flame's Radiance Stipend",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=240852,x=0.282,y=0.562,mapID=2215}},ends={{npcID=240852,x=0.282,y=0.562,mapID=2215}},coords={x=0.282,y=0.562,source="quest_giver",mapID=2215},questType="standard"},
