[93137] = {id=93137,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Steam bursts toward the sky. Blue pools swirl with ancient heat. Look for the tether. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93138] = {id=93138,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Penned in desert bloom. Loyal steeds water and feed. Needles in haystacks. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93139] = {id=93139,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Three huts in spire's shade. Wooden overlook curves out front. Search near a planter. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93140] = {id=93140,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Where kodos take rest. Past gate marked with bone and fire. Dig near the hay bale. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93141] = {id=93141,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Just like Thunder Bluff. Tower watches three swaying paths. Look to the platform. Good luck!",objectivesText="Solve the riddle and find the treasure. Progress: You found the treasure!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93142] = {id=93142,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Near where farmers toil. Beast of burden raises young. Seek the broadest shade. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
