[93148] = {id=93148,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Across gentle falls. Ocean breeze meets the bounty. East end of the bridge. Good luck!",objectivesText="Solve the riddle and find the treasure. Progress: You found the treasure!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93149] = {id=93149,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Smugglers scheme above. Tortollans tend bar below. Search through the seaweed. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93150] = {id=93150,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: A secret beast den. Hidden behind narrow falls. Search the oasis. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93151] = {id=93151,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: The fire never ends. Gather for sorrow or mirth. Search behind the fuel. Good luck!",objectivesText="Solve the riddle and find the treasure.",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93152] = {id=93152,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,mapID=2351,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Life stirs from dry soil. Camp where fishers may take rest. Fire warms the treasure. Good luck!",objectivesText="Solve the riddle and find the treasure. Progress: You found the treasure!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93382] = {id=93382,name="Pardon the Interruption",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=16432,mapID=2451,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",objectivesText="Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 3 times. Progress: Some help! Hopefully you can find a way to interrupt this bot's abilities.",starts={{npcID=249423,x=0.194,y=0.574,zoneID=16432}},ends={{npcID=249456,x=0.208,y=0.598,zoneID=16432}},coords={x=0.194,y=0.574,source="quest_giver",zoneID=16432},questType="standard"},
[93452] = {id=93452,name="Retrieved Crumpled Present",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=16227,description="<It seems the minions of the Greench have fled, leaving behind a small mangled, but still salvageable present. Perhaps one of the Winter Festivities planners would be able to help return it to the original intended recipient.>",objectivesText="Talk to Joanna Copperpinch in the Razorwind Shores neighborhood.",questType="standard"},
[93683] = {id=93683,name="Conditional Objectives - Singular",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=16105,mapID=2352,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",objectivesText="Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.",questType="standard"},
[93877] = {id=93877,name="Conditional Objectives - Sequential",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=16432,mapID=2451,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",objectivesText="Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.",questType="standard"},
[93878] = {id=93878,name="Conditional Objectives - Multiple Steps, No Sequence",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=16432,mapID=2451,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",objectivesText="Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.",questType="standard"},
[93879] = {id=93879,name="Conditional Objectives - Conditional After Sequence",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=7637,mapID=680,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",objectivesText="Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.",questType="standard"},
[93979] = {id=93979,name="Lingering Memories",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,mapID=2472,description="Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath . I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal. We can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.",objectivesText="Meet Alleria and Locus-Walker at the docks.",starts={{npcID=231128,x=0.378,y=0.744,zoneID=15781}},ends={{npcID=230700,x=0.342,y=0.108,zoneID=15781}},coords={x=0.378,y=0.744,source="quest_giver",zoneID=15781},questType="standard"},
[94363] = {id=94363,name="The Gloves Are Off",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=2257,mapID=500,description="If you've found yourself an invite you'll be wanting to put it to good use, no? Use your Blood-Soaked Invitation first then talk to a Bouncer in the Brawlpub and get to brawling!",objectivesText="Talk to a Bouncer in Bizmo's Brawlpub in the Deeprun Tram after using your Blood-Soaked Invitation.",starts={{x=0.537,y=0.616,mapID=499,npcID=253170}},ends={{x=0.537,y=0.616,mapID=499,npcID=253170}},coords={mapID=499,x=0.537,y=0.616},questType="standard"},
[94372] = {id=94372,name="The Gloves Are Off",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=6298,mapID=85,description="If you've found yourself an invite you'll be wanting to put it to good use, no? Use your Blood-Soaked Invitation first then talk to a Grunt in the Brawl'gar Arena and get to brawling!",objectivesText="Talk to a Grunt in the Brawl'gar Arena in Orgrimmar after using your Blood-Soaked Invitation.",starts={{npcID=252933,x=0.734,y=0.316,zoneID=1637}},ends={{mapID=85,npcID=252933,x=0.735,y=0.315}},coords={x=0.734,y=0.316,source="quest_giver",zoneID=1637},questType="standard"},
