[94455] = {id=94455,name="Home at Last",level=0,requiredLevel=0,faction="none",expansion=10,objectivesText="Approach your front door and enter your new house.",questType="standard"},
[94847] = {id=94847,name="Preparations Underway",level=45,requiredLevel=45,faction="both",expansion=10,zoneID=139,mapID=23,description="As you may or may not recall, I once helped young paladins obtain their first armored mount. It was a tedious task that involved months of obtaining materials and sending them all over Azeroth. Thankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord. In order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.",objectivesText="Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.",starts={{x=0.523,y=0.781,mapID=24,npcID=90250}},ends={{x=0.523,y=0.781,mapID=24,npcID=90250}},coords={mapID=24,x=0.523,y=0.781},questType="standard"},
[94850] = {id=94850,name="If You Build It",level=45,requiredLevel=45,faction="both",expansion=10,zoneID=7875,mapID=717,description="If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground. I will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. Here's the list of what you'll need.",objectivesText="Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.",starts={{npcID=119166,x=0.354,y=0.382,mapID=717}},ends={{npcID=119166,x=0.354,y=0.382,mapID=717}},coords={x=0.354,y=0.382,source="quest_giver",mapID=717},questType="standard"},
}
end)
